INSERT INTO Definition (word_id, language_id, pos_id, definition, example)
VALUES (10092,3,1,'နှစ်ဆယ့်သုံးလုံးမြောက်မွန်ဗျည်း။',NULL)
,(10093,3,4,'ဆို့သည်။','ဗကအ် = လည်ပင်းဆို့သည်။ || ဗသြိုဟ် = ရင်ဆို့သည်။ || ‘သဗ’ ဟုလည်းရေးသည်။')
,(10094,3,1,'ပေါက်ပေါက်။',NULL)
,(10095,3,1,'‘ပကဲ’ ရှု။',NULL)
,(10096,3,4,'‘ပကိုင်’ ရှု။',NULL)
,(10097,3,1,'အနီ။',NULL)
,(10097,3,3,'နီသော။','ပ္ကဴဒကှ်ဗ္ကေတ် = ကြာနီ။')
,(10098,3,1,'ဖျော့သောအနီရောင်။ နီကြင်ကြင်။ နီကြန့်ကြန့်။',NULL)
,(10099,3,1,'ခရမ်းရောင်။',NULL)
,(10100,3,4,'လှန့်သည်။ ခြောက်လှန့်သည်။','“(ညးဂမၠိုၚ်) ကဵုပါၚ်ဗကိုတ်ဂမ္အတ်တဴ (ဒြာဲဂှ်) အိုတ်ရ။” (သၠပတ်စန္ဒဝတဳ) = “လူများသည် ထိုသမင်အား အသံပြုခြောက်လှန့်ဟစ်အော်ကုန်၏။”')
,(10101,3,4,'မှာသည်။','“တ္ၚဲယးတေံ အဲတိုန်ဍုၚ်ရောၚ်၊ မူမိက်ဂွံဗကန်ရောအမူ။” = “မနက်ဖြန် ကျွန်တော်မြို့သွားမည်၊ ဦးလေးဘာမှာချင်သလဲ။” || ‘ဂကန်’ ဟုလည်းရေးသည်။')
,(10102,3,4,'မှာကြားသည်။','“သာ်ဝွံဖကန်ဖျန်တုဲ သၟိၚ်ဂံါတိတ်ဍိုက်ကွဳရ။” (ဇ—၄၉၄။ အစွောံ။) = “ထိုသို့မှာကြားပြီးလျှင် မင်းသည် လှမ်းထွက်၍ ရထားတက်စီး၏။” || ‘ဂကန်ဖျန်’ ဟုလည်းရေးသည်။')
,(10103,3,4,'မှောက်သည်။','“ဗြံက်ဂၞာဂှ် ဗကပ်စွံလဝ်ညိ။” = “အုန်းမှုတ်ခွက်ကို မှောက်ထားပါ။” || ‘ဂၠုၚ်ဂှ် ဗြံဗကပ်အာ။’ (ဇ—၄၇၈။ အစွောံ။) = ‘တိုလှေမှောက်၍ နစ်သွား၏။’ || “ဍေံထေဲကဵုမိဍေံတုဲ ဍေံတိက်ဗကပ်လဝ်မုက်ရ။” = “သူ့အမေကို သူစိတ်ဆိုးပြီး မျက်နှာမှောက်၍အိပ်နေသည်။”')
,(10104,3,4,'၁။ သပိတ်မှောက်သည်။ အဆက်အဆံမပြုဘဲ ပထားသည်။ ဖယ်ကြဉ်ထားသည်။','“ပိုဲဗကပ်လဝ်ဗဗေၚ်ကဵုဍေံ ဟွံဆက်ဆောံကဵုဍေံရ။” = “သူ့ကိုငါတို့သပိတ်မှောက်ထားသည်။ သူနှင့်မဆက်ဆံဘဲနေသည်။”')
,(10104,3,4,'၂။ လိုလားချက်ကို လိုက်လျောစေရန် အလုပ်တာဝန်များကို မလုပ်ဘဲနေသည်။ သပိတ်မှောက်သည်။ ဆန္ဒပြသည်။','“ညးဍုၚ်ကွာန်တအ် ဗကပ်ဗဗေၚ်ထ္ၜးဆန္ဒကဵုအလဵုအသဳတၠအဝဵု။” = “ပြည်သူများက အာဏာရှင်အစိုးရကို သပိတ်မှောက်ဆန္ဒပြကြသည်။”')
,(10105,3,1,'ရေညှိရေမှော်။ (ပါဠိ—ပဏက)',NULL)
,(10106,3,1,'ခဲ။','‘ဖကောဝ်’ ရှု။')
,(10107,3,1,'ခဲတံ။','ဗကောဟ်မှၚ် = ဖောင်တိန်။ || ဗကောဟ်တၟအ် = ကျောက်တံ။ || ‘ဖကောဟ်’ ရှု။')
,(10108,3,4,'ပေါများသည်။ ဝေဆာသည်။','“တၞံဆုမွဲသၟတ်၊ ဟွံမွဲသတ်မှာ။ ဒှ်ဒၟံၚ်သုခါ၊ ကၞာၚ်သၠဗ္ဂါတဴ။” (လိက်ဟတ္ထိပါလ။ အစွောံ။) = “တစ်ခုသောသစ်ပင်သည် အသီးမရှိသဖြင့် အကိုင်းအရွက်တို့ဝေဆာလျက် ချမ်းသာစွာရှိ၏။”')
,(10109,3,4,'မိုးရွာကျသည်။ မိုးရွာစေသည်။','“ပတွဵုနူဂှ် အလုံဂြိုပ် ဗြဲဗ္ဂူဒၟံၚ်လၟိုန်။” (ဇ—၁။အစွောံ။) = “ထိုနေရာမှစ၍ တစ်တောလုံးသည် မပြတ်မိုးရွာနေ၏။” || ‘ဂူ’ (ကြိ) လည်းရှု။')
,(10110,3,4,'မျက်ရည်မိုးရွာသည်။ မျက်ရည်ဖြိုင်ဖြိုင်ကျသည်။','“(သၟိၚ်တိတ်ပခမဳရောၚ်ဂးတုဲညးဂမၠိုၚ်) ယိုက်ကေတ်သမိပ်တဲ ဗဂူဗြဲမတ် ယာံအာတ်တဴအခေါၚ်အိုတ်ရ။” (ဇ—၄၅၉။ အစွောံ) = “ဘုရင်တောထွက်ရဟန်းပြုတော့မည်ဟုဆို၍ လူအပေါင်းတို့သည် လက်အုပ်ကိုချီလျက် မျက်ရည်မိုးရွာ၍ ငိုကြွေးတောင်းပန်ကြကုန်၏။” || “(သၟိၚ်အာရဂးတုဲ) မှာဇန်တံညးဂမၠိုၚ် — ယဵုတဲဗဂူဗြဲမတ် တက်သိုဟ်ဂတေဝ်ယာံ—။” (ဇ—၄၉၄။ အစွောံ။) = “မင်းစွန့်ခွာသွားတော့အံ့ဟုတိုင်းသူပြည်သားအပေါင်းတို့သည် လက်ကိုချီမြှောက်ကုန်၍ မျက်ရည်ဖြိုင်ဖြိုင်ကျလျက် ရၚ်ကိုထုကုန်၍ သည်းစွာငိုကြွေးကုန်၏။”')
,(10111,3,1,'၁။ ကြောင်သတ္တဝါ။','“ကၞိကဵုဗဂဲ၊ နဲဂှ်ပမာ။” (လိက်ဇိဝှစက္က) = “ကြွက်နှင့်ကြောင်ပမာတည်း။”')
,(10111,3,1,'၂။ အဖိုးတန်ကြောင်ကျောက်။','“ဍာ်လက်ဖက်ဂှ် ကတဴလောန်ရ။ ဗဂံက်ထောံမွဲခဏတုဲ သုၚ်ညိ။” = “လက်ဖက်ရည်က အလွန်ပူသည်။ ခဏအအေးခံပြီး သောက်ပါ။”')
,(10113,3,1,'ဂျတ်ကောင်။ ရေၚန်ပိုင်းနေ အဆိပ်ပြင်းမြွေတစ်မျိုး။ (?) (ပါဠိ—ဇလပျာလ)',NULL)
,(10114,3,4,'တၚ်သည်။','“ပ္ၚာန်ပုၚ်ဂှ် ဗဂၚ်လဝ်လ္တူဇံၚ်ပုၚ်ညိ။” = “ထမင်းပန်းကန်ကို ထမင်းစားပွဲပေါ်တွင် တင်ထားပါ။”')
,(10115,3,4,'လှည့်သည်။ ရွေ့လျားစေသည်။','“ကောဗၠာဲဇွိတ်ဝေၚ်၊ ဗ္ဂေၚ်တဲၜါ။” (လိက်ဗြရတ်ဣဏၚ်ကၚ်ရဳ) = “ကိုလူပျိုသည် လက်နှစ်ဖက်တို့ကို ရွေ့လျားစေ၍ ပွတ်သပ်ကစား၏။”')
,(10116,3,4,'ကိုယ်ကိုလှည့်သည်။','‘လှ်ေဗဂေၚ်ဒၟံၚ်ဇကု—။’ (ဇ—၄၈၉။ အစွောံ။) = ‘ကိုယ်ကိုလှည့်၍ကနေ၏။’')
,(10117,3,4,'စည်တီးကြေညာသည်။ စည်လည်သည်။','“ကဵုတက်ဗဂေၚ်ဖံ အလုံရးအိုတ်ရ။” (ဇ—၅ဝ၉။ အစွောံ။) = “တိုင်းနိုင်ငံအလုံးကို စည်တီးကြေညာစေ၏။”')
,(10118,3,4,'လှုပ်ရှားသည်။','“ကာလမလှ်ေအဴ၊ ဗ္ဂေၚ်ဗ္ဂံက်တဴဇိုၚ်တဲ။” (လိက်လက္ခဏာဒိပ္ပဗိန္ဒော) = “ကသောအခါ ခြေလက်တို့ကို လှုပ်ရှား၏။”')
,(10119,3,1,'အပင်မှရသောဥ။','ဗဂေါၚ်ဆု = သစ်ပင်၏အဥအတက်။')
,(10120,3,4,'ရဲရင့်အောင်လုပ်သည်။','‘ဂံၚ်’ (ကြိ) လည်းရှု။')
,(10121,3,4,'ရဲဆေးတၚ်သည်။ ရဲစိတ်မွေးသည်။','“(ကၠိက်ဂမၠိုၚ် ညံၚ်ဟွံဂွံဖေက်ကၠဂှ် သၟိၚ်ကၠိက်ဂှ်) ဟီုသၠာံဗဇး ဗဂံၚ်ကဵုစိုတ်ကၠိက်ဂမၠိုၚ်ရ။” (ဇ—၄၉၂။ အစွောံ။) = “တောဝက်များ ကျားကိုမကြောက်ကြရန် တောဝက်မင်းက တောဝက်များကို ပြောဆိုနှစ်သိမ့် ရဲဆေးတၚ်ပေး၏။”')
,(10122,3,4,'ဈေးဆစ်သည်။','“ရာန်ဖျာမ္ဂး ဗဂုတ်တုဲရာန်ညိ။” = “ဈေးဝယ်လျှင် ဈေးဆစ်ပြီးဝယ်ပါ။” || ‘ဒဂုတ်’ ရှု။')
,(10123,3,4,'လှည့်သည်။','ဗဂေတ်ကရောဲ = ဂျင်လှည့်ကစားသည်။ || ဗဂေတ်ဇကု =ကိုယ်ကိုလှည့်သည်။ || “အဲကလောန်ဂၠိုၚ်ဒၟံၚ် ဗဂေတ်ဇကုဟွံဂတာပ်ရ။” = “ကျွန်တော်အလုပ်များနေ၍ ကိုယ်တောင်လှည့်၍မအားပါ။” || ဗဂေတ်ထပိုဲ = ရှင်လောင်းလှည့်သည်။ || ဗ္ဂေတ်က္ဍိုၚ်ကျာ် = ဘုရားထီးတော်လှည့်သည်။')
,(10123,3,9,'အလှည့်။ အပတ်။','“ဗ္ဂေတ်ဇကုပိဗ္ဂေတ်။” (ဇ—၇ဝ။ အစွောံ။) = “ကိုယ်ကို သုံးပတ်လှည့်သည်။” || ‘ဂေတ်’ (ကြိ) လည်းရှု။')
,(10124,3,4,'လှည့်သည်။ လှည့်ပတ်သည်။','‘ရေတ်’ (ကြိ) လည်းရှု။')
,(10125,3,4,'(လှည်း­ နွားမြင်းစသည်) တပ်ဆင်သည်။ ကသည်။','“ဗောဓိသတ်ဗဂန်ကေတ်ကွဳတုဲ စဝ်ဏာရ။” (ဇ—၁၉၄။ အစွောံ။) = “ဘုရားလောင်းသည် လှည်းကိုက၍သွား၏။” (ညောင်ကန်) || “ကောန်တြုံအဲမွဲဂှ် ကွဳဗ္ဂန်ကေတ်သန္ဓဴပန်ဂှ် ဍေံဒးဂၞပ်ရ။” (ဇ—၂၈၉။ အစွောံ။) = “သားသည်ကား အာဇာနည်မြင်းက၊သောရထားကို အလိုရှိ၏။” (ညောင်ကန်)')
,(10126,3,4,'ရန်စရှာသည်။ ပြဿနာရှာသည်။ ခိုက်ရန်ဖြစ်အောင်ဖန်တီးသည်။','“(သမ္ဘာတမ္ၚာသမၠီုဝွံ) မုက်ညးမတဴဝုတ်ဒိုဟ် မဒဒှ်ေဒၟံၚ်ဝွံဟွံသ္ၚဳတုဲ ပကြံဗ္ဂန်ဂလာန် ပလီုစိုတ်ညး ပဂဗုတ်ဒဵုစိုပ်တၠခွါ—။” (ဇ—၁၃၉။ အစွောံ။) = “မိုက်မဲသောတံငါသည်မယားသည် မိမိ၏အိမ်နီးချင်းတို့အား ခင်မင်ရင်းနှီးနေသည်ကိုမျှ မျက်နှာမထောက်ရှုဘဲ အထက်တၚ်စီး ရန်စရှာ၍ သူတစ်ဖက်သားတို့ကို တရားစွဲဆိုရာ ရွာစားဆီသို့ ရောက်ရသည်အထိဖြစ်၏။”')
,(10127,3,4,'ခိုက်ရန်ပြုသည်။ ခိုက်ရန်ဖန်တီးသည်။','“အဲစကာကောန်အဲ ကဵုစဴအာကဵုမိဍေံကဵုဗဂန်ကၠေံသွေက်ဇွဵု ညးမတဴဝုတ်ဒိုဟ်သ္ၚိတံဂှ်—။” (ဇ—၁၃၉။ အစွောံ။) = “ငါ့သားအား သူ့မိခင်ဆီသို့ ပြန်သွားစေ၍ သူ့မိခင်ကို အိမ်နီးချင်းတို့နှင့် ခိုက်ရန်ပြုစေအံ့။”')
,(10128,3,4,'ဥပါယ်ဖွဲ့သည်။ မိမိအကျိုးစီးပွားအောင်မြင်ရန် နည်းပရိယာယ်ဖြင့် ကြံစည်ပြောဆိုပြုလုပ်သည်။','“မၚ်ဗၠာဲဂှ် နွံကဵုစလဳစလး ဗ္ဂန်ဥပ္ပါယ်ဒးတုဲ ဂွံဗၠးနူသ္ကေမ်တဲသတြုရ။” = “ထိုလုလင်သည် လိမ္မာပါးနပ်၍ မှန်သောဥပါယ်တံမျဉ်ဖွဲ့ခြင်းဖြင့် ရန်သူ့လက်တွင်းမှလွတ်၏။”')
,(10129,3,4,'ကပ်သည်။ ဆက်ကပ်သည်။ ကပ်လှူသည်။','“ဗဂိန်ပုၚ်ကဵုခမဳသၚ်ဂမၠိုၚ်။” =“ရဟန်းသံဃာများကို ဆွမ်းဆက်ကပ်သည်။” || “သၟိၚ်စဳရေၚ်ကဵုပုၚ်ဂန္ဓသာလဳ သီုအမာဲကဖျုန်ကၠေၚ်သွဟ်ကၠေၚ်ဗွုတ်တုဲ ဗဂိန်ကဵုထေရ်ရ။” (ဇ—၂၉၂။ အစွောံ။) = “မင်းသည် အမဲသားငါးဟင်းလျာနှင့်တကွ သလေးထမင်း ထောပတ်တို့ကို စီရင်ပြီးလျှင် မထေရ်အားကပ်လှူ၏။”')
,(10130,3,4,'၁။ တပ်ဆင်သည်။','“အပေါတ်စက်ပလှ်လဝ်ဂှ် ကလေၚ်ဗ္ဂပ်ညိ။” = “ဖြုတ်ထားသောစက်ပစ္စည်းများကို ပြန်လည်တပ်ဆင်ပါ။” || “ဇံၚ်ရာန်နၚ်ဂှ် ဗဂပ်လဝ်တုဲရ။” = “ဝယ်လာသောခုတၚ်ကို တပ်ဆင်ပြီးပြီ။”')
,(10130,3,4,'၂။ (ဟင်း) စပ်သည်။','ဗ္ဂပ်သွ = ဆီ၊ ဆား၊ ငရုတ်သီး၊ကြက်သွန်စသည်ထည့်၍ ဟင်းစပ်သည်။')
,(10131,3,4,'(သုံးရန်အဆင်သင့်ဖြစ်အောင်) ပြုလုပ်စီရင်သည်။ ပြင်ဆင်သည်။','“ညးကနှံသ္ၚိပြာသာဒ်ဂှ် — ဟီုကဵုဗ္ၜတ်ဇမၞော်သမၠုၚ် ကဵုဝဍ္ဎကဳတုဲ ဝဍ္ဎကဳလောပ်အာဂြိုပ် ကၠောန်ဗဂပ်ပရာပ်နၚ် (ရ) ။” (ဇ—၁၅၆။ အစွောံ။) = “အိမ်ပြာသာဒ်ဆောက်လုပ်ရန် လူတို့သည် မိမိတို့လိုချင်သော အရွယ်အစား၊ အမြင့်အတိုင်းအတာတို့ကို လက်သမားများအားပေး၍ ထိုလက်သမားတို့သည် တောသို့ဝင်၍ အဆင်သင့်သုံးနိုင်ရန် ပြုလုပ်ပြင်ဆင်၍ ယူဆောင်လာ၏။” || “(ခမဳဂှ်) ယာတ်တရေံမွဲဒကုတ် ဗ္ဂပ်ပြာပ်စဳရေၚ်သ္ၚာ—။” (ဇ—၃၈။ အစွောံ။) = “ထိုရဟန်းသည် အဝတ်ဟောင်းတစ်ပိုင်းကို ပြုပြင်စီရင်၍ သင်္ကန်းချုပ်လုပ်၏။” || “ဂတာံဝွံ ဟိုတ်မညာတ်ဂၠိၚ် ပယောဂဒွး — မသ္ဂောံလနိန်ဗပိန်သတြု စိစုမ်ဗ္ဂပ်ပြာပ်လဝ်ဒးတုဲ (ၜိုန်ပံက်စၞာဲဟီုဘကမၠကီုလေဝ်ဟွံဖေက်ရ။)” (ဇ—၃၈။ အစွောံ။) = “ဗုဇွန်သည် အရှည်ကိုမြင်သဖြင့် ရန်သူကိုအောင်မြင်နိုင်ကြောင်း ကောင်းသောအားထုတ်မှုဖြင့် ပြည့်စုံအောင်စီရင်ထားပြီးဖြစ်သောကြောင့် ဗျိုင်းစဉ်းလဲကပြောဆိုခြိမ်းခြောက်သော်လည်း မကြောက်။”')
,(10132,3,1,'နေ့တစ်ဝက်အချိန်။','“ကွာ်တိုက်မွဲဗဂါပ်မ္ဂး စိုပ်ကွာန်ဂှ်ရောၚ်။” = “တစ်မွန်းတည့် || နေ့တစ်ဝက် ခြေလျင်လျှောက်လျှင် ထိုရွာသို့ရောက်မည်။”')
,(10132,3,9,'အနပ်။','“မွဲတ္ၚဲပိုဲစပုၚ်ၜါဗဂါပ်ရ။” = “တစ်နေ့လျှင် ကျွန်တော်တို့ထမင်းနှစ်နပ်စားသည်။”')
,(10133,3,4,'ငိုက်မျဉ်းသည်။ အိပ်ချင်မူးတူးဖြစ်သည်။','“က္တဵုတုဲဗိုန်ဇၟအ်၊ ဂဇအ်ထၜုဲ။ မတ်စှ်ေဖြိပ်ဖြိပ်၊ ဗဂိပ်ဒကုဲ။ ဂဇအ်ဒၟံၚ်တုဲ၊ မတ်ၜါမှုဲဘိုၚ်။” (လိက်လၞုဟ်ပန်) = “အိပ်ရာမှထပြီးလည်း မြဲစွာကွေး၍ထိုၚ်ပြန်၏၊ မျက်စိမှေးကျကာ မှိတ်တုံဖွင့်တုံ အိပ်ချင်းမူးတူးဖြင့် ငိုက်မျဉ်း၍ထိုၚ်လျက်မျက်လုံးနှစ်ဖက်တို့သည် လေးလံထိုင်းမှိုင်းလျက်ရှိ၏။”')
,(10134,3,4,'(စစ်တိုက်ရာတွင်) ရှေ့တိုး၍လိုက်သည်။','“ညးဂၟံၚ်သၟိၚ်အဿကညးလ္ၚီဂှ် ကၠေံစိုတ်ဗဂုပ်ဗတိုက်တုဲ လ္ပာ်ပၞာန်သၟိၚ်ကလိၚ် ပေက်ကဝ်ကျဒဴအာရ။” (ဇ—၃ဝ၁။ အစွောံ။) = “အဿကမင်း၏ သူရဲတစ်ထောင်တို့သည် ကြိုးစား၍ ရှေ့တိုးလိုက်တိုက်ရာ ကာလိၚ်္ဂမင်း၏စစ်တပ်သည် ကျိုးပျက်ရှုံးနိမ့်၍ ကစဉ့်ကလျား ထွက်ပြေးသွားကြကုန်၏။”')
,(10135,3,1,'ချိုးစိမ်းငှက်။','“ပူပါဗဂီု၊ သီုသာရိကာ။” (လိက်ကောန်သၟိၚ်ပိ။ မာံခစုန်အံက်) =“ချိုးငှက်ချိုးစိမ်းနှင့် ဆက်ရက် || သာရိကာ။”')
,(10136,3,4,'လှည့်သည်။ တိမ်းသည်။','‘ဗဂဲါထောံက္ဍိုပ်ဂၠုၚ်။’ = ‘လှေဦးကိုလှည့်လိုက်သည်။’ || ‘ဂဲါ’ (ကြိ) လည်းရှု။')
,(10137,3,4,'(မီးခိုး၊ အငွေ့) ထွက်လွင့်စေသည်။ ထစေသည်။ မီးခိုးတိုက်သည်။','“ညံၚ်ဂၟိတ်ဂွံဒြေပ်စ္ဍးအာ ပိုဲဒးဗ္ဂုဲယက်ရောၚ်။” = “ခြၚ်များပြေးခွာသွားရန် ငါတို့မီးခိုးတိုက်ရမည်။” || “(နူဍာ်ဂှ် သၟိၚ်နာ်) ဗဂုဲပတိုန်ယက်။” (ဇ—၁၃၃။ အစွောံ။) = “နဂါးမင်းသည် ရေမှ မီးခိုးထစေ၏။” || “ထောံစုတ်သၠဆု ပ္ဍေန်ပၟတ်တုဲဗဂုဲယက်—။” (ဇ—၁၄၁။ အစွောံ။) = “သစ်ရွက်တို့ကိုထည့်ပြီးလျှင် မီးညှိ၍ မီးခိုးတိုက်၏။”')
,(10138,3,1,'၁။ မြွေပါ။','“ပ္ဍဲတဏအ်ဂှ် ဗဂေါဝ်မွဲနွံ။” (ဇ—၁၆၅။ အစွောံ။) = “တခုသောတောင်ပို့­ မြွေပါသည်နေ၏။” (ညောင်ကန်)')
,(10138,3,1,'၂။ အမည်မဖော်နိုင်သောငှက်တစ်မျိုး။','“မပ္တံကဵုဂစေံဓဇဲ၊ ဓမာတ်၊ စာၚ်ဍာ်၊ စာၚ်ကၠိုက်၊ လိုက်ထောဝ်၊ ဗဂေါဝ်၊ ဖဝ်ရဂုတ်—။” (ဇ—ဝေသန္တဝ်။ အစွောံ။)')
,(10139,3,4,'လှစေသည်။ အလှတက်စေသည်။','“(သၟိၚ်အိန်ဇိုန်ကဵုသၟိၚ်ကုသ) မၞိက်မပြဲမဗဂေါဝ်ကဵုရုပ်။” (ဇ—၅၃၁။ အစွောံ။) = “သိကြားမင်းသည် ကုသမင်းအား ရုပ်ကိုလှစေသော မြတ်သောပတ္တမြားကို ပေး၏။” || “ညံၚ်မၞိက်အိန်မဗဂေါဝ်ကဵုမုက်ကုသကီု။” (ဇ—မဟောဟ်သဓ။ အစွောံ။) || “မိဗောဓိသတ်မဗလိုပ်ဖုံဂ္ညိဂ္ညာတ် ဗဂေါဝ်ပတိုန်စရာဲရုပ်တုဲ။” (ပေါရဏာံပေါရဒံါ။ အစွောံ။) = “ဘုရားလောင်း၏မိခင်သည် ဘုရားလောင်းကို ရေချိုးဆင်ယင်စေ၍ ရုပ်အဆင်းအလှကို တက်စေ၏။” || “သဳလမြမောဝ်၊ ဗ္ဂောဝ်ကဵုရုပ်ရဴ။” (လိက်ကောန်သၟိၚ်ပိ။ မာံခစုန်အံက်။) =“သီလနံ့သာသည် ရုပ်ရည်ကိုလှစေ၏၊ (ဝါ) အလှတက်စေ၏။” || ‘ဂေါဝ်’ (ကြိ) လည်းရှု။')
,(10140,3,4,'စကားကိုလှအောင်ပြောသည်။ စကားကောင်းသော်လည်း အလုပ်မကောင်းဖြစ်သည်။','“ယွံတၠအဲလမာဲ၊ တၠအဲသၟိက်လှေအ်လှန်အဲတုဲ တၠအဲဗဂေါဝ်ဝေၚ်ဂလာန်တုဲ တၠအဲမဟီုဂှ် အဲတီဒၟံၚ်ရ” ကၞုဲဂး။ (ဇ—၃၆၅။ အစွောံ။) = “အိုအလမ္ပာယ်၊ သင်သည် ငါ့ကိုမြှူဆွယ်လိုသဖြင့် စကားလှအောင်ပြောသည်ကို ငါသိ၏” ဟုမျောက်ဆို၏။ || “ဍေံဟီုပၠောပ်ကတောဝ် ဗဂေါဝ်အရေဝ်ရ။” (လောကသိဒ္ဓိ။ အစွောံ။) = “သူသည် စကားကိုလှအောင်ပြောပြီး နားချသည်။” || “ကၠုၚ်ဟီုပၠောပ်က္တောဝ်၊ ဗ္ဂောဝ်အရေဝ်ရောၚ်။” (လိက်ကောန်သၟိၚ်ပိ။ မာံခစုန်အံက်။) = “စကားလှအောင် လာ၍နားချပြောဆို၏။”')
,(10141,3,4,'မျက်နှာလှစေသည်။ မျက်နှာကိုရွှင်စေသည်။ ဝမ်းမြောက်ရွှင်လန်းစေသည်။','“ဗောဓိသတ်ညးဗၞိက်လီုဝွံ ကလိဂွံထးထဝ်ၚုဟ်မွဲလက်တုဲ စဴစိုပ်သ္ၚိ မဂွံအဵုဇိုတ်ဗဂေါဝ်မုက်ကောန်သမ္ဘာရ။” (ဇ—၃။ အစွောံ။) = “ဘုရားလောင်းရွဲကုန်သည်သည် အဘိုးတစ်သိန်းထိုက်သော ရွှေခွက်ကိုရရှိ၍ အိမ်ပြန်ရောက်သောအခါ ဝမ်းသာပျော်ရွှင်လျက် အိမ်သူဇနီးသားသမီးများအား မျက်နှာလှစေ၍ ဝမ်းမြောက်ရွှင်လန်းစေ၏။” || “(ဂစေံဒဂိုတ်တံဂှ်) အဲဂွံကေတ်ဖျဴဍေံပၠန်တုဲ ဂွံဗဂေါဝ်ကဵုမုက်ၝောံပၠန်ရ။ ၝောံဒးကအီပၠန်ရ” လၟဂးကဵုသမ္ဘာရ။ (ဇ—၃၃။အစွောံ။) = “ငုံးငှက်တို့ကိုငါဖမ်း၍ အိမ်သို့ယူပြန်လာကာ ရှင်မကို မျက်နှာလှစေပြန်ဦးမည်။ရှင်မ၊ ပြုံးရွှင်ရပြန်ဦးမည်” ဟုမုဆိုးသည် မယားအားပြော၏။ || “ခါအဲဟွံချိုတ်တဴဂှ်လေဝ် အဲဂွံကလေၚ်စဴတုဲ ဂွံဗဂေါဝ်ကဵုမုက်မိရ၊ မိဂွံကအီတဴရမိ” ဗောဓိသတ်ဂး။ (ဇ—၃၉၈။ အစွောံ။) =“မိခင်၊ အကျွန်ုပ်မသေဘဲပြန်လာရလျှင် မိခင်ကို မျက်နှာလှစေပါမည်၊ မိခင်ရွှင်ပြုံးရပါမည်။”')
,(10142,3,4,'‘ဗဂေါဝ်ဂလာန်’ ရှု။',NULL)
,(10143,3,4,'တောက်လောင်စေသည်။','ဗဂဵုပၟတ် = မီးတောက်လောင်စေသည်။ မီးမွှေးသည်။ || ‘ဂဵု’ (ကြိ) လည်းရှု။')
,(10144,3,4,'ထွန်းတောက်စေသည်။ ထွန်းလင်းစေသည်။ ထွန်းကားစေသည်။','“မှာထေရ်အရဟံ နူဍုၚ်မန် အာဗဂဵုလဟဵုသာသနာ ပ္ဍဲဍုၚ်ဗကာံရ။” = “ရှင်အရဟံသည် မွန်ပြည်မှပုဂံပြည်သို့ သာသနာတော်ထွန်းကားအောင် သွားရောက်သာသနာပြုသည်။” || ‘ဂဵုလဟဵု’ (ကြိ) လည်းရှု။')
,(10145,3,4,'၁။ ခံတွင်းမှလေကို ခပ်ပြင်းပြင်းမှုတ်ထုတ်သည်။','ဗဂိုဟ်ပၟတ် = မီးတောက်လောင်အောင်မှုတ်သည်။ မီးမှုတ်သည်။')
,(10145,3,4,'၂။ နှဲ၊ ပလွေစသည်ကို ခံတွင်းလေအားဖြင့် အသံမြည်အောင်မှုတ်သည်။','ဗဂိုဟ်ကလောတ် = ပလွေမှုတ်သည်။ || ဗဂိုဟ်ကၞုသၚ် = ခရုသင်းမှုတ်သည်။')
,(10146,3,1,'စပါးစိုက်သောလယ်။','ဇိက်ဗ္ၚ = လယ်ထွန်သည်။ || ဝါဗ္ၚ = လယ်တော။ လယ်ယာ။')
,(10147,3,4,'ကျွေးသည်။','‘စ’ (ကြိ) လည်းရှု။')
,(10148,3,4,'ကျွေးမွေးသည်။','‘စဟာပ်’ (ကြိ) လည်းရှု။')
,(10149,3,4,'ဆင်ခြင်သည်။ ချင့်ချိန်သည်။','နာဲဗ္စာ = တရားဆုံးဖြတ်သူ၊ တရားသူကြီး။ || ရုၚ်ဗစာ = တရားရုံး။')
,(10150,3,4,'မိမိစိတ်နှင့် နှိုင်းယှဉ်စာနာသည်။ ကိုယ်ချင်းစာသည်။',NULL)
,(10151,3,4,'စဉ်းစားဆင်ခြင်သည်။ ဆင်ခြင်သုံးသပ်သည်။','“မနွံစိုတ်မသာ နပညာဟွံဂွံဗစာရဏာတုဲ—။” (ဇ—၄ဝ၄။ အစွောံ။) = “ပေါ့သောစိတ်ရှိ၍ ပညာဖြင့်မဆင်ခြင်—။”')
,(10152,3,4,'ရှေ့နောက်ဆင်ခြင်သည်။','“မူပပ ဗစာရဏာဂတကြဴညိ။” = “ဘာပဲလုပ်လုပ် ရှေ့နောက်ဆင်ခြင်ပါ။ ”')
,(10153,3,4,'အကျိုးအပြစ်ဆင်ခြင်သည်။','“ယွံဒေံဗြဴ၊ ယြဴပူဂဵုမအောန်ကဵုပညာဂှ် ပြဝမွဲပတုဲ ဟွံဂွံဗစာရဏာဂုန်ဒုဟ်တုဲ ဗွဲမပြဟ်ပြေဟ်မပ္တုဲဂှ် ပြဝဂှ် မဒှ်ဟိုတ်လေၚ်ရောၚ်။” (ဇ—၁၅၂။အစွောံ။) = “ချစ်နှမ၊ အကြင်ပညာနည်းသောသူသည် အမှုတစ်ခုကို ပြုသည်ရှိသော် အကျိုးအပြစ်မဆင်ခြင်မူဘဲ အဆောတလျင်ပြုသော ထိုအမှုသည် ပျက်စီးရခြင်း၏အကြောင်းတည်း။”')
,(10154,3,4,'အမှားအမှန်ဆင်ခြင်သည်။','“ယွံခမဳတံ၊ ပူဂဵုတၠပညာ မဗစာရဏာမုတ်ဒွး မဟွံဂွံစဂျိ (ကလော်မဗဒှ်လဝ်) ဂှ် ဂှ်ပူဂဵုတံဂှ် ဂွံဒှ်တသိုက်စိုတ် တသိုက်ကာယ မဟွံစံၚ်တူရ”ကျာ်တြဲဂး။ (ဇ—၃၆၆။ အစွောံ။) = “ရဟန်းတို့၊ အမှားအမှန်ဆင်ခြင်တတ်ကုန်သော ပညာရှိတို့သည် ဘီလူးတို့တည်ထားသောအဆိပ်ကို မစားသဖြင့် စိတ်၏ချမ်းသာခြင်း ကိုယ်၏ချမ်းသာခြင်းကို ရသည်ဖြစ်၍ မပူပန်ရ။”')
,(10155,3,4,'အကြောင်းအကျိုးဆင်ခြင်သည်။','“ယြဴမၞိဟ်ဟွံဂွံဗစာရဏာဟိုတ်ဖဵုတုဲ ဍေံဂွံဗတဝ်သာဲရဍေံဂးတုဲ မဒးစစုတ်ဂျိဂှ်ရ။” (ဇ—၃၆၆။ အစွောံ။) = “အကြောင်းအကျိုးမဆင်ခြင်တတ်ကုန်သောလူတို့သည် ပျားသကာကို ရပေ၏ဟုဆို၍ ထိုအဆိပ်ကို စားမိကုန်၏။”')
,(10156,3,4,'ပြောင်လက်သည်။ တောက်ပသည်။','“သၟတ်ဗြဴဂှ် လျးသော်ဗစဳဒၟံၚ်ညံၚ်လျးတ္ၚဲ။” (ဇ—၅၂၃။ အစွောံ။) = “ထိုမိန်းမပျို၏ဆံပင်သည် နေရောင်ခြည်ကဲ့သို့ တောက်ပနေ၏။” || “သၟတ်ဗြဴဂှ် မၞုံသော်က္ဍိုပ်လစံက်သ္ဇုၚ်သ္အး မဗစဳတဴညံၚ်ရဴသာ်မၞိက်လမ္စံက်ကီု။” (ဇ—၅၂၆။ အစွောံ) =“ထိုမိန်းမပျိုသည် နက်ကြည်စင်ကြယ်သောဆံပင်ရှိ၍ ပတ္တမြားညိုအဆင်းကဲ့သို့ ပြောင်လက်တောက်ပ၏။” || “မြာ်မၞုံကဵုဂၞဲမဆာဲ မၞုံကဵုရမျှာၚ်မမိပ် မၞုံကဵုသော်ကအ်မဗစဳတဴဂှ်—။” (ဇ—၃၃၉။အစွောံ။) = “လှသောဦးစွန်းရှိသော သာယာသောအသံရှိသော ပြောင်လက်သောလည်မွေးရှိသောဥဒေါင်း။” || “စိၚ်ဂှ် မၞုံအရံၚ်သာ်ဇကုဍေံလစံက်တဴ ညံၚ်ရဴတၟံလစံက်ကီု ဗစဳဒၟံၚ်။” (ဇ—၄၆၃။အစွောံ။) = “ထိုဆင်သည် မျက်စဉ်းတောင်ထွတ်ကဲ့သို့ မည်းနက်၍ ပြောင်လက်နေ၏။”')
,(10157,3,4,'လင်းလက်တောက်ပသည်။ တောက်ပပြောင်လက်သည်။','“(ဂၞကျာ်သမ္ဘူလာ) နလျးအရံၚ်ဇကုဂၞကျာ် ဒတဴဒၟံၚ်မဗမ္စဳခဏဒၟံၚ်ဂှ် အလုံဂြိုပ်ဂှ် တၟးဒၟံၚ်ရ။” (ဇ—၅၁၉။ အစွောံ။) = “မတ်တတ်ရပ်နေသောသမ္ဘူလမိဖုရား၏ တောက်ပသောကိုယ်အရောင်အဆင်းဖြင့်တစ်တောလုံးလင်းနေ၏။” || “ယွံသၟတ်ဗြဴ၊ ဇကုသၟတ်ဗြဴဂှ် ညံၚ်ရဴသၞံၚ်ဂဂဵုကီု ညံၚ်ရဴဇုက်လလဳကီုဒှ်တုဲ လျးဇကုသၟတ်ဗြဴမဗစဳခဏတဴဂှ် ညးသၟတ်ဗြဴဂှ်သ္ဂးရော။” (ဇ—၅ဝ၆။ အစွောံ။) = “အဘယ်၊သင်၏ကိုယ်သည် သောက်ရှူးကြယ်ကဲ့သို့၄င်း လျှပ်စစ်ကဲ့သို့၄င်း သင်၏ကိုယ်ရောၚ်သည် လင်းလက်တောက်ပ၏။ သၚ်မည်သူနည်း။” || “(ညံၚ်သၟိၚ်ဂိတု) ရဴမဗစဳခၞဒၟံၚ် ပ္ဍဲဂၠးအာကာသကီု။” (ပြကိုဟ်ဓမ္မဒေသနာ။ မာံရွှေငိုး။) = “ကောင်းကင်ပြင်­ လင်းလက်တောက်ပနေသော လမင်းကဲ့သို့။”')
,(10158,3,4,'လင်းလက်ပျံ့နှံ့သည်။','“ရဴဗီုဖရိပ်ဇုက်လလဳ မဒြေပ်ဗစဳတရး—။” (ဇ—၂၂၉။ အစွောံ။) = “အနှံ့လင်းလက်တောက်ပ ပြေးသွားသောလျှပ်စီးနွယ်ကဲ့သို့။”')
,(10159,3,11,'(န) အထောက်အပံ့ပစ္စည်း။',NULL)
,(10160,3,1,'သံဃာများအတွက် ပစ္စည်းလေးပါး။ (သင်္ကန်း၊ ဆွမ်း၊ ကျောင်း၊ ဆေးဟူသော ရဟန်းအသုံးအဆောင်။)','“သဘဴခမဳမ္ဂးဂှ် — ဂပ်ဂဝ်အောန်ကဵုပၟိက် ပ္ဍဲဝတ္ထုပစ္စယ်ပန်ရောၚ်။” (ဇ—၄ဝဝ။ အစွောံ။) = “ရဟန်းမည်သည် ပစ္စည်းလေးပါး­ အလိုနည်းသည်ဖြစ်ရာ၏။”')
,(10161,3,1,'အချဉ်။ အချဉ်အရသာ။','‘ဖျး’ (ကြိ) လည်းရှု။')
,(10162,3,4,'စုတ်ပြဲအောင်လုပ်သည်။ ဆုတ်ဖြဲသည်။','ဗစာ်စက္ခော = စက္ကူကို ဆုတ်ပစ်သည် || ဗစာ်ယာတ် = အဝတ်ကိုဆုတ်သည်။ || ‘စာ်’ (ကြိ) လည်းရှု။')
,(10163,3,4,'ကွဲကွာအော်လုပ်သည်။ ကွဲကွာစေသည်။','“ဒးဗစာ်ခြာ၊ ကြာမိကဵုကောန်။” (လိက်ကောန်ဂစေံပိ။ နာဲဗျူ။) = “မိခင်နှင့်သားကို ကွဲကွာရအောင်ပြုမိသည်။” || ‘စာ်ခြာ’ (ကြိ) လည်းရှု။')
,(10164,3,4,'၁။ ထိတွေ့အောင်လုပ်သည်။ ထိကပ်စေသည်။','“ဂတဵုဆုၜါဂတှ်ေဂှ် ဗစုက်ထောံညိ။” = “သစ်ပျဉ်ပြားနှစ်ချပ်ကို ထိနေအောင်ထားလိုက်ပါ။” || ‘စုက်’ (ကြိ) လည်းရှု။')
,(10164,3,4,'၂။တိုက်သည်။ တွန်းတိုက်သည်။','ဗစုက်က္ဍိုပ် = ခေါင်းနှင့်တိုက်သည်။ || “(ဗြဴဂှ်) ဍေံလ္ၚောဝ်ဍေံဂးတုဲ ဍေံဗစုက်က္ဍိုပ် ဍေံရပ်ဗောဓိသတ်ဗိုန်တုဲ ဍေံဒရိုဟ်ဖျေံဏာ ပ္ဍဲလပါ်တၟအ်တေံရ။” (ဇ—၁၉၃။အစွောံ။) = “မယားသည် ဘုရားလောင်းအား ရှိခိုးမည်ဟုဆိုကာ ဦးခေါင်းနှင့်တွန်းတိုက်၍ ဘုရားလောင်းအား မြဲစွာကိုင်၍ တောင်ကမ်းပါးပြတ်သို့ တွန်းချလိုက်၏။”')
,(10165,3,4,'တို့မီး ရှို့မီးလုပ်သည်။ ကုန်းချောသည်။',NULL)
,(10166,3,1,'ဘုမ္မရာဇာ။ (ဆေးဖက်ဝင်)','‘စံက်ဗြဴ’ ဟုလည်းရေးသည်။')
,(10167,3,4,'စောင်းစေသည်။',NULL)
,(10168,3,1,'အချုပ်ဆေး။ အဖန်အရသာ။','ဍာ်ဗစိုတ် = ဖန်ရည်။ || “ယွံနာဲပိုဲဣသိတံ၊ မသပိုၚ်ကေတ်ယာတ်လွံက် နဍာ်ဗစိုတ် မသၠောံကေတ်သ္ၚာယာတ်လွံက် နသကောဝ်ဆု။” (ဇ—၅ဝ၉။ အစွောံ။) = “အရှင်ရသေ့တို့၊ အရှင်တို့သည် ဖန်ရည်စွန်းသော သင်းပိုင်ကိုလည်းဝတ်၍ သစ်ခေါက်ရည်ဆိုးသော သင်္ကန်းကိုလည်း ဖုံးလွှမ်း၏။” || ‘ယာတ်လွံက်ဍာ်ဗစိုတ်။’ (ဇ—၅၁၄။ အစွောံ။) = ‘ဖန်ရည်စွန်းသောအဝတ်။’ || ‘ဖျိုတ်’ (ကြိ) လည်းရှု။')
,(10169,3,1,'မှာကြားချက်။ အမှာစာ။ အမှာစကား။','လိက်ဗစန် = ပါးလိုက်သောစာ။ ပေးပို့သောစာလွှာ။ || “အဲဒၟံၚ်အဏအ် ဂယိုင်လမျီုသီုဒဒိုက်ရောၚ်၊ — ကၠုၚ်ဒုၚ်ဏာအဲညိ” ဂးတုဲ သၟတ်ဗြဴကဵုဏာဗစန် (ကုဗောဓိသတ်) ရ။ (ဇ—၆၃။ အစွောံ။) = “ကျွန်မဤမှာနေရသည်မှာ ဆင်းရဲစွာအသက်မွေးရ၏။ ကျွန်မကို လာကြိုလှည့်ပါ” ဟုဆို၍ ထိုမိန်းမသည် ဘုရားလောင်းအားသတင်းစကားပါးလိုက်၏။ || “ဗောဓိသတ်မိၚ်ဗစန်ဂှ် ပ္တေဟ်တုဲ (ပြာပ်အာဇရေၚ်သၟတ်ဗြဴဂှ်ရ။)” (ဇ—၆၃။ အစွောံ။) = “ဘုရားလောင်းသည် ထိုသူငယ်မ၏ အမှာစကားကိုကြားပြီး ယုံကြည်၍ထိုမိန်းမရှိရာသို့သွား၏။” || “ဂစေံကြေဲဗြဴဂှ် ကေတ်နၚ်ဏာလိက်ဗစန်သၟိၚ်အိုဿီုရ။” (ဇ—၃၄၃။အစွောံ။) = “ထိုကြိုးကြာငှက်မသည် မင်း၏အလုံးစုံသောစာလွှာတို့ကို (တမန်အဖြစ်) ပို့ဆောင်၏။” || “ဗစန်သၟိၚ်ဂှ် အမာတ်ပ္တီဣသိရဴဝွံရ။” (ဇ—၄၃၃။ အစွောံ။) = “မင်း၏မှာကြားချက်ကိုအမတ်သည် ရသေ့အား ဤသို့အသိပေး၏။”')
,(10169,3,4,'မှာကြားသည်။','“လ္ၚောဝ်ပ္တီအတိုၚ်ဂလာန်ဗညာနဲမဗစန်လဝ်ဂှ်ရ။” (အကြီုရာဇာဓိရာဇ်) = “ဗညားနွဲ့မှာကြားထားသည့် စကားအတိုင်း ရှိခိုးလျှောက်တင်၏။”')
,(10170,3,4,'၁။ (ထမင်းဟင်းစသည်) ကျက်အောင်ချက်သည်။','ဗစိန်ပုၚ် = ထမင်းကျက်အောင်ချက်သည်။ || “ဂြောဝ်မဗစိန်ပုၚ်သၟိၚ်။” (သၠပတ်ကုလဇာတ်) = “စားတော်ကဲသည် မင်းအတွက်ထမင်းကိုချက်၏။” || “ပိဏ္ဍပါတ်ဗျန်၊ ဗစိန်တုဲကီု၊ ကဵုဒါန်သီုပန်။” (လိက်ဝိဓူရ) || “ဟီုကဵုဗြဴဖျိန်၊ဗစိန်ဒးရး။” (လိက်မ္ၚဵုပိစှ်ောဒစာံ။ မာံထဝ်စိုပ်။) = “ကောင်းစွာကျက်ရန် မယားအားချက်စေ၏။”')
,(10170,3,4,'၂။ (အနာဒဏ်ရာစသည်) ကျက်စေသည်။','ဗစိန်သရ = အနာကိုကျက်စေသည်။ || ‘စိန်’ (ကြိ) လည်းရှု။')
,(10171,3,3,'ဆေးဆိုးထားသော။ ဖန်ရည်ဆိုးထားသော။ ဖန်ရည်စွန်းသော။','‘ယာတ်ဗစောန်မဖျောန်လဝ်သကောဝ်ဆု။’ (ဇ—၅၁၄။ အစွောံ။) = ‘သစ်ခေါက်ရည်/ဖန်ရည်ဆိုးထားသောအဝတ်သင်္ကန်း။’ || “သပိုၚ်လတက်ကေတ်ယာတ်ဗစောန် သီုဖအိုတ်ရ။” (ဇ—၄၈၅။ အစွောံ။) = “ဖန်ရည်စွန်းသောအဝတ်တို့ကို ဝတ်စေကုန်။” (ညောင်ကန်) || ‘ဖျောန်’ (ကြိ) လည်းရှု။')
,(10172,3,1,'အစပ်။ အဆက်အစပ်။ ဆက်စပ်ထားသောနေရာ။','“ခရာဒိယဇာတ်ဝွံဂှ် ဇက်နၚ်တုဲ ဗစပ်ပိုတ်ၜါဂှ်ဖျပ်ကၠေံတုဲ ကျာ်တြဲသၟဟ်ဇာတ်ရ။” (ဇ—၁၅။ အစွောံ။) = “ခရာဒိယဇာတ်တော်ကိုဆောင်တော်မူပြီးလျှင် အစပ်ပုဒ်နှစ်ခုကိုဆက်စပ်၍ (အနုသန္ဓေကိုစပ်၍) မြတ်စွာဘုရားသည်ဇာတ်ကိုပေါင်းတော်မူ၏။” || “ဇမၞော်ဒမာတ်ဂှ် ဂၠာဲၚဳရံၚ်ကၞပ်တၞိၚ်ဂှ် ဂၠာဲရံၚ်ဟွံညာတ်ဗစပ်ဍေံဂှ်တုဲ—။” (ဇ—၃၈၇။ အစွောံ။) = “ပန်းပဲသူကြီးသည် အပ်အိမ်ကိုကြည့်၍ ဆက်စပ်ထားသောစပ်ရာကို ရှာမတွေ့။”')
,(10172,3,4,'စေ့စပ်သည်။ ဆက်စပ်သည်။ တစ်သားတည်းဖြစ်စေသည်။','“ညံၚ်ဒြၚ်စိၚ်ညးသ္ကုတ်ကၠေံ ကဵုဂတေက်တုဲ ညံၚ်ပက္ကတိတၞဟ်ဂှ် ကဵုဖျပ်ဗစပ်ပၠန် ရဴမဟွံသၟဟ်ရထကီု။” (ဇ—၂၃၄။ အစွောံ။) (ဖျပ် = ဗစပ်) = “လွှဖြင့်ဖြတ်အပ်သောဆင်စွယ်ကို မူလပကတိအတိုင်းဖြစ်အောင် ပြန်ဆက်စပ်၍ မရနိုင်သကဲ့သို့။” || “ယွံမအံက်ပိုဲ၊ ကောန်ၚာ်မ္ဂးဂှ် မတုပ်တဴညံၚ်ရဴထမာဲတိကမၠေတ်ကီု မွဲဝါယာံဍေံပါ်ဒကးအာတုဲ ဗစပ်ဍေံဟွံစပ်ပၠန်ရ။” (ဇ—၃၁၂။ အစွောံ။) = “ခမည်းတော်၊ သူငယ်တို့မည်သည်ကား မြေအိုးနှင့်တူကုန်၏။ တခဏဖြင့်လျှင် ကွဲတတ်ကုန်၏။ ကွဲသောကာလမှစ၍ တဖန်စေ့စပ်ခြင်းငှာ မတတ်နိုင်ကုန်။” (ညောင်ကန်) || ‘ဒးဗစပ်’ (ကြိ) လည်းရှု။')
,(10173,3,4,'ပိတ်အောင်လုပ်သည်။ စေ့အောင်လုပ်သည်။','“ဒေါအ်လ္ပဆက်ဟီုဒၟံၚ်ရ၊ ဗစိပ်ထောံပါၚ်ဗှ်ေကဵုပြဟ်ရ။” = “ရပ်—ဆက်မပြောနေနှင့်တော့၊ နင့်ပါးစပ်ကို မြန်မြန်ပိတ်လိုက်ပါ။” || “ဗစိပ်ထောံတရၚ်ဂှ်ညိ။” = “တံခါးကို စေ့လိုက်ပါ။” || စိပ်’ (ကြိ) လည်းရှု။')
,(10174,3,4,'၁။ ရောက်အောင်ပို့သည်။','“လိက်ဏအ်မွဲတၞး ဗစိုပ်ကဵုသ္ၚိပိုဲညိ။” = “ဤစာတစောၚ်ကို ကျွန်တော်တို့အိမ်သို့ ရောက်အောင်ပို့ပေးပါ။”')
,(10174,3,4,'၂။ အပြီးသို့ရောက်စေသည်။ အပြီးသို့ ရောက်အောင်ဆောင်ရွက်သည်။','“ကိစ္စအဲနွံမွဲဂှ် မ၊ဗစိုပ်ကဵုညိရကောန်” သၟိၚ်ဂးကဵုကောန်တ္ၚေက်ဂှ်ရ။ (ဇ—၂၈၁။ အစွောံ။) = “ချစ်သား၊ ငါ့အရေးကိစ္စတစ်ခုရှိသည်ကို အပြီးသို့ရောက်အောင်ဆောင်ရွက်ပေးပါ။” || ‘စိုပ်’ (ကြိ) လည်းရှု။')
,(10175,3,1,'ကောက်စိုက်စူး။',NULL)
,(10176,3,4,'ဆန့်ထုတ်သည်။ စန့်သွားအောင်ဆွဲသည်။','‘ဇာ’ (ကြိ) လည်းရှု။ || “ယာတ်ဂှ် လ္ပတံၚ်ဗဇာထောံညိ။” = “ထိုအဝတ်ကို စန့်သွားအောင် မဆွဲဆန့်လိုက်ပါနှင့်။”')
,(10177,3,12,'(ကြိ) ပူဇော်သည်။','“အဲသကဵုကသာပ်ထဝ် ဗဇဴဗမၞးပန်လ္ၚီကသာပ်တုဲ—။” (ဇ—၅၁၃။အစွောံ။) = “ငါသည် ရွှေအသပြာပေး၍ ပုဏ္ဏားအား အသပြာလေးထောၚ်ကို ပူဇော်ပြီးလျှင်—။” || ‘ပူဇဴ’ နှင့်အတူတူ။')
,(10178,3,4,'ယဇ်ပူဇော်သည်။','“မွဲဟာန်ကေုာံသၟိၚ်ပိုဲ တၞဟ်နစံၚ်ဗဇဴယတ်ဂှ် တၠအဲဣသိကၠုၚ်ရ”ရဴဝွံအမာတ်ဂး။ (ဇ—၄၃၃။ အစွောံ။) = “ရှင်ရသေ့၊ အကျွန်ုပ်တို့၏မင်းနှင့်တကွ ယဇ်ပူဇော်ရန်လာပါလော့” ဟုအမတ်ဆို၏။ || “ဂွံစံၚ်ဗဇဴယတ်တုဲ အန္တရာဲဂွံဟဲရောၚ်” ဗမၞးဂးကဵုသၟိၚ်။ (ဇ—၄၁၈။ အစွောံ။) = “ယဇ်ပူဇော်ရလျှင် အန္တရာယ်ငြိမ်းပျောက်လတ္တံ့။” || ‘ပူဇဴယတ်’ နှင့်အတူတူ။')
,(10179,3,1,'ပူဇော်သက္ကာရ၊ လာဘ်လာဘ။',NULL)
,(10180,3,1,'ပူဇော်သက္ကာရ။','“သရာဲညးဂၟံၚ်အာဂန္တုကတၟိ မဂွံဗဇဴသကာမဂၠိုၚ်ဂှ်—။” (ဇ—၄၁၃။အစွောံ။) = “များစွာသောပူဇော်သက္ကာရကိုရသော ရောက်သစ်စသောသူရဲကောင်းများ။”')
,(10180,3,4,'ပူဇော်သက္ကာရပြုသည်။','‘ပူဇဴသကာ’ နှင့်အတူတူ။')
,(10181,3,1,'လက်ဖွဲ့။ အဆောင်။','“ဒက်ဗဇံသၠတာမ္ဂး ကလော်ဖေက်ရအဴ။” (ဇ—၅၁ဝ။ အစွောံ။) = “ထန်းရွက်လက်ဖွဲ့ကိုဆွဲလျှင် ဘီလူးတို့ကြောက်ကုန်၏။” || “(ကောန်ၚာ်လရိုအ်ဒၟံၚ်ဂှ်) ကဵုအ္စာတံစုတ်ဂဇမ် ထောံခဏီလေဝ် ဟွံသ္ၚိတ်။” (အကြီုရာဇာဓိရာဇ်) = “ငိုနေသောကလေးကို ဆရာတို့အား လက်ဖွဲ့အဆောင်ထည့်စေသော်လည်း ခေါစာပစ်စေသော်လည်း အငိုမတိတ်။”')
,(10182,3,4,'(မိုး၊ မျက်ရည်မိုး) ရွာသွန်းသည်။','“သၟဝ်ဇရာံဟေၚ်၊ ဒးမံၚ်သေၚ်ဟာ။ ဗြဲဂူဗဇး၊ဍေက်သီုညးၜါ။” (လိက်ကောန်သၟိၚ်ဝါရဝေါၚ်သ။ အစွောံ။) = “စပါးကျီအောက်­ နေရသဖြင့်မိုးရွာသွန်း၍ နှစ်ယောက်စလုံးစိုစွတ်ကုန်၏။” || “ဗြဲမွဲဝှ်ရော၊ သီုသြဗဇး။ ဂှ်လေအန်အာ၊ လေပ်ခြာဝၚ်သ္ဍး။ ဗြဲမတ်ဗဇး၊ ဝၚ်ဍးမာန်ရော။” (လိက်ဇမ္ဗူပတိ။ မာံဒေံဍောတ်။) = “တစ်ဝါတွင်းမှများစွာရွာသောမိုးသည်လည်း နည်းသေး၍ ခြားနိုင်ကွင်းနိုင်စဲနိုင်သေး၏၊ ရွာသွန်းသောမျက်ရည်မိုးသည်ကား ဘယ်သောအခါ ကွင်းနိုင်စဲနိုင်ပါမည်နည်း။” || ‘ပရာတ်ဗဇး’ (ကြိ) လည်းရှု။')
,(10183,3,4,'ခန်းခြောက်အောင်လုပ်သည်။','‘ဍုန်ပုၚ်ဗဇတ်ဍာ်။’ = ‘ထမင်းရေခန်းချက်သည်။’ || “(အစာသိုန်) ကဵုသာတ်ဗဇတ်ဍာ်ကၟာဂှ်။” (ဇ—မဟောဟ်သဓ။ အစွောံ။) = “သေနကအမတ်သည် ရေကန်ထဲမှရေကို ခန်းအောင်ထုတ်ပစ်စေ၏။”')
,(10184,3,4,'(ကြက်ငှက်တို့ကို) ခွပ်အောင်ရန်တိုက်ပေးသည်။ (လူအချင်းချင်း) ရန်တိုက်သည်။','ဗဇဵုစာၚ် = ကြက်တိုက်သည်။ || “မပ္တံဗဇဵုစာၚ်၊ ဗဒိပြေၚ်၊ ဗဒိဂၠဴ၊ ဗဒိဗ္ၜေအ်။” (ပြကိုဟ်ဒ္ဂေတ်ပဋိပတ်သာမဏဳ။ မာံရွှေငိုး။) = “ကြက်တိုက်ခြင်း၊ ကျွဲတိုက်ခြင်း၊ နွားတိုက်ခြင်း၊ ဆိတ်တိုက်ခြင်းစသော။” || ‘ပွမဟီုဂလာန်ဗဇဵုအကြာညး။’ (နဝကောဝါဒကထာ။ ပြကိုဟ်မန်ဍုၚ်သေံ။) = ‘လူနှစ်ဦးကြား­ ပြောဆိုရန်တိုက်ခြင်း။’ || ‘ဇဵု’ (ကြိ) လည်းရှု။')
,(10185,3,4,'ဆင်စီးသူရဲချင်း စစ်ထိုးသည်။','“အဲဒှ်ဨရာဇ်ဗှ်ေ ဗဇဵုစိၚ်ကဵုအဲမွဲကဵုမွဲ ဗှ်ေတြုံခိုဟ်အိုတ်ရ ဗှ်ေသ္ဂးဟာ” တၠညးရာဇာဓိရာဇ် ဂးကဵုမပေတ်နဲရ။ (အကြီုရာဇာဓိရာဇ်) = “နင်၏ရှင်ဘုရင်ဖြစ်သော ငါနှင့်တကွ တစ်ယောက်ချင်း ဆင်စီးချင်းစစ်ထိုးသည်မှာ နင့်ကိုယ်နင် ယောကျာ်းကောင်းဖြစ်သည်ဟု နင်မှတ်သလော” ဟုဘုရင်ရာဇာဓိရာဇ်က ဗျည်းနွဲ့အားဆို၏။ || ‘ဗျဵုစိၚ်’ (ကြိ) နှင့်အတူတူ။')
,(10186,3,4,'ကုန်းချောသည်။ ကုန်းတိုက်သည်။','ပွမဗဇဵုဗပါ်အကြာ = ကုန်းချောခြင်း။ကုန်းတိုက်ခြင်း။ ချောပစ်ခြင်း။ (ပါဠိ—ပေသုဏ)')
,(10187,3,4,'ရှူးတိုက်သည်။','ဗဇုဟ်ကဵုကၠဵု = ခွေးနှင့်ရှူးတိုက်သည်။ || “လၟတုန်အဵု၊ ဗဇုဟ်ကၠဵုသၟတ်။ ဂမှဳဂှ်အဵု၊ ဖေက်ကၠဵုလောန်ဗၞတ်။” (လိက်လၞုဟ်ပန်) = “မုဆိုးသည် ခွေးကိုရှူးတိုက်သည်ရှိသော် ထိုရဟန်းသည် ခွေးကို အလွန်အမင်းကြောက်ရွံ့၏။”')
,(10188,3,1,'၁။ ဗညားဘွဲ့ထူးဂုဏ်ထူး။ သူရဲကောင်းဘွဲ့။','‘ဗညာလ္ဂန်အိန်။’ = ‘ဗညားလဂွန်းအိန်။’')
,(10188,3,1,'၂။ မင်းသား။ မင်းပျို။','“ဆာန်လေၚ်လးဖဲ၊ ကြဴတဲဗညာ။ ဇြဟာန်စိုတ်ဇး၊ စိုတ်ဂတးအာ။” (လိက်သောဝိန်ဇဲယ။ မာံရောဂေါ။) = “ချစ်ကြင်နာမွေ့လျော်၍ ရောင့်ရဲပြီးနောက် မင်းသားသည် နောၚ်အချစ်စိတ်ပျောက်ပြယ်ကာ စိတ်ပြောင်းသွား၏။” || “သၟိၚ်ဗညာဗၠာဲ၊ နာဲပြာသာတ်ထဝ်။” (လိက်ခဂ္ဂေါဟတ္ထဇဲယကုမ္မာ)')
,(10189,3,4,'မျက်နှာရှုံ့မဲ့သည်။ မျက်နှာအမူအရာ ဖောက်ပြန်စေသည်။','“ယွံမၞးတံ၊ ကၞုဲဝွံကၠာတေံ ဍေံဗညံက်ဗညာတ်မုက်မတ်ကဵုပိုဲ ဍေံပစရဵုကဵုဓဝ်သဳလ လၟုဟ်ဝွံဍေံဟွံပ ဍေံမၞုံဒ္ဂေတ်ခိုဟ်အာ သိက်ဍေံဒှ်ရော။” (ဇ—၂၉၉။ အစွောံ။) = “အချင်းတို့၊ ဤမျောက်သည် ရှေး­ ငါတို့အား မျက်နှာကိုရှုံ့မဲ့ပြ၍ သီလတရားကို ပြက်ရယ်ပြုလေ့ရှိ၏။ ယခုမူကား ထိုသို့မပြုတော့၊ ကောင်းသောအကျင့်ရှိသည်ဖြစ်၏။ အသို့ဖြစ်လေသနည်း။”')
,(10190,3,1,'ရဲယိုပင်။ ရဲယိုသီး။',NULL)
,(10191,3,1,'‘ပဍာ်’ ရှု။',NULL)
,(10192,3,4,'ဂျၚ်ကဲ့သို့လည်ပတ်အောင်လုပ်သည်။','ဗဍိတ်ကရောဲ = ဂျၚ်လှည့်သည်။ || ‘ဍိတ်’ (ကြိ) လည်းရှု။')
,(10193,3,4,'ခြေချောင်း၊ လက်ချောင်း၊ ခြေဆစ်၊ လက်ဆစ်ကို ချိုးသောအခါကဲ့သို့ အသံမြည်သည်။ လက်ဖျောက်တီးသကဲ့သို့ အသံမြည်သည်။','“ယဝ်ခရိုဝ်အောန်တုဲ က္တဵုကီု ဂ္ဇအ်ကီု ဂတဴဂံါကွာ်ကီု ဆုတ်ကလေၚ်ကီု ကေံကီု ပၠးကီု ဇုတ်တံဂှ် ဗြုဗဍေပ်တဴရ။ ညံၚ်ညးမတက်ဗရုခဍတ်တဲကီု။” (ဓမ္မဒဳပနဳ။ မာံရွှေငိုး။)')
,(10194,3,4,'(မီးလောင်၍) အသားအရေဖောင်းကြွဖူးရောၚ်သည်။ မီးလောင်ဖုဖြစ်သည်။','“ကာလမဒှ်တေမဳတေံဝွံ ညးမသစံၜတ်ကဵုပၟတ်ရ။ ဇကုဗောဓိသတ်ဗဍအ်အာရ။” (ဇ—တေမဳ။ အစွောံ။) = “တေမိဘဝဖြစ်စဉ်က မီးဖြင့် သူတစ်ပါးတို့ စမ်းသပ်ကုန်၏။ ဘုရားလောင်း၏ကိုယ်မီးလောင်ဖုဖြစ်ရ၏။” || “နကြဳဇှ်ဂဥုဲ (လၟာဲ) ကီု နကြဳဇှ်မန် (လၟာဲ) ဂှ်ကီု ဒွံဒးဇကုဗောဓိသတ် (သၟိၚ်နာ်) တုဲ ဇကုဂှ် ဖဍအ်အာရ။” (ဇ—၅ဝ၆။ အစွောံ။) = “အလမ္ပာယ်၏ဆေးအစွမ်းဖြင့်၄င်း အလမ္ပာယ်၏မန္တရားအစွမ်းဖြင့်၄င်း ဘုရားလောင်းနဂါးမင်း၏ ကိုယ်ကိုထိ၍ ကိုယ်သည် မီးလောင်နာကဲ့သို့ ဖောင်းကြွဖူးရောၚ်လာ၏။”')
,(10195,3,4,'မီးလောင်ခံရ၍ အသားအရေဖောင်းကြွဖူးရောၚ်စုတ်ပြတ်သည်။ မီးလောင်နာဖြစ်သည်။ မီးလောင်ဖုဖြစ်သည်။',NULL)
,(10196,3,1,'အမြီး။','ဗတဇြုံ = မြွေအမြီး။ || ဗတက = ငါးအမြီး။')
,(10197,3,1,'(စေတီရှိ) ငှက်မြတ်နား။',NULL)
,(10198,3,1,'သားမြီး။','ပၞိက်ဗတသတ် = သားမြီးယပ်။ || ဇုက်ဗတသတ် = သားမြီးကြိုး။သားမြီးကျော့ကွင်းကြိုး။')
,(10199,3,1,'သဲ။','ဂၞဴဗတဳ = သဲသောင်ပြင်။ ကန္တာဗတဳ = သဲကန္တာရ။')
,(10200,3,4,'နင်း၍သွားသည်။ နင်းလျှောက်သည်။','“ပ္ဍဲကန္တာဗတဳဂှ် ဗတဳဂှ် စးဂမ္တဴတ္ၚဲတုဲ ညံၚ်ညးမဗတဳလဝ်လ္ၚပၟတ်ကီု တၞဟ်နသလိုန်အာဂှ် ဟွံသၟဟ်ရထရဟေၚ်။” (ဇ—၂။ အစွောံ။) = “ထိုသဲကန္တာရ­ သဲတို့သည် နေအပူရှိန်ထိ၍ မီးကျီးခဲပေါ်­ နင်းလျှောက်ရသကဲ့သို့ဖြစ်၍ နင်းလျှောက်သွားအံ့သောငှာ မတတ်နိုင်ကုန်။”')
,(10201,3,4,'ဂၚ်္ဂါဝါလု သဲစုမက။ (ပွင့်တော်မူပြီးသော ဘုရားပေါင်း၏အရေအတွက်။)','“ကျာ်လောန်စဴအာ ဗတဳဂၚ်ကျ။” (သၠပတ်အနမတဂ္ဂသံသာရကထာ) || “အဂ္ဂဗုဒ္ဓာ၊ နာဲသာလောက။လၟိဟ်ဂၠိုၚ်ဂၠၚ်၊ ဗတဳဂၚ်ကျ။” (လိက်ဂါထာလ္ၚောဝ်ကျာ်) = “လောကထွတ်ခေါၚ်ဗုဒ္ဓမြတ်စွာဘုရားတို့သည် ဂၚ်္ဂါဝါလုသဲစုမက အရေအတွက်များလှကုန်၏။”')
,(10202,3,4,'(ကြိုးစသည်ကို) လိမ်သည်။ ကျစ်သည်။ (= ၜန်၊ ပၠိမ်) (ပါဠိ—ဝဋ္ဋေတိ)',NULL)
,(10203,3,4,'လူးလိမ့်သည်။','“(သေံတံ) ဒးဇမောဝ်ဍာ် လောတ်လောဗတောအာ တဏီဍာ်ချိုတ်ဗွဲမဂၠိုၚ်။” (အကြီုရာဇာဓိရာဇ်) = “ရှမ်းတို့သည် ရေအယဉ်ကိုထိ၍ လူးလိမ့်မျောသွားရာ ရေနစ်၍ များစွာသေကုန်၏။”')
,(10204,3,4,'လူးလိမ့်သည်။ အလူးလူးအလိမ့်လိမ့်ဖြစ်သည်။','“မကၞုဟ်ဒးဍာ်ဇၟောဝ်ကြုၚ်ဂှ် ဇွောဝ်သ္ကာတ်လောန်တုဲ မကၞုဟ်ဒးလောဗ္တောဗ္တက်စှ်ေအာ—။” (ဇ—ဘူရိဒတ်။ အစွောံ။) = “ထိုလိပ်သည် အလွန်အားပြင်းစွာစီးသော မြစ်ရေအယဉ်ကို ထိသည်ရှိသော် အလူးလူးအလိမ့်လိမ့်ဖြင့် အောက်သို့ကျသွား၏။”')
,(10205,3,1,'ည။ ညဉ့်။',NULL)
,(10206,3,1,'ညသန်းခေါၚ်အချိန်။',NULL)
,(10207,3,1,'ညကြီးမင်းကြီး။ ညအချိန်မတော်။','“ဗတံဒမၠု၊ ကောဇုစိုပ်အဲ။ မူနူမကၠုၚ်၊ ဋ္ဌာန်ပ္ညုၚ်မပြဲ။” (လိက်သၟိၚ်ဇဲယဒတ္တ) = “ညအချိန်မတော် ကျွန်ုပ်ဆီ နောင်ကြီးရောက်လာသည်၊ အဘယ်အရပ်မှ လာပါသနည်း။”')
,(10208,3,1,'ပထမယံ၊ သန်းခေါင်ယံ၊ မိုးသောက်ယံ ဟူသောညဉ့်သုံးယံ။ (မွန် — ပထမယာံ၊မဇ္ဇျိမယာံ၊ ပစ္ဆိမယာံ။)','မှတ်ချက်။ မွန်ဘာသာတွင် “ပထမပယာံ၊ မဇ္ဇျိမပယာံ၊ ပစ္ဆိမပယာံ”ဟူ၍လည်းသုံးသည်။ || ‘ပယာံ’ လည်းရှု။')
,(10209,3,4,'ဦးစောက်ပြောင်းပြန်ဖြစ်သည်။','“(စိၚ်ကမၠက်မတ်ဂှ် နူက္ဍိုပ်ဒဵုဂှ်) ဂေတ်ဗတက်စှ်ေတုဲကအ်ကဝ်အာတုဲ ဒးပကာဂစိုတ်ရ။” (ဇ—၃၅၇။ အစွောံ။) = “ဆင်မျက်ကန်းသည် တောင်ထိပ်မှအောက်သို့ လည်၍ဇောက်ထိုးကျရာ လည်ကျိုး၍သေ၏။” || “(သၟိၚ်ဗပုန်ဂှ်) ရပ်စန်ဒက် (သၟိၚ်ဗာရာဏသဳ) တုဲ စုတ်ကဵုလယတုဲ က္ဍိုပ်ကဵုဗတက်ဖျေံဗွဲသၟဝ်တုဲ ကဵုကွက်လဝ် ပ္ဍဲပြဘိုက်တရၚ်ရ။” (ဇ—၃ဝ၃။ အစွောံ။) = “(ခိုးသူမင်းသည်) ဗာရာဏသီမင်းကိုဘမ်း၍ ဆိုင်း­ထည့်စေ၍ မြောက်တံခါးခုံ­ ဦးစောက်ဆွဲစေ၏။” (ညောင်ကန်)')
,(10210,3,4,'ကျွမ်းထိုးသည်။','ပွမဗတက်ဆေလုန် = ကျွမ်းထိုးခြင်း။ (ပါဠိ—မောက္ခစိက)')
,(10211,3,4,'ကျွမ်းထိုးသည်။',NULL)
,(10212,3,4,'ဦးခေါင်းစောက်ထိုးဖြစ်သည်။','“ကောန်ၚာ်ဂှ် ဒတုံစှ်ေနူတၞံဆု က္ဍိုပ်ဗတက်ဗတုန်စှ်ေအာရ။” = “ထိုကလေးသည် သစ်ပင်ပေါ်မှပြုတ်ကျရာ ဦးခေါင်းစောက်ထိုးကျသွားသည်။”')
,(10213,3,4,'လှဲလျက်ထားသည်။','‘ပတိက်’ (ကြိ) ရှု။')
,(10214,3,4,'၁။ တိုက်သည်။ တိုက်ခိုက်သည်။','ဗတိုက်ပၞာန် = စစ်တိုက်သည်။ || ဒမၠဗတိုက် =ဒမြတိုက်သည်။ || “(သၟိၚ်ကောသလရးဂှ်) ဗတိုက်ကေတ်ဍုၚ်ဗာရာဏသဳရ။” (ဇ—၃၅၁။ အစွောံ) = “ကောသလပြည်မင်းသည် ဗာရာဏသီပြည်ကို တိုက်ခိုက်သိမ်းပိုက်၏။”')
,(10214,3,4,'၂။ တိုက်တွန်းသည်။ နှိုးဆော်သည်။','“သၟတ်ဗြဴဝုတ်ဂှ် ဟိုတ်နူကဵုမိဟီုဗတိုက် ဂၠိုၚ်ၚ်ကဵုဝါတုဲ ဒးပ္တဴသ္ၚိကၟိန်ရ။”= “ထိုမိန်းမပျိုသည် မိခင်က ကြိမ်ဖန်များစွာ ပြောဆိုတိုက်တွန်းသဖြင့် အိမ်ထောင်ပြုလိုက်ရသည်။”')
,(10214,3,4,'၃။ ပြင်းစွာရိုက်ခတ်သည်။','“ယွံကောန်ပိုဲ၊ — မကၠေံစိုတ်ပ္ကီုလွဳ တၟအ်လးပ္ဍဲကတိုၚ်ဝွံဂှ်ဗတိုက်ဗပါ်ထောံကၠေံညိ။” (ဇ—၂။ အစွောံ။) = “အမောင်၊ သင်သည် လုံ့လပြုအားစိုက်၍တွင်းထဲရှိကျောက်ဖျာကို ကွဲအောင်ရိုက်ခတ်ပစ်လော့။”')
,(10215,3,4,'ဓါးပြတိုက်သည်။ ဒမြတိုက်သည်။','“ပွကမၠတ်ဒမၠဂှ် တၞဟ်နဗတိုက်စညးမကၠုၚ်ဂှ်ဗောဓိသတ်ညာတ်တုဲ—။” (ဇ—၇၉။ အစွောံ။) = “လာသောသူတို့အား ဓါးပြတိုက်ရန် ထိုခိုးသားဒမြတို့၏လုပ်ရပ်ကို ဘုရားလောင်းမြင်၍—။”')
,(10216,3,4,'စိတ်ကိုစေ့ဆော်သည်။','“ကုသဵုစိုတ်ဗတိုက်စိုတ်တုဲ ကျာ်ဇၞော်အစွောံခၞံဗဒှ်လဝ်လိက်ဓဝ်လောကုတ္တဵု နဘာသာမန် ဗွဲမဂၠိုၚ်ရ။” = “ဝေါဆရာတော်သည် ကောင်းသောကုသိုလ်စိတ်၏ စေ့ဆော်မှုကြောင့် မွန်ဘာသာဖြင့် လောကုတ္တရာစာပေများစွာကို ပြုစုစီရင်ထားခဲ့၏။” || “ဓဝ်ကရုဏာဗတိုက်စိုတ်တုဲ ညးကဵုဒါန်ကဵုရဲဂရၚ်စဂှ်ရ။” = “ကရုဏာတရားက စိတ်ကိုစေ့ဆော်၍ ထိုသူတောင်းစားအား သူပေးကမ်းစွန့်ကြဲလိုက်သည်။”')
,(10217,3,4,'တိုက်တွန်းသည်။ လှုံ့ဆော်သည်။',NULL)
,(10218,3,4,'နှိုးဆော်သည်။ တိုက်တွန်းသည်။',NULL)
,(10219,3,4,'တိုက်တွန်းသည်။ (ပါဠိ—ဣၚ်္ဃ)','“နအလဵုဇကုအဲ ညးမဟွံဒးဗတိုက်ဗတောန် အဲပ္တေဟ်ကံဖဵုပ္ဍဲဒါန်—။” (ဇ—၄၁၅။ အစွောံ။) = “ငါ့အလိုအလျောက် သူတစ်ပါးတို့တိုက်တွန်းစရာမလိုဘဲ ငါသည် အလှူဒါန­ ကံ၊ ကံ၏အကျိုးကို ယုံကြည်၏။”')
,(10220,3,1,'၁။ ပြတင်းပေါက်။','(မှတ်ချက်။ မြန်မာဝေါဟာရ ‘ပြတင်း’ သည် မွန်ဝေါဟာရ ‘ဗတၚ်’ မှ ဆင်းသက်လာသည်။)')
,(10220,3,1,'၂။ ကန့်ကလာပင်။',NULL)
,(10221,3,1,'လေသာပြတင်း။ လေသောက်တံခါး။ (ပါဠိ—ဝါတပါန)',NULL)
,(10222,3,16,'ဖြူသည်။—သော။','က္ဍိုၚ်ဗ္တာၚ် = ထီးဖြူ။ || လသိုန်ဗ္တာၚ်= ကြက်သွန်ဖြူ။ || စိၚ်ဗ္တာၚ် = ဆင်ဖြူ။ || ပ္ကဴဒကှ်ဗ္တာၚ် = ကြာဖြူ။ || “(သၟတ်ဗြဴဂှ် မၞုံသာ်ဇကုမဒးဗၞတ်) ဟွံဒျိုၚ်လောန် ဟွံဗ္တာၚ်လောန်။” (ဇ—၅၂၃။ အစွောံ။) = “ထိုသူငယ်မသည် မမည်းလွန်း မဖြူလွန်း အသားအရောင် အနေတော်ဖြစ်၏။”')
,(10223,3,16,'ဖြူဖွေးသည်။—သော။','“ဇကုဗောဓိသတ် (သၟိၚ်နာ်) မဗတာၚ်ဂွုညံၚ်ရဴဇမန်သြန်ကီု။” (ဇ—၅ဝ၆။ အစွောံ။) = “ဘုရားလောင်းနဂါးမင်း၏ကိုယ်သည် ငွေပန်းဆိုင်းကဲ့သို့ဖွေးဖွေးဖြူ၏။”')
,(10224,3,4,'တင်းနေအောင်ဆန့်သည်။','‘ပတေၚ်’ (ကြိ) ရှု။')
,(10225,3,1,'ပုတတ်။','“တတ်တောဗတတ် ဗကောတ်ဗလီု ဇီုဇြဟ်ဂၠာဲကဵုဒၞာဲ။” (သၠပတ်စန္ဒဝတဳ)')
,(10226,3,1,'တောဆိတ်။',NULL)
,(10227,3,16,'‘ပတုန်’ ရှု။',NULL)
,(10228,3,4,'သင်ကြားသည်။','ဗ္တောန်လိက် = စာသင်သည်။ || ဒလောအ်ဗ္တောန် = ပဲ့ပြင်ဆုံးမသည်။')
,(10228,3,1,'သင်ကြားခြင်း။ သင်ကြားချက်။','“အတိုၚ်ဗတောန်မာၚ်ဗၠာဲဂှ် ကၞိပဗက်ဗ္ဂဲဟွံဂွံစဖျုန်။” (သၠပတ်ရာဇာသာန်) = “လုလင်၏သင်ကြားချက်အတိုင်း ကြွက်လိုက်လုပ်၍ကြောင်သည် အသားကိုမစားရတော့။”')
,(10229,3,4,'သွန်သင်သည်။ ဆုံးမသည်။ သင်ကြားသည်။','“သၟိၚ်သာဓိနဂှ်တုန် — ဟီုဂးဗတောန်ဖျောန်လဝ် မၞိဟ်ပ္တုဲဒါန်တံဂှ်တုဲ စဴကၠုၚ်နန်ပြာသာဒ်ရ။” (ဇ—၄၉၄။ အစွောံ။) =“သာဓိနမင်းသည် အလှူပေးကုန်သောလူတို့အား ပြောဆိုဆုံးမ၍ နန်းပြာသာဒ်သို့ ပြန်လာ၏။” || “အမာတ်ဟီုဇီုဗ္တောန်ဖျောန်သီုသၟိၚ် သီုညးဂၟံၚ်လ္ၚီဂှ်ရ။” (ဇ—၃ဝ၁။ အစွောံ။) = “အမတ်သည်မင်းကို၄င်း သူရဲတစ်ထောင်တို့ကို၄င်း မှာကြားသွန်သင်၏။” || “ဗောဓိသတ်ဗ္တောန်ဖျောန်မၞိဟ်တံဂှ်တုဲ ကဵုတိုန်ပ္တီသၟိၚ်ရ။” (ဇ—မဟောဟ်သဓ။ အစွောံ။) = “ဘုရားလောင်းသည် ထိုလူတို့ကိုသင်ကြားပြီးလျှင် မင်းအား လျှောက်တင်စေ၏။”')
,(10230,3,1,'ယုန်။',NULL)
,(10231,3,1,'အဆီအနှစ်။','ဗတဝ်တိ၊ ရှ်ဗတဝ်တိ = မြေဆီမြေနှစ်။ မြေဆီသြဇာ။')
,(10232,3,1,'ပျားသလက်။ ပျားသကာ။ ပျားလပို့။ ပျားလပို့ခဲ။ (ပါဠိ—မဓုပဋလ)','“ဍေံပတုပ်ညံၚ်ရဴဗတဝ်သာဲဂှ် ပ္ဍဲတရဴညးမတွာ်တံဂှ် ကလော်တံဂှ် ဍေံစွံလဝ်ကီု။” (ဇ—၃၆၆။ အစွောံ။) =“ဘီလူးတို့သည် လူတို့ခရီး­ ပျားလပို့ခဲကဲ့သို့ ပြု၍ထား၏။” || “ကဵုပိုန်တုဲတုဲ နရမျှာၚ်ရဴရှ်ဗတဝ်သာဲဂှ် ကျာ်တြဲကမြဴအနုမောဒနာရ။” (ဇ—၂၆၄။ အစွောံ။) = “ဆွမ်းဘုဉ်းပေးတော်မူပြီးသော် ပျားသကာကဲ့သို့သော သာယာစွာသောအသံတော်ဖြင့် မြတ်စွာဘုရားသည် အနုမောဒနာပြုတော်မူ၏။” || “ယွံတၠညး၊ ဍုၚ်ဗာရာဏသဳတေံဂှ် ညံၚ်ဗတဝ်သာဲ မဟၟဲကဵုၝောံကီု သၟိၚ်ဂှ် ဍိုန်သမှ်သန်အဴ” အမာတ်ဂး။ (ဇ—၅၁။ အစွောံ။) = “အရှင်မင်းကြီး၊ ဗာရာဏသီပြည်မည်သည်ကား ပျားကောင်မရှိသော ပျားလဘို့နှင့်တူ၏။ မင်းသည်လည်း အလွန်နူးညံ့၏” ဟုအမတ်ဆို၏။ (ညောင်ကန်)')
,(10233,3,4,'၁။ (ဗုံး၊ ခဲယမ်းစသည်) ပေါက်ကွဲသည်။ ဖောက်ခွဲသည်။','ဗုၚ်ဗတိုဟ် =ဗုံးပေါက်ကွဲသည်။ || ဗတိုဟ်ဗုၚ် = ဗုံးဖောက်ခွဲသည်။')
,(10233,3,4,'၂။ (ဘောလုံး၊ ပူဖောင်း၊ ကားဘီးတာရာစသည်) ပေါက်သည်။ ကွဲသည်။','“ခဠာကွဳစက်ဗတိုဟ်အာ။” = “မော်တော်ကားဘီးပေါက်သွားသည်။”')
,(10233,3,4,'၃။ (ခြေ၊ လက်စသည်) ပွန်း၍ပေါက်သည်။','“ဒၞပ်ဂှ်ကြံၚ်မ္ၚိုဟ်လောန်ဂှ်ရ လိုန်ဒၞပ်ဂှ် ဇိုၚ်အဲဗတိုဟ်အာရ။” = “ထိုဖိနပ်သည် အလွန်မာကြမ်းသဖြင့် ထိုဖိနပ်ကိုစီး၍ ငါ့ခြေပေါက်သွားသည်။” || “ဂံါထဍိၚ်ဒး၊ သြဒကးပ္ညန်။ ဇိုၚ်ဗတိုဟ်ပါ်၊ လမာ်ဂၠိုၚ်တန်။” (လိက်ကောန်သၟိၚ်ပိ။ မာံခစုန်အံက်။) = “ခြေလှမ်းသည်ရှိသော် ခလုတ်တိုက်မိ၍ ခြေကွဲပေါက်ရှနာခြင်းများစွာဖြစ်၏။”')
,(10233,3,4,'၄။ ဒလဟောယိုစီးသည်။ ပန်းထွက်သည်။','“(နူပါၚ်သရဂှ်) ဆီဇွောဝ်ဗတိုဟ်တိတ်ကၠုၚ် ညံၚ်ဇမောဝ်ဍာ်ရ။” (ဇ—၅၁၄။ အစွောံ။) = “အနာအပေါက်ဝမှ သွေးတို့သည် ရေအယဉ်ကဲ့သို့ ဒလဟောယိုစီးထွက်လာ၏။” || “နူက္ဍိုပ်တၟအ်ဂှ် ဍာ်ဗတိုဟ်တိုန် ဒးဇကုသဗ္ဗညု။” (သၠပတ်ဂမ္စာဲဓါတ်) = “တောင်ထိပ်မှ ရေပန်းထွက်၍ မြတ်စွာဘုရားကိုယ်ကိုထိ၏။”')
,(10234,3,4,'မှီသည်။ မှီကပ်သည်။','“ဍေံဗ္ဒလဝ်ဗ္ဒၚ်တုဲ ဂ္ဇအ်ဒၟံၚ်ရ။” = “သူနံရံကိုမှီပြီး ထိုင်နေသည်။” || “ကမၠတ်ဂှ် အောပ်ဗ္ဒဒၟံၚ်ပ္ဍဲဒမၠုရ။” = “သူခိုးသည် အမှောင်ထဲတွင် ပုန်းအောင်းနေသည်။” || “(လဗိုတ်ကျာဇၞော်ဒြဟတ် ပိုက်ကၠုၚ်ကီုလေဝ် တၞံဆုပ္ဍဲဂြိုပ်တံဂှ်) ညးဂွံဗ္ဒကဵုအဲ အဲဂွံဗ္ဒကဵုညးတုဲ မမိက်ကဵုတၞံဆုမွဲတၞံကီု ဟွံသေၚ်ဂွံဒေါမ်ကဝ်အာဟေၚ်။” (ဇ—၇၄။ အစွောံ။) = “လေပြင်းမုန်တိုင်းတိုက်ခတ်သော်လည်း တော­ရှိသောသစ်ပင်တို့သည် အချင်းချင်းမှီရသည်ဖြစ်၍ တစ်ပင်မျှလည်း ကျိုးကျလဲပြိုခြင်းမရှိ။”')
,(10235,3,4,'မှီခိုသည်။','“ပိုဲဒးဗဒဗဒဲါဒၟံၚ်ညးရ။” = “ငါတို့သူ့ကိုမှီခိုနေရသည်။”')
,(10236,3,12,'(န) ပြဒါး။','‘ပြဒါ’ ရှု။')
,(10237,3,4,'(ဦးချိုရှိသောတိရစ္ဆာန်များ) တိုက်ခိုက်စေသည်။ ဝှေ့အောင်လုပ်သည်။','ဗဒိဂၠဴ = နွားတိုက်သည်။ || “မပ္တံဗဇဵုစာၚ်၊ ဗဒိပြေၚ်၊ ဗဒိဂၠဴ၊ ဗဒိဗ္ၜေအ်။” (ပြကိုဟ်ဒ္ဂေတ်ပဋိပတ်သာမဏဳ။ မာံရွှေငိုး။) = “ကြက်တိုက်ခြင်း၊ ကျွဲတိုက်ခြင်း၊ နွားတိုက်ခြင်း၊ ဆိတ်တိုက်ခြင်းစသော။” || ‘ဒိ’ (ကြိ) လည်းရှု။')
,(10238,3,4,'အတော်ကြီးသည်။','“ကောန်ဗှ်ေဗဒဳရဟာ။” = “နင့်ကလေးအတော်ကြီးပြီလား။”')
,(10238,3,3,'ကြီးသော။',NULL)
,(10239,3,1,'လူတကာတို့ ရိုသေလေးမြတ်ရသောမိန်းမ။ အရှင်သခင်မ။ မင်းသမီး။','“ပတ္တစာရဳ၊ ပဒေသဳဗြဴ။ ဒေါဝ်ဂြိုပ်အပၠဴ၊ ယာံတဴရေဝ်ရောတ်။” (လိက်ပတ္တစာရဳ။ နာဲထဝ်စိုပ်။) =“အရှင်သခင်မဖြစ်သော သူဋ္ဌေးသမီးပဋာစာရီသည် အပြောကျယ်သောတောလယ်­ ငိုကြွေးမြည်တမ်းနေရရှာ၏။”')
,(10240,3,4,'(မြင်းစီး၍) နှင်သည်။','ဗဒဴချေံ = မြင်းနှင်သည်။ || “သၟိၚ်မွဲဇကု ဍိုက်ချေံဗဒဴစဴကၠုၚ်—။” (ဇ—၄၁၅။ အစွောံ။) = “မင်းသည် တစ်ကိုယ်တည်း မြင်းစီးမြင်းနှင်၍ ပြန်လာ၏။”')
,(10241,3,1,'အိမ်ရှိအခန်း။','ဗဒမ်ဒုၚ်ကၟုဲ = ဧည့်ခန်း။ || ဗဒမ်ဟုံဍာ် = ရေချိုးခန်း။ || “ကောန်ဗြဴသေဋ္ဌဳမွဲ — တန်တဴဒၟံၚ်ပ္ဍဲဗဒမ်ကျာ်သြဳ ပ္ဍဲဂၠးလတူပြာသာဒ်ထပှ်ဘုံတေံရ။” (သုဓမ္မဒေသနာ။ ဂရိုက်သာံ။) = “တစ်ယောက်သောသူဋ္ဌေးသမီးသည် ပြာသာဒ်ခုနစ်ဘုံအထက် ကျက်သရေတိုက်ခန်းထဲ­ နေ၏။”')
,(10242,3,4,'၁။ မှီခိုသည်။ ခိုကိုးသည်။','ဗ္ဒးပိုန်ညး၊ ဗ္ဒးသမၞိၚ်ပိုန်ညး (ဇ—၈၃။ အစွောံ။) =သူတစ်ပါး၏အရိပ်အာဝါသကို မှီခိုသည်။ သူတစ်ပါး၏ဘုန်းရိပ်အောက်တွင် ခိုကိုးသည်။')
,(10242,3,4,'၂။ပုန်းကွယ်သည်။','“ယွံမၞးတံ၊ တြုံဂှ်မွဲ မဂ္ဇအ်ဗ္ဒးဒၟံၚ်ပ္ဍဲတရၚ်ဂှ် ညးဂှ်ရော။” (ဇ—၄၉၇။ အစွောံ။) = “အချင်းတို့၊ ထိုတံခါး­ ပုန်းကွယ်လျက်ထိုင်နေသော ထိုယောကျာ်းသည် အဘယ်သူနည်း။” || “လၟအာဂ္ဇအ်ဗဒးဒၟံၚ်တုဲ ရံၚ်သ္ၚဳဂၠိပ်တဴ ဗောဓိသတ်သၟိၚ်ၜိုပ်ထဝ်ရ။” (ဇ—၅၃၄။ အစွောံ။) = “မုဆိုးသည် ပုန်းကွယ်၍ထိုၚ်လျက် ဘုရားလောင်းရွှေဟင်္သာမင်းကို ကြည့်ရှုစုံစမ်း၏။” || “ပၞာန်ဗၟာပိဒပ် မကၞပ်ဗဒးမံၚ်ပ္ဍဲဂြိုပ်။” (အကြီုရာဇာဓိရာဇ်) = “ဗမာစစ်အင်အားသုံးတပ် လျှို့ဝှက်စွာတောထဲ­ ပုန်းကွယ်နေ၏။”')
,(10243,3,12,'(ကြိ) လက်ယာရစ်လှည့်သည်။','“ယွံဒေဝတဴ၊ သြဝ်တၠအဲသ္တိက်လှိၚ်ကဵုသိုက်ညိ” (ဗမၞးဂှ်) ဂးတုဲ လ္ၚောဝ်ပဒက်သိုန်ကဵုတၞံဆုဗပုၚ်ဂှ် ပိလတုန်တုဲ စဴအာသ္ၚိဇကုရ။ (ဇ—၃ဝ၇။ အစွောံ။) = “အို—ရုက္ခစိုဝ်းနတ်၊ အရှင်သည် ချမ်းသာစွာအိပ်စက်ရပါစေသတည်း”ဟုပုဏ္ဏားဆို၍ ပေါက်ပင်ကိုရှိခိုးလျက် လက်ယာရစ်သုံးကြိမ်လှည့်၍ မိမိအိမ်သို့ ပြန်သွား၏။ || “သၟိၚ်ဗာရာဏသဳ ဍိုက်လတူကွိုတ်စိၚ်တုဲ ပဒက်သိုန်ကဵုဍုၚ်တုဲ အာစိုပ်ပဒေသညးၜါဂှ်ရ။” (ဇ—၁၉၄။ အစွောံ။) = “ဗာရာဏသီမင်းသည် မြတ်သောဆင်ကျောက်ကုန်းထက်­စီးလျက် မြို့ကိုလကျာ်ရစ်လည်သည်ကိုပြု၍ ထိုအရပ်သို့ရောက်၏။” (ညောင်ကန်)')
,(10244,3,4,'လျှော့သည်။ ယုတ်လျော့စေသည်။','“ဟွံဗ္ဒေက်ဥဿဟ ဟွံရန်ကဵုလၟောၚ်ကာယ ပ္တိတ်လွဳရ။” (သုဓမ္မဒေသနာ။ ဂရိုက်သာံ။) = “လုံ့လဥဿဟကိုမလျှော့ မောပန်းခြင်းကို အလေးမမူဘဲ ဇွဲဝီရိယဖြင့် အားထုတ်၏။”')
,(10245,3,4,'ကိုယ်အဆင်းရဲခံသည်။ ကိုယ်အပင်ပန်းခံသည်။','“အဵုဂၠုစလံၚ်ၝောံကိုတ်မိဟိုဲ၊ ဂြိုပ် (၁၇) သၞာံ မိဗ္ဒေက်ကာယ ဆမိမယာံဂတေဝ်ဒၟံၚ်ကဵုနာဲ—။” (ဇ—တေမဳ။ အစွောံ။) = “အိုမယ်မယ့်စိန်ဖူး ချစ်သားဦး၊ (၁၇) နှစ်တာမျှ ကိုယ်အပင်ပန်းခံ၍ ချစ်သားနှင့် မယ်မယ်ငိုကြွေးနေခဲ့ရပါ၏။” || “ယွံကောန်အဲမဟောဟ်သဓ၊ ဒ္ဂေတ်ကောန်အဲ မဗ္ဒေက်ဇကုသာ်ဝွံဂှ် ပသပုန်ကဵုအဲဟွံမွဲရ” သၟိၚ်ဂး။ (ဇ—မဟောဟ်သဓ။ အစွောံ။) = “ချစ်သားမဟောသဓ၊ သၚ်ချစ်သားသည် (အိုးလုပ်သမားထံ) ကိုယ်ကိုအဆင်းရဲခံလျက်နေသည်မှာ ငါ့ကိုပုန်ကန်ရန် ကြံရွယ်ချက်မရှိပြီ” ဟုမင်းဆို၏။ || “ညးမွဲသၟိက်ဂ္ညိ၊ ပ္ကဴဝိမူလ။ လန်ဂေၚ်ဂၠာဲကိုပ်၊ လုံဂြိုပ်သ္ပာတ်သ္ဗ။ ပ္ကီုလွဳပရာ၊ ဗ္ဒေက်ဝေၚ်ကာယ။” (လိက်နဲယသမုဒ္ဒြဳ။ အစွောံ။) = “သဖန်းပန်းကိုပန်ချင်သောသူမိုက်သည် ကိုယ်အပင်ပန်းခံ၍ တောအလုံးနှံ့အောင် လှည့်လည်ရှာသော်လည်း ကိုယ်ပင်ပန်းရုံသာရှိမည်။” || “ကၠောန်ၜိုတ်ပဗၞိက်ဇိက်ဗ္ၚ ဗ္ဒေက်ကာယျတုဲရောၚ် မဂွံပတၠဒြပ်။” (လိက်ကာလထေရ်) = “ကုန်သွယ်လယ်ထွန် ကိုယ်အပင်ပန်းခံလုပ်ကိုင်ပြီးမှာသာ ဥစ္စာရှင်ဖြစ်ရ၏။”')
,(10246,3,4,'၁။ မထီမဲ့မြင်ပြုသည်။ မထီမဲ့မြင်သဘောထားသည်။ ကဲ့ရဲ့သည်။ (ပါဠိ—အဝမညတိ)','“ဗြဴမဟီုပဒေက်ဖျဝ်တြုံတၠသ္ၚိ။” (ဇ—၂၆၉။ အစွောံ။) = “လင်ယောကျ်ားအား မထီမဲ့မြင်ပြောဆိုသောမိန်းမ။” || “ညးမဒှ်သဟာဲမိတ်ဇကုတံဂှ် ဟွံဂွံဗဒေက်ဖျဝ်ရ။” (ဇ—၄၅၃။ အစွောံ။) = “မိမိ၏အဆွေခင်ပွန်းဖြစ်သောသူတို့အား မထီမဲ့မြင်မပြုရာ။” || “ညးမၞုံကဵုဂုန် မၞုံကဵုသဳလ မၞုံကဵုအယုက်တံဂှ်လေဝ် မှတ်ရှ်ေသှ်ေအဲပရဲ လ္ပဗ္ဒေက်ဖျဝ်ညိ။” (ဇ—၄၆၈။ အစွောံ။) = “ဂုဏ်ကျေးဇူးရှိကုန်သော သီလရှိကုန်သော အသက်ကြီးကုန်သောသူတို့အား အထူးရိုသေလေးစားပါ၊ မထီမဲ့မြင်မပြုနှင့်။” || “ပ္ဍဲရတ်ပိပြကာ မိမအစာတံဂှ်တုန်လေဝ် မရှာတ်လ္ပဗ္ဒေက်ဖျဝ်ညိ။” (ဇ—၄၉၈။ အစွောံ။) = “မြတ်သောမင်းကြီး၊ ရတနာသုံးပါး မိဘဆရာသမားတို့­ မထီမဲ့မြင်မပြုလင့်။” || “ဗွဲဓဝ်မာနဂှ် ဟွံဂွံဗဒေက်ဖျဝ်ညးသ္အာၚ်ရ။” (ဇ—၄၃၅။ အစွောံ။) = “မာန်မာနဖြင့် သူတစ်ပါးအား မထီမဲ့မြင်မပြု။” || “ပ္ဍဲမိမခံါသဳၜါဂှ် အဲဍိက်ဟွံဂွံရာန်သကိုတ်ဟွံဂွံဗ္ဒေက်ဖျဝ်မွဲလှ်ေအဴ။” (ဇ—၄၈၉။ အစွောံ။) = “မိဘယောက္ခမနှစ်ပါးတို့ကို အကျွန်ုပ်သည်မနှိပ်စက်စဖူး၊ မထီမဲ့မြင်မပြုစဖူး။” || “ယွံဂမှဳတံ၊ မၞးတံလ္ပဗ္ဒေက်ဖျဝ်ဂမှဳဂှ်ရ” ကျာ်တြဲဂး။ (ဇ—၅၃၂။ အစွောံ။) = “ရဟန်းတို့၊ ဤရဟန်းကို မကဲ့ရဲ့ကြကုန်လင့်။” (ညောင်ကန်)')
,(10246,3,4,'၂။ (မိမိကိုယ်ကို) နှိမ့်ချသည်။ မာန်မာနမထား။','“မှတ်ဗ္ဒေက်ဖျဝ်လဝ်ဇကုလၟိုန် ဖဍိုန်လဝ်စိုတ် ညံၚ်ယာတ်ဇၟိက်ဇိုၚ်။” (သၠပတ်အနမတဂ္ဂသံသာရကထာ) = “အစဉ်အမြဲ မိမိကိုယ်ကိုနှိမ့်ချ၍ ခြေသုတ်ဝတ်ကဲ့သို့ စိတ်ကိုပျော့ပျောင်းအောင်ထားပါ။”')
,(10247,3,4,'ဒုက္ခဖြစ်စေသည်။ ဆင်းရဲအောင်လုပ်သည်။','ပၠေၚ်ဗဒိုက် = ဖြုန်းတီး၍ ဆင်းရဲစေသည်။ || “ယွံအမာတ်၊ ဗဒိုက်ဇကုကၠာတုဲ ကြဴဂွံတသိုက်ရောၚ်။” (ဇ—မဟောဟ်သဓ။ အစွောံ) = “အိုအမတ်၊ မိမိကိုယ်ကို အလျင်အဆင်းရဲအပင်ပန်းခံ၍ နောင်ချမ်းသာကိုရလိမ့်မည်။” || ‘ဒိုက်’ (ကြိ) လည်းရှု။')
,(10248,3,4,'နားကြားဆင်းရဲစေသည်။ နားမခံသာအောင်ပြောသည်။','“ယွံစဴ၊ ဂလာန်မ္ဂးဒှ်ဍိက်ညးဂှ် စဴလ္ပဟီုဗဒိုက်ကတောဝ် က္တဵုဗဒှ်ယဲပူမှ်လဇုညိ။” (ဇ—ဝေသန္တဝ်။ အစွောံ။) = “မြေးတော်၊ သူ့ကျွန်ဖြစ်သည်ဆိုသောစကားကို ဘိုးတော်နားမခံသာအောင် စိတ်သောကဖြစ်အောင် မပြောပါလေနှင့်။ || “ထပှ်ဂိတုလ္ပာ် တွာ်တိတ်တွာ်စဴ ပဒိုက်တဴကာယ—။” (ဇ—ဝေသန္တဝ်။ အစွောံ။) = “ခုနစ်လခွဲတိုင်တိုင် ခြေကျင်သွားလိုက်ပြန်လိုက် ကိုယ်အပင်ပန်းအဆင်းရဲခံ၏။” || “ယွံနန္ဒ၊ လုကဴမွဲတွဵုကဝ် ယဝ်တၠအဲတွံဓဝ်သၟဟ်ရထမာန်မ္ဂး လုကဴမွဲတွဵုကဝ်အိုဿီု အဲကျာ်ပဒိုက်ကာယ နပွမဒတဴဒၟံၚ်တုဲ ကလၚ်ပၚ်မိၚ်ဓဝ်ကီုရ”ကျာ်တြဲဂး။ (ဓမ္မဒဳပနဳ။ မာံရွှေငိုး။) = “အိုနန္ဒ၊ အကယ်၍သင်သည် တစ်ကမ္ဘာတိုင်အောင် တရားဟောနိုင်ငြားအံ့၊ ငါဘုရားသည် တစ်ကမ္ဘာပတ်လုံး မတ်တတ်ရပ်လျက် ကိုယ်အပင်ပန်းအဆင်းရဲခံခြင်းဖြင့် တရားနာနိုင်၏။”')
,(10249,3,4,'စိတ်ဆင်းရဲအောင်လုပ်သည်။','“ကောန်သမၠီုဗဒိုက်စိုတ်မိမလၟိုန်ရ။” = “မိုက်မဲသောသားသမီးသည် မိဘစိတ်ဆင်းရဲအောင် အမြဲတမ်းလုပ်သည်။” || ‘ဒိုက်စိုတ်’ (ကြိ) လည်းရှု။')
,(10250,3,1,'နံရံ။ အကာအရံ။',NULL)
,(10251,3,3,'ကြီးသော။ ကျယ်သော။ ကားသော။','မၞုံစၚာၚ်ဂၞိၚ်မဗ္ဒါၚ် = ကားသောတင်ပါးရှိသည်။ (ပါဠိ—ကဋိပုထုလက)')
,(10252,3,1,'မြစ်ပျဉ်း။ (ပါဠိ—ပါရောဟ)',NULL)
,(10253,3,4,'ကမ်းပေးသည်။','“သမ္ဘာသေဋ္ဌဳ ဗဒုၚ်ကဵုထး (ကုဗောဓိသတ်ညးဗၞိက်လီု) ။” (ဇ—၃။အစွောံ။) = “သူဋ္ဌေးမယားသည် ဘုရားလောင်းရွဲကုန်သည်အား ထိုခွက်ကိုကမ်းပေး၏။” || “လိက်ဝွံညာတ်တုဲ တီရအဴ” ဂးတုဲ ဗဒုၚ်ကဵုလိက်ရ။ (ဇ—၁၂၅။ အစွောံ။) = “ဤစာကိုမြင်ပြီးလျှင် (အကြောင်းကို) သိရပါမည်” ဟုဆို၍ စာကိုကမ်းပေး၏။ || “ထဝ်လ္ၚီဂှ် ကောန်သေဋ္ဌဳဗဒုၚ်ကဵု ဗြဴသရာဲဍုၚ်ဂှ်ရ။” (ဇ—၃၁၈။ အစွောံ။) = “ထိုသူဋ္ဌေးသားသည် ဥစ္စာတစ်ထောင်ကို ပြည့်တန်ဆာမအား ကမ်းပေး၏။” || “ပ္ကဴထဝ်ဗဒုၚ်ကဵုကောန်သၟတ်ရ။” (ဇ—ဝေသန္တဝ်။ အစွောံ။) =“ရွှေပန်းကုံးကို သမီးငယ်အား ကမ်းပေး၏။”')
,(10254,3,4,'နောက်ကွယ်တွင် အတင်းပြောသည်။','“လ္ပဗဒုတ်ဗဒီုဟီုတဴပရောညးတၞဟ်ညိ။” =“သူများအကြောင်းကို နောက်ကွယ်တွင် အတင်းမပြောပါနှင့်”')
,(10255,3,4,'၁။ ကွယ်သည်။ ကွယ်ပျောက်သည်။','“ဒေဝတဴဗြဴဂှ် (ဟီုလှေအ်လှန်ခမဳဂှ်ဟွံဂွံတုဲ) ဗ္ဒန်အာကၠေံရ။” (ဇ—၁၆၇။ အစွောံ။) = “ထိုနတ်သမီးသည် ရဟန်းအား မြှူဆွယ်ဖြားယောင်း ခြင်းငှာ မတတ်နိုသဖြင့် ကွယ်လေ၏။” || “သၟိၚ်တ္ၚဲဗ္ဒန်အာ စိုပ်ကာလဗ္တမ်တုဲ သၟိၚ်ဂိတုမံက်တိုန်ပၠန်ရ။” = “နေမင်းကွယ်၍ ညအချိန်ရောက်သောအခါ လမင်းထွက်ပေါ်လာပြန်၏။” || “ပ္ဍဲဋ္ဌာန်မဗ္ဒန်ဂှ် အောပ်ဒၟံၚ်ရ။” (ဇ—၃၈၄။ အစွောံ။) = “ကွယ်ရာအရပ်­ ပုန်းနေ၏။”')
,(10255,3,4,'၂။ ဖုံးကွယ်သည်။ ကွယ်ဝှက်သည်။','“ဂၞကျာ်ဝွံ ဒုဟ်ဇကုဗ္ဒန်လဝ်တုဲ ဒုဟ်အဲရောၚ် ဗဒှ်စုတ်သွံ။” (ဇ—၁၂ဝ။အစွောံ။) = “ဤမိဖုယားသည် မိမိအပြစ်ကို ဖုံးကွယ်ထားပြီးလျှင် ငါ့အပြစ်ဖြစ်လေအောင် ပြုဘိ၏။”')
,(10256,3,4,'ပျောက်ကွယ်သည်။',NULL)
,(10257,3,4,'မြှုပ်နှံသည်။ ဖုံးကွယ်သည်။',NULL)
,(10258,3,4,'ဖုံးကွယ်သည်၊ ကွယ်ဝှက်သည်။',NULL)
,(10259,3,4,'ပုန်းကွယ်သည်။ ပုန်းအောင်းသည်။',NULL)
,(10260,3,1,'ကျည်ကွယ်ရာ။ သေနတ်ကျည်မသင့်ရာ အကွယ်အကာ။',NULL)
,(10261,3,4,'ပုန်းကွယ်သည်။ ပုန်းအောင်းသည်။','ဋ္ဌာန်မဗ္ဒန်ဗ္ဒး = ဖုံးကွယ်ရာအရပ်။လူသူမမြင်သောအရပ်။ || “ယွံရသိ၊ ကၠိက်တံဝွံဂှ် ပ္ဍဲကၠာတေံဍေံညာတ်အဲတုဲ ဍေံဖေက်တဴအဲရောၚ်။ဍေံဂၠာဲဒမံၚ်ဗ္ဒန်ဗ္ဒးရောၚ်” ကၠဂှ်ဂး။ (ဇ—၂၈၃။ အစွောံ။) = “အိုရသေ့၊ ဤဝက်တို့သည် ရှေး­ငါ့ကိုမြင်၍ ငါ့ကိုကြောက်သောကြောင့် ပုန်းအောင်းရာကို ရှာကုန်၏” ဟုကျားဆို၏။ || “ဗြဴအဆေဝ်သွဝ်ဂှ် ဍေံဗဒန်ဗဒးဒၟံၚ် ဝုတ်ဒိုဟ်ဣသိဂှ်တုဲ ဍေံမိၚ်ဣသိဂှ်ယာံ—။” (ဇ—၅၂၃။ အစွောံ။) =“ထိုနတ်သမီးသည် ရသေ့အနီးဝန်းကျင်­ ပုန်းကွယ်လျက်နေ၍ ထိုရသေ့ငိုကြွေးသည်ကို ကြား၏။” || “ညာတ်သၟတ်ဗြဴဒိဋ္ဌမၚ်္ဂလိကာဂှ်တုဲ ပ္ဍဲဋ္ဌာန်မဗၠးဒုဟ်ဗ္ဒန်ဗ္ဒးညိဂှ် မာတၚ်္ဂပဏ္ဍိတဂှ် အာဂ္ဇအ်တန်ဒၟံၚ်ရ။” (ဇ—၄၉၇။ အစွောံ။) = “ဒိဋ္ဌမၚ်္ဂလိကာအမျိုးသမီးကိုမြင်၍ မာတၚ်္ဂပဏ္ဍိတသည်တင့်အပ်ဖုံးကွယ်သောအရပ်­ သွား၍ထိုင်နေ၏။”')
,(10262,3,1,'မျက်ကွယ်ရာ။ မမြင်ရသောနေရာ။','“သၟိၚ်အာစိုပ်ဒၞာဲဗ္ဒန်မတ်ဗောဓိသတ်ဗက် တိၚိတ်ဖျေံဏာဂျိုၚ်ၚ်—။” (ဇ—၃၅၈။ အစွောံ။) = “မင်းသည် ဘုရားလောင်း၏ မျက်ကွယ်ရာရောက်သည်နှင့် မင်းအား အရှင်လတ်လတ် မြေမျိုသွား၏။” || “ဗ္ဒန်မတ်တြုံရ၊ တလသ္ၚိက္ဍၚ်။ ဟွံကၠတ်စိုတ်ရ၊ သစ္စဗိုန်မၚ်။ ဟွံဒေပ်စိုတ်ၜါ၊ မိတ်ၜါလၚ်လၚ်။ ဝွံဝတ်ဗြဴမွဲ၊ ကျာ်တြဲတွံဆင်။” (လိက်ကာကဒိပ္ပ။ မဟာကြၚ်။) = “လင်ယောကျ်ား၏မျက်ကွယ်­ လၚ်ကိုမလှည့်စား မြဲစွာသစ္စာစောင့်၍စိတ်နှစ်မျိုးမထား လၚ်နှစ်ယောက်မထားခြင်းသည် မယားဝတ်တစ်ပါးဟု မြတ်စွာဘုရားဟောတော်မူ၏။”')
,(10262,3,4,'မျက်စိမှကွယ်သည်။ မြင်ကွင်းမှကွယ်သည်။','ဋ္ဌာန်မဗ္ဒန်မတ် = မျက်ကွယ်ရာအရပ်။ || (သၟတ်ဗြဴသုန္ဓရဳဂှ် “အဲတိတ်သတိက် ဂကောံသမဏဂေါတမ ပ္ဍဲဂန္ဓကုဋဳတေံရောၚ်” (ဍေံ) ဂးတုဲ ကာလဗ္ဒန်မတ်ညးတုဲ ဍေံသ္အာတိက်ပ္ဍဲဘာတဳတံတေံရ။ (ဇ—၂၈၅။ အစွောံ။) = (သုန္ဒရီမည်သောအမျိုးသမီးသည် “ရဟန်းဂေါတမနှင့်အတူ ဂန္ဓကုဋဳ­ ငါသွားအိပ်မည်” ဟုဆိုပြီးလျှင်လူများ၏မြင်ကွင်းမှ ကွယ်သောအခါ တိတ္ထိတို့၏ကျောင်း­ သွား၍အိပ်၏။')
,(10263,3,4,'ဝပ်သည်။ (ကိုယ်ကို ကျုံ့ကျုံ့မှောက်လျက် အခင်းပြၚ်နှင့် နီးကပ်အောင်ပြုသည်။)','“ပ္ဍဲလတူတၟံလးဂှ် ကျာံဂှ် ကၠုၚ်သ္တိက်ဗဒပ်ဒၟံၚ်ရ။” (ဇ—၅၇။ အစွောံ။) = “မိကျောင်းသည်ကျောက်ဖျာပေါ်­ လာ၍ဝပ်လျက်နေ၏။”')
,(10264,3,1,'တည်းခိုရန်နေရာ။ စခန်း။','“လအ်သ္ဂောံစိုပ်ဗဒိုပ်ဍုၚ်ကွာန်—” (ဇ—၂၅၅။ အစွောံ။) = “စခန်းမြို့ရွာသို့ မရောက်သေးမီ—။” || ဖျေံဗဒိုပ်၊ ပဗ္ဒိုပ် = တည်းခိုသည်။ စခန်းချသည်။ || “ပိုဲအာစိုပ်ကွာန်ဂှ် ပိုဲပဗ္ဒိုပ်ပ္ဍဲဘာလကျာ်ရ။” = “ကျွန်တော်တို့သည် ထိုရွာသို့သွားရောက်၍ ဘုန်းကြီးကျောင်းတွင် စခန်းချတည်းခိုသည်။” || “မိကြၚ်ကၠုၚ်စိုပ်၊ ဗဒိုပ်ဝွံဆာဲ။” (လိက်ဗြရတ်ဣဏၚ်ကၚ်ရဳ) = “သင်ခြေဦးတည့်ရာသွား၍ ဤစခန်းသာသို့ ရောက်လာ၏။” || “တံဇိုၚ်မှာဲယ၊ သၟိက်ပဗဒိုပ်။” (လိက်သောဝိန်ဇဲယ။ မာံရောဂေါ။) = “ချစ်သူ့ခြေရင်းဝယ် စခန်းချနားခိုလိုပါ၏။”')
,(10265,3,1,'ကျား၊ ဆင်တို့၏အရပ်။ တောကြီး။ (ကဗျာသုံး)',NULL)
,(10266,3,1,'စစ်စခန်း။ တပ်စခန်း။',NULL)
,(10267,3,1,'ကျွဲတို့ကျက်စားရာနေရာ။',NULL)
,(10268,3,1,'ဒုက္ခသည်ကယ်ဆယ်ရေးစခန်း။',NULL)
,(10269,3,4,'အနီး­ကပ်သည်။ ကပ်ထားသည်။','“(နကဵုစိၚ်) ပြာပ်အာဗွဲမတူရူကဵုနန်ပြာသာဒ်ဂှ်တုဲ သီုကဵုဇကုမတဍေက်တဴဂှ် ဗ္ဒေံလုပ်ဒၟံၚ်ပ္ဍဲဗတၚ်နန်ဂှ်တုဲ တန်ဒၟံၚ်ရ။” (ဇ—၂၆၂။ အစွောံ။) =“သွား၍ မင်းအိမ်­ ကောင်းကင်ပြင်သို့ မျက်နှာပြုရာအရပ်­ ဆင်ကို နံရံမကိုမှီ၍ လေသွန်တံခါး၏အနီး­ (ကပ်၍) မိုဃ်းစွတ်လျက်လျှင်တည်၏။” (ညောင်ကန်) || “ဒြပ်ထဝ်သြန်ညးရန်တၟံကဵုဇကု ညးကၠုၚ်စွံပ္တန်ဗဒေမ်လဝ်ဇရေၚ်ဇကု။” (သြဝါဒဒဳပနဳ) = “သူတစ်ပါး၏ရွှေငွေဥစ္စာကို မိမိအားရည်ရွယ်၍ မိမိအနား­ လာ၍ကပ်ထား၏။” || “(ကောန်ပ္ဍဲဂဝ်ဂၞဴဂှ်) စၞတရေံ၊ ဗဒေံဂ္ဇအ်သာ။စၞတမှိ၊ မိပအဟာ။ မဒးယဵုလဝ်၊ သက်သ္ဍဝ်ကၠာ။” (လိက်တရဳသံသာ) = “အမိဝမ်းအိမ်ရှိကလေးသည် အစာဟောင်း­ ကပ်ထိုၚ်လျက် အစာသစ်ကို အာဟာရအဖြစ် မိခင်စားသောအခါ မလွဲမသွေရွက်ထားရ၏။” || “တလာဂှ်ဒွံဇမောဝ် ဟဳဗဒေမ်လောပ်ကၠုၚ်။” (အာန်ဇုနာန်) = “ထိုခေါင်းသည် ရေစီးကြောင်းကို ထိ၍မျောကာ နီးကပ်ဝၚ်လာ၏။” || “ထၟာဲတဲဗ္ဒေမ်ဟေၚ်၊ ပ္ဍဲဇြေၚ်ကြပ်ညး။” (လိက်ကာကဒိပ္ပ။ မဟာကြၚ်။) = “ထွေးခံကို သူ့အနီး­ ကပ်ထား၏။”')
,(10270,3,4,'လှဲချသည်။ လဲကျစေသည်။','“တၞံဆုမဂၠိုၚ် ကောံဒၟံၚ်ပ္ဍဲဂြိုပ်ဂှ် ကျာဗ္ဒောံကၠေံဟွံမာန်ဟေၚ်။” (ဇ—၇၄။ အစွောံ။) = “တော­စုစည်းနေသော များစွာသောသစ်ပင်ကို လေသည်တိုက်လှဲပစ်ခြင်းငှာ မတတ်နိုင်။”')
,(10271,3,4,'ဖြိုလှဲသည်။ ချိုးဖျက်သည်။','“တၟံသိနနရာတ်တၠအစောံဂှ် ၜိုန်ဒှ်ကီုကျာလေၚ်ကဝ် ပိုက်ကသဳဗ္ဒောံပြောံကၠေံတုဲ ဆုသၟာဲသၟဇွဂၞိၚ်အပြောံတံဂှ် မူရဴအလေဝ် ကျာလေၚ်ကဝ် မသ္ပစမိုက်နွံတုန်ရော။” (ဇ—၂၅၁။ အစွောံ။) = “အစွမ်းကြီးစွာသော မြင်းမိုရ်တောင်ကိုပင်လည်း ကမ္ဘာဖျက်လေသည် တိုက်လှုပ်လှဲဖြိုပစ်နိုင်သေး၏။ ဆွေးမြည့်လေပြီးသော အချည်းနှီးသောသစ်ပုပ်မျှကို ကမ္ဘာဖျက်လေသည် အဘယ်မူ၍ ကြောက်ရွံ့ခန့်ညားခြင်း ပြုပါငြားအံ့နည်း။”')
,(10272,3,4,'၁။ ထားသည်။ (ပါဠိ—ဋ္ဌပေတိ)',NULL)
,(10272,3,4,'၂။ ရပ်နားသည်။','“ထာန်ဝွံ တန်ဗဒီုက္ၜၚ်ရ”ဂးတုဲ ဒၞာဲဂှ် ဣတံထောံတၟံဂြဲလဝ်က္ၜၚ်ရ။ (ရာဇာထ္ၜုတ်) = “ဤအရပ်­ သင်္ဘောရပ်နားသင့်၏”ဟု ထိုနေရာ­ သူတို့ကျောက်ဆူးချ၍ သင်္ဘောကိုဆွဲထား၏။ || “ဂလာတံအာစိုပ်ထာန်မွဲ ဗဒီုလဝ်ဖံၚ်ဒၞာဲဂှ်တုဲ ဍေံတံစၚ်ခြၚ်တဴရ။” (ရာဇာထ္ၜုတ်) = “ကုလားတို့သည် တစ်ခုသောနေရာအရပ်သို့ရောက်သောအခါ ထိုနေရာတွင် ဖောၚ်ကိုရပ်နား၍ တိုင်ပင်ကြကုန်၏။”')
,(10273,3,6,'အနီးအနား။','ဗဒဲါဘာ = ကျောင်းအနီးအနား။ || “သ္ၚိညးနွံဗ္ဒာဲသ္ၚိပိုဲရ။” = “သူ၏အိမ်သည် ကျွန်တော်တို့အိမ်၏ အနီးအနားတွင်ရှိသည်။”')
,(10273,3,4,'၁။ မှီသည်။','“ညးဂ္ဇအ်ဗဒဲါလဝ်ကဵုဗဒၚ်ရ။” = “နံရံကိုမှီပြီး သူထိုင်နေသည်။”')
,(10273,3,4,'၂။ မှီခိုသည်။ အမှီပြုသည်။','“ဗဒဲါကဵုညးတုဲ ပိုဲကၠောန်ကလောန်ရ။” = “သူ့ကိုအမှီပြု၍ ကျွန်တော်တို့အလုပ်လုပ်ကြသည်။”')
,(10273,3,4,'၃။ (နတ်စသည်) ဝင်ကပ်သည်။ ဝင်ခိုသည်။','“ဒေဝတဴဆုဂှ် လုပ်ဗဒါယ်ပ္ဍဲဇကုပြောဟိတ်ဂှ်။” (ဇ—၅၂ဝ။ အစွောံ။) = “ထိုသစ်ပင်စောင့်နတ်သည် ပုရောဟိတ်၏ကိုယ်­ ဝင်ကပ်၏။”')
,(10274,3,4,'မိုးကာသည်။ ဆောင်းသည်။ ကာရံသည်။','“ဗောဓိသတ်သၠိုက်ဒၞပ်ထဝ် ဗဒဝ်က္ဍိုၚ်ဗ္တာၚ်တုဲ—။” (ဇ—၃၉၈။ အစွောံ။) = “ဘုရားလောင်းသည် ရွှေခြေနင်းကိုစီး၍ ထီးဖြူကိုဆောင်း၍—။” || “လတူပြာသာဒ်ထဝ် သီုမဗ္ဒဝ်လဝ်က္ဍိုၚ်ဗ္တာၚ်ဂှ်။” (အကြီုရာဇာဓိရာဇ်) = “ထီးဖြူမိုးထားသော ရွှေပြာသာဒ်ပေါ်­။”')
,(10275,3,11,'(န) ဆီးသီး။ ဆီးပၚ်။ (ပါဠိ—ဗဒရ)',NULL)
,(10276,3,4,'ဖြစ်အောင်လုပ်သည်။ ဖြစ်စေသည်။','“ညာတ်ဒြပ်ညး လ္ပဗဒှ်လောဘညိ။” = “သူတစ်ပါး၏ဥစ္စာကိုမြင်ပြီး လောဘမဖြစ်စေနှင့်။” || “သဘၚ်ကျာ်ကွာန်ပိုဲ ညးဗဒှ်ပေဲါရ။” = “ငါတို့ရွာဘုရားပွဲတော်တွင် ပွဲသဘင်ကျင်းပသည်။” || ဗဒှ်ဍုၚ် = မြို့တည်သည်။ || ဗဒှ်ကွာန် = ရွာတည်သည်။ || ဗဒှ်ပၟတ် = မီးမွှေးသည်။ မီးညှိသည်။ || ဗဒှ်လဝ်ဝေါဟာမန် = မန်ဘာသာပြန်ဆိုထားသည်။ || ဗဒှ်ကောန် = သားမွေးသည်။ || ‘ဒှ်’ (ကြိ) လည်းရှု။')
,(10277,3,4,'အိမ်ထောင်ပြုသည်။',NULL)
,(10278,3,4,'ရုပ်အသွင်ဖန်ဆင်းသည်။','“နကွတ်ပၠေၚ်ရုပ်ဗဒှ်ရုပ်ဂှ်လေဝ် ဍေံလေပ်ကီု။” (ဇ—၅၁ဝ။အစွောံ။) = “နဂိုရုပ်အသွင်ကိုဖျောက်ခြင်း အခြားရုပ်အသွင်ကိုဖန်ဆင်းခြင်း အတတ်ကိုလည်းသူတတ်၏။” || ‘ပၠေၚ်ရုပ်’ (ကြိ) လည်းရှု။')
,(10279,3,4,'စကားလုပ်သည်။ အဟုတ်အမှန်မဟုတ်သောစကားကို ဖန်တီးပြောဆိုသည်။',NULL)
,(10280,3,4,'အတာချသည်။ အပြစ်ကိုလွှဲချသည်။','“ပွဗှ်ေပလဝ်ဗၠေတ်ဂှ် ဒှ်ဒုဟ်ဗှ်ေရ။ လ္ပဗဒုဟ်စုတ်အဲညိ။” = “နၚ်ပြုမှားခြင်းသည် နင့်အပြစ်သာဖြစ်သည်။ ငါ့အတာမချနှင့်။”')
,(10281,3,4,'၁။ ရပ်စေသည်။ ရပ်တန့်စေသည်။','“စိုပ်ဓဝ်ကဵုတၞံကြုက်ဂှ်တုဲ — ဗဒိုအ်လဝ်ဂၠုၚ်—။” (ဇ—၄ဝ၇။ အစွောံ။) = “သရက်ပင်နှင့်တည့်တည့်သို့ ရောက်သောအခါ လှေကိုရပ်ထားစေ၏။”')
,(10281,3,4,'၂။ တားသည်။','“မဂဳၜါဂှ် သေက်ဇဵုဒၟံၚ်ညးသ္ကအ် ညးမွဲရောဗဒေါအ်ဟွံမာန်ရ။” = “အဖွားကြီးနှစ်ယောက်တို့ ရန်ဖြစ်နေကြရာ (ရန်ပွဲရပ်သွားအောင်) မည်သူမျှမတားနိုင်ပါ။” || “သၟိၚ်ဂစိုတ်ကော်မ္ဂး ဒးချိုတ်ဖအိုတ်ရ။ မူရဴညးမွဲဗဒိုအ်သၟိၚ်ယီုမာန်ရော။” = “သေမင်းခေါ်လျှင် အားလုံးသေရမည်ချည်းဖြစ်သည်။ သေမင်းကို မည်သူတားနိုင်မည်နည်း။” || ‘ဒေါအ်’။‘ဒိုအ်’ (ကြိ) လည်းရှု။')
,(10282,3,4,'တားမြစ်သည်။','“(မၚ်ရာဲကယျဝ်ဆွာဂှ်) သၟိၚ်ဗိုလ်နာဲဒပ်တံ ဂွံဗဒေါအ်ဗဒဝ်ဂၠိုၚ်ကဵုဝါတုဲရ။ ဂှ်လေဝ်ဟွံကလၚ်—။” (အကြီုရာဇာဓိရာဇ်) = “မင်းရဲကျော်စွာသည်ဗိုလ်မင်းတပ်မင်းများက အကြိမ်ကြိမ်တားမြစ်သော်လည်း နားမထောင်။” || ‘ဒေါအ်ဒဝ်။ဒိုအ်ဒဝ်’ (ကြိ) လည်းရှု။')
,(10283,3,4,'‘ပဓဝ်’ ရှု။',NULL)
,(10284,3,1,'၁။ စက်ဝိုင်း။ အဝန်း။ အဝန်းအဝိုင်း။ (ပါဠိ—မဏ္ဍလ) ။','ဗၞဳစက်ဂိတု = လဝန်း။ || ဗၞဳလျးဂိတု = လထီးဆောင်းရောင်ခြည်ဝန်း။ || “ဗနဳစက်ဂိတုမရာၚ်ဆာဲတဴဂှ်—။” (ဇ—၄ဝ၆။ အစွောံ။) = “တင့်တယ်လှစွာသောလဝန်းသည်—။” || ‘ဒေါဝ်ဗၞဳပုရိသာတ်ပန်’ = ‘ပရိသတ်လေးပါး၏အလယ်’ || ‘ပ္ဍဲဒေါဝ်ဗနဳမၞိဟ်ဂမၠိုၚ်။’ (ဇ—၁၂၂။ အစွောံ။) = ‘လူပုံအလယ်­။’ || “သၟာလက်ဗန်တံဂှ် သာၚ်သောဝ်မှောဝ်ဇာတုဲ လုပ်ကၠုၚ်ပ္ဍဲဗနဳပေဲါဂှ်ရ။” (ဇ—၄၅၄။ အစွောံ။) = “နပန်းသမားတို့သည် ကြွေးကြော်ကြုံးဝါး လက်ပမ်းပေါက်ခတ်ကုန်လျက် ပွဲလယ်သို့ဝၚ်လာကုန်၏။” || “ဗောဓိသတ်လေဝ် ပ္ဍဲမတ်ၜါဂှ် မၞုံကဵုလျုၚ်မသုန်သာ် မၞုံကဵုဗၞဳပိသာ် — မသ္အးသ္ဇုၚ်လောန်ဗၞတ် ပြာကတ်တဴရ။” (ဇ—၃၈၉။ အစွောံ။) = “ဘုရားလောင်း၏မျက်စိတို့သည်ကား ငါးပါးသောကြည်ခြင်းရှိ၏။ သုံးပါးသောအဝန်းရှိ၏။ စင်ကြယ်ကုန်သည်ဖြစ်၍ ထင်ကုန်၏။” (ညောင်ကန်) || “(တြုံဂှ်တၞဟ်နကၠတ်ယာတ်ချီုသၟိၚ်) သ္ဂာဗ္တံ ကၠေံလမျီုတိတ်နူဍုၚ် စိုပ်တၞံယာတ်သာ်ချီုသၟိၚ်ရ။ လိုန်ကၠေံဒပ်တုဲ လုပ်အာပ္ဍဲဗၞဳ—။” (ဇ—၁၄၇။ အစွောံ။) = “(ထိုယောကျာ်းသည် မင်း၏ဝတ်ပန်းကိုခိုးရန်) ညဉ့်အဘို့­ အသက်ကိုစွန့်၍ မြို့မှထွက်၍ မင်း၏ဝတ်ပန်းခင်းသို့သွား၍ စောင်းရန်းကိုနင်း၍ယာတွင်းသို့ဝၚ်၏။” (ညောင်ကန်) (ယာတွင်း = ယာခင်းအဝန်းအဝိုင်းအတွင်း)')
,(10284,3,1,'၂။ အသိုင်းအဝိုင်း။','“ပ္ဍဲခေတ်တ္ၚဲဏအ် ပ္ဍဲဗနဳခမဳကီု ပ္ဍဲဗနဳခရှ်ကီု ညးမဆိုက်ဗ္ဒက်လိက်ပတ်မန် နွံအောန်လောန်ရ။” = “ယနေ့ခေတ်တွင် ရဟန်းအသိုင်းအဝိုင်း­၄င်း၊ လူအသိုင်းအဝိုင်း­၄င်း၊ မွန်စာပေကို ကျွမ်းကျင်သူများ အလွန်ရှားပါးသည်။”')
,(10285,3,4,'၁။ (အလင်းရောင်) ထုတ်လွှတ်သည်။','“ပ္ဍဲပြဝိုန်ဂန္ဓကုဋဳဂှ် သီုမဗၞဳတဴလျးတရဴသာ်ဂှ် (ကျာ်တြဲ) ဂ္ဇအ်တန်ဒၟံၚ်ရ။” (ဇ—၃၂ဝ။ အစွောံ) = “(မြတ်စွာဘုရားသည်) ဂန္ဓကုဋိပရိဝုဏ်­ ခြောက်သွယ်သော ရောင်ခြည်တော်တို့ကိုလွှတ်လျက် နေတော်မူ၏။” (ညောင်ကန်) || “ပိုဲဍိက်မိၚ်ပရိုၚ်ဣသိဂှ် ညံၚ်ရဴဂိတုတ္ၚဲတိုန် ဗၞဳတဴလျးကီုရအဴ။” (ဇ—၅၂၂။ အစွောံ။) = “အလင်းရောင် ခြည်တို့ကို ထုတ်လွှတ်လျက် တက်လာသောနေလတို့ကဲ့သို့ ရသေ့၏သတင်းကို တပည့်တော်တို့ကြားရပါ၏။”')
,(10285,3,4,'၂။ (နေ၊ လ) တက်လာသည်။ ပေါ်ထွက်သည်။','“ကာလဂှ် တ္ၚဲလေဝ်ဗနဳတိုန်။” (ပြကိုဟ်ဂဝမ္ပတိ) = “ထိုအခါ နေမင်းလည်း ပေါ်ထွက်လာ၏။”')
,(10286,3,1,'(= အဝေါန်မတ်) မျက်စိအဝန်း။ မျက်ဝန်း။ (ပါဠိ—အက္ခိမဏ္ဍလ)','“သီုညးၜါဝွံ ဇိုၚ်ခဍဴတုပ်၊ တဲတဍိုဟ် (တုပ်) ၊ ဗနဳမတ်မဟွံသၟဟ်တုပ်—။” (ဇ—၇၈။ အစွောံ။) = “ဤသူနှစ်ဦးတို့သည် ခြေခွင်ခြင်းလည်းတူ၏။ လက်ကောက်ခြင်းလည်းတူ၏။ မညီသောမျက်ဝန်းရှိခြင်းလည်းတူ၏၊ (ဝါ) စွေသောမျက်စိရှိခြင်းလည်းတူ၏။”')
,(10287,3,1,'သာသနာတော်ထွန်းကားပြန့်ပွားရာအရပ်။ သာသနာတော်၏အချက်အချာအရပ်။',NULL)
,(10288,3,1,'အိမ်ခန်းကြီး။',NULL)
,(10289,3,1,'စက်ဝန်း။ အဝန်း။ အဝန်းအဝိုင်း။','ဗနဳအဝေါန်စက်ဂိတု = လမင်း၏အဝန်း။ လဝန်း။')
,(10290,3,1,'စူး။ (= သပူ) (ပါဠိ—ဝေဓက)',NULL)
,(10291,3,5,'အစဉ်။ အမြဲ။','“ဍေံအာဝေၚ်ဒၟံၚ်သ္ၚိဂှ် ဗနိပ်ရ။” = “ထိုအိမ်သို့ သူအမြဲသွားလည်နေသည်။” || “သွဝ်တရဴဘုံ၊ မၞုံထာန်သုခါ။ စသိုၚ်ပိုန်ဒိပ်၊ ဗၞိပ်ဟွံခြာ။” (လိက်ပဒုမဝတဳ) =“သုခရိပ်မြုံ ခြောက်ဘုံနတ်ပြည်­ နတ်စည်းစိမ်ကို အမြဲအစဉ်မခြား စံစားရ၏။”')
,(10291,3,1,'၁။ ဝန်းကျင်။ အတောအတွင်း။ (အချိန်နှင့်နေရာအတွက်သုံးသည်။)','“ဟးလဂေါဝ်ဒိပ်၊ ဗနိပ်ဇိုၚ်ဂြိုပ်။” (လိက်ရတနပဇ္ဇောတ) = “တောစပ်ဝန်းကျင်ရှိ နတ်­ဖြစ်သကဲ့သို့သောလျှိုမြောင်။” || “ဗှ်ဗနုဟ်ဒွိၚ်၊ စိုတ်လွိၚ်ချဳ။ ဗနိပ်သန်ဇျာ၊ အရီုကျာၜဳ။” (လိက်ပဒုမဝတဳ) = “အောက်မေ့စိုးရိမ်ကာ စိတ်လှုပ်ရှားရင်း ဆည်းဆာချိန်အတောအတွင်း­ ပင်လယ်လေတိုက်ခတ်၏။”')
,(10291,3,1,'၂။ ဦးတည်ရှေးရှုရာ။ အထောက်အပံ့။ (?)','“ယြဴညးမွဲ၊ ပ္ဍဲလိုက်ဝွံကၠာ၊ ထာန်ပဏ္ဍိတ္တာ၊ ဂွံအာသိပ်ဂၠိပ်။ ဂလာန်ဇိပ်ဂၠိပ်၊ ဗနိပ်နဳဗာန်။ မၚ်သဳပ္တုဲဒါန်၊ ဂလာန်တအ်ဂှ်။ ဂၠာဲဟီုလဖှ်၊ ဂွံမိၚ်ရှ်ဓဝ်။ ၜးအဿဘဴ၊ ဂွံစဴစိုပ်သွဝ်။” (လိက်မ္ၚဵုပိစှ်ောဒစာံ။ မာံထဝ်စိုပ်။) = “ဤလောက­ အကြင်သူသည် ပညာရှိကိုမှီဝဲ၍နိဗ္ဗာန်သို့ရှေးရှုရာ အထောက်အပံ့ဖြစ်စေသော သီလစောင့်ခြင်း ဒါနပြုခြင်းနှင့်စပ်သော သိမ်မွေ့သောတရားစကားကို ကြားနာရသည်ရှိသော် သေလွန်သော် နတ်ပြည်သို့ လားရောက်ရ၏။”')
,(10292,3,1,'(ဆင်ဖမ်းရန်) ထောင်ချောက်။ (?)','“ဗဝ်မှဝ်လွိၚ်သၠကၞာၚ်တုဲ နူဂြိုပ်ဇၟူစဴစိုပ်ဗနေပ်ပးသရတ် ကမာၚ်ထဍိၚ်ဇိုၚ်။” (သၠပတ်သတိပထာန်) = “ဆင်ဖမ်းသမားသည် သစ်ရွက်သစ်ကိုင်းကို ဝှေ့ယမ်းသည်ရှိသော် တောမှဆင်ပြောင်သည် ထောင်ချောက်သို့ရောက်၍ ကျော့ကွင်းစွပ်မိလျက် ခြေက ထူးကွင်းကိုတိုက်မိ၏။”')
,(10293,3,3,'ယုတ်မာကောက်ကျစ်သော။ လိမ်လည်ကောက်ကျစ်သော။','‘မၞိဟ်ဗနေံစၞာဲ’ (ဇ—၅၂ဝ။ အစွောံ။) = ‘လိမ်လည်ကောက်ကျစ်သောလူ။’')
,(10293,3,4,'လိမ်လည်ကောက်ကျစ်သည်။ လိမ်လည်လှည့်စားသည်။','“ဍေံဟွံဂွံဝေၚ်ပး၊ စာၚ်၊ ခတ်၊ ဍေံဟွံဂွံဗၞေံစၞာဲ ဍေံဟွံဂွံဒှ်လဗၚ်သူရာ၊ လဗၚ်ဗြဴ—။” (ဇ—၅၂၁။ အစွောံ) = “ကြွေအန်လောင်းကစားခြင်း၊ ကြက်တိုက်ခြင်းကိုသူမပြု၊ လိမ်လည်လှည့်စားခြင်းကို သူမပြု၊ သေရည်အရက်ဖြင့်၄င်း မိန်းမတို့ဖြင့်၄င်း အပျော်ကြူးသူမဖြစ်။” || “ယြဴပူဂဵုမွဲ ဗနီစၞာဲကဵုညးဂှ်ဒှ်တုဲ ပူဂဵုဂှ် ဒှ်မၞိဟ်က္ဍိုပ်ကဗတဇြုံရ။” (ပေါရဏာံပေါရဒံါ။ အစွောံ။) = “အကြင်ပုဂ္ဂိုလ်သည် သူတစ်ပါးအား လိမ်လည်ကောက်ကျစ်ပါက ထိုပုဂ္ဂိုလ်သည် ငါးခေါင်းမြွေအမြီးရှိသော လူစားမျိုးပင်တည်း။” || “ပဇနော်ရော၊ လောဘဒေါသ။ဗနေံစနာဲ၊ ဥပဲါကြံကြ။” (လိက်သောဝိန်ဇဲယ။ မာံရောဂေါ။) = “လောဘဒေါသကြီး၍ လိမ်လည်ကောက်ကျစ် ဥပါယ်မာယာများ၏။”')
,(10294,3,3,'လိမ်လည်တတ်သော။ ကောက်ကျစ်ယုတ်မာသော။','‘ဗနေံစၞာဲ’နှင့်အတူတူ။ || “(မဟောဟ်သဓဝွံ) ဟွံဂးဇၞော်သွတ်ယုတ်ပြဲ ဂၠာဲလဖှ်ဆာန်ညး ဟွံဒေပ်စိုတ်ဗၞေံဗ္တက်ဟွံကၠတ်စ။” (ဇ—မဟောဟ်သဓ။ အစွောံ။) = “မဟောသဓသည် ကြီးငယ်ယုတ်မြတ်မဟူ သူတစ်ပါးတို့အား ချစ်ခင်တတ်၍ ယုတ်မာလိမ်လည်တတ်သောစိတ်မရှိ၊ သူတစ်ပါးဥစ္စာကိုလည်း မခိုးမယူ။”')
,(10295,3,3,'(မျက်စိ) မှုန်သော။',NULL)
,(10296,3,4,'ရောၚ်စေသည်။ ဖောင်းစေသည်။','“(ဒြာဲဂှ်ဒးဒၞက်လၟတုဲ ပညံၚ်မချိုတ်တုဲ) လတာ်လေဝ်တလေအ်ပ္တိတ်ကၠေံရ။ ဂၞဴလေဝ် ဗပုကၠေံရ။” (ဇ—၁၆။ အစွောံ။) = “ထိုသမင်သည် မုဆိုးကျော့ကွင်း­မိ၍ သေဟန်ေဆောင်၍ လျှာကိုလည်း တွဲလျားထုတ်ထား၏။ ဝမ်းကိုလည်း ဖူးဖူးရောၚ်စေ၏။”')
,(10297,3,4,'ကွဲအောင်လုပ်သည်။ ခွဲသည်။','“နကဵုလေံဒုဲပသဲဂှ် မၚ်ဗၠာဲတက်ဗပါ်ကၠေံတၟအ်ဂှ် ၜါလပါ်ဟေၚ်။” (ဇ—၂။ အစွောံ။) = “ထိုလုလင်သည် သံတူဖြင့် ကျောက်ဖျာကို နှစ်ပိုင်းကွဲအောင်ရိုက်ခွဲပစ်လိုက်၏။” || “(ကောန်သၟိၚ်) ဂိုၚ်ကေတ်ဗဗေၚ် နူတဲပစ္စေဂဗုတ်တုဲ ဇီုဗပါက်ထောံကၠေံရ။” (ဇ—၂၂ဝ။ အစွောံ။) = “မင်းသားသည် အရှင်ပစ္စေကဗုဒ္ဓာ၏လက်မှ သပိတ်ကိုယူပြီးလျှင်ဆောင့်ခွဲပစ်လိုက်၏။”')
,(10298,3,1,'ချောက်ကမ်းပါးပြတ်။ တောင်ကမ်းပါးပြတ်။','“စိၚ်ဝွံဂှ် ပ္ဍဲတ္ၚဲဝွံဟေၚ် အဲပ္တုံဖျေံပ္ဍဲဗပါ်တၟံတုဲ အဲဂစိုတ်ကၠေံရ” သၟိၚ်ချပ်။ (ဇ—၁၂၂။ အစွောံ။) = “ယနေ့လျှင် ထိုဆင်ကိုတောင်ကမ်းပါးပြတ်­ကျစေ၍ အသက်ကုန်ခြင်းသို့ ရောက်စေအံ့” ဟုကြံ၍—။ (ညောင်ကန်) || “ဗွဲမတူရူကဵုဗပါ်ဇြဟ်ဂှ် ကဵုအ္စာစိၚ်ဍိုက်ဒၟံၚ်စိၚ်တုဲ—။” (ဇ—၁၂၂။ အစွောံ။) = “ဆင်ကို တောင်ကမ်းပါးပြတ်သို့ ရှေ့ရှုပြုစေ၍—။” (ညောင်ကန်) || “ဗပါ်ဇြဟ်မၞုံလျိုဟ် (၆ဝ) သာံဒံၚ်။” (ဇ—၅၁၆။အစွောံ။) = “အတောင်ခြောက်ဆယ်ရှိသော နရက်ချောက်ကမ်းပါးပြတ်။” (ညောင်ကန်)')
,(10299,3,4,'သေသည်။','“ဆိုက်ကဵုဗပါ်သ္ကန် ညန်ကဵုဂစိုတ်။” = “သေအံ့ဆဲဆဲဖြစ်သည်။” || ‘ပါ်ကန်’ (ကြိ) လည်းရှု။')
,(10300,3,4,'သံဃာသင်းခွဲသည်။','“ဒေဝဒတ်ဗပါ်သၚ်။” (ဇ—၁၁။ အစွောံ။) = “ဒေဝဒတ်သံဃာသင်းခွဲသည်။” || “ပွမဗပါ်သၚ်ဂှ် လုပ်လၟိဟ်ပဥ္စနန္တရိက်ကံရ။” = “သံဃာသင်းခွဲခြင်းသည်ပဥ္စာနန္တရိကံ­ ပါဝၚ်သည်။” (ပါဠိ—သံဃဘေဒ)')
,(10301,3,4,'၁။ (ရန်သူ့ဗိုလ်စုကို) ဖျက်သည်။ (ရန်သူ့စစ်ကို) ဖြိုခွဲသည်။ ကစဉ့်ကလျားထွက်ပြေးစေသည်။','“(ညးဂၟံၚ်ချေံဂှ်) ဗဵုပၞာန်ညးမွဲကိုပ်ကၠာဂှ် ဗပေက်ကၠေံ ဇကုဨကရာတ်ဂှ် ရပ်ကေတ်ဂျိုၚ်ဂျိုၚ်တုဲ—။” (ဇ—၂၃။ အစွောံ။) = “(မြင်းစီးသူရဲသည်) ရှေးဦးစွာသော (ရန်သူ့) ဗိုလ်စုကိုဖျက်၍တယောက်သောမင်းကို အရှင်ဖမ်း၍—။” (ညောင်ကန်) || “(သၟိၚ်ကောသလရးမဇက်ကၠုၚ်ပၞာန်ဂှ်) ပိုဲဍိက်ဇက်ဒစးအာတုဲ ဗတိုက်ဗပေက်ကၠေံရ” ညးဂၟံၚ်တံဂှ်ဂး။ (ဇ—၅၁။ အစွောံ။) = “စစ်ချီ၍လာသော ကောသလပြည်မင်းကို အကျွန်ုပ်တို့သည် ဆီးကြိုချီတက်၍ တိုက်ခိုက်ထွက်ပြေးစေကုန်အံ့” ဟုသူရဲတို့ဆိုကုန်၏။ || “ပ္ဍဲတ္ၚဲဝွံ ဗပေက်ကၠေံဍုၚ်တက္ကသဵုဝွံရ” ဂးတုဲ ဗဵုပၞာန်ညးဗာရာဏသဳ ကြီုဂအတ်တဴအိုတ်ရ။ (ဇ—၂၂၉။ အစွောံ။) = “ဤယနေ့­ တက္ကသိုလ်ပြည်ကို ဖြိုခွဲပစ်အံ့” ဟု ဗာရာဏသီစစ်သည်ဗိုလ်ပါတို့သည် ကြုံးဝါးကြကုန်၏။ || “အဲကၠုၚ်ရီုဗပေက်ကဵုသတြုအနုဒိုဟ်ဂွံဇၞး။” (အကြီုရာဇာဓိရာဇ်) = “ငါလာကူတိုက်ထုတ်ပေး၍ အရပ်ရပ်မှရန်သူတို့ကိုအောင်ပွဲရ၏။” || “(ကျာ်တြဲ) မဂွံဗပေက်ကၠေံ ပၞာန်မာ (၅) ပြကာ။” (ဓမ္မဒဳပနဳ။ မာံရွှေငိုး။) =“မြတ်စွာဘုရားသည် ငါးပါးကုန်သောမာရ်စစ်ကို ဖြိုခွင်းအောင်နိုၚ်တော်မူ၏။”')
,(10301,3,4,'၂။ သွားစေသည်။ ထွက်ခွါစေသည်။','“(ဗောဓိသတ်သၟိၚ်ကၞိတုန်) အာသဳကၠဳကၠဵုဂှ် ဗပေက်ဖျဴကၠေံညးဂတတုဲဇကုမွဲစဴကြဴညးရ။” (ဇ—၁၂၈။ အစွောံ။) = “ဘုရားလောင်းကြွက်မင်းသည် ထိုမြေခွေးကို ခစားရန်သွားပြီးနောက် နောက်လိုက်ကြွက်အပေါင်းတို့ကို ရှေ့မှဦးစွာပြန်စေ၍ မိမိသည် နောက်ဆုံးမှပြန်၏။” || ‘ပေက်’ (ကြိ) လည်းရှု။')
,(10302,3,4,'(ရန်သူ့စစ်ကို) ဖြိုခွဲသည်။ ကျိုးပျက်ထွက်ပြေးစေသည်။','“ယွံနာဲဂၟံၚ်ချေံ၊ ဝေၚ်အာနူအဲသိန္ဓဴတုဲဂှ် ချေံမွဲသ္အာၚ် သ္ဂောံဗပေက်ပကဝ်ကၠေံ ပၞာန်ဇၞော်မွဲဒပ်ပၠန်ဂှ် ဟွံမွဲရ။” ချေံသိန္ဓဴဂး။ (ဇ—၂၃။ အစွောံ။) = “အိုမြင်းစီးသူရဲ၊ ငါသိန္ဓောမြင်းကိုထား၍ ငါမှတစ်ပါးသော နောက်စစ်တပ်ကြီးတစ်တပ်ကို ဖြိုခွဲဖျက်ဆီးနိုင်မည့် အခြားမြင်းမည်သည်မရှိ” ဟုသိန္ဓောမြင်းဆို၏။ || “(သၟိၚ်စိၚ်) လနိန်ဗပေက်ပ္ကဝ်ကၠေံ ဗဵုပၞာန်ညးတုဲ—။” (ဇ—၁၅၆။ အစွောံ။) = “ဆင်မင်းသည်ရန်သူ့ဗိုလ်ထုကို နှိမ်နင်းဖြိုခွဲထွက်ပြေးစေသည်။”')
,(10303,3,4,'ထွက်ပြေးစေသည်။','“စိၚ်ဂှ် — သ္ကုတ်ကၠေံဇုက်ဂွာံတုဲ ဗပေက်ဗ္ဒဴကၠေံညးဂမၠိုၚ်—။” (ဇ—၁ဝ၅။ အစွောံ။) = “ထိုဆင်သည် ဆင်ချည်ကြိုးကိုဖြတ်၍ လူတို့ကိုထွက်ပြေးစေ၏။”')
,(10304,3,1,'ပေါက်ပင်။','“တၞံဗပုၚ်ဂှ် တလတံညာတ်ကီုဟာ။” (ဇ—၂၄၈။ အစွောံ။) = “ပေါက်ပင်ကို သင်တို့မြင်ဖူးကုန်သလော။” || “ဗောဓိသတ်ဒှ်ဒေဝတဴတၞံဆုဗပုၚ်—။” (ဇ—၃ဝ၇။ အစွောံ။) = “ဘုရားလောင်းသည် — ပေါက်ပင်စောင့်ရုက္ခစိုဝ်းနတ်ဖြစ်၏။” (ညောင်ကန်)')
,(10305,3,4,'၁။ စနည်းနာသည်။ ထောက်လှမ်းသည်။ စုံစမ်းသည်။','“ပ္ဍဲပယာံဂၠုညိ သၟိၚ်ကဵုမၞိဟ်တိတ်ဗပုၚ်ဗပၚ်ကၞပ်ကလၚ် ပ္ဍဲဘာတံဂှ်ရ။” (ဇ—၂၈၃။ အစွောံ။) = “ညဉ့်မှောင်ချဉ်းသောအခါ­ မင်းသည် လူတို့ကိုစေလွှတ်၍ ကျောင်းတို့­ စနည်းနာထောက်လှမ်း တိတ်တဆိတ်နားထောင်စေ၏။” || “ယွံသၟိၚ်မပြဲ၊ ဂမှဳကွးကျာ်ဂမၠိုၚ်တံဂှ် ဆိုက်ဗဒက်ပ္ဍဲဥပ္ပါယ်ဂၠိုၚ်က္ဍၚ်သန်။ တြုံမၞိဟ်သမုတ်ဂှ် မရာတ်စကာဏာတုဲ ကဵုအာအောပ်ကလၚ်ဗပုၚ်ဗပၚ်ရ” အမာတ်တံဂး။ (ဇ—၄၉၂။ အစွောံ။) = “မြတ်သောမင်းကြီး၊ ရဟန်းတို့မည်သည်ကား အတိုင်အပင်­ အလွန်လိမ္မာကုန်၏။သူလျှိုတို့ကိုစေတော်မူ၍ ကျောင်း­ ရဟန်းတို့၏စကားကို စုံစမ်းခြင်းငှာသင့်၏။” (ညောင်ကန်) || တဘောင်စနည်းနာသည်။ နိမိတ်စကားကို စုံစမ်းသည်။ || “ဗလိဒေဝတဴတုဲ ပိုဲအာဗပုၚ်ဗပၚ်ပါၚ်တရၚ်ဍုၚ်ဗဂေါ။” (အကြီုရာဇာဓိရာဇ်) = “နတ်ပူဇော်ပသပြီးလျှင် ကျွန်ုပ်တို့ ဗဂိုးမြို့တံခါးဝသို့သွား၍ တဘောင်စနည်းနာကြမည်။”')
,(10306,3,1,'ကသစ်ပင်။',NULL)
,(10307,3,1,'ပင်လယ်ကသစ်ပင်။ သိကြားမင်းနေရာ နတ်ပြည်ရှိကသစ်ပင်။ (ပါဠိ—ကောဝိဠာရ)',NULL)
,(10308,3,1,'လပြည့်။','ဗပေၚ်ပသာ် = ကဆုန်လပြည့်။ || “ဒ္စာံမံက်၊ ဒ္စာံစွေက်၊ ဗပေၚ်၊ အာံမဝဟ် သၟိၚ်တိတ်ကဵုဒါန်ရ။” (ဇ—၂၇၆။ အစွောံ။) = “လဆန်းရှစ်ရက်နေ့၊ လဆုတ်ရှစ်ရက်နေ့၊လပြည့်နေ့၊ လကွယ်နေ့တို့­ မင်းသည်ထွက်၍ အလှူပေး၏။”')
,(10308,3,4,'ပြည့်စေသည်။ ဖြည့်သည်။','“ဇရဳဂှ် ဗပေၚ်ထောံဍာ်ညိ။” = “စဉ့်အိုးကို ရေဖြည့်လိုက်ပါ။” || ‘ပေၚ်’ (ကြိ) လည်းရှု။')
,(10309,3,4,'ဝမ်းပြည့်အောင်စားသည်။ ဝမ်းဖြည့်သည်။','“ခ္ဍာ်စၞာဲဂှ် စဗပေၚ်ဂၞဴတုဲ—။” (ဇ—၃၈၄။ အစွောံ။) = “ထိုကျီးစဉ်းလဲသည် ဝမ်းပြည့်အောင်စား၍—။”')
,(10310,3,4,'စိတ်အလိုကိုပြည့်စေသည်။ နှလုံးအလိုကိုပြည့်စေသည်။','“(ပြောဟိတ်ဂှ်) ရပ်စပ်ကဝိုတ်ကဝးသာ်ဇၟာ်အဲတုဲ ဗပေၚ်ဂၞပ်စိုတ်ဇကုတုဲ အာကၠေံရ” ဂၞကျာ်ဂးကဵုသၟိၚ်ရ။ (ဇ—၁၂ဝ။အစွောံ။) = “ပုရောဟိတ်သည် အကျွန်ုပ်အား ချုပ်ကိုင်သတ်ပုတ်ကုတ်ခြစ်၍ မိမိ၏စိတ်အလိုကိုပြည့်စေပြီးလျှင် ထွက်သွား၏” ဟုမိဖုရားသည် မင်းအားပြော၏။')
,(10311,3,4,'ရောင့်ရဲစေသည်။ ကျေနပ်စေသည်။ စိတ်အလိုကို ဖြည့်ဆည်းပေးသည်။','“သဘဴမာတုဂံါသီုဖ္အိုတ်ဂှ် အရီုမ္ဂးဂှ် ဗပေၚ်တရိုပ်စိုတ်ဍေံတံဟွံမာန်ရောၚ်။သဘဴဗပေၚ်တရိုပ်စိုတ်ဟွံမာန်ဂှ် ဒှ်ဓမ္မတာဗြဴဂမၠိုၚ်ရ။” (ဇ—၂၂ဝ။ အစွောံ။) = “ခပ်သိမ်းသောမိန်းမတို့အား မေထုန်အာရုံဖြင့် မရောင့်ရဲစေနိုင်။ ထိုသို့မရောင့်ရဲစေနိုင်သောသဘောသည် မိန်းမတို့၏ဓမ္မတာတည်း။” || “ယွံနာဲပိုဲဣသိ၊ နာဲပိုဲဗပေၚ်တရိုပ်စိုတ်ပိုဲ ဂၠိုၚ်သန်ရ။ နာဲပိုဲကၠုၚ်ဒုၚ်ဒဒိုက် ထပှ်သၞာံ ထပှ်ဂိတု ထပှ်တ္ၚဲဝွံဂှ် အဲဍိက်ခၠေဝ်ဂုန်တဳလညိအဴ” သၟိၚ်ဂး။ (ဇ—၅၃၂။ အစွောံ။) = “အရှင်ရသေ့၊ အရှင်သည် တပည့်တော်တို့၏စိတ်အလိုကို ဖြည့်ဆည်းပေးသည်မှာ များလှစွာ၏။ ခုနစ်နှစ်၊ ခုနစ်လ၊ ခုနစ်ရက်တိုင်အောင် အရှင်လာ၍ဒုက္ခခံသည်ကို အရှင့်ကို တပည့်တော်ကျေးဇူးဆပ်လိုပါ၏” ဟုမင်းဆို၏။ || ‘ပေၚ်တရိုပ်စိုတ်’ (ကြိ) လည်းရှု။')
,(10312,3,4,'ပါရမီဖြည့်သည်။',NULL)
,(10313,3,4,'ဖောင်းစေသည်။ ဖောင်းအောင်လုပ်သည်။','“(ကၞုဲဇၞော်ဒမျိုၚ်မုက်ဂှ်) ဗပေါင်ကၠေံဗုၚ်တုဲ ညံၚ်မဖဲပဒၟံၚ်တုဲ ဒတဴဒၟံၚ်ဂတမုက်ကၞုဲ (ဍောတ်) ဂှ်—။” (ဇ—၂၉၈။ အစွောံ။) = “မည်းသောမျက်နှာရှိသော ထိုမျောက်ကြီးသည် အစာဝသကဲ့သို့ ဝမ်းဗိုက်ကို ဖောင်းအောင်လုပ်၍ မျောက်ငယ်၏ရှေ့­ ရပ်လျက်နေ၏။”')
,(10314,3,1,'၁။ ကမ်းပါး။ ကမ်းပါးပြတ်။ (တောင်၊ ချောက်စသည်၏ နံပါးအရပ်၊ ဘေးဘက်အနီးအပါးအရပ်။) (ပါဠိ—အတဋ)','ဗပါတ်တၟအ် = တောင်ကမ်းပါး။ (‘တၟအ်’ ကို တောင်ဟုယူပါ။) || ဗပါတ်ဇြဟ် = ချောက်ကမ်းပါး။ || “ဟာဲဗာတ်ဇခါတ်၊ မဟာပဒုမကုမ္မာဂှ် ဗှ်ေအာထောံပ္တုံကၠေံပ္ဍဲဗပါတ်ဇြဟ် ဒၞာဲညးဂစိုတ်ကမၠတ်တေံရ” သၟိၚ်ဂး။ (ဇ—၄၇၂။ အစွောံ။) = “ဟယ်ခိုးသူသတ်၊သွားချေ၊ မဟာပဒုမမင်းသားအား ခိုးသူချရာကမ်းပါးပြတ်­ တွန်းချပစ်လော့” မင်းဆို၏။')
,(10314,3,1,'၂။ ပဲခွပ်။','“မၚ်ဗၠာဲမွဲကေုာံမဍေံ ယိုက်ကေတ်ဗပါတ်ဝါစဳ လုပ်အာဂြိုပ်။” (သၠပတ်သတိပထာန်) (ဗပါတ် = ဝါစဳ) = “တစ်ယောက်သောလုလင်သည် ဖခင်နှင့်တကွ ပဲခွပ်တို့ကိုသယ်ယူ၍တောသို့ဝင်သွား၏။”')
,(10315,3,1,'မြတ်စွာဘုရားဟောကြားသောတရားတော်။ မြတ်စွာဘုရား၏ နှုတ်ကပါဋ္ဌ်တော်။ မုက္ခပါဋ္ဌ်။','“(ဓဝ်) မဇွောဝ်တိတ်နူဗပါတ်ပါၚ်ကျာ်ဂမျိုၚ်။” (ဇ—ဝေသန္တဝ်။ အစွောံ။) =“ဘုရားရှင်၏နှုတ်ကပါဋ္ဌ်တော်မှ စီးထွက်တော်မူသောတရားတော်။”')
,(10316,3,4,'လှုပ်တုပ်လှုပ်တုပ်နှင့် သွား/လာ လုပ်ကိုင်သည်။','“ဗပုတ်ကၠုၚ်နူလဵုရော။” = “လှုပ်တုပ်လှုပ်တုပ်နှင့် ဘယ်ကလာသနည်း။” || “မိဗပုတ်ဒၟံၚ်ပ္ဍဲပါၚ်ဖဴ ကၠိုဟ်တ္ၚဲထုတ်ရ။” = “အမေသည် မီးဖိုချောင်­ လှုပ်တုပ်လှုပ်တုပ်နှင့် တစ်နေကုန်လုပ်ကိုင်နေသည်။” || “ပ္ဍဲလောကန္တနရက်ဂှ်— ဂၠုၜိုဟ်တဴလၟိုန်ရ။ သတ်နရက်တံ ဟွံညာတ်ရၚ်သ္ကံတုဲ ဗပုတ်ကၠုၚ် ဗပုတ်အာရ။” (ဇ—နာရဒ။အစွောံ။) = “လောကန္တငရဲ­ အမြဲမှောက်မိုက်နေ၏။ ငရဲသားတို့သည် အချင်းချင်းမမြင်ရကုန်ဘဲ လှုပ်တုပ်လှုပ်တုပ်နှင့် စမ်းတဝါးဝါးသွားလာကုန်၏။”')
,(10317,3,1,'ပုရပိုက်။ ပေ။','“(ဂရုကဓဝ်ဂှ်) ပိုဲချူကေတ်ညိရဂးတုဲ ပၠးဗပိုတ်တုဲ ချူဏာရ။” (ဇ—၂၇၆။ အစွောံ။) = “ဂရုကဓမ္မကို ငါတို့ရေးယူအံ့ဟု ပုရပိုက်ကိုဖြန့်၍ ရေးယူသွား၏။”')
,(10317,3,4,'ဖြတ်သည်။ ပြတ်စေသည်။','“တၠသ္ၚိရုန်ဗပိုတ်ကၠေံ ဇုက်စၞာံ (ပးဓနက်) ဂှ်ညိရအဴ” ဒြာဲဗြဴဂးကဵုသၟိၚ်ဒြာဲထဝ်။ (ဇ—၃၅၉။ အစွောံ။) = “ကျော့ကွင်းသားရေကြိုးကို ရုန်းဖြတ်ပစ်လော့” ဟုသမင်မသည် ရွှေသမင်မင်းအားပြော၏။‘သပိုတ်’ ဟုလည်းတွေ့ရသည်။')
,(10318,3,1,'ထန်းရွက်ပေရွက်စာအုပ်။',NULL)
,(10319,3,1,'(ထိုးလာသော) ရောင်ခြည်။','“သၟိၚ်တ္ၚဲတၠလျးဗပန်လ္ၚီ။” = “ရောင်ခြည်တစ်ထောင် အလင်းဆောင်သောနေမင်း။” || ‘ပန်’ (ကြိ) လည်းရှု။')
,(10320,3,1,'နေရောင်ခြည်။',NULL)
,(10321,3,1,'သူပုန်။','“ယွံအမာတ်တံ၊ ပ္ဍဲသၟိၚ်ဗပုန်တေံဂှ် မၞးတံလ္ပထေဲပၞတ်ညိ” သၟိၚ်ဂး။ (ဇ—၅၁။ အစွောံ။) = “အမတ်တို့၊ ထိုခိုးသူမင်း­ အမျက်မထွက်ကြကုန်လင့်” ဟုမင်းဆို၏။ || “(သၟိၚ်ဇက်ကၠုၚ်ပၞာန်ရဂးတုဲ) ဗပုန်တေံ ဍေံမိၚ်ပရိုၚ်တုဲ ဗပုန်တံဂှ် ဒဴအာကၠေံအိုတ်ရ။” (ဇ—၁၇၆။အစွောံ။) = “မင်းသည် စစ်ချီလာပြီဟုဆိုကာ သူပုန်တို့သည် ထိုသတင်းကိုကြား၍ ထွက်ပြေးသွားကြကုန်၏။” || “(သၟိၚ်ဇက်တိတ်ကၠုၚ်ဂးတုဲ) သပုန်တံဂှ် ဒဴကၠေံအာရ။” (ဇ—၂၂၆။ အစွောံ။) || “ဇၞးပၞာန်သပုန်တုဲ။” (ရာဇာထ္ၜုတ်) = “သူပုန်စစ်ကို အောင်နိုင်ပြီးနောက်။”')
,(10321,3,4,'ပုန်ကန်သည်။','‘ပုန်’ (ကြိ) လည်းရှု။')
,(10322,3,1,'ပုန်ကန်ခြင်း။ သူပုန်ထခြင်း။','(ကြိ) ပုန်ကန်ထကြွသည်။ သူပုန်ထသည်။')
,(10323,3,1,'လင်းလွန်းပၚ်။',NULL)
,(10324,3,1,'ထရံ။ (ဝါး၊ ကျူစသည်ကို ခွဲဖြာ၍ရက်လုပ်ထားသော အကာအရံ။)','“ညးၜါမကဵုကောန် တာန်ဗပေဝ်သွံစ—။” (ဇ—၂၅၇။ အစွောံ။) = “သားအဖနှစ်ဦးတို့သည် ထရံရက်၍ရောင်းစားကုန်၏။”')
,(10325,3,1,'အလွှာ။ (ပါဠိ—ပပ္ပဋက) (= ကွပ်)','ဗပှ်ေတိ = မြေလွှာ။ (ပါဠိ—ဘူမိပပ္ပဋက)')
,(10326,3,1,'ကျူပၚ်။','“ညံၚ်ရဴစိၚ်ဇၟူ မလၞိန်ဗပိန်ကၠေံဂြိုပ်ဗပိုဟ်ကီု။” (ဇ—၂၃ဝ။ အစွောံ။) = “ဆင်ပြောင်ကြီးသည် ကျူတောကို ခြေတို့ဖြင့်နင်းချိုးသကဲ့သို့။” (ညောင်ကန်) || ‘သပိုဟ်’ ဟုလည်းတွေ့ရသည်။')
,(10327,3,1,'ပဲခွပ်။ တံစည်း။ (ပါဠိ—ဝါသိ)',NULL)
,(10328,3,1,'ပြာပူ။',NULL)
,(10329,3,1,'စားပွဲ။','ဗဗံက်ပုၚ် = ထမင်းစားစားပွဲ။ (ပါဠိ—ဘောဇနဖလက)')
,(10330,3,1,'အရွက်။ သစ်ရွက်။ (= သၠ) (ပါဠိ—ပတ္တ)','“တာလပတ္တပါဒုကာ။ န်ဟနပ်ဗဗိုက်တာဂမၠိုၚ်။ ‘သၠတာ’ လေဝ်ဂး။ — ဝေဠုပတ္တပါဒုကာ။ န်ဟနပ်ဗဗိုက်ဒုန်ဂမၠိုၚ်။ — ‘သၠဒုန်’လေဝ်ဂး။” (တြာဲဝိနယသၚ်ရိုဟ်ဂြဳ။ စန္ဒိမာ။)')
,(10331,3,1,'ဖုန်။','‘ဂဗိုက်’ ရှု။')
,(10332,3,1,'ငှက်ပျောဖက်နှင့်လုပ်သော ပူဇော်ပသရန်ခွက်။',NULL)
,(10333,3,1,'ကြက်မောက်သီး။',NULL)
,(10333,3,4,'၁။ မှုန်ဝါးသည်။','မတ်ဗဗုၚ် = မျက်စိမှုန်သည်။')
,(10333,3,4,'၂။ကိုယ်ဝန်ရအောင်လုပ်သည်။','“ဗဗုၚ်လဝ်အဲတုဲ လ္ပထောံလသာကၠေံအဲညိ။” = “ကျွန်မကိုကိုယ်ဝန်ရအောင်လုပ်ထားပြီး ကျွန်မကို စွန့်ပစ်မသွားပါနှင့်။”')
,(10334,3,5,'မှုန်မှုန်။ မှုန်မှုန်ဝါးဝါး။','“ပယျာံသ္ဂာတ္ၚဲလောန် ပယးဂိတုဗဗုၚ်ဗဗုၚ်။” (အကြီုရာဇာဓိရာဇ်) = “သန်းခေါၚ်ယံအချိန်ကျော်လွန်၍ လရောၚ်မှုန်မှုန်ဖြစ်၏။”')
,(10335,3,1,'သပိတ်။','ဗကပ်ဗဗေၚ် = သပိတ်မှောက်သည်။')
,(10336,3,4,'တိုက်သည်။ ထိသည်။','‘ဒဗတ်’ ဟုလည်းရေးသည်။')
,(10337,3,4,'ထိတိုက်သည်။ ထိခိုက်သည်။',NULL)
,(10338,3,4,'‘လဗိုန်’ နှင့်အတူတူ။',NULL)
,(10339,3,3,'နိမ့်သော။ ပုပျပ်သော။','“(ဆု) လ္ၚဵုဆတ္တဝ်၊ သဝ်ဗဗေဝ်ကွ။” (လိက်ဇိဝှစက္က) =“အချို့သောသစ်ပင်တို့သည် နိမ့်ကွပုပျပ်ကုန်၏။”')
,(10340,3,4,'(နေဝန်း) ဝင်သည်။ ကျသည်။','“တရဴလေဝ်သ္ၚောဲဒၟံၚ်ဏီ သ္ဇိုၚ်သ္ဂောံစိုပ် တ္ၚဲသဝ်ဗဗေဝ်အာတုဲရသွံ။” (ဇ—ဝေသန္တဝ်။ အစွောံ။) = “ခရီးလည်းဝေးနေသေး၏။ ရောက်နိုင်ခဲလှ၏။ နေညို၍နေကျနေလေပြီတကား။” || “တ္ၚဲဝွံလေဝ် သဝ်လဗေဝ်အာတုဲရ။” (သၠပတ်စန္ဒဝတဳ) = “နေဝန်းသည်လည်း ကျသွားဝင်သွားလေပြီ။” || ‘ဗေဝ်’ (ကြိ) လည်းရှု။')
,(10341,3,4,'၁။ ပြသသည်။ ရှုစားစေသည်။','“ကာလတ္ၜတ်တ္ၜတ်ဒှ်ဝုတ်ဗၠာဲ မပတၠရုပ်သာ်စရာဲ ညံၚ်ရဴမတခဲါကော် ဗဗဵုစရာဲရုပ်ဇကုကီု။” (ဇ—၄၁၁။ အစွောံ။) = “နုပျိုစဉ်ကာလ တင့်တယ်သောရုပ်အဆင်းရှိ၍ လူတကာတို့ကို လက်ယပ်ခေါ်၍ မိမိရုပ်အဆင်းကို ရှုစားစေသကဲ့သို့။” || “ဇွဂှ်ဟွံကဵုဂိုၚ်ဒဵုမသ္အုဲ ဂြောပ်ဒၟံၚ်ဒၞာဲဂှ် ဗဗဵုညးဂမၠိုၚ်ရ။” (သၠပတ်ဝၚ်ဓါတ်သော်လ္ဂုၚ်) “ထိုအလောင်းကောင်ကို ပုပ်သည်အထိ မဖယ်ရှားစေဘဲ ထိုနေရာတွင်တည်နေစေ၍ လူအများကို ရှုစားစေ၏။”')
,(10341,3,4,'၂။ (ယၚ်ကောင်စသည်) ဝိုင်းအုံသည်။','ရုဲဗဗဵု = ယၚ်အုံသည်။ || “အလုံဇကုဗောဓိသတ် ရုဲဂမၠိုၚ်ကၠုၚ်ဗဗဵုဟုပ်ဒၟံၚ်ရ။” (ဇ—တေမဳ။ အစွောံ။) = “ဘုရားလောင်း၏ကိုယ်အလုံး­ယၚ်ကောင်တို့သည် လာ၍ဝိုင်းအုံနေ၏။”')
,(10342,3,1,'ရှုမငြီးဖွယ်သောအရာ။ ရှုခင်း။','“ဒၞာဲအဲဍိက်မဂတအာ ညးမညာတ်ရုပ်အဲဍိက်ဂှ် ကဵုဂွံအိုဟ်တၟိုဟ်ဒၟံၚ်စိုတ်ညးညိ၊ ကဵုဂွံဒှ်ဗဗဵုမတ်ညးညိ။” (သၠပတ်သုရသာ) = “အကျွန်ုပ်သွားလေရာရာ အကျွန်ုပ်ရုပ်ကိုမြင်သူတိုင်းသည် ဝမ်းမြောက်စေကုန်သတည်း၊ သူတကာတို့၏ရှုမငြီးဖွယ် ဖြစ်ပါစေသတည်း။” || “ဗြံက်ဗြဇကု ဒှ်တဴဗဗဵုမတ်ညး မဂွံအိုက်အာဲမွဲခဏကီု။” (သၠပတ်သတိပထာန်) = “ကိုယ်ကိုဆင်ယင်ကာ တစ်ခဏတာမျှသာ သူတစ်ပါးတို့၏ရှုချင်စရာဖြစ်၍ ပျော်ရွှင်ရ၏။”')
,(10343,3,4,'လိမ်းသည်။ လူးသည်။','ဗဗိုဟ်ဂစေအ် = သနပ်ခါးလိမ်းသည်။ သနပ်ခါးလူးသည်။ || “(ဂၞကျာ်သမ္ဘူလာ) ဂဥုဲရိုဟ်ဆု မဂွံဗဗိုဟ်ယဲဂှ် ချူတုဲတွံဗဗိုဟ်စုတ် ပ္ဍဲဇကုကောန်သၟိၚ်ဂှ်ရ။” (ဇ—၅၁၉။ အစွောံ။) = “သမ္ဘူလမိဖုယားသည် အနာရောဂါကိုလိမ်းရန် ဆေးသစ်မြစ်ကိုသွေး၍ မင်းသား၏ကိုယ်­ လိမ်းကျံပေး၏။” || “သၟိၚ်လ္ၚီဂှ် ကျိုၚ်ကျဝ်ဗြံက်ဗြ ဗဗိုဟ်ကေတ်စၠန်မြမောဝ်—။” (ဇ—၃၅၃။ အစွောံ။) = “ထိုတစ်ထောင်သောမင်းတို့သည် ဝတ်စားဆင်ယင်၍ အမွှေးနံ့သာလိမ်းကျံ၍—။” || “—မြမောဝ်ဂှ် မဗဗိုဟ်ဇကုမညိ။” (ဇ—၃၈၈။ အစွောံ။) =“ထိုအမွှေးနံ့သာဖြင့် သင့်ကိုယ်ကိုလိမ်းလော့။”')
,(10344,3,4,'လိမ်းသည်။ လိမ်းကျံသည်။','“သၟိက်ဂွံကျိုၚ်ကျဝ်၊ မြမောဝ်နာနာ။ စလန်အဂၠဴ၊သ္ၚဴဒေဝဒါ။ ဗဗိုဟ်ဗဗိန်၊ ဟိန်ဗိန်ဂန္ဓာ။” (သၠပတ်ပုံပမာ။ အစွောံ။) = “အမွှေးနံ့သာအမျိုးမျိုး ဖြစ်သော စန္ဒကူး၊ အကျော်၊ ထင်းရူးစေး၊ နတ်ထင်းရူးတို့ကို ဆင်မြန်းလိုကုန်၏၊ ယုတ်ညံ့သောခန္ဓာကို တန်ဆာဆင်လိမ်းကျံလိုကုန်၏။”')
,(10345,3,4,'မျက်နှာကို သနပ်ခါး၊ ပေါင်ဒါတို့ဖြင့်လိမ်းသည်။','“သၟတ်ဗြဴဂှ် ဟုံဍာ်တုဲ ဗဗိုဟ်မုက်လၟိုန်ရ။” = “ထိုသူငယ်မသည် ရေချိုးပြီး အမြဲသနပ်ခါးလိမ်းသည်။”')
,(10346,3,1,'ပုဏ္ဏား။','‘ဗမၞး’ ရှု။ || “ဗောဓိသတ်ပိုဲ ဒှ်ပ္ဍဲဂကူဗဗၞး—။” (ဇ—၃၁၉။ အစွောံ။) = “ဘုရားလောင်းသည် ပုဏ္ဏားမျိုး­ဖြစ်၍—။” (ညောင်ကန်)')
,(10347,3,4,'၁။ (သစ်သီး) ပြွတ်သိပ်၍သီးသည်။','“ကြုက်တၞံဏအ် သတ်ဓဗြိုက်ဒၟံၚ်ရ။” = “ဤသရက်ပၚ်သည် ပြွတ်သိပ်ပြီးသီးသည်။”')
,(10347,3,4,'၂။ (ဆံပင်) ဖွားရရားဖြစ်သည်။','“လ္ပံညာတ်သော်ဗဗြိုက် စရှ်ပ္ကဴလမ္စံက်မ္ဂး ဒှ်ဂဗုတ်ရ။” (လောကသိဒ္ဓိ။ အစွောံ။) = “ဆံပင်ဖွားရရားနှင့် အနက်ရောၚ်ပန်းကို ပန်ဆင်သည်ဟု အိပ်မက်ပါက အမှုအခင်းဖြစ်လိမ့်မည်။”')
,(10347,3,4,'၃။ လျှံကျသည်။ ဖိတ်စဉ်ကျသည်။ ဝေကျသည်။','“ပ္ဍဲထမှာဲပုၚ်ဂှ် သ္ၚုကီု ဍာ်ကီု ညးမစုတ်ဗပေၚ်လဝ်တုဲဂဒဵုလၟဳထၟာဲတုဲ ပတိုက်ပၟတ်ရ။ — ဍေံတဏမ်တၟိုဟ်ဗဗြိုက်တိတ်—။” (သၠပတ်ပုံပမာ။ အစွောံ။) = “ထိုထမင်းအိုးထဲ­ ဆန်ကိုလည်းကောင်း ရေကိုလည်းကောင်း ဖြည့်ထည့်ထားပြီးလျှင် အိုးအဖုံးကိုဖုံး၍ မီးတိုက်သည်ရှိသော် ဆူပွက်၍ ဝေကျလျှံထွက်၏။”')
,(10348,3,4,'(ဆံပင်စသည်) ရှည်၍မသေသပ်ရှုပ်ထွေးသည်။ ဖွားရရားဖြစ်သည်။ စုတ်ဖွားဖြစ်သည်။','“သၟတ်တြုံဂှ် မၞုံသော်ဗဗြိုက်ဗဗြုဲတဴရ။” = “ထိုသူငယ်သည် ဖွားရရားသောဆံပင်ရှိသည်။”')
,(10349,3,4,'(ပါးစပ်၊ နှုတ်ခမ်း) ပေကျံသည်။','“ဍေံစပုၚ်ခပပ်လောန် သၟန်ပါၚ်ဍေံဗဗြီဒၟံၚ်ရ။”= “သူအငမ်းမရထမင်းစား၍ သူ့နှုတ်ခမ်းပေကျံနေသည်။”')
,(10350,3,4,'‘ဗဗြီ’ နှင့်အတူတူ။',NULL)
,(10351,3,4,'ကိုက်ညီသည်။ ဆီလျော်သည်။ လျောက်ပတ်သည်။','‘ဂဥုဲမဗဗွဲကဵုယဲ။’ = ‘ရောဂါနှင့်ဆီလျော်သောဆေး။’ || ‘ပြဝေဏဳမဟွံဗဗွဲကဵုခေတ်ကာလ။’ = ‘ခေတ်ကာလနှင့်မကိုက်ညီသောထုံးတမ်းအစဉ်အလာ။’ || “ကုညးမယဲကိလေသဂှ် ဂဥုဲမတွံဂးပညာ မဒးဗဗွဲရောၚ်။” (ဇ—၄၃၁။အစွောံ။) = “ကိလေသာရောဂါဖြစ်သူအား ပညာတည်းဟူသောဆေးသည် လျောက်ပတ်၏။” || “ညံၚ်ဂွံဗဗွဲကဵုခေတ်သမယ။” (သုဓမ္မဒေသနာ။ ဂရိုက်သာံ။) = “ခေတ်အခါသမယနှင့်လျော်ညီစေရန်။”')
,(10352,3,5,'တရားသဖြင့်။ တရားနှင့်အညီ။','“(ဗောဓိသတ်ဒှ်သၟိၚ်) ဂွံပကၚ်ရၚ်ကၟိန်ဍုၚ် ဗဗွဲဓဝ်ရ။” (ဇ—၃၄၉။ အစွောံ။) = “ဘုရားလောင်းသည်မင်းဖြစ်၍ တိုင်းပြည်ကို တရားနှင့်အညီအုပ်ချုပ်သည်။” || “ဒၞာဲညးသ္ဂုတ်သွာတ်လဝ် ဟွံဒးကဵုသၞောဝ်ဗဗွဲဓဝ်တအ်ဂှ် အမာတ်ဗောဓိသတ်သ္ဂုတ်သွာတ်ကဵုဗဗွဲဓဝ်ရ။” = “သူတစ်ပါးတို့ မတရားသဖြင့် ဆုံးဖြတ်ထားသည်များကို ဘုရားလောင်းအမတ်သည် တရားသဖြင့် ဆုံးဖြတ်ပေး၏။”')
,(10353,3,4,'တိမ်းညွတ်လိုက်ပါသည်။ နောက်သို့လိုက်ပါသည်။','“ဗဵုပၞာန်ပန်ကၞိပ်အိုဿီုဂှ် ရဴမပပဓါန်ကဵုသၟိၚ်မွဲကီု၊ ရဴမတယောဝ်လမောဝ် ဗဗွဲဗက်အာသၟိၚ်မွဲကီု။” (သ္ကေံမိလိန္ဒဝတ္ထု) = “စစ်ကြောင်းလေးကြောင်းတို့သည် တစ်ဦးတည်းသောမင်းကို အမှူးပြုသကဲ့သို့၊ တစ်ဦးတည်းသောမင်းနောက်သို့ တိမ်းညွတ်လိုက်ပါသွားသကဲ့သို့။”')
,(10354,3,5,'အစဉ်အတိုင်း။ အစဉ်သဖြင့်။ အစဉ်အားဖြင့်။','“သကိုပ်သာဗၞိက်သမၠီုဂှ် ဗ္ဂန်ကေတ်ကွဳစောတ်မသုန်ကၠံဂှ်တုဲ ဇက်အာရ။ ဗဗွဲလၟေၚ်ဟေၚ် ကလိကၠေံဒမံၚ်မၞိဟ်တုဲ အာစိုပ်ကန္တာရ။” (ဇ—၁။ အစွောံ။) = “လှည်းကုန်သည်မိုက်သည် လှည်းငါးရာတို့ဖြင့်သွား၏။ အစဉ်သဖြင့်လူ့ရပ်ဋ္ဌာနေကိုလွန်၍ ကန္တာရသို့ရောက်၏။” || “(ကၠဵုဂြိုပ်ဂှ်) စကၠေံသာ်ဝွံ ဗဗွဲလၟေၚ်ဟေၚ် ကၞိတံဂှ်အောန်အာရ။” (ဇ—၁၂၈။ အစွောံ။) = “(ထိုမြေခွေးသည် ကြွက်တို့ကို ဖမ်းစားသည်ရှိသော်) အစဉ်သဖြင့် ကြွက်အပေါင်းသည် ပါးသည်ဖြစ်၏။” (ညောင်ကန်)')
,(10355,3,5,'အစဉ်အတိုင်း။ အစဉ်သဖြင့်။','‘ဗဗွဲလၟေၚ်’ နှင့်အတူတူ။ || “ဓမ္မပါလကုမ္မာ ဇၞော်အာဗဗွဲလွေၚ် အာစိုပ်ဒဒှ်ဗၠာဲတုဲ အာကတ်ကွတ် ပ္ဍဲဍုၚ်တက္ကသဵုရ။” (ဇ—၄၄၇။ အစွောံ။) =“ဓမ္မပါလသတို့သားသည် အစဉ်သဖြင့်ကြီးပြင်း၍ အရွယ်ရောက်လတ်သော် တက္ကသိုလ်ပြည်­အတတ်သၚ်ရန်သွား၏။ ” || “ဗဗွဲလွေၚ် အလုံဂကူဂှ် အာစိုပ်ပလိုက်တုဲ ဒတောဝ်သ္ဂုတ်အာ။” (ဇ—၁၃၇။ အစွောံ။) = “ဤသို့အစဉ်သဖြင့် ထိုအမျိုးသည် ပျက်စီးခြင်းသို့ရောက်၏။ အနွယ်သည်ပြတ်၏။” (ညောင်ကန်) || “(ကၠဵုဂွံစဖျုန်ၚးဇာဒိသိုၚ်ရိုဟ်တ္ၚဲတုဲ) နဗဗွဲလွေၚ်ကြောအ်အာကၠဵုဇၞော်သၠုၚ်စောံထတ်အာ။” (ဇ—၁၄၃။ အစွောံ။) = “မြေခွေးသည် ခြင်္သေ့စားကြွင်းအသားတို့ကို နေ့တိုင်းစားရ၍ အစဉ်သဖြင့်ဝဖြိုးလာကာ ကြီးထွားသန်စွမ်းလာ၏။”')
,(10356,3,4,'‘ပၟိပ်’ ရှု။',NULL)
,(10357,3,1,'အမျိုးသမီးပုဏ္ဏား။ ပုဏ္ဏေးမ။','“ဗမၞိဟ်ဗြဴဂှ် ပကၠေံကာဂစိုတ်ရ။” (ဇ—၁၇၃။အစွောံ။) = “ပုဏ္ဏေးမသည် သေ၏။” (ညောင်ကန်)')
,(10358,3,1,'အပြစ်တင်ခြင်း။ ကဲ့ရဲ့ခြင်း။ အကဲ့အရဲ့။','“(ပွမယာံကဵုညးမချိုတ်ဂှ်) ဒှ်ဗယိတၠပညာရောၚ်သွံ။” (ဇ—၄၁ဝ။ အစွောံ။) = “သေသောသူနှင့်ငိုကြွေးခြင်းသည် ပညာရှိတို့ကဲ့ရဲ့ခြင်းကိုခံရ၏။” || “ယွံသၟိၚ်မပြဲ၊ ယြဴတြုံမွဲဂှ် ဍေံစဇအအ်တၠညးရ။ တြုံဂှ် မဒှ်ဗယိတၠပညာတံရ။” (ဇ—၅ဝ၉။ အစွောံ။) = “မြတ်သောမင်းကြီး၊ အကြင်ယောကျာ်းသည် အရှင်မင်းကြီး၏အန်ဖတ်ကိုစား၏။ ထိုယောကျာ်းသည် ပညာရှိတို့၏အကဲ့အရဲ့ဖြစ်ရာ၏။” || “သၟိက်ဒဴဗယိညးတုဲ ဗောဓိသတ်မဒးပါန်လမျီု (ကဵုပုဏ္ဏက) ရောၚ်။” (ဇ—ဝိဓုရ။ အစွောံ။) = “လူတို့၏ကဲ့ရဲ့ခြင်းကို ရှောင်ရှားလို၍ ဘုရားလောင်းသည် အသက်ချမ်းသာပေးပါရန် ပုဏ္ဏကအား တောင်းပန်ရခြင်းဖြစ်၏။” || ‘ဗျိ’ (ကြိ) လည်းရှု။')
,(10359,3,1,'အစောင့်နတ်။','ဗယိကွာန် = ရွာစောင့်နတ်။ || ဗယိဂြိုပ် = တောစောင့်နတ်။ || “ဗလိဗကဝ်ကလော်မယိဂှ်ရ။” (ဇ—၄၅၉။ အစွောံ။) = “အစောင့်နတ်ကို ပူဇော်ပသကြကုန်အံ့။” || ‘မယေအ်’ ဟုလည်း အရေးရှိသည်။')
,(10360,3,1,'လူတို့ပြောဆိုပြုမူမှားမိလျှင် ဖမ်းစားတတ်သည်ဆိုသော အစောင့်နတ်အမျိုးမျိုးကိုခြုံခေါ်သောဝေါဟာရ။','“မပ္တံကလော်ဗယိဗရာန်တံဂှ် ညံၚ်မဖေက်သၟိၚ် ဖေက်ဒမၠကီု ဖေက်ရပ်စတုဲ—။” (ပြကိုဟ်ဓမ္မရာသဳ။ မာံရွှေငိုး။) || ‘မယိမရာန်’ ဟုလည်းရေးသည်။')
,(10361,3,1,'အိုခြင်း။','“ယွံသၟိၚ်မပြဲ၊ မရာတ်ပြာပ်အာကဵုအဝဲဗယု—။” (ဇ—၃၇၈။ အစွောံ။) = “မင်းမြတ်၊ သင်မင်းမြတ်သည် အရွယ်အိုသို့ ရောက်နေလေပြီ။” || “ဟာဲကောန်၊ ဒြေပ်ဒဴရ။ ပိုဲမိကဵုမဗယု ဒမၠုမတ်ဝွံဂှ် လဝ်ကဵုချိုတ်ရကောန်။” (ဇ—၅၂၂။ အစွောံ။) = “အိုချစ်သား၊ ပြေးလော့။”မျက်မမြင်မိဘအိုဖြစ်သောငါတို့သည် သေလျှင်လည်းသေပါစေတော့။” || ‘ဗျု’ (ကြိ) လည်းရှု။')
,(10362,3,1,'ကဲ့ရဲ့ခြင်း။ စွပ်စွဲခြင်း။ (ပါဠိ—ဥပဝါဒ)','ဂလာန်ဗယံက် = အပြစ်တင်သောစကား။စွပ်စွဲချက်။ || “မကဵုအေၚ်ဒုၚ် ပ္ဍဲမပ္တံဗယံက်ညးဂှ်မွဲ။” (ဥပါသကောဝါဒကထာ။ သဳလဝန္တ။) =“သူတစ်ပါး၏ကဲ့ရဲ့စွပ်စွဲခြင်း အစရှိသည်တို့ကို သည်းခံစေခြင်းသည်လည်းတစ်ပါး။”')
,(10362,3,4,'ကဲ့ရဲ့သည်။ စွပ်စွဲသည်။','“အနုပဝဇ္ဇော။ စိုန်ဟွံဂပ်ဂဝ်ဂရိုဟ်။ ဝါ။ စိုန်ဟွံဂပ်ဂဝ်ဗယံက်။” (တြာဲဝိနယသၚ်ရိုဟ်ဂြဳ။ စန္ဒိမာ။) = “မကဲ့ရဲ့သင့်သည်။ မစွပ်စွဲသင့်သည်။” || ‘ဗျံက်’ (ကြိ) လည်းရှု။')
,(10363,3,4,'(နှုတ်ခမ်း) စူသည်။','“ၚာ်ဗြဴသၟတ်ဂှ် ထေဲကဵုမိဍေံတုဲ ဗယံက်လဝ်ပါၚ်ရ။” = “ထိုကလေးမငယ်သည် မိခင်ကိုစိတ်ဆိုးပြီး နှုတ်ခမ်းစူထားသည်။” || ‘ယံက်’ (ကြိ) လည်းရှု။')
,(10364,3,4,'ဆောင့်ခုန်သည်။ ခုန်ဆောင့်သည်။','“(ကၞုဲအလံၚ်ဒေဝဒတ်ဂှ်) ဍေံဆင်စှ်ေပ္ဍဲစးဗောဓိသတ် (သၟိၚ်ကၞုဲ) ဂှ်တုဲ ဗယောတ်ပ္ဍဲစးဗောဓိသတ်—။” (ဇ—၄ဝ၇။ အစွောံ။) =“ဒေဝဒတ်လောင်းမျောက်သည် ဘုရားလောင်းမျောက်မင်းကျောပေါ်သို့ အဟုန်ဖြင့်ခုန်ဆင်းပြီးလျှင် ဘုရားလောင်းကျောပေါ်­ ခုန်ဆောင့်၏။” || “ဍေံဆင်စှ်ေ လယောတ်ပ္ဍဲစးသွာၚ်ပန်အဲ—။” (ဇ—၄ဝ၇။ အစွောံ။)')
,(11870,3,4,'၁။ အတောင်ခတ်သည်။','ဗယာပ်သၞေၚ်ၜါ = အတောင်နှစ်ဖက်ကိုခတ်သည်။ ပျံသန်းသည်။')
,(11870,3,4,'၂။ ပင့်သည်။ ချီသည်။ (ဓါးစသည်ဖြင့်) ခုတ်ရန်ရွယ်သည်။','“ဣသိရပ်သၞာ်ရတ်ပၚ်ပ္တိုန်ဗယာပ်ကအ်စိၚ်မ္ၚဵု စိၚ်မ္ၚဵုဖေက်ဘဲဂစိုတ် ကရေဲရမျှာၚ်။” (ဇ—၄၃၃။ အစွောံ) = “ရသေ့သည် သန်လျက်ကိုကိုင်၍ ပင့်ချီလျက် မင်္ဂလာဆင်တော်၏လည်ကို ခုတ်ရန်ရွယ်လတ်သော် မင်္ဂလာဆင်တော်သည် သေဘေးမှကြောက်သဖြင့် အသံကုန်အော်၏။” || ‘ဗယာပ်လွဟ်’ (ဇ—၆၃။အစွောံ။)')
,(11870,3,4,'၃။ (အလင်းဖြင့်) ပျံ့နှံ့စေသည်။ အနှံ့ရောက်စေသည်။','“န်ဗၞတ်မွဲလက်ကိုတ်စက္ကဝါဍေံဒမသၟဟ်ရထဗယာပ်ဏာလျးမာန်၊ ၚ်ကုမှာဗြီုဂှ်ကီုလေဝ် (မဒးအာပ်အာလျးကျာ်တြဲ။)” (ဓမ္မဒဳပနဳ။ မာံရွှေငိုး။) = “ကုဋေကဋာစကြဝဠာတိုင်အောင် ကိုယ်ရောင်အလင်းဖြင့် ပျံ့နှံ့စေနိုင်သောမဟာဗြဟ္မာမင်းသည်ပၚ်လည်း မြတ်စွာဘုရား၏ရောင်ခြည်တော်အလင်းကို အပြတ်အသတ် ရှုံးသွားရသေး၏။”')
,(10365,3,4,'မေတ္တာဖြင့်ပျံ့နှံ့စေသည်။ မေတ္တာပို့သည်။','“သဘဴခမဳမ္ဂးဂှ် ညးမဒှ်မိတ်တံဂှ်ကီု ညးမဒှ်သတြုတံဂှ်ကီု ဂပ်ဂဝ်ဗယာပ်ဏာမေတ္တာစိုတ်ရ။” (ဇ—၁၆၉။ အစွောံ။) = “ရဟန်းတို့မည်သည် မိတ်ဆွေဖြစ်သောသူတို့အား၄င်း ရန်သူဖြစ်သောသူတို့အား၄င်း မေတ္တာစိတ်ထားအပ်၏ (ဝါ) မေတ္တာစိတ်ဖြင့် နှံ့စေအပ်၏။” || “မိၚ်ဂလာန်ဍေံ မကြံကြသ္ကာတ်မြဟ်ဂှ်တုဲ နမေတ္တာမဍိုန်ညံဂှ်ဟေၚ် ဗယာပ်ဏာကုဍေံရ။” (ဇ—၄၉၇။ အစွောံ။) = “ရုန့်ရင်းကြမ်းတမ်းသော သူ့စကားကိုကြား၍ သိမ်မွေ့သောမေတ္တာဖြင့်သာလျှင် သူ့အားမေတ္တာပို့၏။” || ‘ဘယာပ်မေတ္တာ’ ဟုလည်းတွေ့ရသည်။')
,(10366,3,3,'မှောင်ရီသော။','“ကာလဂှ် တ္ၚဲလေဝ် သၟိက်ပၠိုတ်ကဵုပၠိုတ် အလုံဂြိုပ် ဗယောံအိုတ်တုဲ။” (သၠပတ်စန္ဒဝတဳ) = “ထိုအချိန်တွင် နေလည်း ကွယ်လုနီး၍ တစ်တောလုံးသည် မှောင်ရီကုန်လေပြီ။” || “တ္ၚဲဗယောံစှ်ေညိတုဲ ညးၜါယောန်လုပ်တိက် အပ္ဍဲဇြပ်ဂှ်ရ။” (သၠပတ်စန္ဒဝတဳ) = “နေအနည်းငယ်မှောင်စပြုသောအခါ နှစ်ဦးသားတို့သည် ဇရပ်ထဲသို့ အသာအယာဝၚ်အိပ်ကြ၏။”')
,(10367,3,1,'ဆာလောင်ခြင်း။ မွတ်သိပ်ခြင်း။','“ပုၚ်ကေတ်ဟွံဂွံ၊ ကၠောဝ်ဇွောံအဟာ။ ဗယဵုလောန်ဗၞတ်၊ ဖျုန်ဆီဇတ်အာ။” (လိက်ပုညကာရဳ) = “ထမင်းရှာမရ အစာရေစာၚတ်ပြတ်ကာ ဆာလောင်ခြင်းလွန်ကဲ၍ အသားအသွေးခန်းသွား၏။” || ‘ဗျဵု—၁’ (ကြိ) လည်းရှု။')
,(10368,3,1,'ကုန်းတိုက်ခြင်း။ ကုန်းချောခြင်း။','‘ဗျဵု—၂’ (ကြိ) လည်းရှု။ || “ယာံရပ္တေဟ်ဗယဵုညးတုဲ သၠေဟ်ပၟာဒၟံၚ်တုဲ ဓဝ်မိတ်ဂှ် ဗွဲပြဟ်ဟေၚ် ဍေံလီုအာရ။” (ဇ—၃၆၁။ အစွောံ။) = “သူတစ်ပါး၏ကုန်းချောမှုကိုယုံ၍ ယုံမှားသံသယဖြစ်နေပါက အဆွေခင်ပွန်းတရားသည် လျင်မြန်စွာပျက်၏။”')
,(10369,3,1,'ကုန်းတိုက်သောစကား။','“ဍေံဟီုဂလာန်ဗယဵုရောၚ် မုဂ္ဂလာန်” သာရိပိုတ်ဂး။ (ဇ—၃၆၁။ အစွောံ။) = “မောဂ္ဂလာန်၊ သူသည် ကုန်းတိုက်သောစကားကိုဆို၏” ဟုသာရိပုတ္တရာဆို၏။ || “ယွံအ္စာပိုဲ၊ ဟိုတ်အဲပ္တေဟ်ဂလာန်ဗယဵုအမာတ်တံဂှ်တုဲ မဒးဖအောဝ်အမာတ် ကဵုဂစိုတ်တၠအဲဟွံမွဲကဵုဒုဟ်ဂှ် အဲကလအ်ရ။ ဒုဟ်ဂှ် အေၚ်ဒုၚ်ကဵုအဲညိရ” သၟိၚ်ဂး။ (ဇ—၅၂၈။ အစွောံ။) =“ဆရာ၊ ငါသည် ထိုအမတ်တို့၏ ကုန်းတိုက်သောစကားကို ယုံမိသောကြောင့် အပြစ်မရှိသောသင့်အားသတ်စေရန် အမတ်တို့ကို ငါစေခိုင်းမိ၏။ ထိုအပြစ်ကို သင်သည်းခံပါလော့” ဟုမင်းဆို၏။')
,(10370,3,1,'ဆာလောင်ငတ်မွတ်ခြင်း။','“တၞဟ်နဗလးဗယဵုတဟၚ်ညိဂးတုဲ ပိုဲပပြဘိုက်ပုၚ်ဍာ်ရ။” = “ဆာလောင်ငတ်မွတ်ခြင်း ပြေပျောက်စေရန်အတွက် ငါတို့ဆန်ပြုတ်သောက်ကြသည်။” || “(ကၠဵုဂှ်ဍေံစစၞဂှ်တုဲ) ဗယဵုတဟၚ်ဍေံဟွံဟဲတုဲ ဍေံကဳတိုန်ပၠန်ရ။” (ဇ—၄၆၉။ အစွောံ။) =“ထိုခွေးသည် ထိုအစာကို စားပြီး၍လည်း ဆာလောင်မွတ်သိပ်ခြင်းမပြေသဖြင့် ဟောၚ်ပြန်၏။” || “တၞဟ်နသ္ဂောံပၠေၚ်ကၠေံဗယဵုတဟၚ် န်ပိဏ္ဍပါတ် ပ္ဍံအဲသိပ်ဂၠိပ်ပပြဘိုက်ရ။” (ပြကိုဟ်ဒ္ဂေတ်ပဋိပတ်သာမဏဳ။ မာံရွှေငိုး။) = “ဆာလောင်ခြင်း ရေငတ်ခြင်းကို ပယ်ဖျောက်ရန်အလို့ငှာ ဆွမ်းကို ငါမှီဝဲသုံးဆောင်၏။”')
,(10371,3,1,'အနည်။ အနည်အနှစ်။',NULL)
,(10372,3,1,'ကစားစရာ။ (a plaything)',NULL)
,(10373,3,1,'အသံ။','“ဗရုဝွံ မူဗရုရော။” = “ဤအသံသည် ဘာအသံပါနည်း။” || ဗရုဇိုၚ်= ခြေသံ။ || ဗရုတွိၚ်တွိုက် = တူရိယာတီးမှုတ်သံ။')
,(10373,3,4,'အသံပြုသည်။','“ကၠာလကျာ်ဟွံကဵုပိုန်ဏီညးဗရုခၞုက်ရ။” = “ဘုန်းကြီးဆွမ်းမဘုဉ်းမီ ကုလားတက်တီးပြီး အသံပြုသည်။” || ‘ဗြု’ (ကြိ) လည်းရှု။')
,(10374,3,1,'နှုတ်သံ။ စကားပြောသံ။','“ဗရုပါၚ်ဍေံ အဲဂွံမိၚ်ဒၟံၚ်ရ။” = “သူ့အသံကို ငါကြားနေရသည်။”')
,(10374,3,4,'နှုတ်သံပြုသည်။ အသံပြုသည်။ စကားပြောသည်။','“အပါသ္တိက်ဒၟံၚ်၊ လ္ပဗရုပါၚ်ထတ်ထတ်ညိ။” = “အဖေအိပ်နေသည်။ အသံကျယ်ကျယ်ဖြင့် စကားမပြောပါနှင့်။” || “ခမဳမွဲဗရုပါၚ် ဟွံတီကဵုပယာံကာလ။” (ဇ—၁၁၉။ အစွောံ။) = “တယောက်သော အချိန်မဟုတ်သည်­ အသံပြုတတ်သောရဟန်း။” (ညောင်ကန်)')
,(10375,3,1,'အသံဗလံ။ မြည်သံ။ ဆူညံသံ။','“ပ္ဍဲသ္ၚိဂှ် သ္ၚိတ်ဇြဒၟံၚ် ဗရုဗရန်ဟွံမွဲရ။” = “ထိုအိမ်­ အသံဗလံမရှိ တိတ်ဆိတ်နေသည်။” || “(သွက်စံၚ်ပူဇဴယတ်ဂှ်) အာကေတ်သတ်တိရစ္ဆာန်တံဂှ်ဗရုဗရန်ဟၟဲရ။” (ဇ—၃၁၄။ အစွောံ။) = “ယဇ်ပူဇော်ရန် တိရစ္ဆာန်များကို သွား၍ယူသောအခါ (ငိုကြွေး) သံများမရှိ။” || “ဥပ္ပးအရဳမသုန်ကၠံဂှ် ကၞပ်ဒၟံၚ်ရ။ ဟွံမွဲကဵုဗရုဗရန်ရ။ လ္ၚုဇကုတုဲ ပ္ကီုတဴလွဳရ။” (ဇ—၁၈၃။ အစွောံ။) = “ငါးရာကုန်သော အရိယာဒါယကာတို့သည် အသံမပြုဘဲ ငြိမ်သက်စွာနေကြကုန်၏။ တစ်ကိုယ်တည်း ငြိမ်းအေးစွာနေ၍ တရားအားထုတ်ကြကုန်၏။” || ဗြုဗြန်’ (ကြိ) လည်းရှု။')
,(10376,3,1,'ပဲ့တၚ်သံ။ ပဲ့တၚ်ထပ်သံ။','“သတြုအဲကွေံရောၚ်သွံ (ဇာဒိသိုၚ်) လဝ်စိုတ်တုဲ ဒေါသဇၞော်က္ဍၚ်အာ ဂစာန်ဒြဟ်ရ။ ဗရုလလောၚ်ကမၠိုၚ်တေံဗြုတုဲကီု မိၚ်ဗရုလမၠောၚ်ကမၠိုၚ်ဂှ်တုဲ ဒေါသသ္ကာတ်က္ဍၚ်အာတုန် ဇၞတ်ဇၞတ်မဂစာန်ဒြဟ်က္ဍၚ်အာဂှ် ဂဍောၚ်ကအ်ဒကးသြိုဟ်ဒကး သၟိၚ်ဇာဒိသိုၚ်ဒးပကာဂစိုတ်။” (သၠပတ်ပုံပမာ။ အစွောံ။) = “ငါ့ရန်သူတည်းဟု ခြင်္သေ့နှလုံးသွင်းလျက် ဒေါသမာန်ဟုန်ဖြင့် အားကုန်အော်၍ဟောက်၏။ ရေတွင်းမှ ပဲ့တၚ်ထပ်သံကိုကြားလျှင် ဒေါသပိုမိုပြင်းထန်လာပြီး တအားအော်ဟစ်ကာ ဟောက်ရင်းဟောက်ရင်းဖြင့် ခြင်္သေ့သည်အာခေါၚ်ကွဲရၚ်ကွဲ၍ သေရလေ၏။” || ‘လလောၚ်’ (ကြိ) ၊ ‘လမၠောၚ်’ (န) တို့လည်းရှု။')
,(10377,3,4,'ဖျန်းသည်။','ဗရဲဍာ် = ရေဖျန်းသည်။ || “ညံၚ်မၚ်ဗၠာဲမွဲ တဵုကြက်စလန် ဗရဲဖဍာ်ဝဳပရာ။” (သၠပတ်သတိပထာန်) = “တစ်ယောက်သောလုလင်ကဲ့သို့ စန္ဒကူးနံ့သာကိုစိုက်ပျိုး၍ ရေဖျန်းရေလောင်းကာ (အပင်ကို) မွေးမြူ၏။” || “လတိုပ်ဗရဲ၊ သၟဟ်မဗြဲပၠန်။” (လိက်ဇိဝှစက္က) =“မိုးပေါက်ပမာ ဆီးနှင်းဆွတ်ဖျန်းသည်။”')
,(10378,3,4,'(လှေ၊ သင်္ဘော) မှောက်စေသည်။','“ၜါမိကဵုကောန် ဍိုက်ကျအ်လှောင်မှာသၟိတ်၊ဇွိုန်လပှ်ဒမြိုဟ် မတဴပ္ဍဲမှာသၟိတ် ဗရံကၠေံကျံဂှ်ရ။” (သၠပတ်သတိပထာန်) = “သားအမိနှစ်ဦးတို့သည် လှေငယ်လေးစီး၍ သမုဒ္ဒရာဖြတ်ကူးကြရာ သမုဒ္ဒရာရှိ ကြမ်းကြုတ်သောလှိုင်းတံပိုးတို့ကထိုလှေငယ်လေးကို မှောက်သွားစေခဲ့၏။”')
,(10379,3,1,'ထုံးအိုင်။ ရေစီးဝၚ်စုဝေး၍ ဖြစ်ပေါ်သောရေအိုင်ကြီး။','“ပ္ဍဲသ္ကဲလအိတ်ဗ္ၚဂှ် ဗရော်ဍာ်ဇၞော်မွဲမၞုံ။ ပ္ဍဲဗရော်ဂှ် ဂတာံထဝ်မွဲ ဇၞော်တၟာပ္ၚာန်သွဂှ်နွံ။” (ဇ—၃၈၉။ အစွောံ။) =“လယ်၏အစွန်း­ ကြီးစွာသောထုံးအိုၚ်သို့ ကပ်၏။ ထိုထုံးအိုၚ်­ ရွှေအဆင်းနှင့်တူသော တစ်ခုသောပုစွန်သည် နေ၏။” (ညောင်ကန်)')
,(10380,3,1,'သုံးမြှောက်မြက်။','“ခမှောံဗရံက်၊ မံက်ဍာ်သဝ်သဝ်။” (လိက်ပထမဗောဓိ။ မၚ်ဍိက်လ။)')
,(10381,3,4,'ယို့တီးယို့တို့ရှိသည်။ ရွံ့တီးရွံ့တွန့်ရှိသည်။ တွန့်ဆုတ်သည်။ ဆုတ်နစ်သည်။ (ပါဠိ—ဝိတ္ထာယတိ)',NULL)
,(10382,3,1,'စိတ်ကြည်နူးခြင်း။ စိတ်ရွှင်လန်းခြင်း။ နှစ်သက်ခြင်း။',NULL)
,(10383,3,1,'‘ဗမြိုက်မတ်’ ရှု။',NULL)
,(10384,3,1,'အစပ်။ အနီးအနား။ ဝန်းကျင်။ (?)','“ပ္ဍဲဒေါဝ်ဂြိုပ်ဂၞိၚ်၊ ဗရိၚ်ဇိုၚ်ဝါ။” (လိက်ဗြရတ်ဣဏၚ်ကၚ်ရဳ) = “လယ်ကွင်းစပ်အနီး တောမြိုင်လယ်­။” || “ဗရိၚ်မိအဴ၊ မၚ်တဴညးအဲ။” (လိက်ကောန်သၟိၚ်ပိ။ မာံခစုန်အံက်။) = “မယ်၏အနီးအနား­ သူသူငါငါ စောင့်နေကြကုန်၏။”')
,(10384,3,1,'အသံ။ (?)','“ဂၚ်ယွံဂၚ်္ဂါ၊ မှာသၟိတ်ကွိၚ်။ ဗရုလွိၚ်၊ ဗရိၚ်သဒ္ဒ။” (လိက်ကောန်သၟိၚ်ပိ။ မာံခစုန်အံက်။)')
,(10385,3,4,'နှာနုတ်သည်။ နှာနှတ်သည်။ (မေ့မြောနေသူကို ကွမ်းရွက်နံ့၊ ရေမွှေးနံ့စသည်ပေး၍ သတိရအောင်လုပ်သည်။) (ပါဠိ—နတ္ထုကမ္မ)',NULL)
,(10386,3,1,'ကြေးသတ္တု။ ကြေးဝါ။ (ပါဠိ—အာရကူဋ)',NULL)
,(10387,3,1,'ကျောက်ရောဂါ။','‘မြန်’ ရှု။')
,(10388,3,1,'သန်ကောင်။','‘မြုန်’ ရှု။')
,(10389,3,3,'(ကျားသစ်ကဲ့သို့) အစက်အပြောက်ဖြစ်သော။','“လဗြဴအာရံၚ်ပ္ဍဲကတိုၚ်ဂှ် ညာတ်ကၠောန်ကၠိက်ဗရောန်စောန်ၜါတံဂှ်တုဲ—။” (ဇ—၃၈၈။ အစွောံ။) = “အဖွားအိုသည်ထိုတွင်း­သွားကြည့်ရာ အစက်အပြောက်အဆင်းရှိသော ဝက်သားလေးနှစ်ကောင်တို့ကိုတွေ့၏။”')
,(10390,3,1,'ချုံနွယ်ပိတ်ပေါင်း။ ချုံတော။',NULL)
,(10391,3,4,'ဖြူးသည်။ ကြဲချသည်။','“နူကဵုဒမၚ်ဇြပ်ဂှ် ကလော်ဂှ် ကနှိက်ကြကောတ်မဇိပ်ဂၠိပ်ဍေံဖရုဲဖျေံရ။” (ဇ—၁၅၅။ အစွောံ။) = “ဇရပ်ထုပ်လျောက်ပေါ်မှ ထိုဘီလူးသည် သိမ်မွေ့သောအမှုန့်ကို ဖြူးချ၏။” || “ကနှိက်မပ္တံအိက်ဂၠဴဇမ္ကဟ် ဂစာဲဗရုဲဗဗွဲလၟေၚ် နကျာပါၚ်ကီုလေဝ် ဗ္ဂိုဟ်ဗ္ဂဵုသိုက်သိုက်တုဲ သၞပၟတ်မဂၠိုၚ် ရဴမက္တဵုဗဒှ်ကီု။” (ဇ—၄။ အစွောံ) = “နွားချေးခြောက်အစရှိသည့်အမှုန့်တို့ကို အစဉ်သဖြင့်ကြဲဖြူး၍ နှုတ်လေဖြင့် ဖြည်းဖြည်းမှုတ်သဖြင့် ကြီးစွာသောမီးလျှံကိုဖြစ်စေနိုင်သကဲ့သို့။” || “မြမောဝ်ဒိပ်ဂှ် ဗရုဲစုတ်လဝ်တုဲ—။” (ဇ—ဘူရိဒတ်။ အစွောံ။) = “နတ်­ ဖြစ်သောအမွှေးနံ့သာကို ဖြူးထည့်၍—။”')
,(10392,3,1,'ပျားရည်စက်။ (?)','“လတူကၞာၚ်ဇြဲတေံဂှ် သာဲဂမၠိုၚ်ဒက်သ္ၚိဂှ်တုဲ ဗရုဲဍာ်သာဲဂှ် ပြဟ်စှ်ေဒးတၞုၚ်ကၟတ်ဂှ်တုဲ—။” (ဇ—၂၅၇။ အစွောံ။) = “ထိုညောင်ကိုင်းထက်­ ပျားများအိမ်ဖွဲ့၍ပျားရည်စက်များသည် အောက်သို့ကျ၍ မြက်ဖျားတို့­ထိ၏။”')
,(10393,3,4,'ထုတ်လွှတ်သည်။ ဖြာထွက်စေသည်။','“ဂွံဇၞးမာတုဲကၠာ၊ နာဲသာကျမုဏိ။ ဗရုဲပ္တိတ်လျးတြဴ၊ ခၠၚ်တဴဒိုဟ်သ္တုံဇွိ။” (လိက်ဗြရတ်ဣဏၚ်ကၚ်ရဳ။ မာံရောဂေါ။) = “မာရ်စစ်ကိုအောင်နိုင်တော်မူပြီးနောက် သကျမုနိမြတ်စွာဘုရားသည် ရောင်ခြည်တော်ခြောက်သွယ်တို့ကို ထုတ်လွှတ်တော်မူရာ လက်ရာလက်ဝဲအရပ်မျက်နှာအားလုံး လင်းထိန်သွား၏။”')
,(10394,3,1,'(ဟင်းချိုချက်ရာတွင်) အရသာအလို့ငှာထည့်သော သားငါးစသည်။','“ဍုန်သွဂစေပ်ဂှ် မူဗရဵုမွဲစုတ်ရော။” = “ချဉ်ပေါင်ဟင်းချက်ရာတွင် ဘာအသားကို အရသာတက်အောင် ထည့်ချက်မည်နည်း။”')
,(10394,3,4,'အရသာတက်အောင် (သားငါးတစ်ခုခုဖြင့်) ထည့်ချက်သည်။','“ဍုန်သွဂစေပ်ဂှ် ဗရဵုလဝ်ကောန်ၚုဲ။” = “ချဉ်ပေါင်ဟင်းချက်ရာတွင် ပုစွန်ဆိပ်ဖြင့် အရသာတက်အောင်ထည့်ချက်ထားသည်။”')
,(10395,3,10,'(န) ခွန်အား။ အစွမ်း။ ဗလ။','ကာယဗလ၊ ညာဏဗလ = ကိုယ်စွမ်းညာဏ်စွမ်း။ || အပေါတ်ဗလိဒေဝတဴ = နတ်ပူဇော်ရန် ဝတ္ထုပစ္စည်း။')
,(10396,3,10,'(ကြိ) နတ်ပူဇော်သည်။ ပူဇော်ပသသည်။','“အဲသမွဲကြန်လဝ်ကဵုဒေဝတဴဂှ် အဲသ္ဒးဗလိဒေဝတဴရ။” (ဇ—၅၃၇။ အစွောံ။) = “ငါသည် နတ်နှင့်ကတိပြုထားသဖြင့် နတ်ကို ပူဇော်ပသရတော့မည်။” || “ဆီကအ်ဍေံဂှ် ဗလိဒေဝတဴတုဲ—။” (ဇ—၄၈၁။ အစွောံ။) = “သူ့လည်ချောင်းသွေးကို နတ်ပူဇော်၍—။”')
,(10397,3,4,'နတ်ပူဇော်သည်။ ပူဇော်ပသသည်။','‘ဗလိဗကဝ်’ နှင့်အတူတူ။ || “ဖေက်ရပ်စတုဲမဒးဗလိဂပဝ်ဗစဖျုၚ်ကလော်ဂှ် သရဏဟွံလီုရ။” (ပြကိုဟ်ဓမ္မရာသဳ။ မာံရွှေငိုး။) = “ဖမ်းစားမည်ကိုကြောက်၍ နတ်ပူဇော်ပသရခြင်းသည် သရဏဂုံမပျက်။” || “ယွံဒေဝတဴ၊ ကဵုပိုဲဂွံဗၠးဂစိုတ်ညိ။ ယာံပိုဲဂွံဗၠးဂစိုတ်တုဲ ပိုဲဗလိဂပဝ်ဒေဝတဴရ။” (ဇ—၁၉၃။ အစွောံ။) = “အရှင်တောင်စောင့်နတ်မင်း၊ အကျွန်ုပ်သည် လၚ်နှင့်တကွ အန္တရာယ်ကင်းသည်ဖြစ်၍ အသက်ကို အကယ်၍ရပါအံ့၊အရှင့်အား ပူဇော်ပသသောအမှုကို ပြုပါအံ့။” (ညောင်ကန်) || “ဒှ်ဆုမယေအ်ရောၚ်။ ဇန်တံညးဂမၠိုၚ် ဗလိဂပဝ်ပူဇဴတဴလၟိုန်ရောၚ်။” (ဇ—၄၆၅။ အစွောံ။) = “တောစိုးသစ်ပင်ဖြစ်၏။ လူအပေါင်းတို့သည် အမြဲပူဇော်ပသကြကုန်၏။”')
,(10398,3,4,'နတ်ပူဇော်သည်။ ပူဇော်ပသသည်။','“မၞိဟ်တံဂမၠိုၚ် ဍေံဗလိဗကဝ်ဒေဝတဴဂှ် ဗ္ၜေံဗမာဗ္ၜေံဂလာတံဂှ်ဂစိုတ်တုဲ ဍေံဗလိဗကဝ်ကလော်ဒေဝတဴရ။” (ဇ—၃၄၇။ အစွောံ။) = “လူတို့သည် နတ်တို့ကို ကိုးကွယ်ကုန်၍ များစွာကုန်သော ဆိတ်မြန်မာ၊ ဆိတ်ကုလား အစရှိသည်တို့ကိုသတ်၍ နတ်တို့အားပူဇော်ခြင်းကို ပြုကုန်၏။” (ညောင်ကန်) || “မၞိဟ်ဂမၠိုၚ် ဍေံအာဗၞိက်ဂးတုဲဍေံတံဂစိုတ်လမျီုသတ်တုဲ ဍေံဗလိဗကဝ်ဒေဝတဴတုဲ—။” (ဇ—၁၉။ အစွောံ။) = “လူတို့သည်ကုန်သွယ်အံ့သောငှာ သွားကုန်လတ်သည်ရှိသော် သတ္တဝါတို့ကိုသတ်ကုန်၍ နတ်တို့အား ပူဇော်ခြင်းအမှုကို ပြုကုန်၍—။” (ညောင်ကန်)')
,(10399,3,4,'နတ်ပူဇော်သည်။ ပူဇော်ပသသည်။','“ဟာဲအယုတ်၊ ဟာဲဗြဴဒွိုက်၊ တ္ၚဲဝွံ အဲဂွံဂစိုတ်ဗမၞး (တြုံသ္ကဲ) ဗှ်ေဂှ်တုဲ အဲဂွံဗလိဗဇဴဒေဝတဴဂှ်ရ” ပြောဟိတ်ဂး။ (ဇ—၄၈၁။ အစွောံ။) = “ဟယ်အယုတ်မ၊ ဟယ်မိန်းမယုတ်၊ ယနေ့ငါသည် နၚ်၏သယောက်လၚ်ဖြစ်သော ပုဏ္ဏားကိုသတ်၍ ဗလိနတ်စာပူဇော်အံ့” ဟုပုရောဟိတ်ဆို၏။')
,(10400,3,10,'(န) စိုးရိမ်ကြောင့်ကြခြင်း။ ပလိဗောဓ။','“ညးမပဒတဴပ္ဍဲသ္ၚိကၟိန်တံဂှ်ဂၠိုၚ်ကဵုဗလိဗောဓအိုတ်ရ။” = “အိမ်ထောင်­ နေသူများသည် များစွာသောကြောင့်ကြမှုရှိကြကုန်၏။”')
,(10401,3,4,'မှောင်ရီသည်။ အုံ့မှိုင်းသည်။','“ဒဂဵုဂတးသက်ကဵုကာလ ပန်ပတုံဒြၚ်တၟံ လျးတ္ၚဲဂၠုဗလဳဒၟံၚ် ဗြဲသက်ကဵုကာလဗ္ဂူဖျေံ။” (အာန်ဇုနာန်) = “အချိန်အခါမဟုတ်သောမိုးကြိုးသည် ကျောက်စွန်းကိုပစ်ချပြီး နေရောင်မှောင်ရီနေ၏၊ အချိန်အခါမဟုတ်သောမိုးရွာချ၏။”')
,(10402,3,1,'ဂေါ်လီလုံး။ (ကစားစရာ) (ပါဠိ—ဂေါဠက)',NULL)
,(10403,3,1,'၁။ ရေခတက်ပင်။',NULL)
,(10403,3,1,'၂။ လက်ရန်း။ လက်ကိုင်တုတ်။ လက်ဖြင့်ကိုင်ပြီးသွားရန် အကာအရံ။',NULL)
,(10404,3,4,'၁။ အားပြုပြီးမှီတွယ်သည်။','“ထဴဗျုဂှ် ဗလဲဇုက်သလဲတုဲ ကွာ်အာဍိုန်ဍိုန်ရ။” =“အဖိုးအိုသည် လက်ရန်းကြိုးကိုအားပြုပြီး ဖြည်းဖြည်းလျှောက်သွားသည်။” || “ဂၠဴဂှ် ပ္ဍဲဒြၚ် ပ္ဍဲကတောဝ် ပ္ဍဲကအ် ကောန်ၚာ်တံဗလဲဝေၚ်။” (ဇ—၂၉။ အစွောံ။) = “ထိုနွားကို ဦးချို­၄င်း နား­၄င်း လည်­၄င်း ကလေးများမှီတွယ်ကစားကုန်၏။” || “ကောန်သၟိၚ်ဟဳအာ ဂွံတၞံဆုကြိက်မွဲ ဗလဲဒၟံၚ် သီုမယာံတဴ ဟဳအာရ။” (ဇ—၇၃။ အစွောံ။) = “မြစ်ထဲ­မျောသောမင်းသားသည် တစ်ခုသောလက်ပံပင်သစ်တုံးကိုရ၍ မှီတွယ်လျက် ငိုကြွေးရင်းမျောသွား၏။”')
,(10404,3,4,'၂။ ဆွဲချသည်။ ဆွဲငင်သည်။','“မၚ်ဗၠာဲလၞုဟ်ဂှ် ဒွါန်တိုန်ဆုဗလဲ ရပ်ကၞာၚ်မွဲ ဗလဲဖျေံမဒ္ဂူကဵုဇကုရ။” (ဇ—၇၁။ အစွောံ။) = “ပျင်းရိသောလုလင်သည် ရေခံတက်ပင်သို့တက်ပြီးလျှင် သစ်ခက်တို့ကိုကိုင်၍ မိမိသို့ရှေ့ရှုငင်၏။” (ညောင်ကန်)')
,(10405,3,4,'လည်ကိုဖက်သည်။','“ယာတ်ချီုမွဲသၠောံစရိုတ် တဲဗလဲကအ်တၠသ္ၚိတုဲ အဲသၟိက်ဂွံဝေၚ်သဘၚ်နက်သတ်ညိအဴ” သမ္ဘာဂှ်ဂး။ (ဇ—၁၄၇။ အစွောံ။) = “ဝတ်ပန်းဆိုးအဝတ်ကိုဝတ်ရုံ၍လက်ဖြင့်လၚ်၏လည်­ဖက်တွယ်ကာ နက္ခတ်ပွဲသဘင်ကစားလို၏” ဟုမယားဆို၏။')
,(10406,3,1,'‘ဗလောဲကျာ’ ရှု။',NULL)
,(10407,3,1,'‘ဗလောဲဍာ်’ ရှု။',NULL)
,(10408,3,1,'တောင်နံဘေး။ (?)','“ဗက်အာဗလဲဗလဲဒဵု။” (သၠပတ်စန္ဒဝတဳ)')
,(10409,3,4,'၁။ လွှတ်သည်။ လွတ်မြောက်စေသည်။','“ပ္ဍဲဍုၚ်သေံ တ္ၚဲဨကရာတ်ဒှ်မၞိဟ်ဂှ် ညးဗလးကၠေံကောန်ထံၚ်မဂၠိုၚ်ရ။” = “ထိုင်းနိုင်ငံတွင် ဘုရင့်မွေးနေ့­ ထောၚ်သားများစွာကို လွှတ်ပေးသည်။” || “ပ္ဍဲကာလအတိက်တေံလေဝ် (သၟတ်ဗြဴဂှ်) ဂွံဗလးတၠပညာနူဂစိုတ်တုဲရ။” (ဇ—၃၅၉။အစွောံ။) = “ရှေး­လည်း ထိုအမျိုးသမီးငယ်သည် ပညာရှိတို့အား သေဘေးမှလွတ်မြောက်စေဖူးပြီ။”')
,(10409,3,4,'၂။ သံသရာဝဋ်ဆင်းရဲမှ လွတ်မြောက်စေသည်။ ကယ်ချွတ်သည်။','‘ယွံကျာ်တြဲမဒှ်တဳလ ညးမဗလးလိုက်ဂမၠိုၚ်—။’ (ဇ—၄ဝ၉။ အစွောံ။) = ‘သတ္တဝါအပေါင်းတို့အား (သံသရာဝဋ်ဆင်းရဲမှ) လွတ်မြောက်အောင် ကယ်ချွတ်တော်မူသော ရှင်တော်မြတ်စွာဘုရား။’')
,(10410,3,4,'မိမိကိုယ်ကို လွတ်မြောက်စေသည်။','“ဘဲအန္တရာဲက္တဵုဒှ်မ္ဂး ဒဴဗလးဇကုညံၚ်ဗၠးညိ။”= “ဘေးအန္တရာယ်ဖြစ်လတ်သော် မိမိကိုယ်ကိုလွတ်အောင် ရှောင်ပြေးပါလေ။”')
,(10411,3,4,'ဒုက္ခမှလွတ်စေသည်။ ကယ်ဆယ်သည်။','(သၟတ်ဗြဴဟဳဒၟံၚ်ပ္ဍဲဍာ်ဂှ် ဗောဓိသတ်ညာတ်တုဲ “အဲဗလးဒဒိုက်မာတုဂံါဝွံညိ” ဗောဓိသတ်ချပ်။ (ဇ—၆၃။ အစွောံ။) = (မြစ်ရေတွင်မျောနေသော အမျိုးသမီးငယ်ကိုမြင်၍ “ဤမိန်းမကို ဘေးဒုက္ခမှကယ်တင်အံ့” ဟုဘုရားလောင်း')
,(10413,3,4,'အပြစ်လွှတ်သည်။','“အဲဟွံတီတုဲ အဲပဒးလဝ်ပွဒုဟ်တုဲရ၊ ဗလးဒုဟ်ကဵုအဲမွဲဝါညိ။”= “ ကျွန်တော်မသိသဖြင့် ကျွန်တော်ပြစ်မှုပြုမိပြီးပြီ၊ ကျွန်တော့်ကို တစ်ကြိမ်တစ်ခါ အပြစ်လွှတ်ပေးပါ။”')
,(10414,3,4,'လွတ်မြောက်အောင်လွှတ်သည်။ ရုန်းကန်လွတ်မြောက်သည်။','“သၟိၚ်ဝါရေဝ်ရောဝ်ခါကုသဵုမကဵုဖဵု ဂစိုတ်သၟိၚ်သုခေါဒါယဂှ်လေဝ် ဗလးဗၠး။ ဂစိုတ်သၟိၚ်ကမ္မလာနဳ သၟိၚ်အလိမာမၚ်သၟိၚ်တရာဗညာ သၟိၚ်ၚဝ်ဒဝ် သီုပရိုက်ဨကရာဇ်ပန်ဂှ်လေဝ် ဗလဗၠး။” (အကြီုရာဇာဓိရာဇ်) =“ဝါရီရူမင်းသည် ကုသိုလ်ကံအကျိုးပေးသောအခါ သောက္ကတဲမင်း၏သတ်ခြင်းမှလည်း မိမိကိုယ်ကို လွတ်အောင်လွှတ်နိုင်ခဲ့၏။ ကမ္မလာနီမင်း၊ အလိမ္မာမင်း၊ တရဖျားမင်း၊ ေငါ်ဒေါမင်းဟူသောမင်းလေးပါးတို၏သတ်ခြင်းမှလည်း လွတ်အောင်လွှတ်နိုင်ခဲ့၏။”')
,(10415,3,4,'ဘေးအန္တရာယ်မှ လွတ်မြောက်စေသည်။','“သၟိၚ်ဒကောတ်တလဇၚဳညာန် — သွက်မဂွံဗလးဘဲ ဂမြေၚ်ကျာမွဲ စဳရေၚ်လဝ်ရ။” (ဇ—၁၄၁။ အစွောံ။) = “ဉာဏ်အမြော်အမြင်နှင့်ပြည့်စုံသောဖွတ်မင်းသည် ဖြစ်ပေါ်လတ္တံ့သောဘေးမှ မိမိကိုယ်ကိုလွှတ်ရန် ကယ်ပေါက်တစ်ခုကိုစီရင်ထားရှိ၏။”')
,(10416,3,4,'ရောဂါပျောက်ကင်းစေသည်။','“တၞဟ်နသ္ဂောံဝဳဗလးယဲအေအာၚ်ဒဳအေတ် (သ်) ဂှ် ဂဥုဲဟွံမွဲဏီရ။” = “အေအိုင်ဒီအက် (စ်) ရောဂါကို ပျောက်ကင်းအောင်ကုသရန် ဆေးမရှိသေးပါ။” || ဂဥုဲမဗလးကဵုယဲ = ရောဂါပျောက်ကင်းစေသောဆေး။')
,(10417,3,4,'အသံလွှင့်သည်။','ဋ္ဌာန်ဗလးရမ်သာၚ်မန် = မွန်အသံလွှင့်ဋ္ဌာန။')
,(10418,3,4,'ချင်ခြင်းကို ပြေပျောက်စေသည်။ ဖြေဖျောက်သည်။','“အဲဖာပ်ဗမၞးဟွံသေၚ်၊ သ္ၚုမွဲတလတ်ဝွံ အဲဖျိန်စဗလးအၚပ်အဲရောၚ်၊ လ္ပကၠုၚ်” သေဋ္ဌဳဂး။ (ဇ—၅၃၅။ အစွောံ။) = “ပုဏ္ဏား၊ငါသည် သင့်အားကျွေးမည်မဟုတ်၊ ငါ၏ချင်ခြင်းကို ဖြေဖျောက်ရန်အလို့ငှာသာလျှင် ဤတစ်ပြည်သောဆန်ကို ချက်စားခြင်းဖြစ်၏၊ သၚ်မလာလင့်” ဟုသူဋ္ဌေးဆို၏။')
,(10419,3,1,'အမြောက်လက်နက်။','‘အမၠံက်’ ရှု။')
,(10420,3,1,'ဖုန်။','‘လမၠိုက်’ ရှု')
,(10421,3,4,'နစ်အောင်လုပ်သည်။ နှစ်သည်။ မြုပ်အောင်လုပ်သည်။ မြှုပ်သည်။','“ကျာံဂှ်ၜိၚ်အာညိတုဲ သၟိက်ဗလိုက်ဂစိုတ်ဗောဓိသတ် (ကၞုဲ) တုဲ တလီုဖျေံဇကုရ။” (ဇ—၃၄၂။ အစွောံ။) =“မိကျောင်းသည် အနည်းငယ်သွား၍ ဘုရားလောင်းမျောက်ကို ရေတွင်နှစ်သတ်လိုသဖြင့် ကိုယ်ကိုနှစ်ချ၏။” || ‘ဗၠိုက်’ (ကြိ) လည်းရှု။')
,(10422,3,1,'ဆီးနှင်း။ နှင်းပေါက်။ နှင်းဥ။','‘လမၠာၚ်’ နှင့်အတူတူ။ || “ညံၚ်ဗီုဍာ်ဗလာၚ်၊ တူထာၚ်ဒကှ်သွာ။” (လိက်ကကၠာ်။ ကောန်ဍး။) = “ကြာလက်ပေါ်ရှိ ဆီးနှင်းပေါက်ကဲ့သို့။”')
,(10423,3,1,'ဖြူကောင်။',NULL)
,(10424,3,1,'ပဲ့တၚ်သံ။','‘လမၠောၚ်ၜဳ’ ဟုလည်းရေးသည်။')
,(10425,3,4,'တစ်စုံတစ်ခုအပေါက်ကြားမှ အပြင်သို့လျှိုထုတ်သည်။','“(ကောန်ၚာ်ဂှ်) ဆဗမဴတှ်ဂှ်ကီု စဵုလဝ်ဇနိက်တုဲ ဆတှ်ညိကီု ဗလတ်ပ္တိတ်တုဲ မဂွံမဴတှ်ရောၚ်။” (ဇ—၂၆၃။ အစွောံ။) = “ထိုကလေးကား နို့တိုက်ရာတွင်လည်း တင်းတိမ်ကာရံ၍ တင်းတိမ်အကြားဖြင့် နို့မျှကိုလျှိုထုတ်မှသာလျှင် နို့ကိုစို့၏။”')
,(10426,3,4,'ရှောင်သည်။ တိမ်းရှောင်သည်။','“(ရသိစၞာဲဂှ် ရပ်လေံကၞဟ်ဂှ်တုဲ) ကၠဟ်ဏာဗောဓိသတ် (ဖရာပ်) ရ။ ဗောဓိသတ်ဗလေတ်ကၠေံတုဲ ကၠဟ်ဟွံဒး—။” (ဇ—၂၇၇။ အစွောံ။) = “ရသေ့စဉ်းလဲသည် ဆောက်ပုတ်ကိုကိုင်၍ ဘုရားလောင်းခိုအား ပစ်လွှတ်၏။ ဘုရားလောင်းသည်ကိုယ်ကိုရှောင်လိုက်၍ မထိမှန်။” || “ခါသၟိၚ်မပန်ဂှ် ဒြာဲဂှ်ဗလေတ်ကၠေံတုဲ ပန်ဟွံဒးရ။” (ဇ—၃၉၈။ အစွောံ။) = “မင်းသည် ပစ်ခတ်သည်ရှိသော် ထိုသမင်သည် ရှောင်တိမ်းလိုက်၍ ပစ်၍မထိ။” || “တၞဟ်နဗလေတ်ဗြဲ၊ ဆုမွဲဇၞော်လောန်။ သဓီုကၞာၚ်သၠ၊ လုပ်ပၠဗဒန်။” (လိက်သုဝဏ္ဏသာံ။ မာံသေၚ်။) = “မိုးကိုရှောင်ရှားရန်အလို့ငှာ အခက်အရွက်ဝေဆာသော သစ်ပင်ကြီးတစ်ပင်သို့ ဝင်ခို၏။” || ‘ဗၠေတ်’ (ကြိ) လည်းရှု။')
,(10427,3,4,'စိုက်ကြည့်သည်။','ဗလန်မတ် = မျက်လုံးပြူးပြီးကြည့်သည်။')
,(10428,3,4,'အနည်းငယ်မျှ လောၚ်ကျွမ်းသည်။',NULL)
,(10429,3,4,'လွန်စေသည်။','‘ဗလောန်ကၠေံၜါပိတ္ၚဲ။’ = ‘နှစ်ရက်သုံးရက်လွန်စေသည်။’')
,(10430,3,4,'ရေသပ္ပါယ်သည်။','“ပ္ဍဲသဘၚ်အတး ဗွဲအခိုက်ပြဝေဏဳမန် ဗလိုပ်ကျာ်ဗလိုပ်သၚ်အိုတ်ရ။” = “သင်္ကြန်ပွဲတော်တွင် မွန်တို့၏ထုံးတမ်းအစဉ်အလာအရ ဘုရားနှင့်သံဃာတော်များကိုရေသပ္ပါယ်ကြသည်။” || သဘၚ်ဗလိုပ်ဇြဲ = ညောင်ရေသွန်းပွဲ။ || ‘ဗၠိုပ်’ (ကြိ) လည်းရှု။')
,(10431,3,4,'၁။ ရေချိုးပေးသည်။','“ကောန်ၚာ်တအ်ဂှ် ဗလိုပ်ဖုံတုဲ ဗ္စထောံပုၚ်သွညိ။” = “ကလေးတွေကို ရေချိုးပေးပြီး ထမင်းဟင်းကျွေးလိုက်ပါ။”')
,(10431,3,4,'၂။ (အမွှေးနံ့သာ) လိမ်းကျံသည်။','“သၟတ်ဗြဴတုန်လေဝ် ဟွံဂွံဂ္ညိဂ္ညာတ်ကျိုၚ်ကျဝ် ဟွံဂွံဗလိုပ်ဖုံမြမောဝ်သက်က်ရ။” (ဇ—၁၂။ အစွောံ။) = “ထိုသူငယ်မသည်လည်း တန်ဆာဆင်ယင်ခြင်း အမွှေးနံ့သာလိမ်းကျံခြင်း လုံးဝမပြု။”')
,(10432,3,1,'အကြီးစားဖွတ်သတ္တဝါ။','‘ဒကောတ်’ လည်းရှု။ || “သၟိၚ်ဒကောတ်ဗလီုမွဲဂှ် ဇၞော်လောန်—။” (ဇ—၁၉၃။ အစွောံ။) = “တခုသောကြီးသောကိုယ်ရှိသောဖွတ်မင်းသည်—။ (ညောင်ကန်)')
,(10433,3,1,'စိမ့်စမ်း။',NULL)
,(10434,3,1,'မျက်တွင်း။ မျက်လုံးအိမ်။','“ဂၚ်ဗလာဲမတ်၊ ရာတီဇတ်ရော။” (လိက်မေဃသန်) = “ငါ၏မျက်လုံးအိမ်တည်းဟူသောမြစ်သည် ဘယ်သောအခါမှ ခန်းခြောက်ပါမည်နည်း။” (ဘယ်သောအခါ ငိုကြွေးရခြင်းသည် ဆုံးပါမည်နည်း။) || “တသေၚ်ဗရဲ၊ ဗြဲဗလာဲမတ်။” (လိက်ကောန်သၟိၚ်ပိ။ မာံခစုန်အံက်။) = “မျက်လုံးအိမ်မှမျက်ရည်မိုး ရွာသွန်းဖြိုး၏။”')
,(10435,3,1,'(မြစ်ချောင်း၏) အောက်အရပ်။ အကြေအရပ်။','ဗလောဲကြုၚ် = ချောင်း၏အကြေအရပ်။ || ဗလောဲဂၚ် = မြစ်၏အောက်အရပ်။ မြစ်အကြေအရပ်။ || “ပ္ဍဲဗလောဲဂၚ်ဂှ် ဗက်တိုန်အာဂွံကြုၚ်သၟတ်မွဲတုဲ ဗက်တိုန်အာရ။” (ဇ—၅ဝ၄။ အစွောံ။) = “ဂၚ်္ဂါမြစ်အကြေသို့ သွားပြီးလျှင် (ချောင်းငယ်တစ်ခုကိုရ၍ လိုက်တက်သွား၏။)” (ညောင်ကန်)')
,(10436,3,1,'လေစုန်။ လေကြေ။','“(ဗောဓိသတ်သၟိၚ်ဖရာပ်) ဗွဲဗလောဲကျာဂှ် အာတန်ဒၟံၚ်တုဲ အမြာဲဇကုရသိဂှ် ဆုၚ်ဒုၚ်သၟူတုဲ ဂွံအမြာဲဖျုန်ဖရာပ်ဂှ်ရ။” (ဇ—၂၇၇။ အစွောံ။) =“ဘုရားလောင်းခိုမင်းသည် လေကြေ­အရပ်နေ၍ ရသေ့စဉ်းလဲ၏ကိုယ်နံ့ကို ခံသည်ရှိသော် ခိုသားနံ့ကိုရ၏။” || “နထးထဝ်အနဂ္ဃၚုဟ်ဂှ် ကဵုစုတ်လဝ်ပုၚ် ညံၚ်ခၟောမ်မၠဵုတုဲ သီုကဵုအမာဲမဒးရးမောဝ်ပ္ဍးတမှာဲဒၟံၚ် ဒစးကျာဗလောဲကျာဂှ်ဒှ်တုဲ—။” (ဇ—၂၆ဝ။ အစွောံ။) = “အဘိုးအနဂ္ဃထိုက်သောရွှေခွက်­ စံပယ်ၚုံနှင့်တူသောထမင်းကို ထည့်ထားစေ၍ ကောင်းသောဟင်းလျာအမည်များနှင့်တကွ လေဆန်လေစုန်အရပ်တို့­ အလွန်မွှေးကြိုင်နေ၏။” || “(က္ၜၚ်ဒကးအာတုဲ) မၚ်ဗၠာဲဂှ် ဂွံဂတဵုက္ၜၚ်မွဲဂတှ်ေဂှ်တုဲ ဍိုက်မံၚ်ဂတဵုဂှ်တုဲ ဋ္ဌာန်ဗလဲကျာဂှ် ဟဳအာတုဲ—။” (ဇ—၃၆ဝ။ အစွောံ။) =“သင်္ဘောကွဲသွားပြီးနောက် လုလင်သည် ပျဉ်ချပ်တစ်ခုကိုစီးလျက် လေစုန်အရပ်ဆီသို့ မျော၍သွား၏။”')
,(10437,3,1,'စိတ်အလို။','“ယွံကောန်၊ သဘဴပိုဲဗြဴဂှ် ဗၞတ်မွဲဗ္တံကီု ဒှ်မွဲဂၞပ်ဂကောံတြုံတုဲမ္ဂး မဒးဗက်ဗွဲဗလောဲစိုတ်တြုံဂှ်ရောၚ်။” (ဇ—၅၃၁။ အစွောံ။) = “ချစ်သမီး၊ ငါတို့မိန်းမသားဆိုသည်မှာ တစ်ညတာမျှ ယောကျာ်းနှင့်တကွ အလိုတူပေါင်းဖက်ပြီးလျှင် ထိုယောကျာ်း၏စိတ်အလိုသို့ လိုက်ရ၏။”')
,(10438,3,1,'ရေစုန်။','‘ဗက်ဗလဲဍာ်၊ က္ၜၚ်ဒိပ်သာ်ဗၠဲ။’ (လိက်ဗောဓိသတ်စှ်။ ပဏ္ဍိတ။) = ‘ပုလဲရောၚ်အဆင်းရှိသော နတ်သင်္ဘောသည် ရေစုန်အတိုင်း လိုက်ဆင်းလာ၏။’ || “ယဝ်အဲဟွံဒှ်ကျာ်မ္ဂး ထးထဝ်ဝွံ ကဵုစှ်ေအာဗလောဲဍာ်ညိ” ကောန်သၟိၚ်သဳဓတ်ပအဓိဋ္ဌာန်။ (ဗုဒ္ဓဝၚ်။ မာံရွှေငိုး။) = “အကယ်၍ငါသည် ဘုရားမဖြစ်ပါက ဤရွှေခွက်သည် ရေစုန်အတိုင်း ဆင်းသွားပါစေသတည်း။”')
,(10439,3,4,'(လေ) တိုက်ခတ်သည်။',NULL)
,(10440,3,4,'မိုမောက်သည်။','“ယဲစၟေၚက်၊ ကၞိၚ်ဝေက်ဗလုဟ်။” (လိက်ပယးအနိစ္စ) = “သွားပိုးရောဂါဖြစ်၍ ပါးရွဲ့စောင်းမိုမောက် ရောင်ရမ်းလာ၏။”')
,(10441,3,1,'ကိုယ်နံ့နံသော တောကြောင်အငယ်စားတစ်မျိုး။','“ကၞုဲဂၚ်ဝုတ်အဵု၊ ဗၜဵုဗဝါ။” (လိက်ပထမဗောဓိ။ မၚ်ဍိက်လ။) = “မျောက်၊ မျောက်ညို၊ မျောက်လွှဲကျော်နှင့် တောကြောင်အကြီးစားအငယ်စား။”')
,(10442,3,4,'ဟိုဘက်ဒီဘက်လွှဲသည်။','ဗဝုဲသရေၚ် = ပုခက်လွှဲသည်။ || “ခုဇ္ဇာဖအုဲ၊ ဗွုဲသရေၚ်ဖျာ။ ဒယှ်ေဖလှိၚ်၊ တွိၚ်ပါၚ်သဒ္ဒါ။” (လိက်ဇိဝှစက္က) = “အထိန်းတော်မသည် သီချင်းညည်းလျက် ပုခက်လွှဲကာ နှုတ်သီချင်းသံဖြင့် သီဆိုချော့သိပ်၏။” || “ပါၚ်ဒယှ်ေသ္ကဲ၊ တဲဗဝုဲကၠာ။” (လိက်ဇိဝှစက္က) = “နှုတ်ကသီဆို၍ လက်က ပုခက်ကိုလွှဲ၏။” || “မိမိန်ဗဴလေၚ်၊ ဗွုဲသရေၚ်ထဝ်။” (လိက်ပထမဗောဓိ။ မၚ်ဍိက်လ။) = “အထိန်းတော်မတို့သည် ရွှေပုခက်ကိုလွှဲကုန်၏။”')
,(10443,3,1,'အစုအပုံ။ အစုအအုံ။','ဗွဝ်သြောအ် = စပါးပုံ။ || ‘ဗွဝ်ကဂမၠိုၚ်ပ္ဍဲဍာ်ၜဳ။’ = ‘ပင်လယ်ထဲရှိ ငါးများအစုံအအုံ။’')
,(10443,3,4,'စုပုံသည်။','“ဂၠိက်ယာတ်ဗွဝ်လဝ်တံဂှ် ကဆံၚ်ထောံညိ။”= “စုပုံထားသော အဝတ်အစားများကို လျှော်ဖွပ်လိုက်ပါ။”')
,(10444,3,1,'ဝှေးစေ့။',NULL)
,(10445,3,1,'မိုဟာမက်ကုလား။','‘ဂလာပသိ’ ရှု။ || “သေံဗမာပၠန်၊ ကၠေဝ်မန်ဗသဳ။” (လိက်မေဃကောန်ဒြာဲ) = “ထိုင်း၊ ဗမာ၊ တမီ၊ မွန်နှင့်မိုဟာမက်လူမျိုးများ။”')
,(10446,3,1,'ခြေရာ။ ခွာရာ။','“တိဗသေက်ဇိုၚ်ဂၠဴမ္ဂးဂှ် လၟုဟ်ညးကော်စ တိဒၞာဲဇိုၚ်ဂၠဴရ။” (တြာဲဝိနယသၚ်ရိုဟ်ဂြဳ။ စန္ဒိမာ။)')
,(11871,3,1,'သရဖူ။ (?)','“ဗောဓိသတ် (သၟိၚ်ပဒုမ) သလိုက်ၝောံကိုတ်၊ ဗြကၞေၚ်၊ ဗသေၚ်၊ တဝ်စရှ်တုဲ—။” (ဇ—၁၉၃။ အစွောံ။) = “ဘုရားလောင်းပဒုမမင်းသည် မကိုဋ်၊ နဖူးတန်ဆာ၊ သရဖူ၊ ဦးဆောက်ပန်းတို့ကို တန်ဆာဆင်ယင်ပြီးသော်—။” ||  “ၝောံကိုတ်၊ ဗြကၞေၚ်၊ပသေၚ်၊ တဝ်စရှ်။” (ဇ—၅၂၇။ အစွောံ။) = (ၝောံကိုတ် = မကိုဋ်။/ ဗြကၞေၚ် = သင်းကျစ်။နဖူးသင်းကျစ်။/ ပသေၚ် = သရဖူ (?)/ တဝ်စရှ် = ဦးဆောက်ပန်း။ ဦးစိုက်ပန်း။)')
,(10447,3,1,'အပူရှိန်။','ဗသာန်တ္ၚဲ = နေအပူရှိန်။ || ဗသာန်ပၟတ် = မီးအပူရှိန်။')
,(10448,3,4,'ရင်­ဆို့နင့်သည်။','‘သဗသြိုဟ်/သ္ဗသြိုဟ်’ နှင့်အတူတူ။')
,(10449,3,1,'၁။ အမြင့်။','ဗဟဳတာ = ထန်းပင်အမြင့်။ || “ညံၚ်ကြက်လကံ၊ ကၠံဗဟဳတာ။” (လိက်သၟိၚ်စိၚ်ဆဒ္ဒန်။ နာဲထဝ်စိုပ်။) = “ထန်းပင်တစ်ရာအမြင့်ရှိသောရှားပင်ကဲ့သို့။” || “ဒၞာဲဂှ် ဒမၠိုက်လက်ကၠိုက်ဒှ် က္တဵုဒှ်သၠုၚ်ဗဟဳတာဟေၚ်။” (ရာဇာထ္ၜုတ်) = “ထိုနေရာ­ ဖုန်မြူမှုန်ထ၍ ထန်းပင်အမြင့်ရှိ၏။” || “ကလာၚ်တိုန်အာ၊ ၜါတာဗဟဳ။” (လိက်ပထမဗောဓိ။ မၚ်ဍိက်လ။) = “ထန်းပင်နှစ်ပြန်အမြင့်အထိ ဈာန်ဖြင့်ပျံတက်သွား၏။” || “နိမိတ်ဗ္ဒဟ်လ္အိတ်၊ ကလော်မိစ္ဆာ။ ဇကုဇၞော်ပ္ညဳ၊သၠုၚ်ဗဟဳတာ။” (လိက်သၟိၚ်ဇဲယဒတ္တ) = “မိစ္ဆာဘီလူးသည် ထန်းပင်အမြင့်ရှိသော ကြီးသောကိုယ်ကို ဖန်ဆင်း၏။”')
,(10449,3,1,'၂။ ယံ။ အချိန်အပိုင်းအခြား။','“ဗၞတ်မွဲဗဟဳ၊ သ္ၚဳမိလှိၚ်အာ။” (လိက်ကောန်သၟိၚ်ပိ။ မာံခစုန်အံက်။) = “တစ်ယံမျှ မယ်အိပ်ပျော်သွား၏။” || “သ္တိက်လှိၚ်ညိပြဲ၊ မွဲဗဟဳပြဟ်။” (လိက်ကောန်သၟိၚ်ပိ။ မာံခစုန်အံက်။) || “လျးပၞာၚ်လျးသ္ဍဴ၊ ဂဵုတဴဖျဳဖျဳ။ ၜါယာံလောန်ညိ၊စိုပ်ပိဗဟဳ။” (လိက်ပဒုမဝတဳ) (ဗဟဳ = ယာံ) = “ဖယောင်းတိုၚ်အလင်းရောင် ဆီမီးအလင်းရောင်သည် တပြောင်ပြောင်ထွန်းလင်းနေ၏၊ နှစ်ယံကိုအနည်းငယ်လွန်၍ သုံးယံသို့ရောက်၏။” || “ပိဗဟဳလောန်၊ ညန်ပန်ပယာံ။” (လိက်ပဒုမဝတဳ) (ဗဟဳ = ပယာံ) = “သုံးယံကိုလွန်၍ လေးယံသို့နီးကပ်သည်။”')
,(10450,3,11,'(န) (သဒ္ဒါ) ဗဟုဝုစ်။ အများကိန်း။',NULL)
,(10451,3,10,'(နဝိ) များသော။ များစွာသော။',NULL)
,(10452,3,10,'(န) အကြားအမြင်များခြင်း။ ဗဟုသုတ။ အကြားအမြင်များသောသူ။','“တိပိုန်ထေရ်အနန်ဂှ် မဒှ်ဗဟုသုတ မဒှ်ဂမြင်ရတ်ပိ။” (ဇ—၄၉၆။ အစွောံ။) = “အရှင်အာနန္ဒာမထေရ်သည် ဗဟုသုတများသူဖြစ်၍ ရတနာသုံးပါး၏ မျက်လုံးသဖွယ်ဖြစ်၏။” || “နွံခမဳမွဲ ဗဟူသုတမဂၠိုၚ်။” (ဇ—၁၇၂။ အစွောံ။) = “ဗဟုသုတများသော ရဟန်းတစ်ပါးရှိ၏။”')
,(10453,3,1,'ကြောက်ခြင်း။ အကြောက်။ ထိတ်လန့်ခြင်း။','“သၟိၚ်နာ်ညာတ်သ္ပဝ်ဂှ်တုဲဗဟေက်က္တဵုဒှ်တုဲ ဗၠိုပ်ဒဴအာပ္ဍဲဍာ်ရ။” (ဇ—၄ဝ၅။ အစွောံ။) = “နဂါးသည် ဂဠုန်ကိုမြင်၍ သေဘေးမှကြောက်သည်ဖြစ်၍ ရေ­ၚုပ်၏။” (ညောင်ကန်) || “စိၚ်ဂှ် သီုဗဟေက်ဟေၚ် ဒၟံၚ်တဴပ္ဍဲဂြိုပ်ဂှ်ရ။” (ဇ—၁ဝ၅။ အစွောံ။) = “ထိုဆင်သည် ထိတ်လန့်ခြင်းဖြင့်သာ ထိုတော­နေ၏။” || “ချိုန်မဗစာရဏာတဴဂှ် ဗဟေက်ဇၞော်က္တဵုဒှ်ရ။” (ဇ—တေမဳ။ အစွောံ။) = “ဆင်ခြင်သောထိုခဏ­ ကြီးစွာသောထိတ်လန့်ခြင်းဖြစ်ပေါ်၏။”')
,(10453,3,4,'ကြောက်စေသည်။ ခြောက်သည်။','“ဒေဝတဴဂှ် နရုပ်မဂပ်ဂဝ်ဖေက်ဂၟံက်ဂှ် ဘဗဟေက်တုဲ ဗက်ဗဒဴကၠေံကၠကဵုဇာဒိသိုၚ်ဂှ်ရ။” (ဇ—၂၇၂။ အစွောံ။) = “ထိုနတ်သည် ကြောက်မက်ဖွယ်ကောင်းသော ရုပ်ကိုဖန်ဆင်း၍ ကျားနှင့်ခြင်္သေ့တို့ကိုခြောက်လှန့်၍ မောင်းထုတ်လိုက်၏။” || “ဣသိဗောဓိသတ် ရပ်ကေတ်အှ်ောမွဲတမိတ်တုဲ ဗဟေက်ကၞုဲတုဲ ကၞုဲစလာ်အာကၠေံရ။ (ဇ—၂၅ဝ။ အစွောံ။) = “ဘုရားလောင်းရသေ့သည် ထင်းမီးကျီးစတစ်စကိုယူ၍ မျောက်ကိုခြောက်လှန့်၍ မျေက်သည်ခုန်ပြေးလေ၏။”')
,(10454,3,1,'ကြောက်ရွံ့မှု။ စိတ်­ကြောက်ရွံ့တုန်လှုပ်ခြင်း။','က္တဵုဒှ်ဗဟေက်စိုတ် = ကြောက်ရွံ့သည်။ ကြောက်စိတ်ဖြစ်ပေါ်သည်။ || “ကၠဵုဒမျိုၚ်မွဲတၟာချေံဇၞော် သၟိၚ်အိန်က္တဵုဗဒှ်တုဲ ဗရုရမျှာၚ်ကၠဵုဂှ် သ္ကာတ်မြဟ်လောန်သန်ဂးတုဲ ညးဍုၚ်ဂမၠိုၚ် က္တဵုဒှ်ဗဟေက်စိုတ် ဗွဲမလောန်ရ။” (ဇ—၄၆၉။အစွောံ။) = “မြင်းကြီးပမာဏရှိသော ခွေးနက်ကြီးတစ်ကောင်ကို သိကြားမင်းဖန်ဆင်း၏။ ထိုခွေး၏မြည်သံသည် အလွန်ပြင်းထန်ကျယ်လောင်သဖြင့် မြို့သူအပေါင်းတို့သည် အလွန်ကြောက်ရွံ့တုန်လှုပ်၏။”')
,(10455,3,1,'ခြောက်နာရီအချိန်အတိုင်းအတာ။',NULL)
,(10456,3,4,'၁။ မူးသည်။ ယစ်သည်။','ဗ္ၜူအရက် = အရက်မူးသည်။ || “(ဗောဓိသတ်တုန်) မဗ္ၜူအာပိုန်ဟာန်တုဲ လုကဴပန်စှ်ောသၞာံ ဟွံဂွံဗှ်သၞာ (သဟာဲဇကု) သက်က်ရ။” (ဇ—၃၇၈။ အစွောံ။) = “ဘုရားလောင်းသည် စည်းစိမ်ဥစ္စာဖြင့် ယစ်မူးသည်ဖြစ်၍ အနှစ်လေးဆယ်လုံးလုံး မိမိအဆွေခင်ပွန်းကို လုံးဝသတိမရ။” || “ဥမ္မာဒန္တဳဂှ် မၞုံတလးစရာဲရုပ်မဂေါဝ်လောန်၊ ဇၟာပ်တြုံတံညာတ်ဒးတုဲ ဗ္ၜူအာရုပ်ဍေံဖအိုတ်ရ။” = “ဥမ္မာဒန္တီသည် ရုပ်အဆင်းအလွန်လှပတင့်တယ်၏။ ယောကျာ်းတိုင်းမြင်၍ သူမ၏ရုပ်အဆင်းဖြင့် ယစ်မူးသွားကုန်၏။”')
,(10456,3,4,'၂။ မူးဝေသည်။','“မၞိဟ်ယဲဂှ် ဒြဟတ်ဆီအောန်တုဲ ဗ္ၜူဒၟံၚ်ရ။” = “လူနာသည် သွေးအားနည်းပြီး မူးဝေနေသည်။” || ‘တ္ၜူ’ ဟုလည်းတွေ့ရသည်။')
,(10457,3,4,'(ဆင်) မုန်ယိုသည်။ မုန်ယစ်သည်။','စိၚ်ဇၟူမဗ္ၜူဒၟံၚ်ကၠေၚ် = မုန်ယိုနေသောဆင်ပြောင်ကြီး။')
,(10458,3,4,'စိတ်ကိုယစ်မူးစေသည်။ နှစ်သက်စွဲလမ်းစေသည်။','“ကောန်ဗြဴမာပိလၟိတ်ဗဒှ်ရုပ်မကမွဲ ရုပ်မဒိပ်မဗ္ၜူကၠေံစိုတ်ညး—။” (ဇ—၁၃၂။ အစွောံ။) = “မာရ်နတ်သမီးသုံးယောက်တို့သည် သူတကာတို့၏စိတ်ကို ညှို့ယူဆွဲဆောင်ယစ်မူးစေတတ်သော ရုပ်အသွင်အမျိုးမျိုးကို ဖန်ဆင်း၏။” || “ပ္ကဴကြက်စၠန် — ပကၚ်ရၚ်လဝ်မြမောဝ် မဗ္ၜူကဵုစိုတ်ထိုၚ်သာဲအဒဲါ—။” (ဇ—ဝိဓုရ။ အစွောံ။) = “စန္ဒကူးနံ့သာပန်းသည် အမွှေးရနံ့ကိုဆောင်လျက် ပိတုန်း၊ ပျား၊ လိပ်ပြာတို့၏စိတ်ကို ဆွဲဆောင်ယစ်မူးစေ၏။”')
,(10459,3,4,'မူး၍ယိမ်းယိုင်စွာသွားသည်။','“ကောန်တြုံသေဋ္ဌဳဂှ် သုၚ်စဗ္ၜူဒလူဒၟံၚ် ရိုဟ်တ္ၚဲရ။” = “ထိုသူဋ္ဌေးသားသည် နေ့တိုင်းသောက်စားမူးယစ်၍ ဒယီးဒယိုင်သွားနေသည်။”')
,(10460,3,4,'မူးဝေသည်။ မူးနောက်သည်။ မူးယစ်သည်။',NULL)
,(10461,3,4,'မာန်ယစ်သည်။',NULL)
,(10462,3,4,'‘တ္ၜူမာဲ’ ရှု။',NULL)
,(10463,3,4,'ချန်ထားသည်။','“ကလောန်သွက်ဂွံကၠောန်ပ္တုဲမွဲတ္ၚဲဂှ် လ္ပဗၜက်လဝ်ညိ။” = “တစ်နေ့အပြီးလုပ်ရန်အလုပ်ကို မချန်ထားပါနှင့်။”')
,(10464,3,4,'မျက်စိမှိတ်သည်။','“သဘဴကျာံတံဂှ် ယာံဍေံဟာပါၚ်တုဲ မတ်ဍေံဗ္ၜေက်အာရ။” (ဇ—၅၇။ အစွောံ။) = “မိကျောင်းတို့အား ခံတွင်းကိုဖွင့်သည်ရှိသော် မျက်စိတို့သည်မှိတ်ကုန်၏။” (ညောင်ကန်) || “တၞဟ်နလှေံလှန်ကျာ်တြဲဂှ် (ကောန်ဗြဴမာပိ) ပြာပ်ကၠုၚ်တုဲ ကျာ်တြဲဗ္ၜေက်ကၠေံ ဟွံဂွံၚဳရံၚ်သက်က်ဟေၚ်။” (ဇ—၁၃၂။ အစွောံ။) = “မြတ်စွာဘုရားကို ဖြားယောင်းရန်ကပ်လာသော မာရ်နတ်သမီးသုံးယောက်တို့ကို မြတ်စွာဘုရားသည် လုံးဝကြည့်တော်မမူဘဲမျက်စိတို့ကို မှိတ်တော်မူ၏။” || “သတ္တံလ္ၚဵုဂှ် ကၠာနူကွာ်ဟွံဒှ်ဂှ်လေဝ် ဒးပကာဂစိုတ်ကီု။ ပ္ဍဲအယာံမဗၜေက်ကီု မမၠာ်ကီု မဒးစုတိအာကီု။” (ဇ—၃၂၈။ အစွောံ။) = “အချို့ကုန်သောသတ္တဝါတို့သည် မလျှောက်တတ်သေးခင်လည်း သေရကုန်၏။ မျက်စိမှိတ်ခိုက်­၄င်း မျက်စိဖွင့်ခိုက်­၄င်းသေရကုန်၏။”')
,(10465,3,4,'ကြည်လင်သည်။ သန့်ရှင်းသည်။',NULL)
,(10466,3,4,'ဖေးမသည်။ ကူညီသည်။','“ယွံမၞးဒေဝတဴတံညးဂမၠိုၚ်၊ ဗိုၚ်ဆောံမထံက်ပၚ် ဗၜၚ်လဘာ်အဲဍိက်ဗြဴတုဲ ကဵုအဲဍိက်ဗြဴဂွံဆဵုဒးကောန်သ္ဍိုက်အဲသုရသာ မွဲဝါညိလေဝ်ဒေဝတဴတံ။” (သၠပတ်သုရသာ) = “အိုအသၚ်နတ်အပေါင်းတို့၊ ကျွန်တော်မ၏ချစ်သားသုရသာကို တွေ့နိုင်ဖို့ရန်ကျွန်တော်မအား ဝိုင်းဝန်းစောၚ်မကူညီဖေးမတော်မူကြပါကုန်လော့။”')
,(10467,3,4,'အချိန်ဆွဲသည်။ နှောင့်နှေးစေသည်။ ကြန့်ကြာစေသည်။','“ယဝ်ဟီုဗၜိၚ်၊ ဇလိၚ်ဇမ္ၚောဲ။” = “ရှည်ဝေးလေအောင် ပြောဆိုအချိန်ဆွဲလျှင်။”')
,(10468,3,1,'အတိုင်းအတာ။','“ကေတ်ဗ္ၜတ် သွက်ဂွံဇိၚ်ပလောအ်။” = “အင်းကျီချုပ်ရန်အတွက် ကိုယ်တိုင်းကိုယူသည်။”')
,(10469,3,1,'မြေယာကို တိုင်းတာရသောအရာရှိ။ မြေတိုင်းစာရေး။','“ဂရုကဓဝ်အဲဂှ် ဟွံဗိုန်သ္အးက္ဍၚ်။ ပ္ဍဲဇရေၚ်အမာတ်ဗၜတ်တဝ်တိတေံဂှ် သ္အးဗိုန်ဂၠိုၚ်၊ မၞးတံအာချူကေတ်ညိရ။” (ဇ—၂၇၆။ အစွောံ။) = “ငါ၏သီလသည် အလွန်မမြဲမြံမစင်ကြယ်။ မြေတိုင်းအမတ်၏သီလသည်ပို၍စင်ကြယ်မြဲမြံ၏။ ၄င်းထံသို့သွား၍ သင်တို့ရေးယူသွားကြကုန်လော့။”')
,(10470,3,4,'စုပ်သည်။','ဗၜေတ်စ = စုပ်စားသည်။ || ဗၜေတ်တှ် = နို့ကိုစုပ်သည်။')
,(10471,3,4,'(မျက်နှာ၊ ပါးစသည်) ပိန်ချုံးသည်။','“သၟတ်ဗြဴဂှ် ယဲအာတုဲ ဇြာဲဇြေဟ်မုက်ဗၜေါတ်ဒၟံၚ်ရ။” = “ထိုသူငယ်မသည် ဖျားသွားသဖြင့် ကြုံလှီ၍ မျက်နှာပိန်ချုံးနေသည်။”')
,(10472,3,3,'ကျစ်ထားသော။ လုံးအောင်လှိမ့်ထားသော။','ဇုက်ဗ္ၜန် = ကျစ်ထားသောကြိုး။ || ပၞာၚ်ဗ္ၜန် = လက်ဖြင့်လှိမ့်ထားသောဖယောင်းတိုင်။ || တောဝ်ဗ္ၜန် = ကျစ်ထားသောချည်။ || “နဇုက်စၞာံဗၜန်မခိုၚ်ဂှ် (လၟ) ပြာၚ်ထံၚ်ပံါလဝ်ဓနက်ဂှ်ရ။” (ဇ—၅ဝ၁။ အစွောံ။) = “ခိုင်ခံ့သောကျစ်ထားသော သားရေလွန်ကြိုးဖြင့် မုဆိုးသည် ကျော့ကွင်းထောင်ထား၏။”')
,(10473,3,4,'တုံးစေသည်။','ဗၜိုမ်ထောံမြ = ဓါးကိုတုံးသွားစေသည်။')
,(10474,3,3,'‘သၜဲါ’ ရှု။',NULL)
,(10475,3,4,'ရွဲ့စောင်းအောင်လုပ်သည်။','ဗၜေဲလဝ်ပါၚ် = ပါးစပ်ကို ရွဲ့အောင်လုပ်ထားသည်။')
,(10476,3,4,'မျက်စိမျက်နှာမဲ့ရွဲ့သည်။ မနှစ်မြို့ကြောင်းကို အမူအရာဖြင့်ပြသည်။',NULL)
,(10477,3,4,'‘ဂၜေါဝ်’ ရှု။',NULL)
,(10478,3,1,'တောကြောင်။',NULL)
,(10479,3,1,'ကောက်ညှင်းပေါင်းအနံ့ထွက်သည့်တောကြောင်။ ကြောင်ဝံပိုင့်။ ဝံပိုင့်။',NULL)
,(10480,3,1,'ရှူးပျံ။ (လက်နှင့်ကိုယ်အကြားတွင် အရေပြားပြၚ်ရှိသော ရှဉ့်နှင့်တူသည့်သတ္တဝါ)',NULL)
,(10481,3,4,'ဖဲ့သည်။','‘ခၜိဟ်’ ရှု။')
,(10482,3,1,'အမြှုပ်။','ဗၜိုဟ်ဍာ် = ရေမြှုပ်။ || ဗၜိုဟ်ဗံၚ် = ဆပ်ပြာအမြှုပ်။')
,(10483,3,4,'အေးစေသည်။ အအေးခံထားသည်။','“ညံၚ်ရဴဗြဲဇၞော်မဗဂူဖျေံတုဲ ဗၜိုဟ်ကဵုတိဇၞော်ဂှ်ကီု။” (ဇ—၄၂ဝ။ အစွောံ။) = “မိုးကြီးရွာချ၍ မြေကြီးကို အေးစေသကဲ့သို့။” || “(ဖျုန်ဂှ်) ပရာၚ်စိန်တုဲ တၞဟ်နဗၜိုဟ်လဝ်ဂှ် ဍေံစွံလဝ်ပ္ဍဲမုဟ်ဂတဵုမွဲ—။” (ဇ—မှာဇနက်။ အစွောံ။) = “အသားကိုကၚ်၍ ကျက်သောအခါ အအေးခံရန်အလို့ငှာ တစ်ခုသောအင်းပျဉ်စွန်း­ထား၏။” || ‘လၜိုဟ်’ (ကြိ) လည်းရှု။')
,(10484,3,4,'စိတ်အပန်းဖြေသည်။ စိတ်အေးစေသည်။','‘လၜိုဟ်စိုတ်’ နှင့်အတူတူ။')
,(10485,3,1,'၁။ ဆိတ်။ သာမန်ဆိတ်။ ဆိတ်မြန်မာ။',NULL)
,(10485,3,1,'၂။ ဆိတ်နှင့်သိုးကို ခြုံခေါ်သောအမည်။','“ဗ္ၜေံဂှ် ညာတ်ပြဘာတ်ဂှ်တုဲ ဍေံဆုတ်ဒိုအ်ကၠေံရ။” (ဇ—၃၂၄။ အစွောံ။) = “သိုးသည် ပရိဗိုဇ်ကိုမြင်၍ ခတ်လိုရကား နောက်သို့ဆုတ်၏။” (ညောင်ကန်) || “ပ္ဍဲသၞာစၞာံဗ္ၜေံမဍိုန်ဂှ် လးလဝ်တုဲ—။” (ဇ—၄ဝ၇။ အစွောံ။) = “သိုးရေကိုခင်းစေ၍—။” (ညောင်ကန်)')
,(10486,3,1,'သိုး။ ဆိတ်ကုလား။ (ပါဠိ—ဨဠက)','“မၞိဟ်တံဂမၠိုၚ် ဍေံဗလိဗကဝ်ဒေဝတဴဂှ်ဗ္ၜေံဗမာဗ္ၜေံဂလာတံဂှ် ဂစိုတ်တုဲ ဍေံဗလိဗကဝ်ကလော်ဒေဝတဴရ။” (ဇ—၃၄၇။ အစွောံ။) = “လူတို့သည် နတ်တို့ကိုကိုးကွယ်ကုန်၍ များစွာကုန်သော ဆိတ်မြန်မာဆိတ်ကုလား အစရှိသည်တို့ကိုသတ်၍ နတ်တို့အားပူဇော်ခြင်းကို ပြုကုန်၏။” (ညောင်ကန်) (ဆိတ်ကုလား = သိုး)')
,(10487,3,1,'ဆိတ်သိုး။ ဆိတ်ထီးကြီး။','“(အ္စာတဳဂှ်) သ္ၚာဟွံမွဲစိ၊ ညံၚ်ဗီုဗၜေအ်ဒုဲ။ သော်ပါၚ်သော်ဒဳကီု၊ သီုသော်လကေတ်ထုဲ။” (လိက်ဂၞကျာ်ဝိသာခါ) = “ထိုတိတ္ထိဆရာသည် သင်္ကန်းမပါ (ကိုယ်ချည်းဗလာ) ဆိတ်သိုးကဲ့သို့ မုတ်ဆိတ်မွေး၊ ပေါင်မွေး၊ ဖင်မွေးတို့နှင့်ထွေးယှက်ဖြစ်၏။”')
,(10488,3,1,'သာမန်ဆိတ်။ ဆိတ်မြန်မာ။ (ပါဠိ—အဇ)','“ဨဠကစမ္မံ။ န်စၞာမ်ဗ္ၜေံကလာကီု။ အဇစမ္မံ။ န်စၞာမ်ဗ္ၜေံဗၟာကီု။” (တြာဲဝိနယသၚ်ရိုဟ်ဂြဳ။ စန္ဒိမာ။) = “သိုးရေကိုလည်းကောင်း၊ ဆိတ်ရေကိုလည်းကောင်း။”')
,(10489,3,4,'ပိန်ချိုင့်စေသည်။ ပြားအောင်လုပ်သည်။','“စိၚ်ဂှ် လိုန်ဗၜေအ်ထောံစေဝ်ဂှ်ရ။”= “ဆင်သည် ပုံးကို ပြားချိုင့်အောင် နင်းပစ်လိုက်သည်။”')
,(10490,3,4,'ပိတ်သည်။ စေ့သည်။','“ဗအေပ်ထောံတရၚ်ညိ။” = “တံခါးကိုစေ့လိုက်ပါ။”')
,(10491,3,4,'ပူဇော်သည်။ မြတ်နိုးသည်။','“ဗွဲဂါရဝ ဒးရှ်ေသှ်ေရဴဂဴ ယိုက်ဒိုက်သၞေအ်သၞဴဗဥုဲဗဂုဲခမဳဂှ်။” (နဝကောဝါဒကထာ။ ပြကိုဟ်မန်ဍုၚ်သေံ။) = “ဂါရဝတရားဖြင့် ထိုရဟန်းအားရိုသေလေးမြတ် ချီးမြှောက်ပူဇော်ရပါမည်။”')
,(10492,3,1,'တောင်း။ ပလိုင်း။','“ပြိုက်ထိုၚ်စုတ်ဗာ။” (လိက်ဗြရတ်ဣဏၚ်ကၚ်ရဳ) = “အိတ်ထဲသွတ်၍ ပလိုင်းထဲထည့်သည်။”')
,(10492,3,4,'ပလိုင်းလွယ်သည်။',NULL)
,(10493,3,12,'(န) အနောက်မြောက်အရပ်။',NULL)
,(10494,3,1,'အမည်မဖော်နိုင်သောငှက်တစ်မျိုး။','“ဂစေံဒဇဲ၊ ဂစေံဒၟာတ်၊ ဂစေံဗာရခါတ်။” (ဇ—ဝေသန္တဝ်။ အစွောံ။)')
,(10495,3,1,'ဗာရာဏသီပြည်။',NULL)
,(10496,3,10,'(န) လူမိုက်။',NULL)
,(10497,3,12,'(န) ၁။ ဥသျှစ်သီး။',NULL)
,(10497,3,12,'(န) ၂။ ပုလင်းငယ်။ ဗူးငယ်။','“ဗၠာဲတံသက်သက်၊ ဆန်အရက်ပ္ညဳ။အမာတ်သေဏာ၊ ညးမွဲၜါဗဳ။” (လိက်ဗြရတ်ဣဏၚ်ကၚ်ရဳ) = “လူပျိုတို့သက်သက် အရက်ကို ဝေငှကုန်၏၊ အမတ်သေနာပတိတို့သည် တစ်ဦးကိုနှစ်ဗူးရကုန်၏။” || ဗဳမှၚ် = မှၚ်အိုး။ || ဗဳသၞာံ= နွားအစာအိမ်နှင့်လုပ်ထားသော ထည့်စရာအိတ်။ || “ဍာ်ပ္ကဴမြမောဝ်မသုန်ဗဳ။” (အကြီုရာဇာဓိရာဇ်) = “ပန်းအမွှေးနံ့သာရည်ငါးဗူး။”')
,(10498,3,16,'(န) ၁။ မျိုးစေ့။ မျိုးရိုး။ ဗီဇ။',NULL)
,(10498,3,16,'(န) ၂။ ပင်ကိုစရိုက်။',NULL)
,(10499,3,1,'ဗီဇနာ။ (နှစ်ဆယ့်လေးစက္ကန့်နှင့် ညီမျှသောအချိန်အတိုင်းအတာ။)','“ပါတ်ဗိဇ္ဇနာ၊ လမေၚ်နာဍဳ။ တရဴစှ်ောသ္ကဲ၊ ပ္ညပ်မွဲဒိတ္ထဳ။ ပိစှ်ောဒိတ္ထဳ၊ ပ္ညဳမွဲဂိတု။” (လိက်ဗောဓိသတ်စှ်။ ပဏ္ဍိတ။) = “ပါတ်၊ ဗဳဇနာ၊ နာရီစဉ်အတိုင်း (ရေတွက်သော်) နာရီခြောက်ဆယ်သည် တစ်ရက်ဖြစ်၏၊ ရက်သုံးဆယ်သည် တစ်လဖြစ်၏။” (မှတ်ချက်။ ရှေးသုံးနာရီကို ဆိုလိုသည်။)')
,(10500,3,1,'မဲဇလီပၚ်။',NULL)
,(10501,3,1,'ဗီရို။ ဗီဒို။ (?)','“ဗဳဒဵုတလာ၊ ယာတ်ဍောတ်ကြာထဝ်။” (လိက်သောဝါနနဟောၚ်)')
,(10502,3,1,'မဟာဗိနနဲနတ်။','“ဗဳသၞုဇၞော်အဒ္ညာ၊ ဗဳနာဲဂၠိုၚ်ထာဏ။” (လိက်သုပိဏ္ဏကုမ္မာ) = “ပညာကြီးသောဗိဿနိုးနတ်နှင့် နေရာဋ္ဌာနများစွာရှိမဟာဗိနနဲနတ်။” || ‘မှာဗဳနာဲ’ နှင့်အတူတူ။')
,(10503,3,11,'(န) သျှိသျှားခေါ် ဆီးဖြူတစ်မျိုး။ ဥပသကာပၚ်။','“ဗောဓိသတ်ကဵုကေတ်နၚ်သၠဗဳယၚ်ကဵုထၞက်ဝတ်ကေတ်ဍာ်ဍေံ ဍာ်ဗဳယၚ်ဂှ် (ကဵုဂၠဴသုၚ်။)” (ဇ—မဟောဟ်သဓ။ အစွောံ။) =“ဘုရားလောင်းသည် သျှိသျှားရွက်ကို ဆောင်ယူစေပြီးလျှင် ညက်စွာထောင်းပြီးမှ ရေနှင့်ဖျော်၍ (နွားကို) တိုက်စေ၏။” (မင်းပူးဦးသြဘာသ။) || “(ဂွါကၟက်ကအ်အဲဍိက်ဂှ်) ပ္ကဴဗဳယၚ် အဲထီုလဝ်ရအဴ” ဗြဴတၠဒြပ်ဂှ်ဂး။ (ဇ—မဟောဟ်သဓ။ အစွောံ။) = “အကျွန်ုပ်သည် ဤလည်ရွဲကို သျှိသျှားပွင့်ဖြင့်သာလျှင် — လိမ်းသုတ်ရ၏။” (မင်းပူးဦးသြဘာသ)')
,(10504,3,1,'ဆွမ်း။','‘ပိဏ္ဍပါတ်’ နှင့်အတူတူ။ || “ပဥ္စသဳလံၚ်၊ ဒ္ဂိုန်မံၚ်ဟွံခြာ။ ဗဳလပါတ်ဗျန်၊ဆန်ကဵုအ္စာ။ ရိုဟ်ဒဒှ်တ္ၚဲ၊ အဲဥပ္ပကာ။” (လိက်ဂါထာလ္ၚောဝ်ကျာ်) = “ငါးပါးသီလကို အမြဲမခြားခံယူဆောက်တည်၍ ဆွမ်းဟင်းလျာများကိုလည်း ဆရာအတွက်စံမံပေး၍ နေ့စဉ်နေ့တိုင်း ငါလုပ်ကိုင်ပေး၏။”')
,(10505,3,1,'ရေတွင် သစ်သားကိုစားသောတီပိုး။',NULL)
,(10506,3,1,'အိမ်မွေ့ပင်။ ၚုပင်။','ဍာ်ဗဳလၚ် = ၚုရေ။')
,(10507,3,12,'(န) ဗိသုကာ။ လက်သမား။ ဆောက်လုပ်ရေးသမား။','“ဝဍ္ဎကဳဗဳသကဝ်ဓယှ်ဂှ်—။” (ဇ—၃၅၃။ အစွောံ။) = “ထိုလက်သမားဗိသုကာအကျော်အမော်သည်—။” || “ဝိသုကမ္မပလွေဟ်ဗဳသကဝ်တုဲ ပြာပ်ကၠုၚ်ဇရေၚ်ဓဇဲဂမၠိုၚ်—။” (ဇ—၄၈၉။ အစွောံ။) = “ဝိသုကြုံနတ်သားသည် ဗိသုကာအသွင်ဆောင်၍ လက်သမားများဆီသို့ ချဉ်းကပ်လာ၏။” || “ဇကုသၟိၚ်အိန်မရပ်တြာဗိုတ်၊ သၟိၚ်ဗြီုပဗဳသကဝ်။” (ရာဇာဝံသသံခိပ်။ အစွောံ။) = “သိကြားမင်းကိုယ်တိုင်စိန်တံဆိပ်တုံးကိုကိုင်၍ ဗြဟ္မာမင်းက ဗိသုကာလုပ်သည်။”')
,(10508,3,12,'(န) ၁။ အကျယ်။ အနံ။ အကျယ်ချဲ့ခြင်း။ (သ—ဝိသ္တာရ)','“သတိပထာန်၊ ပန်ပ္ကာန်ဗဳသ္တာ။” (လိက်နဲယသမုဒ္ဒြဳ။ အစွောံ။) = “သတိပဋ္ဌာန်တရားသည် အကျယ်အားဖြင့် လေးပါးအပြိုင်ရှိ၏။” || “မၞိဟ်ပန်လက်ဓဝ်၊ သိုၚ်နန်ထဝ်ကၠာ။ မၞိဟ်တရဴလက်၊ ဒက်ဍုၚ်ဗဳသ္တာ။” (လိက်နဲယသမုဒ္ဒြဳ။ အစွောံ။) = “လူအင်အားလေးသောင်းတို့သည် ရွှေနန်းဆောက်လုပ်ကြကုန်၏။ လူအင်အားခြောက်သောင်းတို့သည် မြို့တည်အကျယ်ချဲ့ကြကုန်၏။” || “စိုပ်ဥဒျာန်ပ္ညဳ၊ မံၚ်တဴသ္အဳဗ္ဂါ။ ပ္ကဴအံၚ်ရေၚ်ပ္ဍး၊ ဗြော်လးဗဳသ္တာ။” (လိက်ပ္တံပါရမဳ။ အစွောံ။) = “ဥယျာဉ်သို့ရောက်၍ စုရုံးလျက်နေ၏။ မွှေးကြိုင်သောအင်ကြင်းပန်းတို့ဖြင့် ပြည့်နှက်စွာ အကျယ်ဖြန့်ခင်းထား၏။” || “တ္ၚဲဒှ်မၞိဟ်ပ္ညဳ၊ လုံဂြိုပ်ဗဳသ္တာ။ လုံဟေမဝန်၊ ဂဵုခၠၚ်လောန်အာ။” (လိက်ရတနပဇ္ဇောတ) = “လူဖြစ်သောနေ့­ တောလုံးအကျယ် ဟိမဝန္တာတောအလုံး အလွန်ထွန်းပသွား၏။”')
,(10508,3,12,'(န) ၂။ ကျယ်ပြန့်ညီညာသောမျက်နှာပြင်။ (?)','“တၞံဆုဒၟံၚ်သွိၚ်၊ တရေၚ်ဗျိၚ်ဗ္ဂာ။ ဒေဝတဴသၟဟ်၊ဗ္ဒဟ်လဝ်နာနာ။ ဗွဲလတူသွံ၊ ကၞာၚ်ထောံဒၟံၚ်ဗ္ဂာ။ အသၟဝ်တးလး၊ သၟးဗဳသတာ။” (လိက်သၚ်ဂဒါ။သဳလဝန္တ။) = “နတ်တို့ဖန်ဆင်းထားသော သစ်ပင်အမျိုးမျိုးတို့သည် ညီညာစွာစီတန်းနေကုန်၏။အကိုင်းအခက်တို့သည် အထက်တွင်ရှိ၍ အောက်ပိုင်း­ ပြန့်ပြူးနေသည်မှာ ညီညာသောမျက်နှာပြင်ပမာတည်း။”')
,(10508,3,12,'(န) ၃။ အမှန်ပကတိ။ တကယ်ပကတိ။','“ဖဵုဟွံမွဲဟေၚ်၊ ဍေံဟီုသေၚ်ဟာ။ ထာန်သွဝ်ဗြီုပ္ညဳ၊ ဟွံမွဲဗဳသ္တာ။ ပြိုတ်နရက်သ္ကဲ၊ ဟွံမွဲမွဲဝါ။” (လိက်နဲယသမုဒ္ဒြဳ။ အစွောံ။) = “(ကုသိုလ်တရား၊ အကုသိုလ်တရားတို့၏) အကျိုးဆက်မည်သည်မရှိ၊ နတ်ပြည်ဗြဟ္မာပြည်တို့ တကယ်ပကတိမရှိ၊ ပြိတ္တာငရဲမရှိဟု သူဆို၏။”')
,(10509,3,1,'ဥက္ကာ။ ဥက္ကာပျံ။ ဥက္ကာခဲ။ (မတေေံရ)','ဗဳသတဳဒတုံ၊ ဗဳသတဳသရိုဟ် = (အာကာသမှ) ဥက္ကာကြွေသည်။ ဥက္ကာခဲကျသည်။ || “ဗြဲသက်ကာလ၊ မဗ္ဂူဖျေံကီု။ လလဳစဳပျး၊ ဂတးပန်ပြီု။ပ္ဍဲအကာသ၊ ခဏဂၠုဓီု။ ဗဳသတဳသရိုဟ်၊ ဇၟာပ်ဒိုဟ်အိုတ်သီု။ လလောၚ်ကြဵုကြီု၊ သီုစက္ကဝါ။” (လိက်ပထမဗောဓိ။ မၚ်ဍိက်လ။) = “အခါမဟုတ်သည်­ မိုးကြီးရွာချ၏၊ လျှပ်စီးလက်၍ မိုးကြိုးပစ်၏၊ အာကာသ­ မှောင်မိုက်၏၊ အရပ်မျက်နှာအားလုံး­ ဥက္ကာကြွေ၏၊ စကြာဝဠာအလုံး ထစ်ကြိုးမြည်ဟည်းကုန်၏။”')
,(10510,3,1,'ဟိန္ဒူဗိဿနိုးနတ်။','“ဗဳသၞုဇၞော်အဒ္ညာ၊ ဗဳနာဲဂၠိုၚ်ထာဏ။” (လိက်သုပိဏ္ဏကုမ္မာ) =“ပညာကြီးသောဗိဿနိုးနတ်နှင့် နေရာဋ္ဌာနများစွာရှိမဟာဗိနနဲနတ်။”')
,(10511,3,12,'(န) ဝေဿဝဏ်နတ်မင်း။','“ယွံညးမသၟဟ်ကဵုပိုဲ၊ ကြုက် (အဘန်တဵု) ဂှ် ပြဘိုက်သၟိၚ်ဗဳသြဴရောၚ်။” (ဇ—၂၈၁။ အစွောံ။) = “အဆွေ၊ အဗ္ဘန္တရသရက်ကား ဝေဿဝဏ်နတ်မင်း၏ အသုံးအဆောင်တည်း။” (ညောင်ကန်) || “ကလော်ဗြဴဂှ် ဒးအလန်မဒးအာကၠောန်ၜိုတ် ဇရေၚ်သၟိၚ်ဗဳသြဴတုဲ အယုက်ဍေံအိုတ်တုဲ ချိုတ်အာရ။” (ဇ—၅၁၃။ အစွောံ။) = “ဘီလူးမသည်ဝေဿဝဏ်နတ်မင်းကြီး၏အမှုကိစ္စကို ဆောင်အံ့သောငှာသွား၍ ထိုဝေဿဝဏ်နတ်မင်းကြီးအထံ­လျှင် သေ၏။” (ညောင်ကန်)')
,(10512,3,1,'အနာကျပ်ကိရိယာ။ နားကျပ်ကိရိယာ။ ဂွမ်းဖတ်။ (အနာပေါက်၊ နားစသည်ကိုကျပ်ရန်အတွက် အစွန်းတွင် ဂွမ်းစသည်ကပ်ထည့်ထားသောအရာ။)','“သရတၠအဲဂှ်ဍေံသ္ဇိုဟ်ဒၟံၚ် —နကဵုဇြေဟ်ဆုတံဂှ် ပဗဳသြုန်တုဲ ကဵုအဲထပူညိဟာ။” (ဇ—၅၂၆။ အစွောံ။) = “သင်၏အနာသည်နက်၏။ သစ်သားအမျှင်တို့ဖြင့် အနာကျပ်ကိရိယာလုပ်၍ သင့်အနာကို ငါ့အားကျပ်စေပါမည်လော။”')
,(10513,3,1,'ရင်းရဲပၚ်။ (သောၚ်စပ်တွင် ပၚ်ချင်းထောင်၍ ပေါက်လေ့ရှိသည့် အလေ့ကျအပၚ်တစ်မျိုး။)','“ဆုကြေၚ်ဗဳလှန်မရာၚ်ဆာဲဂှ်။” (ဇ—၅၂၄။ အစွောံ။) = “သပြေပၚ်တို့ဖြင့်လည်းကောင်း၊ ရင်းရဲပၚ်တို့ဖြင့်လည်းကောင်း။” (ညောင်ကန်)')
,(10514,3,16,'ဖြူသည်။—သော။',NULL)
,(10515,3,16,'ဖြူဖွေးသည်။—သော။','“ဒၞာဲဂှ် ဍာ်ဗုကိုဟ်တဴ ညံၚ်ရဴဍာ်တှ်ကၟုဟ်ဍာ်တှ်သၟာကီု။” (ဇ—၄၆၃။ အစွောံ။) = “ထိုအရပ်­ ရေသည် နို့ဓမ်းနို့ရည်ကဲ့သို့ ဖွေးဖွေးဖြူ၏။”')
,(10516,3,11,'(န) အသိပညာ။ အတတ်ပညာ။',NULL)
,(10517,3,16,'(န) ဗေဒင်။','တော်ဗေဒၚ် = ဗေဒင်တွက်သည်။')
,(10518,3,1,'ဗေဒင်လေးကျမ်း။ ဗေဒင်လေးပုံ။','“ဗေဒၚ်ပန်ရ၊ နာမဟီုသ္ကဲ။ ဇယဗေဒ၊ ဟီုပၠမွဲတဲ။ မွဲသတ္တပ္ပ၊ ဗေဒဟီုသ္ကဲ။ ဣတိဟာသ၊ ဝွံဗေဒမွဲ။ နက္ခယုပြဲ၊ ပန်သ္ကဲဗေဒၚ်။” (လိက်သောဝိန်ဇဲယ။ မာံရောဂေါ။) = “ဗေဒင်လေးပုံ၏ အမည်နာမများမှာ ဇယဗေဒ၊ သတ္တပ္ပဗေဒ၊ ဣတိဟာသဗေဒ၊ နက္ခယုဗေဒတို့ပၚ်တည်း။” || ဗိုတ်ပိဗေဒၚ်ပန် = ဝေဒသုံးပုံနှင့်ဗေဒင်လေးကျမ်း။ || ‘ဗိုတ်ပိ’ (န) လည်းရှု။ || (မှတ်ချက်။ မြန်မာတွင် ‘ဗေဒင်သုံးပုံ’ ဟုလာသော်လည်း မွန်တွင်‘ဗေဒင်လေးပုံ/ဗေဒင်လေးကျမ်း’ ဟုလာသည်။)')
,(10519,3,12,'(န) ဝိသာခါနက္ခတ်။',NULL)
,(10520,3,1,'ဘုရားပွင့်တော်မူရာအောင်မြေ။ ကမ္ဘာမြေကြီး၏ အလယ်ဗဟို အချက်အချာအောင်မြေ။ ဗောဓိမဏ္ဍိုၚ်။','“(သၟိၚ်စက္ကဝဝ်ဍိုက်ကေတ်စိၚ်ရတ်ဂှ်တုဲ) ပ္ဍဲမကလာၚ်အာစိုပ် ဒမံၚ်ဗောဓိပဏိဟ်တိ မဒှ်ဒမံၚ်ကျာ်တံတမၠာမဇၞးမာဂှ် စိၚ်ရတ်ဂှ်ဟွံဂံၚ်အာ။” (ဇ—၄၇၉။ အစွောံ။) = “ခပ်သိမ်းကုန်သောဘုရားရှင်တို့၏ မာရ်ငါးပါးကိုအောင်တော်မူရာ ရတနာပလ္လင်တော်ဖြစ်သော မြေ၏ချက်မအချာ မဟာဗောဓိမဏ္ဍိုၚ်၏ အထက်အဘို့­ ထိုမင်း၏ရတနာဆင်ဖြူတော်သည် သွားခြင်းငှာမဝံ့။” (ညောင်ကန်)')
,(10521,3,1,'ဗောဓိပက္ခိယတရား။','‘ဓဝ်ဗောဓိပလိုဟ် (၃၇) ။’ (ဇ—၅၆။ အစွောံ။) = ‘သုံးဆယ့်ခုနစ်ပါးအပြားရှိသော ဗောဓိပက္ခိယတရား။’ (ညောင်ကန်)')
,(10522,3,1,'ဘုရားမှီရာဗောဓိပၚ်။ ဘုရားပွင့်ရာဗောဓိပၚ်။','“ဆုဗောဓိပလောဟ်ကျာ်ဂှ် နွံတဴလမှဳမဂွုသ္အး ညံၚ်သၟးဂၠးသြန်။” (သၠပတ်ဂမ္စာဲဓါတ်) = “ဘုရားပွင့်တော်မူရာဗောဓိပၚ်သည် ငွေသားကဲ့သို့ဖြူစင်သော ပၚ်စည်ရှိ၏။”')
,(10523,3,1,'မြတ်စွာဘုရား၏ဗောဓိပလ္လင်တော်။','“ဗောဓိပဏၚ်က္တဵုဒှ်တုဲ ဟွံဂတာပ်လအ် ပၞာန်မာကၠုၚ်စိုပ်ရ။” (ရာဇာဝံသသံခိပ်။ အစွောံ။) = “ဗောဓိပလ္လင်တော်ပေါ်ထွန်းပြီးနောက် မကြာမြင့်မီ မာရ်နတ်စစ်သည်ရောက်လာ၏။” || “ထပှ်တ္ၚဲ ကျာ်တြဲဒၟံၚ်ပ္ဍဲဗောဓိပလ္လၚ်ရ။” (ရာဇာဝံသသံခိပ်။ အစွောံ။) = “မြတ်စွာဘုရားသည် ဗောဓိပလ္လင်­ ခုနစ်ရက်နေတော်မူ၏။”')
,(10524,3,11,'(န) ဘုရားလောင်း။ ဗောဓိသတ်။ (ပါဠိ—ဗောဓိသတ္တ)',NULL)
,(10525,3,1,'၁။ အဘွား။','ဗဴကဵုလ = အဘွားနှင့်အဘိုး။ || “ဗဴကဵုလရောၚ်၊ မွဲတောင်ဟီုဂျ။” (လိက်သၟိၚ်ဇဲယဒတ္တ)')
,(10525,3,1,'၂။ အစောင့်နတ်မိန်းမ။','ဗဴဇုကွာန် = ရွာစောင့်နတ်မိန်းမ။ ရွာစောင့်နတ်အဘွား။')
,(10526,3,1,'ချစ်လှစွာသောအဘွား။','“ဗဴဇု၊ ရာန်လီုမွဲကဵုအဲညိ။” (ဇ—၃။ အစွောံ။) = “ချစ်ဘွားဘွားရေ၊ သမီးကို ရွဲတစ်ခုဝယ်ပေးပါနော်။ ”')
,(10527,3,1,'ဝသုန္ဓရေစောင့်နတ်သမီး။ ကမ္ဘာမြေစောင့်နတ်သမီး။','“သၟိၚ်ကဵုဂၞကျာ်စရိုဟ်ဍာ် ပ္တီဗဴတိသုန္ဓရဳ ပ္ဍဲကာလဂှ်ရ။” (သၠပတ်အရုဒုမ္မ) = “မင်းနှင့်မိဖုရားသည် ထိုအခါ ရေသွန်းလောင်း၍ဝသုန္ဓရေစောင့်နတ်သမီးအား တိုၚ်တည်ကြားသိစေ၏။”')
,(10528,3,1,'လယ်ယာမြေစောင့်နတ်သမီး။','“ယွံဗဴမိန်ဂၠုၚ်၊ ဗဴဓုၚ်ဗဴဝါ။ ဒေဝတဴၜဳ၊ မနဳခလာ။ မၞးတံမၚ်မွဲ၊ သတ်ပ္ဍဲသံၚ်သာ။” (လိက်ဇိဝှစက္က) = “အို—လှေစောင့်နတ်သမီး၊ လယ်မြေစောင့်နတ်သမီး၊ မနိမေခလာ ပင်လယ်စောင့်နတ်သမီးတို့၊ သံသရာမှသတ္တဝါအပေါင်းကို သင်တို့စောင့်ရှောက်ပါကုန်လော့။”')
,(10529,3,1,'မယ်သီလရၚ်။ သီလရှင်။',NULL)
,(10530,3,1,'ဖခင်၏အမေဖြစ်သောအဘွား။ ဖခင်ဘက်မှအဘွား။',NULL)
,(10531,3,1,'မိခင်၏အမေဖြစ်သောအဘွား။ မိခင်ဘက်မှအဘွား။',NULL)
,(10532,3,1,'အထိန်း။ အထိန်းတော်။','“ကဵုမိနဳဗဴလေၚ်ၝဲဂမာ မြိမြန်ဇၞော်ပၟဝ်လဝ် (ကောန်ၚာ်ဂှ်) ။” (အာန်ဇုနာန်) (မိနဳ = ဗဴလေၚ် = ၝဲဂမာ) = “ထိုကလေးငယ်အား အထိန်းတော်မတို့ကို ပြုစုမွေးမြူစေ၏။” || “မိမိန်ဗဴလေၚ်၊ ဟေၚ်ဂွံဗမဴ။” (မိမိန် = ဗဴလေၚ်) (လိက်ကောန်သၟိၚ်ပိ။ မာံခစုန်အံက်။) = “အထိန်းတော်မတို့သည်သာလျှင် (ကလေးငယ်အား) နို့တိုက်ခွင့်ရကုန်၏။”')
,(10533,3,1,'နောက်လွယ်ပလိုင်း။ အဖုံးပါပြီး ဆီမယိုထွက်နိုင်သောပလိုင်း။ စည်ပိုင်း။','ဗမ်ဍာ် =ရေစည်ပိုင်း။')
,(10534,3,1,'ကျောပိုးသယ်ရသောခြင်းတောင်းတစ်မျိုး။',NULL)
,(10535,3,4,'၁။ လိုက်သည်။ လိုက်ပါသည်။','“မိအာပေဲါ အဲဗက်အာမိရ။” = “အမေပွဲသွားရာကျွန်တော်အတူလိုက်သွားသည်။” || ဗက်အာတြုံ = လၚ်နောက်လိုက်သည်။')
,(10535,3,4,'၂။ မောင်းသည်။နှင်သည်။','ဗက်ဖျေံနူသ္ၚိ = အိမ်မှနှင်ချသည်။ || “ဗက်ထောံရုဲညိ။” = “ယၚ်ကောင်ကို မောင်းလိုက်ပါ။” || “(အမာတ်မၞုံဒုဟ်ဂှ်) သၟိၚ်ဗက်ထောံကၠေံနူရးရ။” (ဇ—၃ဝ၃။ အစွောံ။) = “မင်းသည် အပြစ်ရှိသောအမတ်အား တိုင်းနိုင်ငံမှ နှင်ထုတ်ပစ်လိုက်၏။”')
,(10535,3,4,'၃။ (ငွေ) ကောက်ခံသည်။','“ညးကၠုၚ်ဗက်တဴသြန်ဂအုံ သွက်သဘၚ်အတး။” = “သင်္ကြန်ပွဲတော်အတွက် ရန်ပုံငွေလာကောက်ခံသည်။” || ဗက်အကံက်အခေါန်၊ ဗက်အခေါန်ဖလာ = အခွန်ကောက်ခံသည်။ || “မၞိဟ်ဗက်အခေါန်တံဂှ်—။” (ဇ—၅၂ဝ။ အစွောံ။) = “အခွန်ကောက်သောလူတို့သည်—။”')
,(10535,3,4,'၄။ လိုက်ဖက်သည်။','“ပလောအ်သာ်ဗ္ကေတ်ဂှ် ဗက်ကဵုဍေံကွေံရ။” = “အင်္ကျီအနီရောင်က သူနှင့်တကယ်လိုက်ဖက်သည်။”')
,(10536,3,5,'(သဗဓ) —သည်နှင့်—ချက်ချင်း။ တစ်ပြိုင်နက်။','“သၟတ်တြုံကဵုသၟတ်ဗြဴဂှ် ချိုန်မညာတ်ရၚ်သ္ကအ်ဗက် ဇြဟာန်စိုတ်စပ်အာရၚ်သ္ကအ်ရ။” = “သူငယ်နှင့်သူငယ်မတို့သည် တစ်ဦးနှင့်တစ်ဦး မြင်မြင်ချင်း ချစ်ကြိုက်သွားကြသည်။” || “အမာတ်ဇၞော်သၟိၚ်ပဿိုန်ၜါဂှ် ဒၞာဲဒၞာဲမညာတ်ဒးရေၚ်သ္ကံဂှ်ဗက် သွေက်ဇဵုရေၚ်သ္ကံရ။” (ဇ—၁၅၄။ အစွောံ။) = “(ကောသလမင်း၏) အမတ်ကြီးနှစ်ယောက်တို့သည် အချင်းချင်း (တွေ့မြင်ကြသည်နှင့်တစ်ပြိုင်နက်) တွေ့မြင်ကြရာအရပ်­ ငြင်းခုံခြင်းကို ပြုကုန်သတတ်။” (ညောင်ကန်)')
,(10537,3,4,'လိုက်စားသည်။','ဗက်စလ္ပာ်လိက်ပတ် = စာပေဘက်လိုက်စားသည်။')
,(10538,3,4,'စိတ်အလိုကိုလိုက်သည်။ အလိုလိုက်သည်။','“ညးဂှ် ဗက်စိုတ်နာဲပိုဲဗြဴမာန်ရော။” (ဇ—၄၁၇။ အစွောံ။) = “သင့်စိတ်အလိုကို မည်သူလိုက်နိုင်ပါမည်နည်း။”')
,(10539,3,4,'လၚ်နောက်လိုက်သည်။ ခိုးရာလိုက်သည်။',NULL)
,(10540,3,4,'မောင်းထုတ်သည်။ နှင်ထုတ်သည်။ ထွက်ပြေးစေသည်။','“ဒေဝတဴဂှ် နရုပ်မဂပ်ဂဝ်ဖေက်ဂၟံက်ဂှ် ဘဗဟေက်တုဲ ဗက်ဗဒဴကၠေံကၠကဵုဇာဒိသိုၚ်ဂှ်ရ။” (ဇ—၂၇၂။ အစွောံ။) = “ထိုနတ်သည် ကြောက်မက်ဖွယ်ကောင်းသော ရုပ်အသွင်ကိုဖန်ဆင်း၍ ကျားနှင့်ခြင်္သေ့တို့ကို ခြောက်လှန့်၍ မောင်းထုတ်လိုက်၏။” || “ကၠဵုဗြဴဝွံ အဲစမြဗဟေက်တုဲ အဲဒးဗက်ဗဒဴကၠေံခိုဟ်ရောၚ်” ဇာဒိသိုၚ်ဗြဴဂှ်ချပ်။ (ဇ—၁၅၇။ အစွောံ။) = “ဤမြေခွေးမကို ငါခြိမ်းခြောက်မောင်းမဲ၍ ထွက်ပြေးစေရလျှင် ကောင်းမည်” ဟုခြင်္သေ့မ၊ကြံ၏။ || “သၟိၚ်ဣန်ဗက်ဗ္ဒဴထောံကၠေံ ကလော်တံဂှ်—။” (ဇ—၃၄၇။အစွောံ။) = “သိကြားမင်းသည် ထိုဘီလူးတို့ကို မောင်းထုတ်၍ပြေးစေ၏။”')
,(10541,3,4,'မျက်နှာလိုက်သည်။ ဘက်လိုက်သည်။ လိုလားသူကို အခွင့်အရေးပိုပေးသည်။',NULL)
,(10542,3,4,'အပျော်လိုက်သည်။ အပျော်အပါးလိုက်စားသည်။',NULL)
,(10543,3,4,'(တိရစ္ဆာန်) မိတ်လိုက်သည်။','“ဂၠဴဥဿဘမွဲဂှ်ဗက်လွၚ်—။” (ဇ—၄ဝ၈။ အစွောံ။) = “တစ်ခုသောဥဿဘနွားသည် မိတ်လိုက်၏။”')
,(10544,3,4,'တရားအတိုင်းလိုက်နာသည်။','“ကလောတွဳဝါရဇကုဂှ်ရောၚ် ဍေံလုပ်သွး၊ ဍေံဟွံဗက်သၞောဝ်။” (ဇ—၄၇၃။ အစွောံ။) = “မိမိဆွေမျိုးအခြံအရံတို့ကိုသာ သူဘက်လိုက်၍ တရားအတိုင်း သူမလိုက်နာ။”')
,(10545,3,4,'အလိုလိုက်သည်။ အလိုသို့လိုက်သည်။','“ကောန်ၚာ်ကမြမ်ဂှ် လ္ပဗက်အလိုက်ညိ။” = “ထိုကလေးဆိုးကို အလိုမလိုက်ပါနှင့်။” || “ဗက်အလိုက်ညး၊ ပစးညိကောန်။” (လိက်ဝိဓူရ) = “အိုချစ်သား၊ သူတစ်ပါးအလိုကိုလိုက်ပါ၊ မဆန့်ကျင်လေနှင့်။”')
,(10546,3,4,'၁။ ခုတ်သည်။','“ညးဗာ်ထောံတၞံဆုဂှ်ရ။” = “ထိုသစ်ပင်ကို သူခုတ်ပစ်လိုက်သည်။”')
,(10546,3,4,'၂။ ခုတ်မောင်းသည်။','‘က္ၜၚ်ဗာ်ဒၟံၚ်ပ္ဍဲဍာ်။’ = ‘ရေထဲတွင် သင်္ဘောခုတ်မောင်းနေသည်။’')
,(10547,3,4,'ခုတ်ထွင်ရှင်းလင်းသည်။','“တၞံဆုဂြိုပ်ပိုဲဝွံ မၞိဟ်ဂမၠိုၚ်ဗာ်ဆာ်အိုတ်ရအဴ၊ သိက်ပဒးညိရောအဴ” ဒေဝတဴဆုဂှ်ဂး။ (ဇ—၂၇၂။ အစွောံ။) = “ငါတို့၏ဤသစ်တောကို လူများသည် ခုတ်ထွင်ရှင်းလင်းကြကုန်ပြီ၊ အသို့ပြုရအံ့နည်း” ဟုရုက္ခစိုဝ်းနတ်ဆို၏။ || “ပ္ဍဲဂြိုပ်ဂှ် (မၞိဟ်ဂမၠိုၚ်) ဗဒှ်ကၠေံဂၠံၚ်ဇၞော်တုဲ ကုတ်ဒန်ဗာ်ဆာ်ဆုဒုန်တံဂှ်အိုတ်ရ။” (ဇ—၂၇၂။ အစွောံ။) = “လူတို့သည် ထိုတော­ လမ်းဖောက်လုပ်၍ သစ်ဝါးပၚ်တို့ကို ဖြတ်တောက်ခုတ်ထွင်ရှင်းလင်းကြကုန်ပြီ။”')
,(10548,3,1,'အစုအဖွဲ့။ အသင်းအပင်း။ ဂိုဏ်း။ ဘက်တော်သား။','“ပုရိသာတ်ဂမၠိုၚ် ပါ်အာၜါဗော်ရ။” = “ပရိသတ်များ နှစ်ခြမ်းကွဲသွားသည်။” || ဗော်တဳမိစ္ဆာဒိဋ္ဌိ = မိစ္ဆာဒိဋ္ဌိအယူရှိသောထိတ္ထိဂိုဏ်း။ || “ပဟိုတ်ကဵုဗော်တဳ မဒှ်သဟာဲအနာထပိဏ္ဍကသေဋ္ဌဳ ညးမသုန်ကၠံဂှ် အပဏ္ဏကဇာတ်ဝွံ ကျာ်တြဲတွံရ။” (ဇ—၁။ အစွောံ။) = “အနာထပိဏ်သူဋ္ဌေး၏ အဆွေခင်ပွန်းဖြစ်ကုန်သော တိတ္ထိအသင်းအပင်းဖြစ်သော ငါးရာကုန်သောသူတို့ကို အကြောင်းပြု၍ ဤအပဏ္ဏကဇာတ်ကို ဟောတော်မူ၏။” || “ညးမဒှ်ဗော်ကျာ်တံဂှ် သၟိက်ကဵုလပါ်ကျာ်ရ။” (ဇ—၁၆၃။ အစွောံ။) = “ဘုရားဘက်တော်သားဖြစ်ကုန်သောသူတို့သည် ဘုရားဘက်ခြမ်းကို ပေးလှူလိုကြ၏။” || “သမာလှ်ေမၞုံတြဴလ္ၚီနာၚ် — ပါ်ထပှ်ဗော်တုဲ ကဵုလှ်ေတဴအိုတ်ရ။” (ဇ—၄၈၉။ အစွောံ။) = “ခြောက်ထောၚ်သောကချေသည်တို့ကို အစုအဖွဲ့ခုနစ်စုခွဲ၍ ကစေကုန်၏။” || “ဂလာန်မဟွံဒှ်စၟတ်ဂှ် — ဍေံဒှ်ဗော်အကုသဵုရောၚ်။” (ဇ—ဘူရိဒတ်။ အစွောံ။) = “မမှန်သောစကားသည် အကုသိုလ်၏အသင်းအပင်းဖြစ်၏။” || “ဗော်ဗြဴကၟာဲဂှ်၊ မိဒှ်သေၚ်ဟာ။ ယာံဒးဒှ်ကၟာဲ၊လောန်ကာဲလ္ၚာပ်လ္ၚာ။” (လိက်ဝါရဝေါၚ်သ။ အစွောံ။) = “မိခင်သည် မုဆိုးမအသင်းဝၚ်ဖြစ်ရပါလိမ့်မည်။ မုဆိုးမ၊ဖြစ်လေသော် လွန်ကဲစွာပူပန်ရလိမ့်မည်။”')
,(10549,3,4,'(နံ့သာစသည်) လူးသည်။ လိမ်းသည်။','“သၟိၚ်ဂွံစဟာပ်ကျိုၚ်ကျဝ် ဗော်မြမောဝ်တုဲ—။” (ဇ—၅၁။ အစွောံ။) = “မင်းသည် စားသောက်၊ တန်ဆာဆင်ယင်၍ နံ့သာလိမ်းကျံပြီးသော်—။” || “ဗောဓိသတ်ပၠန်တုန်လေဝ် ဟုံဍာ်ဗော်မြမောဝ်တုဲ—။” (ဇ—၂၄၃။ အစွောံ။) =“ဘုရားလောင်းသည် ရေချိုး၍ အမွှေးနံ့သာလိမ်းကျံပြီးသော်—။”')
,(10550,3,4,'(ကလေးသူငယ်) ဝဖြိုးသည်။','“ကောန်ၚာ်ဗှ်ေဗော်ကွေံရ။” = “နင့်ကလေးကတကယ်ဝဖြိုးသည်။”')
,(10551,3,1,'အမျိုး။ အမျိုးအစား။ အပါး။','“ရတ်ဒစိတ်ဗော်၊ ရေၚ်လဝ်ဗြော်ဗြ။” (လိက်ပထမဗောဓိ။ မၚ်ဍိက်လ။) = “ရတနာကိုးပါးတို့ကို အနှံ့အပြားစီရီထားရှိ၏။”')
,(10552,3,4,'(ကလေးသူငယ်) ဝဖြိုးသည်။ ဝဝတစ်တစ်နှင့် ချစ်စရာကောင်းသည်။',NULL)
,(10553,3,1,'ဖခင်ဘက်။ ဖခင်အထံ။','‘ဗော်မိ’ တွင်ရှု။')
,(10554,3,1,'မိခင်ဘက်။ မိခင်အထံ။','“ကောန်မသုန်ဂှ် ဇၞော်ညိတုဲ လ္ပာ်ဗော်မိဂှ် နဲမသုန်ကၠံ ဂိုၚ်ကတ်ကေတ်၊ လ္ပာ်ဗော်မဂှ် နဲမသုန်ကၠံ ဂိုၚ်ကတ်ကေတ်တုဲ နဲလ္ၚီလ္ၚီဟေၚ် လေပ်သီုညးမသုန်ရ။” (ဇ—၃ဝ၁။ အစွောံ။) = “ထိုသားသမီးငါးယောက်တို့သည်လည်း လိမ္မာသောအဖြစ်သို့ ရောက်ကုန်သည်ရှိသော် အမိအထံမှ ဝါဒငါးရာ၊ အဘအထံမှ ဝါဒငါးရာအားဖြင့် ဝါဒတထောၚ်ကို သၚ်ကုန်၏။” (ညောင်ကန်)')
,(10555,3,1,'မိခင်ဖခင်နှစ်ဖက်စလုံးနှင့်ဆိုင်သော ဆွေမျိုးအသိုင်းအဝိုင်း။','“မိဟွံမွဲကၠာ၊ ကလောမသ။ ဟွံမွဲသ္တုံဇွိ၊ ဗော်မိဂၠးမ။” (လိက်ပဒုမဝတဳ) = “မယ့်မှာဆွေမျိုးများမရှိပါ၊ လက်ဝဲဘက်လက်ယာဘက် မိဘနှစ်ဖက်လုံးမှဆွေမျိုးအသိုင်းအဝိုင်းများမရှိပါ။” || “ညးနွံသဳနော်၊ ဗော်မိဂၠးမ။— သ္အဳသ္အဳရိုၚ်ရိုၚ်၊ ညးဗိုၚ်ဆောံမ။” (လိက်ပဒုမဝတဳ) = “ဒေါ်လေးဦးလေးစသော မိဘနှစ်ဖက်မှဆွေမျိုးအသိုင်းအဝိုင်းရှိသောသူအား ထိုဆွေမျိုးများက သိုက်သိုက်ဝန်းဝန်း ဝိုင်းဝန်းကူညီကြသည်။”')
,(10556,3,1,'အခြံအရံ။ ခြွေရံသင်းပင်း။ နောက်လိုက်ဗိုလ်ပါ။ ဘက်တော်သား။ မိမိလူ။','“ယွံမၞးတံ၊ အနာထပိဏ္ဍိကသေဋ္ဌဳဂှ် ဇကုမွဲလေဝ် ဒ္ဂေတ်ဓဝ်သဳလတုဲ ဗော်သွးဇကုသီုဖအိုတ်ဂှ် ကဵုဒ္ဂေတ်ဓဝ်သဳလသီုဖအိုတ်ကီု။” (ဇ—၃၈၂။ အစွောံ။) = “ငါ့ရှင်တို့၊ အနာထပိဏ်သူဋ္ဌေးသည်ကား မိမိကိုယ်တိုင်လည်း သီလစောင့်၍ မိမိ၏အခြံအရံများ အားလုံးတို့ကိုလည်း သီလစောင့်စေ၏။” || “သကိုပ်သာသမၠီု မဟွံဆိုက်ဗ္ဒက်ပ္ဍဲဥပ္ပါယ် မအာဂတတေံဂှ် သီုဗော်သွး ကလော်စကၠေံံမဒှ်ရ။” (ဇ—၁။ အစွောံ။) = “ရှေ့မှသွားသောလှည်းကုန်သည်မိုက်သည် အကြောင်းဟုတ်သည် မဟုတ်သည်ကို မသိသည်ဖြစ်၍ နောက်လိုက်အခြံအရံများနှင့်တကွ ဘီလူးတို့စားပစ်ပြီးဖြစ်လတ္တံ့။”')
,(10557,3,4,'ဘက်လိုက်အုပ်စုဖွဲ့သည်။','“ဒဵုကောန်သမ္ဘာမဆာန် သၟဟ်ကဵုလမျီုၜိုန်ဒှ်ကီု လ္ပၚဳမုက် လ္ပပဗော်သွးညိ။” (ဇ—၉၈။ အစွောံ။) = “အသက်နှင့်ထပ်တူချစ်ရသော သားမယားပၚ်ဖြစ်စေကာမူ မျက်နှာမလိုက်လေနှင့်၊ ဘက်မလိုက်အုပ်စုမဖွဲ့လေနှင့်။”')
,(10558,3,4,'ဖောင်းသည်။ ပွသည်။',NULL)
,(10559,3,4,'ပုဆိုးဝတ်သည်။','ဗိုက်ဂၠိက် = လုံချည်ဝတ်သည်။ || “ရဴယာတ်ဗွိုက်၊ ဗိုက်လဝ်ဟွံ ခြာ။” (လိက်သုဝဏ္ဏသာံ။ မာံသေၚ်။) = “အဝတ်ပုဆိုးကိုကဲ့သို့ အမြဲတစေ ဝတ်ထား၏။”')
,(10560,3,4,'အဝတ်အစားဝတ်ဆင်သည်။','“ဗိုက်လတက်အိုတ်ညိ ဗွိုက်လတက်မန်။” =“မွန်ဝတ်စုံအဝတ်အစားကို ဝတ်စားဆင်ယင်ပါ။”')
,(10561,3,1,'ချောက်ကမ်းပါး။','ဗၚ်ဒဵု = တောင်ချောက်။')
,(10562,3,1,'ရိုင်ပတ်။ (ကောက်ပဲသီးနှံထည့်ရန် ခွေပတ်၍သုံးသော ဖျာရှည်တစ်မျိုး။)',NULL)
,(10563,3,1,'ချောက်ကမ်းပါး။ ချောက်ကမ်းစောက်။ (ပါဠိ—ပပါတ)',NULL)
,(10564,3,3,'ကြမ်းတမ်းသော။ အမွေးများသော။ (ခွေး) အမွေးရှည်သော။ အမွေးစုတ်ဖွားဖြစ်သော။',NULL)
,(10565,3,1,'ရွှံ့ညွန်ထူသောအိုင်။ ကျုံး။ (?)','“ဗၚ်ဗဲတဲလှာ၊ သ္ၚိဇွာရေၚ်ဂျ။” || “ပြယေန်ပြယံက်၊ လဇံက်ရေၚ်မတ်။ ဒှ်ဗွဝ်ရတ်၊ သ္ဇက်တောအ်ၜတ်စ။ ဗၚ်ဗွဲတဲလှာ၊ ရေၚ်ဗ္ဂာသလ။” (လိက်သောဝိန်ဇဲယ။ မာံရောဂေါ။)')
,(10565,3,4,'လှုပ်ရှားသည်။','“ဍောၚ်ဒကှ်သွာ၊ ကျာပိုက်ဗၚ်ဗွဲ။ပံက်ထာၚ်ရာၚ်ဗြံက်၊ ကဝံက်ဗက်တ္ၚဲ။” (လိက်ဒေဝကိနနဳ။ နာဲသိုက်ဇု။) = “ကြာပန်းတို့သည်လေတိုက်သောအခါ လှုပ်ရှားနေကုန်၏။ ပွင့်ချပ်တို့ကိုဖွင့်၍ ပွင့်လန်းကာ နေရှိရာဘက်သို့ညွတ်ကျကုန်၏။”')
,(10566,3,1,'အမည်မဖော်နိုင်သော တောသစ်သီးတစ်မျိုး။','“သစ္ဆုမပ္တံကဵုသတ်မုက်၊ သတ်ဗၠတ်၊သတ်ဣဥူ၊ မ္ၚူ၊ မ္ၚ၊ သတ်ဗၚ်ယ၊ သတ်ချ—။” (ဇ—ဝေသန္တဝ်။ အစွောံ။)')
,(10567,3,1,'၁။ ဝမ်းဗိုက်။','ဗုၚ်ဂိ = ဗိုက်နာသည်။ || ဗုၚ်ခအံၚ် = ဗိုက်အောင့်သည်။')
,(10567,3,1,'၂။ ကိုယ်ဝန်။','“ဗုၚ်သၟတ်ဗြဴဂှ် ဂွံမူစိဂိတုရရော။” = “သူငယ်မ၏ကိုယ်ဝန်သည် ဘယ်နှလရှိပြီလဲ။”')
,(10567,3,4,'ကိုယ်ဝန်ရှိသည်။','“သမ္ဘာညးဗုၚ်ဒၟံၚ်ရ။” = “သူ၏ဇနီးသည် ကိုယ်ဝန်ရှိနေသည်။”')
,(10568,3,4,'(ဆာလွန်း၍) ဝမ်းထဲတွင် မခံချိမခံသာဖြစ်သည်။','“အဲဗျဵုလောန် ဗုၚ်ကဝဲဒၟံၚ်ဣရ။” = “ငါသည် အဆာလွန်၍ ဝမ်းမခံချိမခံသာဖြစ်နေပြီ။”')
,(10569,3,4,'ဝမ်းဖောဝမ်းရောင်ဖြစ်သည်။',NULL)
,(10570,3,4,'ဝမ်းထဲမှမြည်သည်။','‘ဗုၚ်တဏမ်’ ရှု။')
,(10571,3,4,'စားပြီး၍ တင်းတိမ်ရောင့်ရဲသည်။ (‘ဗုၚ်ဟွံကၟန်’ ဟူ၍အသုံးများသည်။)','“ဆဂွံစလဝ်ပုၚ်တုဲကီုလေဝ် ဗုၚ်ဟွံကၟောန်ဏီ။” = “ထမင်းစားပြီးခါစပၚ်ရှိသေးသော်လည်းဗိုက်မရောင့်ရဲသေးပါ။” (တစ်စုံတစ်ခု ထပ်စားချင်သေးသည်ဟု ဆိုလိုသည်။)')
,(10572,3,4,'(အစာကြေသွား၍) ဝမ်းချောင်သည်။',NULL)
,(10573,3,4,'ဗိုက်ရွှဲသည်။','(နဝိ) ဗိုက်ရွှဲသော။')
,(10574,3,4,'ဝမ်းဗိုက်ထဲတွင် ပူလောင်သည်။',NULL)
,(10575,3,4,'ဝမ်းဗိုက်အတွင်း လေနှင့်ရေတို့ကြောင့် အသံမြည်သည်။ (ဗိုက်ဆာသည့်အဓိပ္ပါယ်ဖြင့်လည်း မွန်ဘာသာတွင်သုံးသည်။)','“အဲဗျဵုပုၚ်လောန် ဗုၚ်တဏမ်မံၚ်ရ။” =“ကျွန်တော်ထမင်းဆာလွန်းလို့ ဝမ်းဗိုက်ထဲက အသံမြည်နေပြီ။”')
,(10576,3,4,'ဗိုက်ထွက်သည်။ တရားဝၚ်ဖခင်မရှိဘဲ မွေးဖွားလာသည်။','ကောန်ဗုၚ်တိတ် =ဗိုက်ထွက်၍ရသောကလေး။ တရားဝၚ်အဖမရှိသောကလေး။')
,(10577,3,4,'ဝမ်းဝသည်။ ဝမ်းပြည့်သည်။','“လ္ပညှာ စဒဵုဗုၚ်ဖဲဏး။” = “အားမနာနှင့်။ ဝမ်းဝသည်အထိ စားနော်။”')
,(10578,3,1,'ဆပ်ပြာ။','ဗံၚ်ကလောအ် = ဆပ်ပြာအတုံး။ || ဗံၚ်ခနှိက် = ဆပ်ပြာအမှုန့်။')
,(10579,3,1,'(အပၚ်အရွက်) နူနာဖြစ်ခြင်း။ တွန့်လိမ်ကောက်ကွေးခြင်း။','“တၞံခဍောၚ်ဏအ်မွဲတၞံတၞးဍေံဒှ်ဒၟံၚ်ဗံၚ်ခဲါဒုတ်အိုတ်ရ။” = “ဤခရမ်းပၚ်တစ်ပင်သည် အရွက်များ နူနာဖြစ်နေကုန်ပြီ။”')
,(10580,3,1,'၁။ ကိုင်းပင်။',NULL)
,(10580,3,1,'၂။ စပါးလှောင်သောတောင်းကြီး။',NULL)
,(10581,3,4,'၁။ ဝိုင်းရံသည်။','“ဗဵုပၞာန်ထပှ်က္ဍိုၚ်ဗ္တာၚ်ကၠုၚ်တုဲ ဗိုၚ်လဝ်ဍုၚ်ဗာရာဏသဳရ။” = “ခုနစ်ပြည်ထောင်မင်းတို့၏ စစ်သည်များလာ၍ ဗာရာဏသီမြို့ကို ဝိုင်းရံထားကြ၏။”')
,(10581,3,4,'၂။ ဝိုင်းကူသည်။','“ကိစ္စဝွံ သီုပိုဲညးဂမၠိုၚ် မဒးဗိုၚ်ပ္တုဲရောၚ်။” (ဇ—၄၈၆။ အစွောံ) = “ဤကိစ္စကို ငါတို့တွေအားလုံး ဝိုင်းကူဆောင်ရွက်ရပါမည်။”')
,(10582,3,4,'ဝိုင်းကူသည်။',NULL)
,(10583,3,4,'ပတ်ပတ်လည်ဝိုင်းရံသည်။ ခြံရံ၍တည်သည်။','“(ကၞုဲဂမၠိုၚ်စတဴသတ်မုက်၊ မၞိဟ်ဂမၠိုၚ်) ရပ်ကံတ္ၚလေံတၞဟ်တုဲ အာဗိုၚ်လဝ်တၞံမုက်တုဲ — ဗိုၚ်ကလောအ်လဝ်ရ။” (ဇ—၁၇၇။ အစွောံ။) = “မျောက်များသည် တည်သီးကိုစားနေကြရာ လူများသည် လေးမြှားတုတ်ဓါးကိုင်ကုန်လျက် တည်ပၚ်ကို ပတ်ပတ်လည်ဝိုင်းရံထားကြကုန်၏။” || “မ္ၚး (ဍာ်) ဂှ် ဂြိုပ်ဟံၚ်ရံသက်သက် မွဲယောဇနာ ဗိုၚ်ကၠောံဒၟံၚ်ရ။” (ဇ—၅၁၄။ အစွောံ။) = “ရေ၏အခြားမဲ့­ တယူဇနာအနာံရှိသော ကြာသိမ်တောသည် — ခြံရံ၍တည်၏။” (ညောင်ကန်)')
,(10584,3,4,'စေးကပ်သည်။ မချောမွတ်။','“ကၞဳဆုဏအ် ဟွံဂွံပေါတ်ဓဇိုတ်လဝ်ကဵုသၞံက်သတ်ဗြဴတုဲဗတ်ဒၟံၚ်ရ။” = “ဤသစ်သားကြမ်းပြင်သည် အုန်းခွံဖြင့် မပွတ်တိုက်ထားရသဖြင့် မချောမွတ်ဘဲစေးနေသည်။”')
,(10585,3,5,'၁။ ဖာသာ။ အလိုအလျောက်။','“အဲအာဗတ်အဲ မူကေၚ်ကာဗှ်ေနွံရော။” = “ငါ့ဖာသာငါသွားတာ နၚ်နှင့်ဘာဆိုင်သလဲ။” || “ကျာ်ဂ္ၚေၚ်အာဗွဲဗတ်ကျာ်။” (ဇ—၄၂၈။ အစွောံ။) = “မြတ်စွာဘုရားသည် ကိုယ်တော့်ဖာသာ (တစ်ပါးတည်း) ကြွသွားတော်မူ၏။” || “ဟာဲလဗြဴ၊ဗှ်ေဒတုံစှ်ေဗတ်ဗှ်ေဂှ် မူပဗှ်ေလက်သၟိၚ်ရော။ မူဒုဟ်သၟိၚ်မနွံရော” ပြောဟိတ်ဂး။ (ဇ—၅၂ဝ။ အစွောံ။) = “ဟယ်မိန်းမအို၊ နင့်ဖာသာနၚ်ပြုတ်ကျတာ ဘုရင်ကို ဘာကြောင့်နၚ်ဆဲသလဲ။ ဘုရင်မှာ ဘာအပြစ်ရှိလို့လဲ။”')
,(10585,3,5,'၂။ ဘာသာစကားဖြင့်။ —လို။','“ဟီုဗတ်မန်ညိ၊ လ္ပဟီုဗတ်ဗၟာညိ။”= “မွန်လိုပြောပါ၊ ဗမာလိုမပြောပါနှင့်။” || “ကဝိတမၠာ၊ လောန်အာအိုတ်ရ။ ပ္ဍဲထာန်ဒေသ၊ ထာဏရးမန်။ လိက်ပတ်မဂး၊ သွက်ညးဂွံဆန်။ ဟွံမွဲသေၚ်ဟာ၊ ဗတ်ဘာသာမန်။” (လိက်ဗြရတ်ဣဏၚ်ကၚ်ရဳ။ မာံရောဂေါ။) = “ရှေးကဝိစာဆိုတော်များသည် ကွယ်လွန်သွားကြကုန်ပြီ။ မွန်တိုင်းဋ္ဌာန­ စာပေများကို မွန်ဘာသာဖြင့် ရေးသားစပ်ဆိုမည့်သူများမရှိတော့။”')
,(10585,3,6,'ကဲ့သို့။သဖွယ်။ လို။','‘မံၚ်ဗတ်သေဋ္ဌဳ။’ = ‘သူဋ္ဌေးကဲ့သို့နေသည်။’ || “ဍေံစကာအဲ ဗတ်ဍိက်ရ။” =“ငါ့ကို ကျွန်လိုသူခိုင်းသည်။” || “(သၟိၚ်ကုသ) ကော်ခုဇ္ဇာရ။ — (ခုဇ္ဇာ) ပဗတ်ဟွံမိၚ်တုဲ ကွာ်အာတဴရ။” (ဇ—၅၃၁။ အစွောံ။) = “ကုသမင်းသည် ခုဇ္ဇာကိုခေါ်၏။ ခုဇ္ဇာသည် မကြားသကဲ့သို့ပြု၍မကြားချင်ဟန်ဆောင်၍) လျှောက်သွား၏။”')
,(10586,3,7,'အကယ်၍။','“ကျာ်တြဲဂှ် ဗတ်ရဣတေံတဴပ္ဍဲသ္ၚိကၟိန်ဂှ် ဒှ်စက္ကဝဝ်ရောၚ်။” (ဇ—၂၈၁။ အစွောံ။) = “သဗ္ဗညုမြတ်စွာဘုရားသည် အကယ်၍အိမ်­နေငြားအံ့၊ စကြဝတေးမင်းဖြစ်လတ္တံ့။” (ညောင်ကန်) || “ဍေံဝွံဂှ် ဗတ်ရဍေံဒှ်ကလော်ဂှ် ဍေံလုပ်ကၠုၚ်တုဲ ဍေံရပ်စအဲရ။ဍေံဝွံ ကလော်ဟွံသေၚ်၊ ဣသိရောၚ်မတန်ဒှ်ရ။” (ဇ—၅၂၆။ အစွောံ။) = “ဤသူသည် အကယ်၍ဘီလူးဖြစ်ငြားအံ့၊ ကျောင်းတွင်းသို့ဝင်၍ တည်သောငါ့ကို ကျွတ်ကျွတ်မြည်စေ၍ စားလေရာ၏။ ဤသူသည် ဘီလူးမဟုတ်၊ ရသေ့ဖြစ်လတ္တံ့။” (ညောင်ကန်)')
,(10587,3,5,'မိမိဖာသာအထီးတည်း။','“ဒြာဲသ္ဇိုၚ်ဒလောံဗတောန်ဂှ် ဂ္ၚေၚ်အာဗတ်ဇကုမွဲတုဲအာဒးဒနက်လၟရ။” (ဇ—၁၅။ အစွောံ။) = “ဆိုနိုင်ခက်သောသမင်သည် မိမိဖာသာအထီးတည်းလှည့်လည်သွားသည်ရှိသော် မုဆိုး၏ကျော့ကွင်း­မိ၏။” || “(ကလော်ဗြဴဂှ်) ပ္ဍဲဇရေၚ်တရၚ်ဂှ် ဍေံဂ္ဇံဒၟံၚ်ဗတ်ဇကုမွဲရ။” (ဇ—၉၆။ အစွောံ။) = “ထိုဘီလူးမသည် တံခါးအနီး­ မိမိဖာသာအထီးတည်းထိုင်နေ၏။” || “ယြဴဆုမွဲဂှ် ဒၟံၚ်ပ္ဍဲတၞံဗတ်ဇကုမွဲဂှ် ၜိုန်တၞံဆုဇၞော်ဂှ်လေဝ်ကဵုဒှ်ကီုရ၊ ဒးဒြဟတ်ကျာဇၞော်တုဲ မဒးကဝ်ဒေံါအာကီု။” (ဇ—၇၄။ အစွောံ။) = “မိမိဖာသာအထီးတည်းတည်ရှိသောအကြင်သစ်ပင်သည် အပၚ်ကြီးစေကာမူ အားပြင်းသောလေနှင့်တွေ့သောအခါ ကျိုးပြတ်လဲကျသွားရ၏။”')
,(10588,3,11,'(န) သိကြားမင်း၏ဝရဇိန်လက်နက်။','“ပတၠညာန်ပညာ ညံၚ်လွဟ်ဗဇ္ဇဗတ်။” (သၠပတ်အနမတဂ္ဂသံသာရကထာ) = “ဝရဇိန်လက်နက်နှင့်တူသော ဉာဏ်ပညာရှင် ဖြစ်သည်။” || ‘လေံဗတ်’ နှင့်အတူတူ။')
,(10589,3,5,'သဘာဝအလျောက်။ သူ့အလိုအလျောက်။','“ဗောဓိသတ်ပိုဲဒှ်ၜိုပ်ထဝ် အာဂ္ၚေၚ်စသြောံဂန္ဓသာလဳမဒှ်ဗတ်ဍေံဂှ်ရ။” (ဇ—၃၇ဝ။ အစွောံ။) = “ဘုရားလောင်းသည် ရွှေဟင်္သာမျိုး­ဖြစ်၍ အလိုလိုဖြစ်သော သလေးစပါးကိုစား၍ သွားလာ၏။”')
,(10590,3,11,'(န) ပြာ။ ဖွဲပြာ။ (ပါဠိ—ဘသ္မ)','“နာဲသာဗၞိက်မွဲဂှ်ပဲါလဝ်တုဲ ကောန်ဗၞိက်သမၠီုတံဂှ် ကဵုဒှ်ဗတ်သၟရ၊ ကဵုဒှ်ချောံပတေၚ်ရ” သၟိၚ်နာ်ဂး။ (ဇ—၄၉၃။ အစွောံ။) (ဗတ်သၟ= ချောံပတေၚ်) = “လှည်းကုန်သည်မှူးကိုသာလျှင်ထား၍ ထိုကုန်သည်မိုက်တို့ကို ဖွဲပြာဖြစ်စေကုန်လော့” ဟုနဂါးမင်းဆို၏။ || “ယာံစိၚ်ဂမၠိုၚ်ဂွံကျာမၞိဟ် ဆဵုဒးသတြုတုဲ လၞိန်ဖလှေက်ကၠေံ ဒှ်အာဘသၟရောၚ်။” (ဇ—၅၁၄။ အစွောံ။) = “ထိုဆင်များသည် လူနံ့ရ၍ ရန်သူကိုမြင်သည်ရှိသော် ပြာဖြစ်သွားအောင် နင်းခြေပစ်ကြလိမ့်မည်။”')
,(10591,3,12,'(န) တူရိယာပစ္စည်း။',NULL)
,(10592,3,1,'လခြမ်းတူရိယာ။',NULL)
,(10593,3,1,'ကြေးနောၚ်ဆယ်လုံးရှိ လခြမ်းပတ်ဝိုင်း။ ဆိုင်းဝိုင်း။',NULL)
,(10594,3,1,'သံပတ္တလား။',NULL)
,(10595,3,1,'ပတ္တလား။',NULL)
,(10596,3,1,'ဝါးပတ္တလား။',NULL)
,(10597,3,1,'ဝါးဆစ်တူရိယာ။',NULL)
,(10598,3,1,'ပတ်ဝိုင်း။',NULL)
,(10599,3,1,'သားရေနှင့်ဆိုင်သော တူရိယာပစ္စည်းများ။',NULL)
,(10600,3,1,'ကြေးဝါနှင့်လုပ်ထားသော မောင်း၊ ပတ္တလားစသည်။',NULL)
,(10601,3,1,'ကြေးနီနှင့်လုပ်ထားသော မောင်း၊ ပတ္တလားစသည်။',NULL)
,(10602,3,1,'ခိုးသူသတ်။ ဘုရင်၏အာဏာပါးကွက်သား။','“(သၟိၚ်) ကော်နၚ်ဗာတ်ဇခါတ်ရ။” (ဇ—၃၁၃။ အစွောံ။) = “(မင်းသည်) ခိုးသူသတ်ကို ခေါ်စေ၏။” (ညောင်ကန်) || “(သၟိၚ်) ကဵုအာကော်ဗာဇ္ဇခါတ်ရ။” (ဇ—၃၅၈။ အစွောံ။)')
,(10603,3,12,'(န) ဗြိစ္ဆာရာသီ။ (ဆယ့်နှစ်ရာသီတွင် ကင်းမြီးကောက်ရုပ်ဖြင့် မှတ်အပ်သောအဋ္ဌမရာသီ။)',NULL)
,(10604,3,1,'‘ဗဳဇနာ’ ရှု။',NULL)
,(10605,3,16,'(န) အတတ်ပညာများနှင့် ပြည့်စုံသောအရပ်။','“ဗိတ်ဒျာဓနဳ၊ဂၠိုၚ်ကွတ်ဖဳတ္ၜန်။” (လိက်သောဝိန်ဇဲယ။ မာံရောဂေါ။) = “ဗိတ်ဒျာဓါနဳဆိုသည်မှာ အတတ်ပညာများ များပြားပြည့်စုံသောအရပ်တည်း။” || ‘ဓနဳပန်သာ်’ (န) လည်းရှု။')
,(10606,3,4,'၁။ ကြိတ်သည်။','ဗုတ်သ္ၚု = ဆန်ကြိတ်သည်။')
,(10606,3,4,'၂။ ပွတ်တိုက်သည်။','“ဆုဇမ်ကှ်ၜါဝွံ ဗုတ်ဒၟံၚ်ရၚ်သ္ကံ ကနှိက်ဆုမတိတ်ဗဝ်ဒၟံၚ်ဝွံဂှ် ဗွဲကြဴဍေံက္တဵုဗဒှ်ပၟတ်ရောၚ်။” (ဇ—၃၆။ အစွောံ။) = “ဤသစ်ခက်ခြောက်နှစ်ခုတို့ အချင်းချင်းပွတ်တိုက်၍ သစ်မှုန့်တို့ထွက်ပုံနေသည်မှာ နောၚ်မီးကိုဖြစ်ပေါ်စေလိမ့်မည်။”')
,(10606,3,4,'၃။ ချောအောင်ပွတ်သည်။ ချောအောင်သွေးသည်။','“ဒဇဲဒမာတ်၊သောန်ဒါတ်ၜုန်မြ။ ချူပုတ်ဗုတ်သောန်၊ ကလောန်သဗ္ဗ။” (လိက်သောဝိန်ဇဲယ။ မာံရောဂေါ။) =“လက်သမား၊ ပန်းပဲတို့သည် ဓါး၊ ဓါးမတို့ကို သွန်းထုပြုလုပ်ခြင်း၊ ထက်အောင်သွေးခြင်း၊ ထွင်းထုခြင်း၊ ချောအောင်ပွတ်ခြင်း၊ သွန်းခြင်း အလုပ်မှန်သမျှကို ပြုလုပ်ကုန်၏။”')
,(10607,3,4,'ပူဆာသည်။ ထပ်တလဲလဲတောင်းဆိုသည်။ မရမကတောင်းဆိုသည်။','“ကၞုဲဂမၠိုၚ်သၟိက်ဂွံစ (သတ်မုက်) တုဲ ဗုတ်စဝ်ဗောဓိသတ် (သၟိၚ်ကၞုဲရ။)” (ဇ—၁၇၇။ အစွောံ။) = “မျောက်များသည် တည်သီးကိုစားချင်၍ ဘုရားလောင်းမျောက်မင်းအား ပူဆာကုန်၏။” || “ကောန်ၚာ်သၟတ်သမၠီုမွဲဂှ် ဍေံညာတ်စက်ဂိတုတုဲ ယွံယာဲပိုဲ တေံစက်ဂိတုတေံဂှ် ကေတ်ကဵုအဲညိ အဲပကွဳဍေံဂးတုဲ ဍေံဗုတ်စဝ်ယာံတဴရ။” (ဇ—၃၅၄။ အစွောံ။) = “တစ်ယောက်သောသူငယ်မိုက်သည် လဝန်းကိုမြင်၍ အို—မိခင်၊ ထိုလဝန်းကို ယူပေးပါ၊ အကျွန်ုပ်လှည်းလုပ်ပါမည်ဟု ပူဆာငိုကြွေး၏။” || “ကောန်ၚာ်ဗြဴ—ဂှ် ဍေံညာတ်ညးသ္အာၚ်စရှ်ပ္ကဴထဝ်တုဲ ဍေံယာံဗုတ်စဝ်ရ။” (ဇ—၄ဝ၆။ အစွောံ။) = “ထိုကလေးမငယ်သည် သူတစ်ပါးတို့ ရွှေပန်းပန်သည်ကိုမြင်၍ (လိုချင်၍) ငို၍ပူဆာ၏။” || “သၟိၚ်ကုသသၟိက်ဂွံညာတ် ပြဘာဝတဳပၠန်တုဲ ဗုတ်စဝ်မိပၠန်ရ။” (ဇ—၅၃၁။ အစွောံ။) = “ကုသမင်းသည် ပဘာဝတီကို မြင်လိုပြန်၍ မယ်တော်အား ပူဆာတောင်းဆိုပြန်၏။” || “သၟတ်ၜါမၠာ်မွဲ ညာတ်သစ္ဆုတံဂှ်တုဲ သၟိက်ဂွံစ ယာံဗုတ်စဝ်တဴရ။” (ဇ—ဝေသန္တဝ်။ အစွောံ။) =“ကလေးနှစ်ယောက်တို့သည် ကြည့်လေသော် သစ်သီးတို့ကိုမြင်၍ စားချင်သည်ဖြစ်၍ ငိုကြွေးပူဆာကုန်၏။”')
,(10608,3,10,'(န) ဗုဒ္ဓဘုရား။',NULL)
,(10609,3,11,'(န) ဗုဒ္ဓ၏ဂုဏ်တော်။ မြတ်စွာဘုရားဂုဏ်တော်။','“ကဵုဂွံဗှ်ဗၞုဟ်မံၚ် ဗုဒ္ဓဂုဏ်ဓမ္မဂုဏ် သံဃဂုဏ်လၟိုန်—။” (အကြီုရာဇာဓိရာဇ်) = “ဘုရားဂုဏ်တော်၊ တရားဂုဏ်တော် သံဃာဂုဏ်တော်တို့ကို အစဉ်အောက်မေ့နေပါစေ။”')
,(10610,3,11,'(န) ဗုဒ္ဓကိုယ်ပွားတော်။ နိမ္မိတ။','“ဗုဒ္ဓနိမိတ်အဲကျာ် ပၠလျးတရဴသာ်ရ။” (သၠပတ်အဓါန်မသုန်။ အစွောံ။) = “ငါဘုရား၏ဗုဒ္ဓကိုယ်ပွားတော်သည် ရောင်ခြည်တော်ခြောက်သွယ်ကို လွှတ်လတ္တံ့။”')
,(10611,3,10,'(န) ဗုဒ္ဓဘာသာ။ ဗုဒ္ဓတရားတော်ကို ယုံကြည်သူ။','ကောန်ဗုဒ္ဓဘာသာ = ဗုဒ္ဓဘာသာဝင်။')
,(10612,3,11,'(န) ဘုရားရတနာ။','“ပ္ဍဲဗုဒ္ဓရတ်ကီု ပ္ဍဲသံၚ်ဃရတ်ကီု — အဲပူဇဴလၟိုန်ရ။” (ဇ—၄၉၆။ အစွောံ။) = “ဘုရားရတနာကို၄င်း သံဃာရတနာကို၄င်း ငါသည် အမြဲပူဇော်၏။”')
,(10613,3,11,'(န) ဗုဒ္ဓရုပ်ပွားတော်။',NULL)
,(10614,3,1,'ဗုဒ္ဓဟူး။','တ္ၚဲဗုဒ္ဓဝါ = ဗုဒ္ဓဟူးနေ့။ || ဂြိုဟ်ဗုဒ္ဓဝါ = ဗုဒ္ဓဟူးဂြိုဟ်။')
,(10615,3,11,'(န) ဗုဒ္ဓမြတ်စွာဘုရား၏ ဖြစ်စဉ်အကြောင်း၊ ဗုဒ္ဓဝင်။ (ပါဠိ—ဗုဒ္ဓဝံသ)',NULL)
,(10616,3,10,'(န) ဗုဒ္ဓသာသနာ။',NULL)
,(10617,3,11,'(န) ဗုဒ္ဓသာသနာသက္ကရာဇ်။',NULL)
,(10618,3,11,'(န) ဗုဒ္ဓဘုရားတစ်ဆူနှင့်တစ်ဆူကြားကာလ။ ဘုရားနှစ်ဆူတို့၏အကြား။ (ပါဠိ—ဗုဒ္ဓန္တရ)',NULL)
,(10619,3,10,'(န) ဗောဇ္ဈၚ်။ အရဟတ္တမဂ်ဉာဏ် သဗ္ဗညုတဉာဏ်ကို သိခြင်း၏အကြောင်း။',NULL)
,(10620,3,1,'၁။ အိုးပုတ်ကလေး။ အိုးငယ်။','“(ဣသိတုန်) သၠကလှာၚ်သြိုဟ်ၜိုဟ်လဝ်ဂှ် ဟွံစကဵုကၠေံဒါန်တုဲ ဗကပ်ကၠေံဗောတ်ဂှ်ရ။” (ဇ—၄၈ဝ။ အစွောံ။) = “ရသေ့သည် ပြုတ်ထားသောကံပြင်းရွက်ကို မစားဘဲ အလှူပေးလိုက်ပြီးလျှင် ထိုအိုးငယ်ကို မှောက်ထားလိုက်၏။” || “ဍာ်တှ်မွဲဗောတ်။” (သၠပတ်ရာဇာသာန်) = “နို့တစ်အိုး။”')
,(10620,3,1,'၂။ ဝှေးကြီးခြင်း။','ယဲဗောတ် = ဝှေးကြီးရောဂါ။ မုတ်ကြီးရောဂါ။ ကပ်ပယ်အိတ်ရောၚ်နာ။')
,(10621,3,12,'(န) စိန်ကျောက်။','“ဒၞာဲဝွံ မတ်ဗိုတ်နွံဗွဲမဂၠိုၚ်ရ။” (ဇ—၄၆၃။ အစွောံ။) =“ထိုသမုဒ္ဒရာ­ ဝဇိရစိန်ကျောက်မျိုးသည် များ၏။” (ညောင်ကန်)')
,(10622,3,4,'၁။ ပစ်သည်။','“(မၚ်ဗၠာဲ) သဥ္ဇိဝရပ်ကြေဟ် မန်မဂၠိုၚ်ကဵုလတုန်တုဲ ဗိုတ်စုတ်ဇွကၠ ခြုဟ်ဇွကၠဒလိုက်က္တဵု—။” (ဇ—၁၅ဝ။ အစွောံ။) = “သဥ္ဇိဝလုလင်သည် ကျောက်စရစ်ကိုကိုင်၍မန္တရားကို အကြိမ်ကြိမ်သရဇ္ဈာယ်ပြီးလျှင် ကျားသေကို ကျောက်စရစ်ဖြင့်ပစ်၏။ ကျားသေသည်ရုတ်ချည်းထ၏။”')
,(10622,3,4,'၂။ စွန့်ပစ်သည်။','“မၞိဟ်ဗ္ၜူအရက်ဂှ် ဗိုတ်ထောံကၠေံဂၠိက်ယာတ်တုဲ မံၚ်ကေတ်ဇကုသၟးရ။” = “ထိုအရက်သမားသည်မူး၍ အဝတ်အစားကိုစွန့်လျက် ကိုယ်လုံးတီးဖြင့်နေ၏။”')
,(10622,3,4,'၃။ သုတ်ယူသည်။ သုတ်ချီသည်။','“အသီမွဲဗိုတ်ဂွံဏာဖရာပ်ဗြဴဂှ်—။” (ဇ—၄၉ဝ။ အစွောံ။) = “သိမ်းငှက်သည် ခိုမကို သုတ်ချီသွား၏။”')
,(10622,3,4,'၄။ လိမ်လည်သည်။ လှည့်စားသည်။','“အဲညာတ်ဒၟံၚ်နမတ်အဲရ။ ပမဗိုတ်အဲပၠန်ရော။” (ဇ—၁ဝ၄။ အစွောံ။) = “ငါ့မျက်စိနှင့် ငါတပ်အပ်မြင်နေရပါလျက် အဘယ်ကြောင့် ငါ့ကို သၚ်လိမ်လည်ပြန်ဘိသနည်း။”')
,(10623,3,1,'ဝေဒကျမ်း။','လေပ်ဗိုတ်ပိ = ဝေဒသုံးကျမ်းကိုတတ်သည်။')
,(10624,3,1,'ဝေဒသုံးကျမ်း။ ဝေဒသုံးပုံ။','“သုတိဗိုတ်မွဲ၊ ပ္ဍဲပထမ။ သမုတ္တိကီု၊ သီုလက္ခဏ။ ဣဝွံဗိုတ်ပိ၊ ယုတ္တိဂါမ။” (လိက်သောဝိန်ဇဲယ။ မာံရောဂေါ။) = “သုတိ၊ သမုတ္တိ၊ လက္ခဏဟူသောဝေဒသုံးပုံ/ဝေဒသုံးကျမ်း။” || ဗိုတ်ပိဗေဒၚ်ပန် = ဝေဒသုံးပုံနှင့်ဗေဒင်လေးကျမ်း။ || (မှတ်ချက်။ မြန်မာတွင် ‘ဗေဒင်သုံးပုံ’ ဟု အဆိုရှိသော်လည်း မွန်တွင် ‘ဗေဒင်လေးပုံ/ဗေဒင်လေးကျမ်း’ဟုလာသည်။) || ‘ဗေဒၚ်ပန်’ (န) လည်းရှု။')
,(10625,3,4,'(ကျောက်ခဲစသည်ဖြင့်) ပစ်ခတ်သည်။ ပစ်ပေါက်သည်။','“ပ္ဍဲအဲလုပ်အာကဵုသၟိၚ်လၟုဟ်ဝွံဂှ် လ္ပကဵုညးဂွံဗိုတ်ကၠဟ်အဲညိအဴ” သာ်ဝွံဗောဓိသတ်သၟိၚ်ကၠဵု ပအဓိဋ္ဌာန်။ (ဇ—၂၂။ အစွောံ။) = “မင်းထံသို့ယခုသွားသောငါ့အား လူတို့သည် ပစ်ပေါက်တိုက်ခိုက်ခြင်း မပြုပါစေသတည်း” ဟုဘုရားလောင်းခွေးမင်း အဓိဋ္ဌာန်ပြု၏။')
,(10626,3,4,'ပဋိသန္ဓေတည်သည်။','“ဗောဓိသတ်စုတိစှ်ေကၠုၚ် နူဍုၚ်ဗြီုတုဲ စှ်ေဗိုတ်ပဋိသန္ဓိပ္ဍဲဂၠံဂဝ်ဗမၞိဟ်ဂှ်—။” (ဇ—၄၄၃။ အစွောံ။) = “ဘုရားလောင်းသည် ဗြဟ္မာ့ပြည်မှ စုတေခဲ့၍ ထိုပုဏ္ဏေးမ၏ဝမ်း­ ပဋိသန္ဓေတည်၏။”')
,(10627,3,4,'ဖက်သည်။',NULL)
,(10628,3,4,'(ချစ်ခင်ကြောင်းဖော်ပြသောအားဖြင့်) လည်ချင်းဖက်သည်။','“(ဒကာဗြဴဂှ် ပကၠေံကာဂစိုတ်တုဲ) မှာထေဇၞော်တံဂှ် တိတ်စိုပ်ဘာတုဲ ဗန်ကအ်ညးသ္ကံတုဲ ယာံတဴအိုတ်ရ။” (ဇ—၁၄၆။အစွောံ။) = “ထိုဒကာမကြီးသေသည်ရှိသော် ထိုရဟန်းကြီးတို့သည် အချင်းချင်းလည်ကိုဖက်၍ငိုကြကုန်၏။”')
,(10629,3,4,'လက်ပိုက်သည်။','“ဍေံဒှ်ဒၟံၚ်ဒဒိုက်တၟာဏအ် ဗန်တဲတုဲ ဗှ်ေရံၚ်ဗဵုတိုန်စိုတ်ဟာ။” =“သူဒီလောက်ဒုက္ခဖြစ်နေတာ နၚ်လက်ပိုက်ပြီး ကြည့်နေရက်သလား။” || “(သၟာတ္ၚဒယှ်) ညးပန်ဂှ်ကာလကံအိုတ်သ္အးအာတုဲ ဗန်တဲကၞပ်ဒၟံၚ်ရ။” (ဇ—၅၂၂။ အစွောံ။) = “လေးသမားကျော်လေးယောက်တို့သည် မြားကုန်သွားသောအခါ လက်ပိုက်၍ ငြိမ်သက်နေ၏။” || “ဟိုတ်လၞုဟ်ပၠန်၊ ဂဇအ်ဗန်တဲ။” (လိက်သၟိၚ်စိၚ်ဆဒ္ဒန်။ နာဲထဝ်စိုပ်။) = “ပျင်းရိသောကြောင့် လက်ပိုက်၍ထိုင်နေရ၏။”')
,(10630,3,1,'လင်ပန်း။ (လှူဖွယ်ဝတ္ထု၊ လက်ဆောင်ပစ္စည်းစသည်ထည့်စရာ)',NULL)
,(10630,3,4,'၁။ (အစေးဖြင့်) ကပ်သည်။','“လိက်လလောၚ်တြးဂှ် ဗာန်လဝ်ပ္ဍဲဗ္ဒၚ်ဘာညိ။” = “ကြော်ငြာစာကို ကျောင်းနံရံတွင် ကပ်ထားပါ။”')
,(10630,3,4,'၂။ အနားကပ်သည်။','“ကောန်ၚာ်ဂှ် ဗာန်ဒၟံၚ်ယာဲလၟိုန်ရ။” = “ထိုကလေးသည် အမြဲမိခင်အနားကပ်နေသည်။” || “ကၞုဲဂၚ်ဝုတ်အဵု၊ ရမျှာၚ်ကြဵုဇာ။ ကောန်ဗာန်ပ္ဍဲသြိုဟ်၊ ဗြိုဟ်ခလှာ်အာ။” (လိက်ဇိဝှစက္က) = “မျောက်၊ မျောက်ညို၊ မျောက်လွှဲကျော်တို့သည်ကြုံးဝါးအော်မြည်နေကုန်၏၊ သားကိုရၚ်မှာကပ်ထားလျက် အမြန်ခုန်သွားကြကုန်၏။”')
,(10631,3,1,'အခွန်။','“အခေါန်ဗာန်ဒါ ရိုဟ်သၞာံမဒးပလံၚ်ကဵုသၟိၚ်ဓဝ်သမလ။” (ရာဇာထ္ၜုတ်) (အခေါန် = ဗာန်ဒါ) = “သမလမင်းအား နှစ်တိုင်းအခွန်ပို့ဆက်ပေးရ၏။” || “ရိုဟ်သၞာံမဒးဆက်တွာဲ အခေါန်ဗာန်ဒါတၠညးဟေၚ်။” (ရာဇာထ္ၜုတ်) || “အခေါန်ဗာန်ဒါ၊ အရာသဗ္ဗ။” (လိက်ကောန်သၟိၚ်ပိ။ မာံခစုန်အံက်။)')
,(10632,3,10,'(န) အစက်အပေါက်။','‘ထပက်ဗိန္ဒု’ (ကြိ) လည်းရှု။')
,(10633,3,12,'(န) ၁။ ဗိန္ဒော။ (သစ်ရွက်၊ သစ်ဖုစသည်တို့ဖြင့် ဖော်စပ်ကုသသောဆေးပညာ)','ဂဥုဲဗိန္ဒော = ဗိန္ဒောဆေး။ || “သဝ်မဒယှ်၊ သၟဟ်ဇဳဝက။ ပြကိုဟ်ဗိန္ဒော၊ နဳဒါန်ရောဂ။ ထပှ်သာ်တၟပ်၊ တီအိုတ်သဗ္ဗ။” (လိက်နဲယသမုဒ္ဒြဳ။ အစွောံ။) = “ဆရာဇဳဝကနှင့်တူညီသော သမားတော်အကျော်အမော်များသည် ရောဂါအကြောင်းဖြစ်သော ဗိန္ဒောကျမ်းခုနစ်စောၚ်တို့ကို အလုံးစုံတတ်မြောက်ကုန်၏။”')
,(10633,3,12,'(န) ၂။ ဗေဒင်ဟူးရားအတတ်။ ဗေဒင်ဟူးရာပညာရှင်။','“တိုန်သက္ကရာဇ်တၟိတုဲ ဇက်အာရောၚ်ခိုဟ် နူအ္စာဗိန္ဒောဟောရာတံပ္တီ။” (အကြီုရာဇာဓိရာဇ်) = “နှစ်သစ်ကူးမှစစ်ချီလျှင် ကောင်းလိမ့်မည်ဟု ဗေဒင်ဟူးရားဆရာ အခါတော်ပေးတို့ လျှောက်တင်ကြ၏။”')
,(10634,3,4,'သုံးမကုန်အောင်','ပြောမကုန်အောင်များသည်။ ဗုံးပေါလအောများသည်။ || “အကြီုဟေမဝန်၊ နွံတဴဗုန်ဗဝ်။ ဗက်ဟီုဟွံအိုတ်၊ ဟိုတ်ဒှ်အသဝ်။” (လိက်သၟိၚ်စိၚ်ဆဒ္ဒန်။ နာဲထဝ်စိုပ်။) = “ဟိမဝန္တာတော၏အကြောင်းကား များလှစွာ၏။ အံ့ဖွယ်အကြောင်းတို့ကို ဆို၍မကုန်နိုင်။” || “(သ္ၚုဂှ်) ညးကၠုၚ်သြးလဝ်၊ ဗုန်ဗဝ်သေၚ်ဟာ။” (လိက်သၟိၚ်အသး။ နန္ဒသာရ။) =“ဆန်ကိုလာဖွပ်ထားပေးသည်မှာ ဗုံးပေါလအောများလှသည် မဟုတ်လော။” || “ကဝ်လဗမြိုက်၊သတ်သတိုက်ဗဝ်။ သဗ္ဗနွံသၟတ်၊ အပေါတ်ကျိုၚ်ကျဝ်။ ဂၠိက်ယာတ်ထဝ်သန်၊ သတ်တိတ်ဗုန်ဗဝ်။” (လိက်သုပိဏ္ဏကုမ္မာ။ မၚ်သၚ်ကြာ။) = “နတ်­ဖြစ်သောပဒေသာပင်သည် အသီးပြွတ်သိပ်၍ အရာခပ်သိမ်းရှိကုန်၏၊ လှဝတ်တန်ဆာ အဝတ်ပုဆိုးရွှေငွေတို့သည် သုံးမကုန်အောင် ပြွတ်သိပ်ပေါများစွာ သီးထွက်ကုန်၏။”')
,(10635,3,4,'အထူးတောင်းဆို၍ ဝယ်ယူသည်။ မရမကတောင်းဆို၍ ဝယ်ယူသည်။','“သ္ၚုညးဂှ်သွက်သွံစဟွံသေၚ် သွက်ညးစရောၚ်ညးဂး။ အဲဗေန်ရာန်နၚ်ဘာ်နရ။” = “သူ့ဆန်က ရောင်းဖို့မဟုတ် သူစားဖို့သာဖြစ်သည်ဟု သူဆိုသည်။ ကျွန်တော်မရမကတောင်းဆို၍ တင်းဝက်ဝယ်ယူလာသည်။”')
,(10636,3,4,'ပါးပါးခုတ်လှီးသည်။','“ကတ်စဳကြံၚ်ကြံၚ်ဂှ် ဗောန်တုဲ ညးတအ်ပေက်စပွေက်ရ။” =“သင်္ဘောသီးအစိမ်းကို ပါးပါးခုတ်လှီးပြီး သူတို့လက်သုပ်သုပ်စားကြသည်။”')
,(10637,3,4,'၁။ ခိုင်ခံ့သည်။ မြဲမြံသည်။','“မၞိဟ်လွပ်ဂှ် ဒက်လဝ်ဇုက်ကဵုဗိုန်ညိ။” = “ဖမ်းထားသောလူ (တရားခံ) ကို ခိုၚ်အောင်ကြိုးတုပ်ထားပါ။” || “ဗွဲမဆာန်သၟိန်ဒဒှ်ေယှ်မဗိုန်ဂှ် ဒှ်တဴရ။ ညးဟီုပလီုဟွံမာန်ရ။” (ဇ—၃ဝ၂။ အစွောံ။) = “အကျွမ်းဝင်ခြင်းသည် အလွန်မြဲမြံ၏။ တစုံတယောက်သောသူသည်လည်း မဖျက်ဆီးနိုင်။” (ညောင်ကန်) || “ယြဴသၟိၚ်မွဲ ဂွံဗိုန်ဒၟံၚ်ပ္ဍဲဓဝ်စှ်ပြကာ—။” (ဇ—၃၅၁။ အစွောံ။) = “မင်းကျင့်တရားဆယ်ပါး­ မြဲစွာတည်သောမင်း။”')
,(10637,3,4,'၂။ မှန်ကန်သည်။သေချာသည်။','“အတိုၚ်ဂလာန်မၞးဂှ် ဒှ်ဗိုန်ရဟာ။” = “သင့်စကားအတိုင်း သေချာသလော။” || “နာဲပိုဲဟွံဟီုကဵုညးဗိုန်ရဟာ။” “အဲဟွံဟီုဗိုန်ရ။” (ဇ—၅၁၈။ အစွောံ။) = “သူတစ်ပါးအား သၚ်မပြောပြပါဟုဆိုသည်မှာ သေချာပါသလား။” “ငါမပြောပါ၊ သေချာပါသည်။”')
,(10638,3,4,'ခိုင်မြဲသည်။ ခိုင်ခံ့သည်။ မြဲမြံသည်။','“ပြတရၚ်ဍုၚ်တက္ကသဵုဂှ် ခိုၚ်ကၠိုက်ဗိုန်က္ညန်သန်—။” (ဇ—၂၂၉။ အစွောံ။) = “တက္ကသိုလ်ပြည်၏ မြို့တံခါးမျှောၚ်စၚ်သည် အလွန်ခိုင်ခံ့မြဲမြံ၏။” || “ယြဴစရၚ်ကိစ္စမွဲဂှ် ဟွံဂွံစဳစတ်စံၜတ်ဗိုန်က္ညန်တုဲ ဗွဲမပြဟ်ပြေဟ်ဂှ် လ္ပပ္တုဲညိ။” (ဇ—၅၂၁။ အစွောံ။) = “အကြင်အမှုကိစ္စကို မြဲမြံစွာမစိစစ်မစုံစမ်းဘဲ အဆောတလျင်မပြုပါနှင့်။” || “သၟိၚ်ၜါတြုံဗြဴ၊ ချပ်တဴဗိုန်က္ညန်။” (လိက်သၟိၚ်ဇဲယဒတ္တ) = “မင်းမိဖုရားနှစ်ပါးတို့သည် မြဲမြံစွာစဉ်းစားတိုင်ပင်ကြ၏။”')
,(10639,3,4,'ခိုင်ခံ့သည်။ ခိုင်မြဲသည်။','“တၠသ္ၚိကဵုသမ္ဘာညးၜါဂှ် သစ္စမေတ္တာဗိုန်ခိုၚ်တဴရ။” =“လင်မယားနှစ်ယောက်တို့သည် သစ္စာမေတ္တာခိုင်မြဲကြသည်။”')
,(10640,3,4,'မြဲသည်။ တည်မြဲသည်။ တည်တံ့သည်။ ခိုင်မြဲသည်။','“သၚ်္ခါရဓဝ်အိုဿီုဂှ် ဍေံဟွံဗိုန်ဂၠိ ဟွံထဳတိကဵုသတ္တံညးဂမၠိုၚ်ရောၚ်။ ပ္ဍဲသၚ်္ခါရဓဝ်ဟွံဗိုန်ဂၠိဂှ် ဟွံဂပ်ဂဝ်ချပ်စံၚ်တူရောၚ်။” (ဇ—၃၁၇။ အစွောံ။) = “အလုံးစုံသော သၚ်္ခါရတရားတို့သည် သတ္တဝါအပေါင်းတို့အား မမြဲသောသဘော မတည်တံ့သောသဘောရှိ၏။ မမြဲသောသၚ်္ခါတရားတို့­ တွေးကြံပူပန်ခြင်းမပြုအပ်။” || “ဓဝ်မိတ်အဲပ္ဍဲညး လ္ပကဵုလီုဇြဟာန်ညိ၊ ကဵုဗိုန်ဂၠိဒၟံၚ်ပ္ဍဲညးညိ အဲလဝ်စိုတ်တုဲ—။” (ဇ—၁၃၁။ အစွောံ။) = “သူ­ငါ၏အဆွေခင်ပွန်းတရားနှင့် ချစ်ခြင်းမပျက်ပါစေနှင့်၊ သူ­တည်မြဲနေပါစေဟုငါသဘောထား၍—။” || “ပိုန်ဒြပ်မ္ဂးဂှ် ဍေံဟွံဗိုန်ဂၠိကဵုသတ္တအ်သက်က်ရောၚ်။” (ဇ—၃၅၁။ အစွောံ။) = “ဥစ္စာမည်သည်ကား လူတို့အား မတည်မြဲ။”')
,(10641,3,5,'တပ်အပ်သေချာ။ အမှန်စင်စစ်။ မုချဧကန်။','“ယာံရအဲဂွံဗၠးဘဲဂစိုတ်နူဝွံတုဲ အဲတိတ်ပခမဳ ဇရေၚ်တမ်ဇိုၚ်ကျာ်တြဲ ဗိုန်စၟတ်ဨကန္တရ” ကောန်တြုံသေဋ္ဌဳချပ်။ (ဇ—၁၁၈။ အစွောံ။) = “အကယ်၍ငါသည် ဤသေဘေးမှလွတ်ပါက မြတ်စွာဘုရားခြေတော်ရင်း­ မုချဧကန္တ ငါရဟန်းပြုအံ့” ဟုသူဋ္ဌေးသားကြံ၏။ || “ဗိုန်စၟတ်သာ်ဝွံ၊ ဟွံမုသာပၠန်။” (လိက်ဇိဝှစက္က) = “မုသားမဆို ဤကဲ့သို့မှန်ကန်သေချာ၏။”')
,(10642,3,4,'၁။ မြဲမြံသည်။ ခိုင်ခံ့သည်။','“ညာတ်ကၠိက်တံဂှ် ဒၟံၚ်သိပ်ဂၠိပ်ခိုဟ်ဗိုန်ဇၟံဂှ်တုဲ (ကၠဂှ်) ဖေက်ဒည ဟွံဂံၚ်လောပ်—။” (ဇ—၂၈၃။ အစွောံ။) = “တောဝက်တို့ စေ့စပ်မြဲမြံခိုင်ခံ့စွာနေသည်ကို ကျားမြင်လတ်သော် ကြောက်ရွံ့၍မဝင်ဝံ့။” || “သာ်ဝွံဖျေံစိုတ်ဗိုန်ဇၟအ်တုဲ—။” (ဇ—သုဝဏ္ဏသာံ။ အစွောံ။) = “ထိုကဲ့သို့မြဲမြံစွာ စိတ်ဆုံးဖြတ်ချက်ချ၍—။” || “တလုၚ်လအာမွဲ ကဵုဗိုန်ဇၟံညိ။” (အကြီုရာဇာဓိရာဇ်) = “အသွားအလာ မြဲမြံပါစေ။” || “မဂွံဟီုဂလာန်ဗိုန်ဇၟံ မၞုံကဵုဒတုဲမြမောဝ်။” (ပြကိုဟ်မ္ၚိုလ်ပိစှ်ောဒစာံ) = “အကျိုးရှိသော မြဲမြံသောစကားကို ပြောဆိုခြင်း။”')
,(10642,3,4,'၂။ မြဲမြံသောဣန္ဒြေရှိသည်။ တည်ငြိမ်၍ ဣန္ဒြေရသည်။','“ကောန်ဗြဴအဲဝွံ ဂြိုၚ်ကအီဒှ်လောန်အာဟွံဗိုန်ဇၟအ်လေဝ်ဟွံတီ” မဂှ်ချပ်။ (ဇ—၂၁၇။ အစွောံ။) = “ငါ့သမီးသည် အလွန်ရယ်ရွှင်တတ်လွန်းသည်။ မြဲမြံသောဣန္ဒြေ မရှိလေသလောမသိ။”')
,(10643,3,4,'ခိုင်မာသည်။ မြဲမြံသည်။','“အမၠံက်စွံရေၚ်၊ ပြေၚ်လဝ်ဗိုန်ဒု။” (လိက်သၟိၚ်အသး။ နန္ဒသာရ။) = “အမြောက်များကို မြဲမြံစွာစီတန်းထားရှိ၏။”')
,(10644,3,4,'ခိုင်မြဲသည်။ ခိုင်ခံ့သည်။ မြဲမြံသည်။','“(မၞးတံ) ကဵုဗိုန်ဗတ်ညိ။ (ကၠဂှ်) လ္ပကဵုဍေံလုပ်” သၟိၚ်ကၠိက်ဂးကဵုကၠိက်ဂမၠိုၚ်ရ။ (ဇ—၄၉၂။ အစွောံ။) = “သင်တို့မြဲမြံပါစေ။ ထိုကျားကိုမဝၚ်စေနှင့်” ဟုဝက်မင်းက ဝက်အပေါင်းကိုဆို၏။ || “ကၠာဟွံဗိုန်ဗတ်၊ ဖလုတ်စှ်ေအာ။” (လိက်ဇိဝှစက္က) = “မခိုင်မြဲခၚ် လွတ်ကျသွား၏။”')
,(10645,3,5,'အမှန်တကယ်။ သေသေချာချာ။','‘ကၠုၚ်ဗိုန်ဗိုန်ညိ။’ = ‘လာဖြစ်အောင်လာပါ။’ (ဝါ) ‘ဆက်ဆက်လာပါ။’ || “ယွံနန္ဒ၊ ရံၚ်စၟတ်လဝ်ဗိုန်ဗိုန်ညိ။” (ဇ—၁၈၂။ အစွောံ။) = “နန္ဒ၊သေသေချာချာကြည့်၍ မှတ်ထားပါ။”')
,(10646,3,4,'အရှည်တည်သည်။ ခိုင်မြဲသည်။','“ဟိုတ်မသလှ်ေပၟာတဴဂှ်ရ ဓဝ်မိတ်ဂှ် ဍေံဟွံဂွံဗိုန်လအ်ရ။” (ဇ—၃၆၃။ အစွောံ။) = “ယုံမှားသံသယဖြစ်ခြင်းကြောင့် ထိုအဆွေခင်ပွန်းတရားသည် အရှည်မတည်မြဲ။”')
,(10647,3,4,'တည်တံ့သည်။ ခိုင်မြဲသည်။','“သာသနာ (၅ဝဝဝ) သၞာံ ကဵုဂွံဗိုန်သ္ဍာံဒၟံၚ်ညိအဴ။” (ဇ—သုဝဏ္ဏသာံ။ အစွောံ။) = “သာသနာတော်အနှစ် (၅ဝဝဝ) တည်တံ့ခိုင်မြဲပါစေ။”')
,(10648,3,4,'(သီလစသည်) မြဲမြံစင်ကြယ်သည်။','“ညးစှ်မွဲဝွံ မၚ်မွဲကရုကဓဝ်ရ၊ ဗိုန်သ္အးတဴရ၊ဗိုန်ပ္ဍဲသဳမသုန်ရ။” (ဇ—၂၇၆။ အစွောံ။) = “တစ်ဆယ့်တစ်ယောက်ကုန်သောသူတို့သည် ကရုကဓမ္မကို စောင့်စည်းကြကုန်၏၊ မြဲမြံစင်ကြယ်၏၊ ငါးပါးသီလတို့­ မြဲမြံကုန်၏။”')
,(10649,3,4,'အဝတ်မလျှော်ခၚ် ရေနှင့်စိုအောင်လုပ်သည်။','“ဗပ်လဝ်ဂၠိက်ယာတ် သွက်ဂွံကဆံၚ်။” =“လျှော်ဖွပ်ရန်အတွက် အဝတ်အစားကို ရေစိမ်ထားသည်။”')
,(10650,3,4,'၁။ (နားပန်၊ နားရင်းကို) ရိုက်သည်။','“ဗာပ်ကဵုတမ်ကတောဝ်။” = “နားရင်းအုပ်ရိုက်သည်။”')
,(10650,3,4,'၂။ ကိုင်ညှစ်သည်။','“(ကလော်ဗြဴဂှ်) ဍေံလဟဵုအာကဵု (ဂၞကျာ်) စန္ဒဝတဳတုဲ တဲမွဲဍေံဗာပ်လဝ်ကတက် တဲမွဲဍေံရပ်လဝ်ဂၞိၚ်တၚ်က္ၜံၚ် ဍေံခေါအ်လဝ်ကဵုသြိုဟ်ဂၞကျာ်တုဲ ဍေံဝးဖ္ဍိုပ်ကအ်ဂၞကျာ်—။” (သၠပတ်စန္ဒဝတဳ) = “ထိုဘီလူးမသည် စန္ဒဝတီမိဖုရားဆီ ဒေါမာန်ဖြင့်သွားပြီး လက်တစ်ဖက်ဖြင့် လည်ကုပ်­ကိုင်ညှစ်၍ လက်တစ်ဖက်ဖြင့် ခါးဒူးဆစ်တို့­ကိုင်လျက် မိဖုရားရင်ဘတ်နှင့် ခုထားပြီးလျှင် မိဖုရားလည်ပင်းကို ချိုးခေါက်ချလိုက်၏။”')
,(10651,3,4,'စုတ်ပြတ်ပျက်စီးသည်။ ကွဲပေါက်သည်။ (= သြလီု) (ပါဠိ—ဘိနန)','“ဇွဂှ် ဗောပ်အာတုဲရ။” = “ထိုအလောင်းသည် စုတ်ပြတ်ပျက်စီးသွားပြီ။”')
,(10652,3,5,'(မုတ်ဆိတ်၊ နှုတ်ခမ်းမွေးစသည်) ဖွားရရားဖြင့်။','“လကိုဟ်ဇၞော်မွဲ၊ သဲကၠုၚ်ဂတ။ ေၚက်ကိုဟ်ဓညန်၊ မတ်ဓလန်ဒ။ သော်ပါၚ်ဗိုပ်ဗိုပ်၊ က္ဍိုပ်တမာန။” (လိက်သၚ်ဂဒါ။ သဳလဝန္တ။) = “ရှေ့မှအတင်းဝၚ်လာသောဘီလူးသည် ဖြူသောသွားများကိုဖြဲလျက် မျက်လုံးပြူးကာ နှုတ်ခမ်းမွေးဖွားရရားဖြင့် ဦးခေါင်းသည် တောင်းပမာဏရှိ၏။”')
,(10653,3,4,'နတ်ကနားပေးသည်။ (?)','“တရဴဒိတ္ထိမတွံဂး မယိဗရာန်တံဂှ် ဒေါၚ်ယာဗမ္ၚိက်ဗမ္ၚာဲ မအာသာတ်ဒြာတ်တဴတံဂှ် သတ္တံဒးစိုတ်လုပ်စိုတ် မပ္တေဟ်လောန်သန်။” (သၠပတ်သတိပထာန်) = “မိစ္ဆာဒိဋ္ဌိဟုဆိုအပ်သော နတ်စိမ်းအစောင့်နတ်စသည်တို့ကို နတ်ဝၚ်သည် || နတ်ကတော်တို့က နတ်ကနားပေး၍ ပူဇော်ပသသည်တို့ကို လူများနှစ်သက်စိတ်ဝၚ်စား၍ အလွန်အမင်းယုံကြည်ကုန်၏။” || “အဲဝွံ အတိုၚ်ကွေတ်မိမပိုဲ မပကလော်သေံမန်ဗၟာဂှ် ပိုဲသ္ပညိဂးတုဲ ဟွံသေၚ်ဟာ၊ ကော်နၚ်ဒေါၚ်ယာ ကၠုၚ်ဗမ္ၚိက်ဗမ္ၚာဲဒၟံၚ်ပၠန်။ ပွဂှ် ဒှ်မရာဒနာအပဲါပန်ရ။” (သၠပတ်သတိပထာန်) = “ငါသည် ငါတို့မိဘ၏အယူအတိုင်း ထိုင်းမွန်ဗမာတို့၏ ကိုးကွယ်ရာနတ်တို့ကို ပူဇော်ကြကုန်အံ့ဟုဆိုကာ နတ်ဝၚ်သည် || နတ်ကတော်တို့ကို ခေါ်ဆောင်လာပြီးလျှင် နတ်ကနားပေးနေပြန်၏။ ဤအမှုကား အပါယ်လေးပါးကို တောင့်တသောအမှုပၚ်တည်း။”')
,(10654,3,4,'တောက်ပသည်။','‘ဗစဳ’ နှင့်အတူတူ။ || “ဂိုဟ်သုံမထိုက်၊ စလိုက်ဗမ္စဳ။” (လိက်မေဃကောန်ဒြာဲ) = “ဖန်လိုဏ်ဂူသည် လင်းလက်တောက်ပ၏။” || “လျးဍောၚ်သွာဂှ်၊ ခၠၚ်မြဟ်ဗမ္စဳ။” (လိက်ဓနဥ္ဇယျကုမ္မာ။ အစွောံ။) = “ထိုကုမုဒြာကြာပွင့်၏ အရောင်အဆင်းသည် ထွန်းပြောင်တောက်ပနေ၏။”')
,(10655,3,4,'‘ဗစဳခဏ’ နှင့်အတူတူ။',NULL)
,(10656,3,12,'(န) ပုဏ္ဏား။ ဗြဟ္မဏ။','“ဗောဓိသတ်ပိုဲ ဒှ်ဂကူဗမၞး ဒှ်ဗၠာဲတုဲ အာကတ်ဍုၚ်တက္ကသဵု—။” (ဇ—၃၃၇။ အစွောံ။) = “ဘုရားလောင်းသည် ပုဏ္ဏားမျိုး­ဖြစ်၍ အရွယ်သို့ရောက်လတ်သော် တက္ကသိုပြည်­ ခပ်သိမ်းသောအတတ်တို့ကိုသၚ်၍—။” (ညောင်ကန်) || ‘ဗၞး’/‘ဗဗၞး’ဟုလည်း အချို့ရေးသည်။')
,(10657,3,1,'မြွေပါ။','‘ဇၞးဇာတ်’ နှင့်အတူတူ။')
,(10658,3,1,'ပုဏ္ဏေးမ။ အမျိုးသမီးပုဏ္ဏား။','“ပ္ဍဲကာလဂှ် ဗမၞိဟ်ကဵုဗမၞးချပ်။” (ဇ—၅၃၂။အစွောံ။) = “ထိုကာလ­ ပုဏ္ဏေးမနှင့်ပုဏ္ဏားသည် တွေးကြံကြ၏။” || “(ဗမၞး) ညာတ်နက်သတ်ဂှ်တုဲ ကော်ပ္တိတ်ဗမၞိဟ်ရ။” (ဇ—၂၈၉။ အစွောံ။) = “ပုဏ္ဏားသည် ထိုနက္ခတ်ကိုမြင်၍ ပုဏ္ဏေးမကို ထွက်လာရန်ခေါ်၏။” || “ဒဒှ်ဂှ် ဗမၞိဟ်ဗြဴပ္တီဗမၞးရ။” (ဇ—၅၃၂။ အစွောံ။) = “ထိုအဖြစ်ကိုပုဏ္ဏေးမသည် ပုဏ္ဏားအားအသိပေး၏။” || “ဗမၞိဟ်ဗြဴဝွံဂှ် ဒှ်မိအဲမသုန်ကၠံဘဝ ဟွံဂွံသ္ဂုတ်—။”ကျာ်တြဲဂး။ (ဇ—၆၈။ အစွောံ။) = “ဤပုဏ္ဏေးမသည် မပြတ်ဘဝငါးရာတို့ပတ်လုံး ငါ၏မိခင် ဖြစ်ခဲ့ဖူး၏။”')
,(10659,3,1,'မျက်ရှု။ ရှုမငြီးဖွယ်။','“ဂုဏ်မိတ်သ္ဍိုက်၊ ရုပ်ဗမြိုက်မတ်။ ကာယလေဝ်ဍောၚ်၊ လမောင်လေဝ်ထတ်။” (လိက်သောဝါနနဟောၚ်) = “ရှုမငြီးဖွယ်ချစ်သူ့ရုပ်လွှာအတွက်ကြောင့် ကိုယ်ပင်ပန်း၍ အပန်းကြီးရ၏။” || “ဟွံမွဲဒဒိုက်၊ ဗံရိုက်မတ်ဇန်။” (ဇိဝှစက္က) = “ဆင်းရဲခြင်းမရှိသော လူတကာတို့၏မျက်ရှု။” || ‘ဗရိုက်မတ်’ ဟုလည်းတွေ့ရသည်။ || “ဟးကောန်သ္ဍိုက်၊ ဗရိုက်မတ်မ။” (လိက်ဇိဝှစက္က) = “အိုဖခင်မျက်ရှု သားရွှေဥ။”')
,(10660,3,1,'ကြေးသတ္တု။ ကြေးဝါ။ (ပါဠိ—ရဳတိ)','“ကွတ်မကၠုၚ်နူသၠုဲသာ်ကီုလဝ်၊ ကွတ်မကၠုၚ်နူဗကောဝ်ဒမြိုတ်ကီုလဝ်။” (ပြကိုဟ်နဝဗျတ္တိ) = “ကြေးနီကြေးဝါမှလာသောအတတ်သည်၄င်း၊ ခဲကြေးသတ္တုမှလာသော အတတ်သည်၄င်း။” || “ဇကုဝွံပၠန်၊ သြန်ထဝ်ဟွံသေၚ်။ သၠာ်သၠုဲဗမြိုတ်၊ ဍိုတ်တၟအ်ဟွံသေၚ်။” (လိက်ပုညကာရဳ) = “ဤခန္ဓာကိုယ်သည် ရွှေငွေမဟုတ်၊ ကြေးဝါ၊ ကြေးနီ၊ ကြေးသတ္တု၊ အုတ်၊ ကျောက်မဟုတ်။”')
,(10661,3,4,'တောက်ပသည်။ ထွန်းလင်းသည်။','“ဒစၚ်ဗၜၚ်၊ လျးခၠၚ်ဗပန်။ စဳပျးလုံနန်၊ လျးတ္ၜန်ဗမၠိတ်။” (လိက်သောဝိန်ဇဲယ။ မာံရောဂေါ။) = “ပြိုးပြိုးပြက်ပြက်သောအလင်းရောင်ဖြင့် နန်းတော်အလုံးကို ထွန်းလင်းတောက်ပစေ၏။”')
,(10662,3,1,'အခိုၚ်။ အတွဲ။ အပြွတ်။ (ပါဠိ—ထဝက)',NULL)
,(10663,3,1,'ပုံ။ ပုံစံ။ စံနမူနာ။','သ္ပဗီု = စံပြုသည်။ စံနမူနာယူသည်။ || “မၞိဟ်ဇၞော်တအ်ဂှ် ညံၚ်မၞိဟ်သၟတ်တအ် ဂွံပဗီုဒ္ဂေတ်ကွာ်ဗက်ဂှ် ဂပ်ဂဝ်ဒးပၠကဵုဗီုဒ္ဂေတ်တဝါ်မဒးရးရောၚ်။” = “လူကြီးများသည် လူငယ်များစံနမူနာယူနိုင်အောင် ကောင်းသောအမူအကျင့်ဖြင့် ရှေ့ဆောင်လမ်းပြပေးသင့်သည်။”')
,(10664,3,1,'မြေပုံ။',NULL)
,(10665,3,1,'ပုံ။ ပုံစံ။ ပုံပန်းသဏူဌာန်။','“ယွံၝဲခုတ်ဇာ၊ ပညာစိုန်သ္ကီု။ ၝဲမဟီုနၚ်၊ ဗီုပြၚ်အိုဿီု။” (လိက်ပဒုမဝတဳ) = “ပညာနှင့်ပြည့်စုံသော အို—အစ်မအထိန်းတော်၊ အလုံးစုံသောပုံသဏူဌာန်ကိုအစ်မတော်ပြောဆိုလာ၏။” || “(က္ၜၚ်ဂှ်) ဇမၠိၚ်ကၠံဟတ်၊ ဒးသၞောတ်ဗီုပြၚ်။” (လိက်တပူတဗဝ်) = “ထိုသင်္ဘောသည် အလျားအတောင်တစ်ရာရှိ၍ အချိုးအစားပုံပန်းကျ၏။” || “အဲဂၠာဲဟီုနၚ်၊ ဗီုပြင်ပမာ။” (လိက်ဘောဂရေန်) = “ပုံပမာကို ငါဆောင်ကြဉ်းယူလာ၏။” || “ညးဇၞော်နွံကွေံ၊ပညာသ္ဂေဟ်သွဟ်။ ဂှ်ညးတအ်ဂှ်၊ ကဵုသှ်ညိအဴ။ ဗီုပြၚ်တၚ်တှ်၊ သွဟ်သဘဴ။ အဲဍိက်သမၠီု၊ ပၚ်မိၚ်ကီုအဴ။” (လိက်ဓနဥ္ဇယျကုမ္မာ။ အစွောံ။) = “ကြီးသူတို့သည် ပညာပြည့်စုံကုန်သည်ဖြစ်ငြားအံ့၊ထိုသူတို့အား ဖြေကြားစေကုန်လော့။ ပုံစံနည်းနာ ဖြေဆိုခြင်းသဘောကို မိုက်မဲသူဖြစ်သောအကျွန်ုပ်သည်လည်း နာကြားလိုပါ၏။”')
,(10666,3,5,'ဘယ်ကဲ့သို့။ ဘယ်လို။','“ဗီုလဵုဂွံပရော။” = “ဘယ်လိုလုပ်ရမလဲ။”')
,(10667,3,1,'အသွင်သဏူဌာန်။','“ပွမၞိဟ်ကဵုမၞိဟ်သ္ပဍိက် အိုတ်ကဵုဗီုလွေဟ်ဍေံအိုတ်သီုတအ်ဂှ် မဒးသ္ဂုတ်ပလီုဆေဝ်ဒဝ်ကၠေံရောၚ်။” = “လူလူချင်းကျွန်ပြုခြင်း အလုံးစုံသောအသွင်သဏူဌာန်အားလုံးတို့ကို တားမြစ်ရပ်စဲစေရမည်။”')
,(10668,3,1,'မရီး။ အစ်ကို၏မယား။','“တြုံဂှ် ဟီုကဵုဗာဲဂှ်ရ။” (ဇ—၃၉ဝ။ အစွောံ။) = “ထိုယောကျာ်းသည် မရီးအားပြော၏။”')
,(10669,3,4,'၁။ စုပုံသည်။','“ဗတဳမွဲကွဳဂှ် ဗဝ်စွံလဝ်ဒၞာဲဂှ်ညိ။” = “သဲတစ်လှည်းကို ထိုနေရာတွင်ပုံထားပါ။” || “ညံၚ်ညးဗဝ်လဝ်၊ ဗွဝ်ဆံက်အဴ။” (လိက်ကကၠာ်။ ကောန်ဍး။) = “သူစုပုံထားသော ကောက်ရိုးပုံကဲ့သို့။”')
,(10669,3,4,'၂။ များပြားသည်။ ပေါများသည်။',NULL)
,(10669,3,5,'အမြောက်အမြား။ပေါများစွာ။ စုပုံလျက်။','“ပ္ဍဲတ္ကအ်ဂှ် သတ်ဆုနွံဗဝ်ရ။” = “ထိုကျွန်း­ သစ်သီးပေါ၏။” || “ပ္ဍဲဗၞဳယာတ်သာ်ချီုသၟိၚ်တေံ ယာတ်ချီုနွံဗဝ်ဒၟံၚ် ဟွံသေၚ်ဟာ။” (ဇ—၁၄၇။ အစွောံ။) = “မင်း၏ဝတ်ပန်းခင်း­ များစွာသောဝတ်ပန်းသည် ရှိသည်မဟုတ်လော။” (ညောင်ကန်) || “(သၟိၚ်) ကဵုဂစိုတ်ခဍာ်တုဲ — ခဍာ်ချိုတ်ဗဝ်ဒၟံၚ်ရ။” (ဇ—၁၄ဝ။ အစွောံ။) = “မင်းသည် ကျီးတို့ကိုသတ်စေ၍ကျီးတို့သည် သေကြေစုပုံနေ၏။”')
,(10670,3,1,'၁။ ဆင်ထိန်း။ ဆင်ဆရာ။ ဆင်ဖမ်းသမား။','‘မှဝ်/မှောဝ်’ နှင့်အတူတူ။ || “မၞိဟ်ကမတ်စိၚ်ကီု သဝ်စိၚ်ကီု အပေါတ်ဂ္ညိစိၚ်ကီု ဂတေဝ်ပးဇာထဝ်ဂရောပ်စိၚ်ကီု ဗဝ်မှောဝ်ကီုစိၚ်သီုအပေါတ်အိုဿီုဝွံဂှ် အဲကဵုဒါန်ကဵုကလောဗြီုရ” သၟိၚ်ဂးကဵုဗမၞး။ (ဇ—၂၇၆။ အစွောံ။) =“ဆင်မြက်သမားကို၄င်း၊ ဆင်သမားတော်ကို၄င်း၊ ဆင်တန်ဆာတို့ကို၄င်း၊ အလွှမ်းတန်ဆာရွှေကွန်ရက်ကို၄င်း၊ ဆင်ထိန်းကို၄င်း ဆင်နှင့်တကွသော အလုံးစုံသောပစ္စည်းတန်ဆာတို့ကို သင်တို့အားငါပေးအံ့” ဟုမင်းဆို၏။')
,(10670,3,1,'၂။ အိုးထိန်းစက်။ (စက်ဗဝ်မှဝ် = စက်လမာန်)',NULL)
,(10671,3,4,'ဗုံးပေါလအောများသည်။ အလျှံပယ်ပေါများသည်။ အလွန်များသည်။','“(တိရစ္ဆာန်တံဂှ်) ဍေံတံဂိုၚ်နၚ်သစ္ဆု မပ္တံသတ်ကြုက် သတ်ကြေၚ် ဓရေဲဒယာ် သစ္ဆုဗဝ်သအဝ်ဒၟံၚ် ရိုဟ်ဟွံမာန်ရ။” (ဇ—၁၂၄။ အစွောံ။) = “ထိုတိရိစ္ဆာန်တို့သည် သရက်သီး၊ သပြေသီး၊ ကနစိုးသီး၊တောင်စလဲသီး အစရှိသောသစ်သီးတို့ကို ယူဆောင်လာရာ သစ်သီးတို့သည် မရေမတွက်နိုင်အောင် အလျှံပယ်ပေါများ၏။” || “(ထေရ်အနန်ဂှ်) ပ္ကဴဥပ္ပဵုမဂၠိုၚ်ကဵုစန် ညးကလိဂွံဗဝ်သ္အဝ်ဒၟံၚ်ရောၚ်။” (ဇ—၂၆၁။ အစွောံ။) = “အာနန္ဒာမထေရ်သည် ကြာညိုပန်းစည်းများ ဗုံးပေါလအောရ၏။” || “ဒြပ်ရတ်ထဝ်သြန်အဲလေဝ် နွံဂၠိုၚ်ဗဝ်သ္အဝ်ဒၟံၚ်ရ။” (ဇ—၄၉၉။ အစွောံ။) = “ငါ၏ဥစ္စာရတနာရွှေငွေတို့သည် အလွန်များလှစွာ၏။”')
,(10672,3,4,'ဘုရားဆွမ်းတော်တၚ်သည်။',NULL)
,(10673,3,4,'၁။ အလေးချိန်ကြောင့် နစ်ကျသည်။','“ဟိုတ်နူလျိုၚ်အပေါတ်ဗၞိက်တုဲ က္ၜၚ်ဂှ်ဗေဝ်စှ်ေရ။” = “ကုန်စည်အလေးချိန်ကြောင့် သင်္ဘောနိမ့်ဆင်းနစ်ကျ၏။” (မမြုပ်သေးသောနစ်ခြင်းကိုဆိုလိုသည်)')
,(10673,3,4,'၂။ (နေဝန်း) ဝင်သည်။ ကျသည်။','တ္ၚဲဗေဝ်စှ်ေ = နေဝင်သည်။ || ‘ဗဗေဝ်’ ဟုလည်းတွေ့ရသည်။ || ‘ဗဗေဝ်’ ရှု။')
,(10673,3,3,'ငယ်ရွယ်သော။ ပျိုရွယ်သော။','“ယွံဝိမာလ၊ ဒေံမကုမ္မာ။ ဒေံဍောတ်သွတ်ဗေဝ်၊ သ္ၚေဝ်ဂၠာဲအစာ။ ဍုၚ်တက္ကသဵု၊ တၚ်ဃဵုအဒ္ညာ။” (လိက်သၟိၚ်အသး။နန္ဒသာရ။) = “အိုညီငယ်ဝိမလ၊ ညီငယ်သည် နုမျစ်ပျိုရွယ်၏။ အတတ်ပညာအစွမ်းရှိသောတက္ကသိုလ်ပြည်­ အတတ်သၚ်ရန် ဆရာရှာပါလေဦး။” || “ပညာလၜေတ်ဗေဝ်။” (လိက်ဗြရတ်ဣဏၚ်ကၚ်ရဳ။ မာံရောဂေါ။) = “ပညာလည်းနုငယ်သေး၏။”')
,(10674,3,1,'ယောကျာ်းအၚ်္ဂါဇာတ်။ ယောကျာ်းလိၚ်။',NULL)
,(10675,3,4,'ကြည့်သည်။','ဗဵုပေဲါ၊ ဗဵုသဘၚ် = ပွဲကြည့်သည်။ || ရံၚ်ဗဵု = စောင့်ကြည့်သည်။')
,(10676,3,11,'(န) ၁။ စစ်သည်ဗိုလ်ပါ။ အင်အား။','“အမာတ်တံဇက်တိတ်အာ — ဆိုက်ညန်ကဵုအဿမာပိုတ်ဣသိဂှ်တုဲ ဗဒိုအ်လဝ်ဗဵုဂမၠိုၚ်ရ။” (ဇ—၅၂၆။ အစွောံ။) = “အမတ်တို့သည်ထွက်ချီသွားကြကုန်ရာ ရသေ့၏ကျောင်းအနီးသို့ရောက်သော် စစ်သည်ဗိုလ်ပါတို့ကို ရပ်စေ၏။” || “ဗိုလ်စှ်ကိုတ်ရ။” (အကြီုရာဇာဓိရာဇ်) = “စစ်သည်ရဲမက်အင်အားဆယ်သိန်း။”')
,(10676,3,11,'(န) ၂။ ရှေးမွန်မြန်မာစစ်တပ်တွင် တပ်မှူးငါးယောက် တပ်ငါးတပ်ပေါင်းအင်အား။ ရဲမက်အင်အားတသောင်း။တစ်ဗိုလ်။','“သီုဖအိုတ်ဒှ်ပၞာန်ဒစိတ်ဗိုလ် ဂိုၚ်ကေတ်မွဲဗိုလ်မွဲလက် သီုဖအိုတ်ဂှ် ဒှ်မၞိဟ်ဒစိတ်လက်ရ။” (အကြီုရာဇာဓိရာဇ်) = “အားလုံးပေါင်းစစ်အင်အား (၉) ဗိုလ် တစ်ဗိုလ်လျှင် တစ်သောင်းကျစီယူ၍ စုစုပေါင်းလူအင်အားကိုးသောင်းရှိ၏။”')
,(10676,3,11,'(န) ၃။ (ယနေ့ခေတ်သုံး) ဗိုလ်။ စစ်ဗိုလ်။','ဗိုလ်ဇၞော် = ဗိုလ်ကြီး။ || သကိုပ်ဗိုလ် = ဗိုလ်မှူး။')
,(10677,3,4,'ကြည့်ရှုသည်။ ရှုစားသည်။','“ဗြဴဂှ် မၞုံကဵုရုပ်သာ် ဂပ်ဂဝ်သ္ဇုၚ်သ္ဍိုက် ဂပ်ဂဝ်ဗဵုဒ္ၚောဝ်ရောၚ်။” (ဇ—၂၆၇။ အစွောံ။) = “ထိုမိန်းမသည် ချစ်ခင်ကြည်ညိုဖွယ် ရှုချင်စဖွယ်ရုပ်အဆင်းရှိ၏။” || “ဇဖန်မတ်ပိုဲနွံဝွံဂှ် ပိုဲဇိုန်ကဵုကၟိန်ဍုၚ် ကဵုကောန်ပိုဲရ။ နူပိုဲမဂျိုၚ်တဴဂှ် ပိုဲဂွံဗဵုဒ္ၚောဝ်ကောန်ပိုဲရောၚ်” သၟိၚ်မသၟိၚ်မိဂး။ (ဇ—၂၅၂။ အစွောံ။) = “ငါတို့မျက်စိရှိတုန်း ငါတို့၏သားတော်ကို တိုင်းပြည်အပ်နှင်းကြအံ့။ ငါတို့အသက်ရှင်စဉ် ငါတို့၏သားတော်ကို ရှုစားကြကုန်အံ့”ဟု ခမည်းတော်မယ်တော်တို့ဆို၏။ || “ဟာဲသၟတ်၊— မၞုံမုက်မဂေါဝ် ညးမဂပ်ဂဝ်ဗဵုဒ္ၚောဝ်ရောၚ်။” (ဇ—၅၁၃။ အစွောံ။) = “အိုသူငယ်၊ (သင်သည်) ကြည်ရွှင်သောမျက်နှာရှိ၍ သူတစ်ပါးတို့ ရှုချင်စဖွယ်ဖြစ်၏။”')
,(10678,3,1,'စစ်သည်ဗိုလ်ပါ။ စစ်တပ်။ စစ်ကြောင်း။','“ဇက်တိတ်ဂြီုဂြီု၊ သီုဗဵုပၞာန်ပန်။” (လိက်ဇမ္ဗူပတိ။ မာံဒေံဍောတ်။) = “(ဆင်တပ်၊ မြင်းတပ်၊ ရထားတပ်၊ ခြေသည်တပ်) စစ်ကြောင်းလေးခုစလုံး စုစုရုံးရုံးထွက်ချီသည်။”')
,(10679,3,1,'စစ်တပ်လေးတပ်။ အၚ်္ဂါလေးပါးရှိသောစစ်သည်။ ဆင်တပ်၊ မြင်းတပ်၊ ရထားတပ်၊ ခြေသည်တပ်ဟူသော စစ်အင်္ဂါလေးပါး။ (ရှေးသုံး)','“သၟိၚ်ဂန္ဓရးဂှ်— ကေုာံဗဵုပၞာန်ပန်ကၞိပ်ဇက်အာတုဲ ဗိုၚ်လဝ်ဍုၚ်ဗာရာဏသဳရ။” (ဇ—၂၃ဝ။ အစွောံ။) = “ဂန္ဓာရမင်းသည် — အၚ်္ဂါလေးပါးရှိသောစစ်သည်ဖြင့် လာလတ်၍ (ဗာရာဏသီ) မြို့ကိုဝန်းရံ၍—။” (ညောင်ကန်) || “ပြေၚ်လဝ်ပၞာန်ပန်ကၞိပ် မပ္တံပၞာန်စိၚ်ချေံတိုက်ကွဳ သီုဗဵုလဗး။” (သၠပတ်စန္ဒဝတဳ)')
,(10680,3,1,'နောက်လိုက်ဗိုလ်ပါ။ စစ်သည်ဗိုလ်ပါ။','“သၟိၚ်သီုဂၞကျာ်မိပ်စိုတ်တုဲ သီုဗော်သွးဗဵုလဗးမဂၠိုၚ်ဂှ် ဂိုၚ်ကေတ်တုဲ ဇက်တိတ်အာနူဍုၚ်ရ။” (ဇ—၅၃၁။ အစွောံ။) = “မင်းနှင့်မိဖုရားသည် ဝမ်းမြောက်လျက် များစွာသောအခြံအရံဗိုလ်ပါများနှင့်တကွ မြို့မှထွက်ချီလေ၏။” || “သၟိၚ်ပကောံကေတ်ဗဵုလဗးတုဲ သၟိၚ်ဇက်အာလဒံရး။” (ဇ—၁၂ဝ။ အစွောံ။) = “မင်းသည် ဗိုလ်ပါကိုစုရုံး၍ တိုင်းစွန်­သူပုန်ထသည်ကို နှိမ်နင်းရန်သွား၏။”')
,(10681,3,4,'ဖူးမြင်သည်။ ဖူးမျှော်သည်။','“တၞဟ်နသဳကၠဳဗဵုလ္ၚောဝ်ကျာ်တြဲဂှ် သၟိၚ်ပြာပ်တိတ်အာဘာဇေတဝန်ရ။” = “မြတ်စွာဘုရားကို ဆည်းကပ်ဖူးမြင်ရန် မင်းသည် ဇေတဝန်ကျောင်းတော်သို့ ထွက်သွား၏။” || “အာဗဵုလ္ၚောဝ်ကျာ်လ္ဂုၚ်။” = “ရွှေတိဂုံဘုရားကို သွားရောက်ဖူးမျှော်သည်။”')
,(10682,3,4,'၁။ ဖတ်သည်။','ဗှ်လိက် = စာဖတ်သည်။ || ဗှ်ပယျၚ် = ပဥ္ဇင်းဖတ်သည်။ ပဥ္ဇင်းတၚ်သည်။')
,(10682,3,4,'၂။ (ရှုထောင့်မှ) ရှုသည်။ ကြည့်သည်။ နှိုင်းယှဉ်သည်။ ထောက်ရှုသည်။','“ယွံ ပြောဟိတ်၊ အဲကဵုတၠအဲဂှ် ပိုဲညးၜါဝွံ ဗှ်ကဵုဇာတိဂကူကီု ဗှ်ကဵုဒြပ်ကသပ်ကီု တန်ဂွံခၠေဝ်ဒုၚ်မာန်ကီုရဂးတုဲ အဲဟီုပ္ညုၚ်ထ္ၜးတၠအဲရောၚ်” သေဋ္ဌဳဂး။ (ဇ—၉၂။ အစွောံ။) = “အိုပုရောဟိတ်၊ အကျွန်ုပ်နှင့်သင် ငါတို့နှစ်ဦးတို့သည် အမျိုးဇာတိအရကြည့်လျှင်၄င်း၊ ဥစ္စာဓနအရကြည့်လျှင်၄င်း (ဤရင်ဆိုင်နေရသောအမှုကို) တုံ့ပြန်ခုခံနိုင်ကောင်းအံ့ဟု နှလုံးသွင်း၍ သင့်အားညွှန်ပြလိုက်ခြင်းဖြစ်ပါ၏” ဟုသူဋ္ဌေးဆို၏။ || “ယွံၜိုပ်ထဝ်၊ လ္ပဗှ်ကဵုဒုဟ်ညိရ။ ဟံၚ်အဲကဵုဒါန်လမျီုညိရ” ခ္ဍာ်ဂး။ (ဇ—၂၇ဝ။ အစွောံ။) = “အို—ရွှေဟင်္သာ၊ အပြစ်ကိုမရှုပါနှင့်။ အကျွန်ုပ်ကိုဆယ်တၚ်၍ အသက်ကိုပေးပါလော့” ဟုကျီးဆို၏။ || “တရာဗညာဟွံဗှ်ကဵုဂုဏ် ဟွံညာတ်ကဵုမိတ်စှ်ပြကာ။” (အကြီုရာဇာဓိရာဇ်) = “တရဖျားသည် ကျေးဇူးကိုမထောက်ရှု ခင်ပွန်းကြီးဆယ်ပါးကိုမမြင်။”')
,(10683,3,4,'သတိရသည်။ အောက်မေ့သည်။',NULL)
,(10684,3,4,'ကျေးဇူးအောက်မေ့သည်။','“ကာလညးဗှ်ဂုန်တီဂုန်တုဲ ကာလဂှ် ညးဇိုန်ကဵုပိုန်ဟာန်ဣန်သွဵု ကဵုဥပးဗြဴပၠန်ရ” ကျာ်တြဲဂး။ (ဇ—၃၂ဝ။ အစွောံ။) = “သီတင်းသည်မ၊ ဤယောကျာ်းသည် — အကြင်အခါ သင်၏ကျေးဇူးကို အောက်မေ့၏၊ ထိုအခါ အလုံးစုံသောစည်းစိမ်ကို ပေးဘူး၏။” (ညောင်ကန်)')
,(10685,3,4,'ဖတ်ရှုသည်။','“ပ္ဍဲပရိယတ္တိပါဠိအရထ ဟွံဂွံစှ်ေစိုတ် ဟွံဂွံတီဏီဂှ် သွဂ်ဂွံဗှ်ဂၠဟ်ဍေန်ဍဟ်။” (နဝကောဝါဒကထာ။ ပြကိုဟ်မန်ဍုၚ်သေံ။) = “သဘောမပေါက်သေးသော မသိသေးသော ပရိယတ္တိပါဠိအနက်ပြန်ကို ဖတ်ရှုကျက်မှတ်ရန်။” || “သွဂ်ဂွံပ္ဍေန်ပ္ဍဟ်၊ ဗှ်ကၠဟ်ရံၚ်သ္ၚဳ။” (ဇာတ်မဟာဒုက်။ နာဲမန်ၜိုပ်ထဝ်။) = “နှုတ်တက်ရအောင် ကျက်မှတ်ဖတ်ရှုကြည့်ရှုရန်။”')
,(10686,3,4,'သတိရသည်။ အောက်မေ့သည်။','“ဒဒှ်သၟိၚ်ပၞတ်အာကဵုအဲဝွံဂှ် ကျာ်တြဲတၠလျးတရဴ ဟွံတီရသ္ဒဟ်” ရဴဝွံဂၞကျာ်မလ္လိကာ ချပ်ဗှ်ဗၞုဟ်ကျာ်တြဲရ။ (ဇ—၃ဝ၆။ အစွောံ။) = “ငါ့အား မင်းသည်အမျက်ထွက်သောအဖြစ်ကို ရောင်ခြည်တော်ခြောက်သွယ်ရှင် မြတ်စွာဘုရားသည် မသိပါလေ” ဟု မလ္လိကာမိဖုရားကြံ၍ မြတ်စွာဘုရားကို အောက်မေ့၏။ || “ဂုန်ကျာ်ဂုန်ဓဝ်ဂုန်သၚ်လေဝ် မၞးတံဗှ်ဗၞုဟ်ညိ။” (ဇ—၃၅၄။ အစွောံ။) = “ဘုရားတရားသံဃာတို့၏ဂုဏ်တော်ကို သင်တို့အောက်မေ့ကြကုန်လော့။”')
,(10687,3,4,'ကျေးဇူးအောက်မေ့သည်။ ကျေးဇူးသိသည်။','“အဲဗှ်ဗၞုဟ်တဴဂုန်ရတ်ပိပြကာလၟိုန်ရ။” = “ရတနာသုံးပါး၏ကျေးဇူးကို ငါအမြဲတမ်းအောက်မေ့သည်။” || “ယွံသၟိၚ်မပြဲ၊ — မရာတ်ဂွံဗှ်ဗၞုဟ်ဂုန်ညး မဂွံခၠေဝ်ရော်ဂုန်ညး မပ္တုဲလဝ်ပ္ဍဲဇကုဂှ်တုဲ ပ္ဍဲလိုက်ဝွံ မၞိဟ်ဒေဝတဴမဒးထိုၚ်သးရ။” (ဇ—၄ဝ၉။ အစွောံ။) = “မြတ်သောမင်းကြီး၊ မိမိအားပြုထားအပ်သော သူ့ကျေးဇူးကိုအောက်မေ့၍ ကျေးဇူးဆပ်ခြင်းသည် လောက­ လူနတ်တို့ချီးမွမ်းကုန်၏။” || ‘ဗှ်သၞာဂုန်’ နှင့်အတူတူ။')
,(10688,3,4,'အပြစ်ကို အောက်မေ့သည်။ အမှတ်ရသည်။','‘ဗှ်သၞာဒုဟ်’ နှင့်အတူတူ။ || “အဲဟွံဂွံထေဲပၞတ် ဟွံဂွံဗှ်ဗၞုဟ်ဒုဟ်ကောအဲမွဲလှ်ေ။” (ဇ—၅၁၃။ အစွောံ။) = “နောင်တော်အား ငါအမျက်မထွက်စဖူး။ နောင်တော်၏အပြစ်ကို တစ်ခါမျှငါမအောက်မေ့စဖူး။”')
,(10689,3,4,'အောက်မေ့သည်။',NULL)
,(10690,3,4,'အောက်မေ့သည်။ သတိရသည်။','“အဲဒးသြာဲခြာဒၟံၚ်ကဵုမိအဲတုဲ အဲဗှ်သၞာဒၟံၚ်မိအဲ ရိုဟ်ဒဒှ်တ္ၚဲရ။” = “အမေနှင့်ဝေးကွာနေသဖြင့် အမေ့ကို နေစဉ်နှင့်အမျှ ကျွန်တော်လွမ်းဆွတ်သတိရနေသည်။” || “ယွံမၞးတံ၊ ဒါန်သဳလပိုဲဂှ် မၞးတံဗှ်သၞာညိ။” (ဇ—၃၁။ အစွောံ။) = “အချင်းတို့၊ငါတို့၏ဒါနသီလကို သင်တို့အောက်မေ့ကြလော့။” || “နန္ဒဒှ်ခမဳတုဲ ဗှ်သဏာကဵုရမျှာၚ်ဇနပဒကလျာဏဳမကော်ဂှ်တုဲ ရမျှာၚ်ဂှ် နွံဒၟံၚ်ပ္ဍဲကတောဝ်ဂှ် ဗှ်သဏာတုဲ စိုတ်ဟွံလှိၚ်ပ္ဍဲသာသနာသက်က်ရ။”= “ညီတော်နန္ဒသည် ရဟန်းဖြစ်ပြီးနောက် ဇနပဒကလျာဏီခေါ်သောအသံကို အောက်မေ့လျက်နား­ကြားယောၚ်နေ၍ သာသနာတော်­ လုံးဝမပျော်မွေ့ဘဲရှိ၏။” || “(သၟိၚ်) ဗှ်သၞာဂလာန်ဗောဓိသတ်ရ။” (ဇ—၃၅၃။ အစွောံ။) = “မင်းသည် ဘုရားလောင်းစကားကို သတိရ၏။”')
,(10691,3,4,'ကျေးဇူးကိုအောက်မေ့သည်။ ကျေးဇူးသိတတ်သည်။','‘ဗှ်ဗၞုဟ်ဂုန်’ နှင့်အတူတူ။ || “သၟိၚ်ဗှ်သၞာဂုန်ဗောဓိသတ် မဒှ်အ္စာဂှ်တုဲ လ္ၚောဝ်လဒိုဟ်တဴအ္စာရ။” (ဇ—၃၃၈။ အစွောံ။) =“မင်းသည် မိမိဆရာဖြစ်သော ဘုရားလောင်း၏ကျေးဇူးကို အောက်မေ့၍ ဆရာရှိရာအရပ်ဆီသို့ရှိခိုးဦးချ၏။”')
,(10692,3,4,'မှတ်မိသည်။ အမှတ်ရသည်။ သတိရသည်။','“ပိုဲညးၜါ ပ္ဍဲကာလမဒှ်ကောန်ၚာ်တေံပိုဲဝေၚ်တဴခနှိက်တိမွဲစွံဂှ် ဗှ်ေဗှ်သၞာဒးဏီဟာ။” = “ငါတို့နှစ်ယောက် ငယ်စဉ်ကလေးဘဝက အတူတကွ မြေမှုန့်ကစားခဲ့ကြသည်ကို နၚ်အမှတ်ရသေးရဲ့လား။” || “ယွံၝောံ၊ ပ္ဍဲကၠာတေံ အဲဂ္ၚေၚ်အာတုဲ လုကဴထပှ်တ္ၚဲ အဲဟွံဂွံစဴစိုပ်ၝောံဂှ် ၝောံဗှ်သၞာဒး ၝောံတီဟာ” ဇာဒိသိုၚ်ကၟက် ဂးကဵုသမ္ဘာဇကုရ။ (ဇ—၁၅၇။ အစွောံ။) = “ရှင်မ၊ ယခင်က ငါလှည့်လည်ကျက်စား၍ ခုနစ်ရက်တိုင်တိုင်ရှင်မထံသို့ ငါပြန်မရောက်သည်ကို ရှင်မ၊မှတ်မိပါသေးသလား။” || “ယွံဗမၞး၊ ပ္ဍဲဘဝမတုဲတေံတၠပညာတံ ဟီုကဵုဗမၞးမွဲဝါတြသွံ။ ဟိုတ်မဒစဵုအာဘဝတၞဟ်တုဲ ဗမၞးဗှ်သၞာဟွံဒးရောၚ်” ကျာ်တြဲဂး။ (ဇ—၁၅၇။ အစွောံ။) = “ပုဏ္ဏား၊ ရှေး­လည်း ပညာရှိတို့သည် (ဤအမေးကို) သင့်အားတစ်ကြိမ်ဖြေဖူးပြီ။ ဘဝတစ်ပါးဖြင့် ဖုံးလွှမ်းသည်၏အဖြစ်ကြောင့် သၚ်မမှတ်မိခြင်းဖြစ်၏” မြတ်စွာဘုရားမိန့်တော်မူ၏။')
,(10693,3,4,'(တစ်စုံတစ်ဦးက မိမိအားပြုထားသော) အပြစ်ကို အောက်မေ့သည်။ အမှတ်ရသည်။','“ကောန်တြုံသၟိၚ် ဂွံဒှ်သၟိၚ်တုဲ ဗှ်သၞာဒုဟ်အ္စာမတက်ဂှ်တုဲ ‘အဲသကဵုဂစိုတ်ကၠေံအ္စာညိ’ချပ်တဴရ။” (ဇ—၂၅၂။ အစွောံ။) = “မင်းသားသည် မင်းအဖြစ်ကိုရပြီးလျှင် မိမိအားရိုက်ထားဖူးသော ဆရာ၏အပြစ်ကို အောက်မေ့၍ ‘ဆရာ့ကိုသတ်စေအံ့’ ဟုကြံ၏။”')
,(10694,3,16,'သင်။ နင်။ မင်း။',NULL)
,(10695,3,4,'၁။ (အရောင်အဆင်း) မှေးမှိန်သည်။','“ဟိုတ်နူတ္ၚဲကၠာန်ထောံဂၠိုၚ်တုဲ ဂၠိက်ဂှ် အရံၚ်ဗိုဟ်အိုတ်ရ။” = “နေလျက်ထားသည်များသောကြောင့် လုံချည်သည် အရောင်မှိန်သွားကုန်ပြီ။”')
,(10695,3,4,'၂။ လိမ်းသည်။','ဗိုဟ်မြမောဝ်၊ ဗောဟ်မြမောဝ် = အမွှေးနံ့သာလိမ်းသည်။ || “ကဵုရေက်သော် ကဵုဟုံဗိုဟ်မြမောဝ်သ္အးဇ္ၚးတုဲ—။” (ဇ—၃ဝ၂။ အစွောံ။) = “ဆံကိုဖြတ်စေ၍ အမွှေးနံ့သာလိမ်းကျံစေ၍ သန့်စင်စေပြီးလျှင်—။” || “ဗှ်ေဂွံဗိုဟ်လဝ်မြမောဝ် ဒးရးဒၟံၚ်တုဲရ။” (ဇ—၃၇၅။ အစွောံ။) = “နၚ်အမွှေးနံ့သာလိမ်းထားသည်မှာ လျောက်ပတ်နေလေပြီ။”')
,(10696,3,4,'(ပိုးလောက်) ထိုးသည်။ (ပိုးလောက်ကဲ့သို့) ထိုးစားသည်။','“ယွံပြိုတ်၊ တၠအဲဂှ်မၞုံကဵုပါၚ်လေဝ်မသ္အုဲလောန်၊ မၞုံကဵုဇကုတယုဗိုဟ်စဒၟံၚ်ဗြိုက်ဗြိုက်။” (ဓမ္မဒဳပနဳ။ မာံရွှေငိုး။) =“အိုပြိတ္တာ၊ သင်သည် အလွန်ပုပ်နံသောပါးစပ်ရှိ၍ ပိုးလောက်ထထိုးစားနေသော ခန္ဓာကိုယ်ရှိ၏။” || “တယုဗိုဟ်စ၊ သ္အုဲမသဂိ။” (လိက်ဗောဓိသတ်စှ်။ ပဏ္ဍိတ။) = “ပိုးလောက်ထိုး၍ အလွန်ပုပ်နံ၏။” || “ဒှ်ဗွဝ်ဇွ၊ သီုပိစှ်ောၜါ။ တယျုဗိုဟ်ထုဲ၊ စၞရုဲပၠာ။” (လိက်သုပိဏ္ဏကုမ္မာ။ မၚ်သၚ်ကြာ။) = “ကောဋ္ဌသသုံးဆယ့်နှစ်ဖြာသည် အပုပ်ကောင်ချည်းဖြစ်၏၊ ပိုးလောက်ထိုး၍ ယၚ်ကောင်အစာဖြစ်၏။”')
,(10697,3,4,'(အရည်၊ ဆီစသည်ဖြင့်) လိမ်းကျံသည်။ ပေကျံသည်။','“(ခ္ဍာ်မကၠတ်စဖျုန်ဂှ် ညးပိုက်ကၠေံတသော်တုဲ) ညးလံက်စုတ်ဍာ်တက်ဂှ် ဗိုဟ်ဗိန်တဴရ။” (ဇ—၂၇၅။ အစွောံ။) = “အသားကိုခိုးစားသောကျီးကို (စားဖိုမှူးက) အမွေးအတောင်တို့ကို နှုတ်ပစ်ပြီးလျှင် ရက်တက်ရည်ဖြင့်သုတ်လိမ်းသဖြင့် တစ်ကိုယ်လုံး ပေကျံလျက်ရှိ၏။”')
,(10698,3,1,'လဘို့။','ဗအ်ဂၠဴ = နွားလဘို့။ || “ဂၠဴဥဿဘမွဲ မၞုံဗအ်မသၠုၚ်နူဂၠဴဂမၠိုၚ်—။” (ဇ—၂၃၂။အစွောံ။) = “နွားတကာတို့ထက် ပိုမြင့်သောလပို့ရှိသော တစ်ခုသောဥဿဘနွား။” || ‘လဗအ်/သဗအ်’ နှင့်အတူတူ။')
,(10698,3,4,'ကျောပိုးသယ်ဆောင်သည်။','“ကောန်ၚာ်ဍောတ်ဂှ် အပါဍေံဗအ်ဏာရ။” = “ကလေးငယ်ကို သူ့အဖေက ကျောပိုးချီသွားသည်။”')
,(10699,3,3,'ပုကွသော။္ၚ',NULL)
,(10700,3,1,'လယ်။','ကၠောန်ဗ္ၚ = လယ်လုပ်သည်။ || ဇိက်ဗ္ၚ = လယ်ထွန်သည်။ || ဝါဗ္ၚ = စပါးစိုက်သောလယ်တော။')
,(10701,3,1,'၁။ ပြိန်းမြက်။ (ကျူ၊ ကိုင်းမျိုးဝၚ် မြက်ကြမ်းတစ်မျိုး။) (ပါဠိ—ဨရက)','“တြုံမွဲဂှ် လွဟ်သ္အာၚ်ဍေံဟွံကလိဂွံတုဲ နူဂြိုပ်ဗၞူဂှ် တဝ်ဗၞူဂှ် ဍေံဂိုၚ်ကေတ်ရ။ တဝ်ဗၞူဂှ် ယာံဍေံရပ်ကေတ်ဗက်ဟေၚ် ဒှ်အာရိကြက်လကံရ။” (ဇ—၄၅၄။ အစွောံ။) = “တစ်ယောက်သောသူသည် တစ်ပါးသောဆောက်ပုတ်ကို မရသည်ဖြစ်၍ ပြိန်းမြက်တောမှ ပြိန်းရွက်ကိုကိုင်၏။ ထိုပြိန်းရွက်သည်ကိုင်မိကာမျှဖြင့်လျှင် ရှားကျည်ပွေ့ဖြစ်၏။” (ညောင်ကန်)')
,(10701,3,1,'၂။ ကြာပၚ်တစ်မျိုး။','“ပ္ဍဲသ္ကဲဇြပ်ဂှ်ခၞံလဝ်ကၟာလစ တဵုလဝ်ဒကှ်ဗၞူသွာရ။” (ဇ—၃၁။ အစွောံ။) = “ထိုဇရပ်နံဘေး­ ရေကန်ကိုတူးထားပြီး ကြာမျိုးတို့ကို စိုက်ထား၏။” || “ဍာ်သာ်အဇ၊ အိန္ဒနဳလာ။ ဒကှ်ဥပဵု၊ ရာၚ်တသဵုဗ္ဂာ။ ဂ္ညိဂ္ညာတ်ပေၚ်သူ၊ လစံၚ်ဗၞူသွာ။” (လိက်သောဝိန်ဇဲယ။ မာံရောဂေါ။)')
,(10702,3,1,'မိဿလၚ်။',NULL)
,(10703,3,1,'မြွေပါ။',NULL)
,(10704,3,1,'အနက်။','ဗၞက်က္ၜံၚ် = ဒူးဆစ်အနက်။ || “ဍုၚ်သွဝ်တေံဂှ် ဟွံမွဲကဵုသရီုလက်ကၠိုက်ဂဗိုက်တိ၊ ထဝ်သက်က်ဗၞက်ဗၞက်က္ၜံၚ် မဒှ်ဗတဳညးဍုၚ်သွဝ်တေံရောၚ်။” (ဇ—၂၄၃။ အစွောံ။) = “နတ်ပြည်­ ရွှံ့ညွန်ဖုန်မှုန့်မြေမှုန့်များမရှိ။ ဒူးဆစ်အနက်မျှရှိသော ရွှေသက်သက်သည်လျှင် နတ်ပြည်၏သဲဖြစ်၏။”')
,(10705,3,1,'အိမ်ရိုက်သံ။ သံမှို။','“မွဲထပ်ဍိုတ်တၟအ်၊ ဗိုန်ဇၟအ်ညံၚ်ဗၞာ်။ မ္ၚးဂှ်လၟာ်၊ မွဲသာ်ဍိုတ်သွံၚ်။” (လိက်တပူတဗဝ်) = “ကျောက်အုတ်တစ်ထပ်သည် သံမှိုစွဲထားသကဲ့သို့ မြဲမြံ၏။ ထိုမှအပြင်ဘက်တွင် ဖုတ်အုတ်တစ်ထပ်ရှိပြန်၏။”')
,(10706,3,1,'ကုန်စည်။','ပဗၞိက်၊ အာဗၞိက်၊ အာပဗၞိက် = ကုန်အရောင်းအဝယ်လုပ်သည်။ကုန်သွယ်သည်။ || ညးဗၞိက် = ကုန်သည်။ || ‘ပဗၞိက်’ (ကြိ) လည်းရှု။')
,(10707,3,1,'ကုန်စည်။ ကုန်ပစ္စည်း။','“သွံရာန်ဗၞိက်ဇိက် ဂွံပရဲ မွဲကဵုၜါ မွဲကဵုပိပန်။” (ဇ—၂။အစွောံ။) = “ကုန်ပစ္စည်းရောင်းဝယ်ကြရာ နှစ်ဆ၊ သုံးလေးဆ အမြတ်ရ၏။” || “မဂဒူဟေၚ်ပနာဲရဲ — ဒးကာလပ္ဍိုက်ဒလေၚ် ဗပေၚ်ဗၞိက်ဇိက်တုဲ မှတ်တိုန်အာသွံရာန်ဗၞိက် ပ္ဍဲဍုၚ်သုခေါဒါယ။” (အကြီုရာဇာဓိရာဇ်) = “မဂဒူးသည် ကုန်သည်အဖွဲ့ခေါင်းဆောင်လုပ်၍ အချိန်ရောက်လျှင်ထမ်းပိုးများ­ ကုန်ပစ္စည်းဖြည့်ဆည်းတင်ဆောင်၍ ကုန်အရောင်းအဝယ်လုပ်ရန် သောက္ကတဲမြို့သို့အားထုတ်၍သွား၏။”')
,(10708,3,1,'ကုန်ခြောက်။',NULL)
,(10709,3,1,'ကုန်မာ။ (ပတ္တာ၊ သံ၊ ဝက်အူစသော အဆောက်အအုံသုံးကုန်မျိုး။)',NULL)
,(10710,3,1,'ကုန်ချော။',NULL)
,(10711,3,1,'ကုန်စိမ်း။',NULL)
,(10712,3,1,'နိဗ္ဗာန်ကုန်။','“တ္ၚဲဝွံဍိက်လွဳ၊ ဗၞိက်နဳဗာန်။ လ္ၚီကသာပ်ထဝ်၊ ကမဝ်ဍိက်ရာန်။” (လိက်ဗောဓိသတ်စှ်။ ပဏ္ဍိတ။) = “ယနေ့­ အကျွန်ုပ်သည် နိဗ္ဗာန်ကုန်အကျိုးငှာအားထုတ်၏၊ ရွှေအသပြာတစ်ထောင်ဖြင့် (အလှူပေးရန်) ကမ္ဗလာကိုဝယ်ယူ၏။”')
,(10713,3,1,'သွင်းကုန်။ ပြည်ပမှပြည်တွင်းသို့ တၚ်သွင်းသောကုန်ပစ္စည်း။',NULL)
,(10714,3,1,'ကုန်ကြမ်း။ ကုန်ရိုင်း။',NULL)
,(10715,3,1,'ကန်သင်း။ လယ်ကွက်အဖြစ် ခြားကန့်ထားသောမြေရိုး။','ဇုက်ဗၞၚ် = ကန်သင်းရိုး။')
,(10716,3,1,'ပယ်။ မင်းပယ်။ ရှေးခေတ်မြေအတိုင်းအတာ။ (၁ာ၇၅) ဧကနှင့်ညီမျှသည်။','“(ဇိက်ဗ္ၚလ္ၚီဗၞၚ်) သြောံမသုန်ကၠံဗၞၚ်ဂှ် ကဵုသ္ကအ်ဇကုမၚ်ရ။ မသုန်ကၠံဗၞၚ်ဂှ် လိၚ်မၞိဟ်ကဵုမၚ်ရ။” (ဇ—၄၈၄။ အစွောံ။) = “ပယ်ငါးရာအတိုင်းအရှည်ရှိသောလယ်ကို မိမိလူတို့အားလျှင် စောင့်ရှောက်စိမ့်သောငှာပေး၍ ကြွင်းသောပယ်ငါးရာ အတိုင်းအရှည်ရှိသောလယ်ကို အခစားပြုလုပ်သော တယောက်သောသူရင်းငှားအား ပေး၏။” (ညောင်ကန်) || “ပၟတ် (ဂြိုပ်) ဂှ် ကၠာဟွံစိုပ်ကျာ်ကေုာံသၚ်ဂှ် ဗၞတ်စှ်တြဴဗၞၚ်သၟိၚ်ဂှ် ညံၚ်ပၟတ်မိန်ရှောမအာစိုပ်ဍာ်ကီု သိုဟ်ပၠိုတ်အာကၠေံ အိုတ်သ္အးရ။” (ဇ—၃၅။ အစွောံ။) = “(ထိုတောမီးသည် ဘုရားနှင့်သံဃာတို့ဆီမရောက်မီ) တဆယ့် ခြောက်ပယ်မျှသော အရပ်သို့ရောက်၍ ရေ­ပစ်အပ်သော မြက်မီးရှူးကဲ့သို့ ငြိမ်း၏။” (ညောင်ကန်)')
,(10717,3,1,'အတိုင်းအရှည်။ အတိုင်းအတာ။ ပမာဏ။ အရွယ်ပမာဏ။','ဗၞတ်ကာလစှ်တ္ၚဲ =ဆယ်ရက်တာကာလ။ || သ္ၚုဗၞတ်မသုန်န = ဆန်ငါးတင်းပမာဏ။ || သြန်ဗၞတ်ၜါစှ်ောဒကေဝ် =ငွေနှစ်ဆယ်ကျပ်ပမာဏ။ || “ကောန်သၟိၚ်ဒကောတ်ဂှ် ဗဗွဲလၟေၚ်ဇကုဇၞော်အာ၊ ဒကုဲတိုၚ်ဗၞတ်တၞံကီု။” (ဇ—၁၄၁။ အစွောံ။) = “ဖွတ်မင်း၏သားသည်လည်း အစဉ်သဖြင့် ကြီးသောကိုယ်ရှိသည်ဖြစ်၏။ ပုတ်သင်သည်ကား ရှေး (အရွယ်) ပမာဏ ရှိသည်သာလျှင်ဖြစ်၏။” (ညောင်ကန်) || “ဇကုသၠုၚ်သဝ်ဇၞော်သွတ်ဂှ် ဟွံဒှ်ဗၞတ်ရအဴ။” (ဇ—ဘူရိဒတ်။ အစွောံ။) = “ခန္ဓာကိုယ်မြင့်နိမ့်ကြီးငယ်သည် ပမာဏမဟုတ်။ (ဝါ) အဓိကမဟုတ်။” || ‘ဒးဗၞတ်’ (ကြိ) လည်းရှု။')
,(10718,3,4,'ဆောက်လုပ်သည်။ ဖန်တီးသည်။','“ယွံဝိသုကမ္မ၊ — တၞဟ်နဒမံၚ်အရာအဿမာပိုတ်ဂှ် ဇလိၚ်ပိစှ်ောယောဇနာ အနာံစှ်သုန်ယောဇနာ မၞးစှ်ေဗၞတ်လဝ်ညိ” သၟိၚ်အိန်ဂး။ = “အမောင် ဝိသုကြုံနတ်သား၊ နေထိုင်ရန်နေရာ အလျားယူဇနာသုံးဆယ် အနံတစ်ဆယ့်ငါးယူဇနာရှိသော ကျောင်းသင်္ခမ်းကို သၚ်သွား၍ဖန်ဆင်းလော့” ဟုသိကြားမင်းဆို၏။')
,(10719,3,3,'နည်းနည်းနောနောမဟုတ်။ အသေးအဖွဲမဟုတ်။မည်ကာမတ္တမဟုတ်။ သာမန်မဟုတ်သော။ အံ့သြဖွယ်ဖြစ်သော။','“ယွံမၞးတံ၊ ကျာ်တြဲနာဲပိုဲ ဂွံထောံကၠေံနန်ပြာသာဒ်ကောန်သမ္ဘာဂှ် ဗၞတ်ညိညဟွံသေၚ်ရ” ခမဳဂမၠိုၚ်ဂး။ (ဇ—၄၁၁။ အစွောံ။) = “အချင်းတို့၊ ငါတို့မြတ်စွာဘုရားသည် ထီးနန်းစည်းစိမ် သားမယားတို့ကို စွန့်ခြင်းသည် မည်ကာမတ္တမဟုတ်၊ အံ့ဖွယ်ရှိစွ။” || “တြုံဝွံ ညိညဗၞတ်တြုံဟွံသေၚ်ရောၚ်” (ဇ—၃၇၄။ အစွောံ။) = “ဤယောကျာ်းသည် ယောကျာ်းမည်ကာမတ္တမဟုတ်။”')
,(10720,3,1,'အရွယ်ပမာဏ။ အရွယ်အစား။','“ဍာ်မၞုံဗၞတ်တမာတၞံတာဂှ် ဇွောဝ်တိတ်ရ။” (ဇ—၄၉၃။ အစွောံ။) = “ထန်းလုံးပမာဏရှိသောရေသည် စီးထွက်လာ၏။” || “(ထေရ်ဂှ်) မၞုံဇကုသၠုၚ်ဒတဴမသွတ်လောန် မၞုံဇကုမသဝ်ကွတဴ ဗၞတ်တၟာသာမဏဳဍောတ်တ် မအာဒြေပ်ဝေၚ်ကီုမဒှ်ရ။” (ဇ—၂ဝ၂။ အစွောံ။) = “ထိုမထေရ်သည် ငယ်သောကိုယ်အရပ်အမောင်းရှိ၏။ ပုကွသောကိုယ်ရှိ၏။ ပြေးကစားသောသာမဏေငယ်၏ အရွယ်ပမာဏမျှသာဖြစ်၏။” || “ကလော်ဒမြိုဟ်ဂှ်ဍေံရပ်ကေတ်ပသဲမွဲ မဂဵုဒၟံၚ်ညံၚ်သၞပၟတ်ဂှ် မၞုံဗၞတ်တၟာတၞံတာ—။” (ဇ—၃၄၇။ အစွောံ။) = “ကြမ်းကြုတ်သောဘီလူးသည် မီးလျှံကဲ့သို့ တပြောင်ပြောင်တောက်နေသော ထန်းပင်အရွယ်ပမာဏရှိသော သံတုတ်ကိုင်စွဲ၍—။”')
,(10721,3,1,'အတိုင်းအတာပမာဏ။ အပိုင်းအခြား။','“အနာထပိဏ္ဍကသေဋ္ဌဳ ကဵုဒါန်ဟွံတီကဵုဗၞတ်တွဵုရ။” = “အနာထပိဏ်သူဋ္ဌေးသည် ပမာဏမသိ (မရေမတွက်နိုင်အောင်) အလှူပေး၏။”')
,(10722,3,5,'တစ်သက်ပတ်လုံး။ တစ်သက်တာလုံး။','“ဗၞတ်တွဵုအယုက်ဂှ် ဗောဓိသတ်ဗှ်ဒၟံၚ်သၞာဒါန်ဇကုဂှ်ရ။” (ဇ—၄၁၅။ အစွောံ။) = “ဘုရားလောင်းသည် မိမိ၏ဒါနကို တစ်သက်ပတ်လုံး အောက်မေ့နေ၏။”')
,(10723,3,1,'အတိုင်းအတာ။ ပမာဏ။',NULL)
,(10724,3,3,'၁။ ပမာဏမဟုတ်သော။ လက်ခံနိုင်ဖွယ်မဟုတ်သော။','(ဒဒှ်ဗမၞိဟ်ဗြဴ လှိၚ်စိုတ်ကဵုတြုံသ္အာၚ်ဂှ် ဗမၞးတီတုဲ “ယွံကောန်၊ ပွမိနာဲဂှ် ဗၞတ်ဟွံသေၚ်သွံကောန်” ဗမၞးဂးကဵုတ္ၚေက်ရ။ (ဇ—၁၄၅။ အစွောံ။) = (တစ်ပါးသောယောကျာ်းတို့နှင့်တကွ ပျော်မွေ့သောပုဏ္ဏေးမအကြောင်းကို ပုဏ္ဏားသိ၍ “ချစ်သား၊ သင့်မိခင်၏အပြုအမူသည် လက်ခံနိုင်ဖွယ်မဟုတ်ပါလေ”ဟုပုဏ္ဏားသည် ကျေးသားအားဆို၏။')
,(10724,3,3,'၂။ နည်းနည်းနောနောမဟုတ်။ မည်ကာမတ္တမဟုတ်။','‘ဗၞတ်ညိညဟွံသေၚ်’ နှင့်အတူတူ။ || “သကိုပ်ပၞာန်ဓဝ်ဝွံ ဂွံဇိုန်ကဵုပိုန်လောကဳလောကုတ္တဵုကဵုလဗြဴဂှ်ဗၞတ်ဟွံသေၚ်ရ” ခမဳဂမၠိုၚ်ဂး။ (ဇ—၂၅၄။ အစွောံ။) = “တရားစစ်သူကြီး (အရှင်သာရိပုတ္တရာ) သည် ထိုအဖွားအိုအား လောကီလောကုတ္တရာ နှစ်ဖြာသောစည်းစိမ်ဥစ္စာကို ပေးဆောင်ခြင်းသည် နည်းနည်းနောနောမဟုတ်ပါလေ” ဟုရဟန်းများဆိုကုန်၏။')
,(10725,3,1,'ဆုံ။','‘ဗွုတ်’ ရှု။')
,(10726,3,1,'ပွတ်ခုံ။ မီးဖြစ်အောင်ပွတ်တိုက်ရာ အောက်ခံခုံ။',NULL)
,(10727,3,5,'‘ဗနိပ်’ ရှု။',NULL)
,(10728,3,4,'ကစားကျီစယ်သည်။','“ၜိုပ်က္ၜၚ်ပါကဟၚ်ထဝ် မပဝ်အာစိုပ်လစရတ်တုဲ ဝေၚ်ဂြိုၚ်ဗၞိပ်ဗၟက် စစၞဖဲလဲတုဲ—။” (ဇ—ဝိဓုရ။ အစွောံ။) = “ရွှေဟင်္သာတို့သည် ရေအိုင်သို့ ပျံသန်းသွားရောက်၍ ရယ်ရွှင်ကစားကျီစယ်ကုန်၍ အစာကို ဝအောင်စားပြီးနောက်—။”')
,(10729,3,4,'(ရိုက်ချက်) အရှိုးထၚ်သည်။','“အဲတက်စးမပိလစုတ် ကဵုဗၞောဝ်ဒၟံၚ်တုဲ လံက်မိတ်ဂပဵု—။” (ဇ—မဟောဟ်သဓ။ အစွောံ။) = “သင့်ကျောကို သုံးချက်ငါရိုက်၍ အရှိုးထၚ်နေစေပြီးလျှင်နနွင်းထုံးလိမ်းပါ။” || “စးဗၞောဝ်လီ၊ မုက်ဗြီထညောန်။” (လိက်ကောန်သၟိၚ်ပိ။ မာံခစုန်အံက်။) =“(ရိုက်ချက်ကြောင့်) ကျော­အရှိုးထင်၍ မျက်နှာရှုံ့မဲ့၏။”')
,(10730,3,1,'လှံတံ။',NULL)
,(10730,3,4,'အောက်မေ့သည်။','ဗၞုဟ်ဂုန်ကျာ် = ဘုရား၏ဂုဏ်တော်ကို အောက်မေ့သည်။ || “ဗောဓိသတ် (သၟိၚ်ခဍာ်) ဗၞုဟ်ပါရမဳစှ်တုဲ ဗယာပ်မေတ္တာကဵုသၟိၚ်—။” (ဇ—၁၄ဝ။ အစွောံ။) = “ဘုရားလောင်းကျီးမင်းသည် ဆယ်ပါးသောပါရမီတို့ကို အောက်မေ့ဆင်ခြင်၍ မင်းအားမေတ္တာပို့၏။” || “ကောန်ကဵုဂအှ်တံဂှ် ဗၞုဟ်ဂုန်မိတုဲ—။” (ဇ—၄၁၇။ အစွောံ။) = “သားနှင့်ချွေးမတို့သည် မိခင်၏ကျေးဇူးကို အောက်မေ့၍—။”')
,(10731,3,1,'မှိန်းခက်ရင်း။',NULL)
,(10732,3,1,'ဗမာလူမျိုး။ ဗမာတိုင်းရင်းသား။',NULL)
,(10732,3,4,'လေးဘက်ထောက်သွားသည်။ တွား၍သွားသည်။ ဝပ်၍သွားသည်။','“စၟစၚ်စေဝ်အသုဘဂှ် ဍေံဗၟာတိုန်အာမံၚ် လတူအသုဘဂှ်ရ။” (ဇ—၂၂၇။ အစွောံ။) = “ထိုမစင်စားသောပိုးသည် မစင်ပုံပေါ်သို့ ဝပ်၍တက်သွား၏။” || “စိၚ်ဂှ် မိၚ်ၚဴဂတာဇြဟ်ဂှ်ဗြုတုဲ ဗၟာစှ်ေပၠန်ရ။” (ဇ—၃၅၇။ အစွောံ။) = “ဆင်သည် ချောက်တွင်းနက်မှဖားအော်သည်ကို ကြားသည်ရှိသော် ဝပ်၍ဆင်းပြန်၏။”')
,(10733,3,1,'ဆားနယ်မြေ။',NULL)
,(10734,3,4,'နို့တိုက်သည်။','“ပ္ဍဲမကဵုဗမဴတှ်ဂှ် သၟတ်ဂှ်ယာံတဴရ။” (ဇ—၂၆၃။ အစွောံ။) =“နို့တိုက်စေသောအခါ ထိုကလေးသည် ငို၏။” || ‘မဴ’ (ကြိ) လည်းရှု။')
,(10735,3,4,'ကျီစယ်သည်။ ကျီစားသည်။','“သၟိၚ်ဗြဟ္မဒတ္တ သၟိက်ပဗမက်ဝေၚ်ကဵု (ညးဗျုဗျုတအ်ရ။)” (ဇ—၂ဝ၂။ အစွောံ။) = “ဗြဟ္မဒတ်မင်းသည် သူအိုတို့အား ကျီစယ်ကစားလေ့ရှိ၏။” || “သၟိၚ်ဗိမ္ဗိသာဂှ် ဗမက်ဝေၚ်ကဵုကောန်ညိတုဲ—။” (ဇ—၃၇၃။ အစွောံ။) = “ဗိမ္ဗိသာရမင်းသည် သားနှင့်ကစားကျီစယ်၍—။”')
,(10736,3,1,'အရှေ့အရပ်။ နေထွက်ရာအရပ်။','ဒိုဟ်ဗၟံက် = အရေ့အရပ်။')
,(10737,3,4,'ဖော်သည်။ ပေါ်အောင်ထားသည်။','“ကၞုဟ်မွဲဂှ် မံက်တိုန်နူဍာ်တုဲ ဆကၞိပ်ဗမံက်လဝ်ပ္ဍဲသြၚ် ပါၚ်ဟာဒၟံၚ် ဒုၚ်ဒၟံၚ်တ္ၚဲတုဲ လှိၚ်အာရ။” (ဇ—၂၇၃။ အစွောံ။) = “တစ်ခုသောလိပ်သည် ရေမှတက်၍ ဦးခေါင်းကိုသာလျှင် ကမ်း­ဖော်ထား၍ ဂၚ်္ဂါနား­ ခံတွင်းကိုဖွင့်၍ နေပူခံလျက်အိပ်၏။” || “ဒကောတ်ဂှ် လုပ်အာပ္ဍဲဂမြေၚ်တုဲ တိတ်ဗၟံက်လဝ်က္ဍိုပ် ပ္ဍဲတဏအ်ဂှ်—။” (ဇ—၃၂၅။ အစွောံ။) = “ဖွတ်သည် တွင်းသို့ဝင်၍ တောင်ပို့­ ဦးခေါင်းကိုဖော်၍ထား၏။” || “ကာလသ္ပဝ်တံကၠုၚ်ဂှ် ပိုဲ (နာ်တံ) လ္ပံက်လဝ်ေၚက်ပိုဲတုဲ ညံၚ်မသၟက်ဂှ်ပတုဲ ပိုဲဗမံက်လဝ်က္ဍိုပ်—”သၟိၚ်နာ်ဂး။ (ဇ—၅၁၈။ အစွောံ။) = “ဂဠုန်တို့လာသောအခါ ငါတို့နဂါးတို့သည် သွားတို့ကိုဖွင့်၍ ဂဠုန်တို့ကို ဖမ်းကိုက်အံ့သကဲ့သို့နေ၍ ခေါင်းတို့ကိုဖော်ထား၏။” || (မှတ်ချက်။ ယနေ့ခေတ်တွင် လူအများအပြားတို့ ရေးနေကြသော ‘ဓမံက်’/‘ထမံက်’ သည် စာလုံးပေါင်းပုံမမှန်ကြောင်း သတိပြုစေလိုသည်။)')
,(10738,3,4,'အကောင်အထည်ဖော်သည်။ ရုပ်လုံးဖော်သည်။',NULL)
,(10739,3,4,'စောင့်သည်။ စောင့်မျှော်သည်။ ၚံ့လင့်သည်။','“လၟုဟ်ဝွံလေဝ် ကောအဲညးတရဴနွံဏီ။ ဗမတ်ကောအဲစိုပ်ညိကၠာရ။” (ဇ—၁၅၂။ အစွောံ။) = “ယခုလည်း ငါ့အစ်ကိုခြောက်ယောက်တို့သည် ရှိသေး၏။ ငါ့အစ်ကိုတို့ပြန်ရောက်သည်ကို စောင့်ဦးအံ့။” || “ကျာ်တြဲပဒတဴ ပ္ဍဲဂြိုပ်ဇာဒိဖဵုဂှ် ပိဂိတုရ။ လလအ်ညာန်ပညာပါရမဳသၟတ်ဘဒ္ဒဇိကုမာ ကြံၚ်ဍုဟ်တုဲဂှ် မဗမတ်ဒၟံၚ်ရ။” (ဇ—၂၆၄။ အစွောံ။) = “မြတ်စွာဘုရားသည် အလိုလိုဖြစ်သောတော­ ဘဒ္ဒဇိသတို့သား၏ ဉာဏ်ရင့်ခြင်းကို ၚံ့တော်မူလျက် သုံးလပတ်လုံး နေတော်မူ၏။” (ညောင်ကန်) || “မိသၟတ်ဂှ်တုန် ဗၟတ်ဒၟံၚ်ကောန်မစဴကၠုၚ်ဂှ်ရ။” (ဇ—၄၃၉။ အစွောံ။) = “သူငယ်၏မိခင်သည် သားပြန်ရောက်သည်ကိုစောင့်မျှော်လျက်နေ၏။” || “ဗမတ်မအံက်အဲစိုပ်ညိကၠာ။” (ဇ—၁ဝ၆။ အစွောံ။) = “ငါ့ဖခင်ရောက်သည်ကို စောင့်ပါဦး။” || ‘ဂမတ်/ဂမောတ်’ ဟု၄င်း ‘လမတ်/လမောတ်’ ဟု၄င်း အချို့ရေးကြသည်။')
,(10740,3,4,'စောင့်ဆိုင်းသည်။','“ပၠဳပၠအ်ဒၟံၚ်တုဲ သၟိၚ်မာရဏတေံ ဗမတ်လဇဒၟံၚ်အဲဟာ။” (ဇ—၅ဝ၉။ အစွောံ။) = “အချိန်ရွှေ့ဆိုင်းနေသဖြင့် သေမင်းက ငါ့ကို စောင့်ဆိုင်းနေပါမည်လော။”')
,(10741,3,1,'စုန်း။','ဗၟုဲစ = စုန်းပြုစားသည်။ || “ဒေဝတဴတံညးဂမၠိုၚ် ကော်နၚ်ဗၟုဲ၊ ကော်နၚ်ကလော်၊ ကော်နၚ်လကိုဟ်။” (သၠပတ်ကွိက်ကၠိ) = “နတ်အပေါင်းတို့သည် စုန်း၊ သရဲသဘက်၊ဘီလူးတို့ကို ခေါ်ဆောင်လာ၏။”')
,(10742,3,1,'ဥရိုး။ မျိုးဥ။','“ကဒါတ်ဗက်ဗျ ကောန်ဗက်မိမ။” = “ကဒတ်က ဥရိုးကိုလိုက်သည်။သားသမီးက မိဘကိုလိုက်သည်။” (မွန်စကားပုံ) ‘ဘမျိုးဘိုးတူ’ နှင့်ဆင်တူသည်။')
,(10743,3,4,'ကွဲပျက်သည်။','“စိုပ်ဒေါဝ်ၜဳဂျ၊ ဂၠုၚ်က္ၜၚ်ဗျအာ။” (လိက်နဲယသမုဒ္ဒြဳ။ အစွောံ။) =“သမုဒ္ဒရာလယ်သို့ရောက်သော် လှေသင်္ဘောကွဲပျက်သွား၏။”')
,(10744,3,11,'(န) ပြောကြားခြင်း။ ဖြေဆိုခြင်း။ ဗျာကရိုဏ်းကျမ်း။',NULL)
,(10745,3,10,'(န) နာခြင်း။ ဗျာဓိ။',NULL)
,(10746,3,10,'(န) သူတစ်ပါးအား ပျက်စီးစေလိုသောစိတ်ထား။ ဗျာပါဒ။',NULL)
,(10747,3,10,'(န) လုံ့လထုတ်ခြင်း။ အားထုတ်မှု။',NULL)
,(10748,3,4,'အပြစ်တင်သည်။','“လ္ပဗျိအဲပြဟ်ဏီ၊ သၟာန်ရံၚ်ပရေၚ်ဒဒှ်အဲညိကၠာ။” = “ကျွန်တော့်ကိုအပြစ်တင်မစောပါနှင့်၊ ကျွန်တော်၏ဖြစ်ကြောင်းကို ဦးစွာမေးကြည့်ပါအုံး။”')
,(10749,3,4,'အပြစ်တင်မြည်တွန်သည်။',NULL)
,(10750,3,4,'အပြစ်တင်ရှုတ်ချသည်။ ကဲ့ရဲ့ရှုတ်ချသည်။','“အမာတ်မၞုံဒုဟ်ဂှ် သၟိၚ်ဗျိပၠုတ်ကၠေံရ။”= “အပြစ်ရှိသောအမတ်ကို မင်းသည် အပြစ်တင်ရှုတ်ချ၏။” || “ညံၚ်ပါၚ်မကြီုကၠာတေံ ဍေံဟွံဒှ်သွံ” ဗောဓိသတ်ဂးတုဲ ဟီုဗျိပၠုတ် (ဘိမ္ဗသေဏရ။) (ဇ—၈ဝ။ အစွောံ။) = “ယခင်သင်ကြုံးဝါးသကဲ့သို့ မဖြစ်ပါလား” ဟုဆိုကာ ဘုရားလောင်းသည် ဘီမသေနအား ကဲ့ရဲ့ရှုတ်ချ၏။ || “(မၚ်ဗၠာဲဂှ် ပ္ဍဲအခိၚ်စသုၚ်ဂှ်) ဂရိုဟ်ဗျိပၠုတ်ဒၟံၚ် ကွာၚ်ယာဂုစၞအမာဲတံဂှ်လၟိုန်ဟေၚ်။” (ဇ—၁၂၅။ အစွောံ။) = “ထိုလုလင်သည် စားသောက်ချိန်­ အစားအစာတို့ကို အမြဲတမ်းပၚ် ကဲ့ရဲ့အပြစ်ဆိုနေ၏။” || “ဇန်တံညးဂမၠိုၚ်ဂှ် ဍေံဂရိုဟ်အဲကီု ဍေံဗျိပၠုတ်အဲကီု အဲသ္ဂောံတီညိခိုဟ်ရောၚ်” သၟိၚ်ချပ်။ (ဇ—၁၅၁။ အစွောံ။) = “လူအပေါင်းတို့သည် ငါ့ကို ကဲ့ရဲ့ကြကုန်သလော၊ ငါ့ကို အပြစ်ဆိုရှုတ်ချကြကုန်သလော သိရလျှင်ကောင်းမည်” ဟုမင်းကြံ၏။')
,(10751,3,4,'အပြစ်တင်သည်။ ရှုတ်ချသည်။ ကဲ့ရဲ့သည်။','“ညးတံသၟာန်ဂလာန်ကုပိုဲတုဲ ယဝ်ရပိုဲသှ်ကဵုသၟာန်ညးတံဟွံဒးမ္ဂး ညးတံဗျိဗျံက်ဂရိုဟ်တုဲ ပိုဲဒးဂွရ။” (ဇ—၃၃၆။ အစွောံ။) = “လူတို့သည် ငါတို့အား ပြဿနာကိုမေးကုန်၍ ငါတို့မဖြေနိုင်ပါက ၄င်းတို့ကဲ့ရဲ့ရှုတ်ချသဖြင့် ငါတို့အရှက်ရကုန်လတ္တံ့။”')
,(10752,3,4,'အလင်းရောင်ထိုးသည်။',NULL)
,(10753,3,4,'၁။ (အလင်းရောင်၊ မေတ္တာတရားစသည်) ပျံ့နှံ့သည်။ လွှမ်းခြုံသည်။','“လျးသၟိၚ်တ္ၚဲဗျဳဗျာပ်တဴ အလုံတိဇၞော်ရ။” = “ကမ္ဘာမြေအလုံးကို နေမင်း၏အလင်းရောင် ပျံ့နှံ့လွှမ်းခြုံထားသည်။” || “(မြမောဝ်ဓဝ်သဳလဂှ်) ပ္ဍးတၟာဲအာဇဳ မောဝ်ဗျဳဗျာပ်အာရောၚ်။” (သုဓမ္မဒေသနာ။ ဂရိုက်သာံ။) = “သီလမွှေးရနံ့သည် အရပ်ရပ်သို့နှံ့၍ သင်းပျံ့မွှေးကြိုင်၏။” || “ဇၟာပ်မိမတံဂှ်မေတ္တာဗျဳဗျာပ်တဴ ပ္ဍဲကောန်အိုတ်ရ။” = “မိဘတိုင်းသည် သားသမီး­ မေတ္တာတရား ပျံ့နှံ့ကုန်၏။”')
,(10753,3,4,'၂။ ပေးကမ်းမျှဝေသည်။','“ပကာန်ညးမဒှ်သတြုမ္ဂးဂှ် — ဘောဇိုန်ခိုဟ်ကလိဂွံဂှ်လေဝ်ဟွံဗျဳဗျာပ်ကဵုညး။” (ဇ—၄၇၃။ အစွောံ။) = “ရန်သူဖြစ်သောသူ၏လက္ခဏာကား ကောင်းမြတ်သောဘောဇဉ်ကို ရသည်ရှိသော် သူတစ်ပါးအား မပေးကမ်းမမျှဝေ။” || “ပူဂဵုမဒှ်မိတ်ဂှ်တုန် —ကလိဂွံဘောဇိုန်ဂှ် ဆန်ၜန်ဗျဳဗျာပ်ကဵုညး။” (ဇ—၄၇၃။ အစွောံ။) (ဆန်ၜန် = ဗျဳဗျာပ်) =“မိတ်ဆွေဖြစ်သောသူသည် ဘောဇဉ်စားဖွယ်ကို ရသည်ရှိသော် သူတစ်ပါးအား ခွဲခြမ်းဝေမျှပေး၏။” || “သီုကဵုဗစဲပန် ဆန်က္ၜန်ဗျဳဗျာပ်ကဵုဒါန်သၚ်တုဲ။” (သၠပတ်အရုဒုမ္မ) = “ပစ္စည်းလေးပါးတို့ကို သံဃာများအား ပေးလှူဝေမျှ၏။” (ဆန်က္ၜန် = ဗျဳဗျာပ်) || “(ပိုန်ဒြပ်ဇကုတံဂှ်) ကုမိမကောဒေံ ကၟိန်ကလောဒညာတ်တံဂှ် ဂပ်ဂဝ်သၚ်ရိုဟ်ဗျဳဗျာပ်ပရအ်ဗဒုၚ်ကဵုရောၚ်။” (ဇ—၃၉ဝ။ အစွောံ။) = “မိမိ၏စည်းစိမ်ဥစ္စာတို့ကို မိဘမောင်နှမဆွေမျိုးတို့အား ထောက်ပံ့မျှဝေပေးကမ်းသင့်၏။”')
,(10753,3,4,'၃။ အသက်ရှင်သန်နိုင်ရန် မှီဝဲသည်။ မျှလောက်သည်။','‘ယိုပ်ယာပ်’ နှင့် အဓိပ္ပါယ်အတူတူ။ || “ယွံနာဲပိုဲတၠရသိ၊ — တၠအဲမဂၠာဲၚဳသစ္ဆုလၟုဟ်လၟတ် မစိဂွံဗျဳဗျာပ်ညိဟာ။” (ဇ—ဝေသန္တဝ်။ အစွောံ) = “ရှင်ရသေ့၊ ကိုယ်တော်အဘယ်သို့ ရှိပါသနည်း။ တောသစ်မြစ်သစ်သီး (ကြီးငယ်) ရှာမှီးခြင်းဖြင့် မျှလောက်ပါ၏လော။” (မင်းပူးဦးသြဘာသ) || “(ပ္ဍဲဋ္ဌာန်ဂြိုပ်ဝွံ) နမဂၠာဲၚဳသစ္ဆုစၞ ပိုဲမဂွံဗျဳဗျာပ်တဴရ။” (ဇ—ဝေသန္တဝ်။ အစွောံ။) = “ဤတောအရပ်­ သစ်သီးအစာရှာခြင်းဖြင့် ငါတို့မျှလောက်ပါကုန်၏။” || “ဟိုတ်နူမဂွံဗျဳဗျာပ်အာဟာရတုဲ မဂွံဂျိုၚ်တဴလမျီု—။” (ဓမ္မဒေသနာ။ မာံရွှေငိုး။) = “အာဟာရကို မှီဝဲရသောကြောင့် အသက်ရှင်သန်ရ၏။”')
,(10753,3,4,'၄။ သာယာနာပျော်ဖွယ်ဖြစ်သည်။ နားဝၚ်ပီယံဖြစ်သည်။','“ဒှ်ဂလာန်သုဘာသိုတ် နွံရှ်သာဍာတ်ကြိုအ် ဍုက်ဍေက်ဗျဳဗျာပ်ပ္ဍဲကတောဝ်ညး။” (နဝကောဝါဒကထာ။ ပြကိုဟ်မန်ဍုၚ်သေံ။) = “သူတစ်ပါးတို့အား နားဝၚ်ချိုနာပျော်စေသော ကောင်းသောစကား။”')
,(10754,3,1,'လျှပ်စီး။','‘ဖျဳလလဳ’ ရှု။')
,(10755,3,4,'အိုသည်။',NULL)
,(10756,3,16,'အိုမင်းသည်။—သော။','“လၟုဟ်ဝွံလေဝ် အဲဗျုဇၞော်အာတုဲရ။” (ဇ—၁၅၆။ အစွောံ။) = “ယခုအခါ ငါသည် အိုမင်းလေပြီ။” || “သၟိၚ်မအဲဂှ် ဗျုဇၞော်အာတုဲ ဍိုန်ကဵုဒြဟတ်—။” (ဇ—၃၈၁။ အစွောံ။) = “ငါ့ဖခင်သည် အိုမင်းကြီးရင့်၍ အားနည်း၏။” || ‘ဇၞော်ဗျု’ နှင့်အတူတူ။')
,(10757,3,4,'ရင့်ရော်ဟောင်းနွမ်းသည်။','“ခန္ဓသတ်တအ်ဂှ် ဟွံဗိုန်ဂၠိ မၞုံသဘဴမဒးဗျုတြေံရ။” = “သတ္တဝါတို့၏ခန္ဓာသည် မတည်မြဲ ဟောင်းနွမ်းရင့်ရော်ရမည့် သဘောရှိသည်။”')
,(10758,3,4,'အိုမင်းသည်။ ကြီးရင့်သည်။','“အဲလမုဟ်ဝွံ၊ အယုက်ဗျုထဴ။” (လိက်ပထမဗောဓိ။မၚ်ဍိက်လ။) = “ငါသည် ယခုအသက်ကြီးရင့်လေပြီ။”')
,(10759,3,4,'အိုမင်းသည်။ ရင့်ရော်သည်။','“ညံၚ်တၞံဆု ၝောံဍေံဂှ် ဗျုဗျသၟာဲသၟအာတုဲ ဗၠိုၚ်ဆုဂှ် ရဴမထပ်တိုန်ဒၞာဲဂှ်ကီု။” (ဇ—ဝိဓုရ။ အစွောံ။) = “သစ်ပင်ကဲ့သို့ အပၚ်မကြီးသည် အိုမင်းပုပ်ဆွေးသွားသောအခါ အညွန့်အတက်တို့သည် ထိုနေရာ­ တက်ပြန်သကဲ့သို့။” || “ဇၞော်အာတုဲရောၚ်၊မွဲတောင်ဗျုဗျ။” (လိက်ဟတ္ထိပါလ။ အစွောံ။) || “ဟွံတီဗျုဗျ၊ ရာဂတဏှာ။” (လိက်ဇိဝှစက္က) =“အိုမင်းသည်ကိုမသိသော ရာဂတဏှာ။”')
,(10760,3,4,'အနားယူသည်။ အနားပေးသည်။','ဗျူကာယ = ခန္ဓာကို အနားပေးသည်၊ အနားယူသည်။ || ဗျူချေံ = မြင်းကို အနားပေးသည်။ || “ပိုဲဍိက်ဗျူဗိုလ်လဗး ကဵုနွံဒြဟတ်ညိကၠာ—။” (အကြီုရာဇာဓိရာဇ်) = “ကျွန်တော်မျိုးတို့စစ်သည်ဗိုလ်ပါများကို ခွန်အားရှိအောင် အနားပေးပါဦးလော့။” || “တၠညးဖရၚ်မၚ်ဂံၚ် ဗျူဒပ်ပၞာန်ဒိုအ်မံၚ်။” (အကြီုရာဇာဓိရာဇ်) = “ဘုရင်မင်းခေါင်သည် စစ်တပ်ကိုအနားပေးပြီး ရပ်နားနေ၏။” || “စိုပ်ဂြိုပ်မာလာ၊ ဗျူတဴကာယျ။” (လိက်သၟိၚ်စိၚ်ဆဒ္ဒန်။ နာဲထဝ်စိုပ်။) = “ပန်းတောသို့ရောက်၍ ခန္ဓာကိုယ်ကိုအနားပေး၍ အမောဖြေ၏။”')
,(10761,3,4,'အမောဖြေသည်။ အမောအပန်းဖြေသည်။','“ဗျူကၠေံလၟောၚ်လၟေတ်ကၠာရ။” (ဓမ္မဒေသနာ။ မာံရွှေငိုး။) = “အမောအပန်းဖြေပါဦးလော့။”')
,(10762,3,10,'(န) စစ်ဆင်ခြင်း။ ဗျူဟာ။','“ယွံမၞးတံ၊ ဋ္ဌာန်စၞေဟ်ဂှ် ဒှ်ပိသာ်တုန်။ ဗျူဟာညံၚ်ပ္ကဴဒကှ်မွဲ ညံၚ်စက်မွဲ ညံၚ်မုက်ကွဳစောတ်မွဲ ဣဝွံပိသာ်ရ။ ပၞောဝ်ပိသာ်ဂှ် ဗျူဟာညံၚ်ပ္ကဴဒကှ်ဂှ်ကေတ်ရ။” (ဇ—၂၈၃။ အစွောံ။) = “စစ်ထိုးခြင်းမည်သည်ကား ပဒုမဗျူဟာ စက္ကဗျူဟာ သကဋဗျူဟာဟု သုံးပါးအပြားရှိ၏။ ဤသုံးပါးအနက် ပဒုမဗျူဟာကို ယူကြမည်။” || “ညံၚ်ဗီုအသူ၊ ဝေၚ်ပၞာန်ဗျူဟ။” (လိက်ကောန်သၟိၚ်ပိ။ မာံခစုန်အံက်။) = “အသူရာနတ်များ စစ်ဗျူဟာခင်းကျင်းသကဲ့သို့။”')
,(10763,3,4,'အပြစ်တင်သည်။ စွပ်စွဲသည်။',NULL)
,(10764,3,4,'ပြောဆိုစွပ်စွဲသည်။','“ယွံခမဳတံ၊ စိဉ္စမာဏဴဝွံ နဂလာန်မဟွံဒှ်စၟတ် မဟီုဗျံက်အဲဂှ်ဆလၟုဟ်ဟွံသေၚ်၊ ပ္ဍဲကာလမတုဲတေံကီုလေဝ် နဂလာန်ဟွံဒှ်စၟတ် ဍေံဟီုဗျံက်အဲတုဲရ” ကျာ်တြဲဂး။ (ဇ—၁၂ဝ။ အစွောံ။) = “ရဟန်းတို့၊ စိဉ္စမာဏဝိကာသည် ယခုသာလျှင် ငါ့ကို မဟုတ်မမှန်သဖြင့် စွပ်စွဲသည်မဟုတ်သေး။ ရှေး­လည်း စွပ်စွဲဖူးသလျှင်ကတည်း” ဟုမြတ်စွာဘုရားမိန့်တော်မူ၏။ (ညောင်ကန်)')
,(10765,3,4,'စွပ်စွဲသည်။','“မိၚ်ညးဟီုလှံက်၊ က္ၜေဟ်လက်ဗျံက်ဗျ။” (လိက်နဲယသမုဒ္ဒြဳ။ အစွောံ။) = “သူတစ်ပါးတို့ ပြက်ရယ်ပြုဆဲဆိုစွပ်စွဲသည်ကို ကြား၍။” || “ဒ္ၚဳဟီုဗျံက်ဗျ၊ ပ္ဍဲကာလဂှ်။” (လိက်ဘောဂရေန်) || “ကဵုသမ္ဘာညး၊ ဟီုဂးဗျံက်ဗျ။” (လိက်သၟိၚ်ဇဲယဒတ္တ) = “သူတစ်ပါးမယားအား ပြောဆိုစွပ်စွဲသည်။”')
,(10766,3,4,'ယှဉ်၍ထားသည်။ စီတန်းသည်။ အပြိုၚ်ယှဉ်တွဲသည်။','“ဗျာၚ်လဝ်ဂၠုၚ်ဇၞော်တံဂှ်—။” (ဇ—၄ဝ၇။ အစွောံ။) = “လှေကြီးတို့ကို လှေချင်းယှဉ်၍ထားသည်။” || “ဂိတုလေဝ်တိုန်သီုကဵုလျး ကွဳမာတလိလေဝ်သီုကဵုလျး လျးဂိတုသီုကဵုလျးကွဳဗျာၚ်စှ်ေကၠုၚ် သီုမှာဇန်တံညးဂမၠိုၚ်ညာတ်တုဲ—။” (ဇ—နေမိ။ အစွောံ။) = “လမင်းသည် အလင်းရောင်နှင့်တကွ တက်လာ၏။ မာတလိနတ်သား၏ရထားသည်လည်း အလင်းရောင်နှင့်တကွလာ၏။ လ၏အလင်းနှင့်ရထား၏အလင်းအပြိုၚ်ယှဉ်တွဲ၍ ဆင်းလာသည်ကို လူအပေါင်းတို့မြင်လေသော်—။” || “ညံၚ်ရဴဗၠိုၚ်တာၜတ်ၜတ်ၜါဗျာၚ်လဝ်မွဲစွံကီု။” (ဓမ္မဒဳပနဳ။ မာံရွှေငိုး။) = “နုသောထန်းအညွန့်အတက်နှစ်ခုကို အတူတကွယှဉ်တွဲထားသကဲ့သို့။” || “ဂြိုဟ်မ္ဂးဂှ် ဒှ်ဂၠးဂတှ်ေဖျုန် (၂) ကလောအ် မဗျာၚ်ဒၟံၚ်ရ။” (ဓမ္မဒဳပနဳ။မာံရွှေငိုး။) = “အသည်းဟူသည်ကား အသားစိုၚ်ချပ်လွှာ (၂) တုံး အပြိုင်ယှဉ်တွဲတည်ရှိနေ၏။” || “ဇဝ်ကဵုဇဝ်ဗျာၚ်၊ ပံက်ထာၚ်ရာၚ်ဗဝ်။” (လိက်သၟိၚ်စိၚ်ဆဒ္ဒန်။ နာဲထဝ်စိုပ်။) = “အဖူးအဖူးချင်း ယဉ်တွဲစီတန်း၍ ပွင့်ချပ်ကိုဖွင့်ကာ များစွာပွင့်လန်းကုန်၏။”')
,(10767,3,5,'အတူတကွ။ စီတန်းလျက်။ အပြိုၚ်ယှဉ်တွဲလျက်။','“တေံကြေဲမွဲတုံ၊ မံၚ်ကောံမွဲစွံ။ ကဵုရမျှာၚ်သွံ၊ မွဲစွံဗျာၚ်ဗျာၚ်။” (လိက်ကောန်သၟိၚ်ပိ။ မာံခစုန်အံက်) = “ဟိုမှာ ကြိုးကြာငှက်အစုသည် အတူတကွစုရုံးနေကာ တကွအပြိုၚ် အသံပေး၏။” || “ဟးသၞံၚ်ၝောံစာၚ်၊ ဗျာၚ်ဗျာၚ်သီုဆော။ မိညာတ်သၞံၚ်ရော၊ ဗှ်ကောစာ်သၠ။” = “?ကြယ်သည် အစုံနှင့်တကွ အပြိုၚ်တွဲလျက်ရှိ၏၊ ထိုကြယ်ကို မယ်မြင်လတ်သော် ကွဲကွာနေသောမောင်ကို သတိရမိ၏။”')
,(10768,3,4,'စီတန်းလျက်ရှိသည်။ စီရရီဖြစ်သည်။','‘ဇၞောဝ်ရာဲတံၚ်ခေါန်တံဂှ် ကဵုသြံၚ်ဗျိၚ်လဝ်။’ (ဇ—၄၉၇။ အစွောံ။) = ‘တံခွန်ကုက္ကားတို့ကို စိုက်ထူစီတန်းထားသည်။’ || “ပ္ကဴတံဂှ်ဗျိၚ်အာ တဝ်ကဵုတဝ်ရေၚ်ဒၟံၚ်ဗွဲပ္ဍဲ ထာၚ်ကဵုထာၚ်တိတ်သၟုက်ဒၟံၚ်မ္ၚး သၟးညးမဇန်တရေၚ်လဝ်ကီု ဗျိၚ်ဒၟံၚ်ရ။” (ဓမ္မဒဳပနဳ။ မာံရွှေငိုး။) = “ထိုပန်းတို့သည် စီတန်းနေကုန်၏။ ရိုးညှာတံအချင်းချင်း အတွင်းဘက်­ စီနေကုန်၏။ ပွင့်ချပ်အချင်းချင်း အပြင်ဘက်­ စီနေကုန်၏။ သီကုံးထားသည့်အလား စီရရီစီတန်းနေကုန်၏။”')
,(10768,3,9,'ကြိယာ၊ နာမ်စသည်ကို ထောက်ပံ့သောစကားလုံး။','“ပၚ်ပတိုန်ဗျိၚ်၊ တူဓလိၚ်ပၠ။” (လိက်မၚ်ဗၠာဲဟောံလွဳ) = “ထမ်းစင်ပေါ်သို့ ပင့်တင်လိုက်သည်။”')
,(10769,3,4,'စီတန်းခြံရံသည်။','“သီုနာံမြိုင်ကောန်စဴ ဍိက်သ္ကအ်ဂၠဴပြေၚ် ဗျိၚ်တရေၚ်ဒၟံၚ်ကဵုဗော်သွး—။” (ဓမ္မဒေသနာ။ မာံရွှေငိုး။) = “မိတ်ဆွေသားမြေး ကျေးကျွန်ကျွဲနွား မိမိဘက်တော်သားများနှင့်တကွ စုံစုံညီညီ စီတန်းခြံရံလျက်။” || “ဂၠိုၚ်ကဵုဗဵုလဗးဗော်သွး သ္တုံဇွိဂတကြဴ ဍိက်သ္ကံဂၠဴပြေၚ် ဗျိၚ်တရေၚ်ဒၟံၚ် ဟွံတီကဵုတွဵုလၟိဟ်။” (ဓမ္မဒဳပနဳ။ မာံရွှေငိုး။)')
,(10770,3,4,'စီတန်းသည်။ စီရရီဖြစ်သည်။','“ကၟာၚ်ဍုၚ်ဂှ် မတၟုဲတဴနရတ်ထပှ်ထပ်၊ဝုတ်ဒိုဟ်ကၟာၚ်ဍုၚ်ဂှ် မတၟုဲတဴနတာရတ်ထပှ်ထပ် မဗျိၚ်ဒရိၚ်ဒၟံၚ်တဴရ။” (အဓါန်မသုန်။ အစွောံ) =“မြို့ရိုးသည် ရတနာခုနစ်ထပ်ဖြင့် တန်ဆာဆင်လျက်ရှိ၏၊ မြို့ရိုးပတ်လည်တွင် ရတနာထန်းပင်ခုနစ်ထပ်ဖြင့် အထပ်ထပ် စီတန်းလျက်တည်ရှိ၏။” || “သီုပၞာန်စိၚ်ချေံတိုက်ကွဳ ဇက်သ္အဳတွဳဗျိၚ်ဒရိၚ်ဒၟံၚ်။” (ဇ—၅၃၇။ အစွောံ။) = “ဆင်တပ်၊ မြင်းတပ်၊ ခြေသည်တပ်၊ ရထားတပ်တို့ဖြင့်ပေါင်းရုံးစုထပ် စီတန်းလျက်ရှိ၏။” || “သၟိၚ်နေမိညာတ်ပြာသာဒ် (သွဝ်) တၟေၚ်တၟဟ် တ္ၜန်တ္ၜောဲတရေၚ်ဗဂါ ဗျိၚ်ဒရိၚ်ဒၟံၚ်နာနာသာ်။” (ဇ—နေမိ။ အစွောံ။) = “အထူးထူးအပြားပြား စီရရီယှက်သန်းစီတန်းနေသော နတ်ဘုံပြာသာဒ်ကို နေမိမင်းမြင်သော်—။” || “ဆုမၞုံကဵုဂကူတၞဟ်တၞဟ် မသၟဟ်သၟန်ဗျိၚ်ဒရိၚ်ဒၟံၚ်။” (ဇ—ဝိဓုရ။ အစွောံ။) = “သစ်ပင်မျိုးစုံတို့သည် ညီညာစွာစီတန်းလျက်ရှိကုန်၏။” || “ရုၚ်ချေံရုၚ်စိၚ်၊ ဗျိၚ်ဒမြိၚ်ဗ္ဂာ။” (လိက်ပထမဗောဓိ။ မၚ်ဍိက်လ။) = “မြင်းတင်းကုပ်ဆင်တင်းကုပ်တို့သည် စီတန်းပြည့်ယှက်နေကုန်၏။”')
,(10771,3,4,'(ဘေးဘယ်ညာမှ) အပြိုင်သွားသည်။','“သၟိၚ်ကွဴဝွံ လ္ပကဵုဒွအ်ပရိုက်ကျာလမုဟ်ဂမ္တဴ လတိုပ်လမၠာၚ်ညိ” ဂးတုဲ ဗွဲၜါဒိုဟ်သတုံဇွိဂှ် ကွဴဝုတ်မသုန်ကၠံဂှ် ကဵုပဝ်ဗျိုၚ်ဗက်အာ—။ (ဇ—၅၃၆။အစွောံ။) = “ဥသြမင်းအား အချမ်းသည်၄င်း အပူသည်၄င်း ဆီးနှင်းပေါက်သည်၄င်း မထိစေသတည်း” ဤသို့နှလုံးသွင်း၍ ငါးရာကုန်သောဥသြငှက်မတို့သည် နံပါးနှစ်ဖက်­ အပြိုၚ်ပျံသွားစေကုန်၏။')
,(10772,3,4,'၁။ (ရေချိုးပြီး၍ကိုယ်ကို) ရေခြောက်အောင်စစ်သည်။','“သမိဒ္ဓိထေရ်ဗၠိုပ်ဟုံတုဲ အတ္တဘဴဇကု မတုပ်တဴညံၚ်ရဴသာ်ထဝ်ဂှ် ဗျတ်ဍာ်ဇကုတုဲ သပိုၚ်ကၠေံသ္ပိုၚ်ရ။” (ဇ—၁၆၇။ အစွောံ။) =“သမိဒ္ဓိမထေရ်သည် ရေချိုးပြီး၍ ရွှေအဆင်းနှင့်တူသော အဆင်းရှိသောမိမိကိုယ်ကို ခြောက်စေပြီးလျှင် သင်းပိုၚ်ကိုဝတ်၏။” || “(သၟိၚ်စိၚ်ဆဒ္ဒန်) ဟုံဍာ်ကၠာတုဲ တိုန်ကၠုၚ်ဒတဴဒၟံၚ် လတူဒဵုတုဲဗျတ်ဇကုရ။” (ဇ—၅၁၄။ အစွောံ။) = “ဆဒ္ဒန်ဆင်မင်းသည် ဦးစွာရေချိုးပြီးလျှင် ရေမှတက်၍ကုန်းပေါ်­ရပ်လျက် ကိုယ်ကိုခြောက်အောင် ရေစစ်၏။”')
,(10772,3,4,'၂။ (ရေချိုးပြီးခါစ ကိုယ်မှရေစက်များ) ယိုစီးကျသည်။','“(ဗောဓိသတ်သၟိၚ်စိၚ်ဆဒ္ဒန်ဟုံဍာ်တုဲ) ဍာ်ဇကုဗောဓိသတ် မဗျတ်ထၞဟ်စှ်ေဒးဇကုလၟဂှ်တုဲ—။” (ဇ—၅၁၄။ အစွောံ။) = “ဘုရားလောင်းဆဒ္ဒန်ဆင်မင်းသည် ရေချိုးပြီးသော်ဘုရားလောင်းကိုယ်မှရေသည် တစက်စက်ယိုစီးကျ၍ မုဆိုး၏ကိုယ်ကိုထိ၏။”')
,(10772,3,4,'၃။ ရေခန်း ခြောက်ကုန်စၚ်အောင် ထုတ်သည်။','“သၟိၚ်ကဵုဗျတ်ကၠေံဍာ်ကၟာ—။” (ဇ—၁၅၉။ အစွောံ။) =“မင်းသည် ရေကန်ထဲမှရေကို ကုန်ခန်းအောင်ပယ်ထုတ်စေ၏။” || “ကောန်အဲဝွံကွေံ၊ တလှ်စှ်ေအာ။ ဟိုတ်ဂှ်ပိုဲသၟတ်၊ သာတ်ဗျတ်ဂၚ်ဂါ။ (ဂစေံဂး)” (လိက်ပဒုမဝတဳ) = “ငါ့ကလေးရေထဲကျသွားသောကြောင့် ငါတို့သည် ပင်လယ်ရေကို ခန်းခြောက်အောင် ခပ်ထုတ်ပစ်နေခြင်းဖြစ်သည်။ (ငှက်ဆို၏)”')
,(10772,3,4,'၄။ ဆန်းစစ်သည်။ သေသေချာချာစိစစ်သည်။','“အလုံလောကဳ (၃၁) ဘုံအိုဿီုခါဗျတ်ကၠေံတုဲ သ္အာၚ်အာနူဓဝ်နာံကဵုဓဝ်ရုပ်ဟၟဲရ။” (သၠပတ်အနမတဂ္ဂသံသာရကထာ) = “အလုံးစုံသော (၃၁) ဘုံကို သေချာစွာဆန်းစစ်လိုက်သောအခါ နာမ်တရားနှင့်ရုပ်တရားမှတစ်ပါး အခြားဘာမျှမရှိ။”')
,(10773,3,10,'(န) ဗျတ္တိ။ သတ္တိစွမ်းအား ပေါ်လွင်ထင်ရှားမှု။',NULL)
,(10774,3,11,'(န) ၁။ ဗျည်း။','‘ဗျန်မန်ပိဣသုန်မ။’ = ‘မွန်ဗျည်းသုံးဆဲ့ငါးလုံး’ || “ညံၚ်ဗၠဲဇ မန်၊ ဗျန်အက္ခရာ။” (လိက်ရတနပဇ္ဇောတ) = “ပုလဲကုံးကဲ့သို့သော ဗျည်းအက္ခရာအစီအကုံး။”')
,(10774,3,11,'(န) ၂။ ဟင်းလျာ။','“ဗၞတ်ပုၚ်မွဲဇန် ဗျန်မွဲပ္ၚာန်။” (ဓမ္မဒေသနာ။ မာံရွှေငိုး။) = “ထမင်းတစ်ဇွန်းဟင်းလျာတစ်ပန်းကန်။” || “သဗ္ဗစဏ၊ အဟာရဗျန်။” (လိက်ဇိဝှစက္က) = “အလုံးစုံသော အစာအာဟာရဟင်းလျာ။”')
,(10775,3,11,'(န) သံယုဂ်ဗျည်း။ သရအခြားမရှိသောဗျည်းတို့။ နှစ်လုံးဆင့်၊သုံးလုံးဆင့်ဗျည်း။','(ပါဠိ—သံယောဂ × ဗျဥ္ဇန)')
,(10776,3,4,'(အလင်းရောင်၊ အနံ့၊ အသံ၊ အရသာ၊ မေတ္တာတရား၊ ပီတိစသည်) နှံ့သည်။ ပျံ့နှံ့သည်။ လွှမ်းမိုးသည်။','“ပ္ကဴကက္ကာရုဂှ် အလုံဍုၚ်ဗာရာဏသဳ စှ်ၜါယောဇနာဂှ် မြမောဝ်ဗျာပ်ဒှ်အာမွဲရောၚ်။” (ဇ—၃၂၆။ အစွောံ။) = “ကက္ကာရုကနတ်ပန်း၏မွှေးရနံ့သည် တစ်ဆယ့်နှစ်ယူဇနာရှိသော ဗာရာဏသီမြို့အလုံးသို့ တစ်စပ်တည်းပျံ့နှံ့သွား၏။” || “လျးကျာ်တြဲအရဳယျဗျာပ်အာဗွဲလ္တူဒဵုဍုၚ်ဗြီု ဗွဲသၟဝ်ဒဵုနရက်အဝိက်ရ။ ပ္ဍဲဂၠးတိဝွံဂှ် ယးတၟးဒၟံၚ်ဟွံတီဗတံတ္ၚဲရ။” (အဓါန်မသုန်။အစွောံ။) = “အရိမေတ္တေယျမြတ်စွာဘုရား၏ ရောင်ခြည်တော်သည် အထက်ဗြဟ္မာပြည်အောက်အဝီစိငရဲတိုင်အောင် ပျံ့နှံ့လွှမ်းမိုးလိမ့်မည်။ ဤမြေပြင်­ နေ့မှန်းညမှန်းမသိအောင် လင်းထိန်နေလိမ့်မည်။” || “(ကြုက်ဂှ်) မၞုံကဵုရှ်ဒိပ် ရှ်ကြုက်ဂှ် ယာံဒွအ်ဒးလတာ်အဲတုဲ အလုံလတေၚ်ထပှ်လ္ၚီဂှ် ဗျာပ်အာတုဲ ဗျဵုတဟၚ်ဗၠးအိုတ်ရ။” (ဇ—၅၁၁။ အစွောံ။) = “ထိုသရက်သီးသည် နတ်သြဇာအရသာရှိ၏။ ထိုသရက်အရသာသည် ငါ၏လျှာဖျား­ထိသည်နှင့် အကြောပေါင်းခုနစ်ထောၚ်လုံးသို့နှံ့၍ မွတ်သိပ်ခြင်းသည် ပြေပျောက်ကုန်၏။” || “နရမျှာၚ်မဒဂူ တဝှ်ဓဝ်ဗောဓိသတ်မတွံကဵုဂှ် ဗြုလလောၚ်ဗျာပ်အာ ဗၞတ်စှ်ၜါယောဇနာရ။” (ဇ—၅၁၅။ အစွောံ။) = “သာယာစွာသောအသံဖြင့် တရားဟောသော ထိုဘုရားလောင်း၏အသံသည် တဆယ့်နှစ်ယူဇနာရှိသော အလုံးစုံသောဗာရာဏသီမြို့ကို လွှမ်းမိုး၏။” (ညောင်ကန်) || “(စဒးသတ်ဂျိဂှ်တုဲ) ဂျိဂှ်ဗျာပ်အာတုဲဒးပကာဂစိုတ်အိုတ်တုဲရ။” (ဇ—၈၅။ အစွောံ။) = “အဆိပ်သီးကိုစားမိ၍ ထိုအဆိပ်သည် ခန္ဓာကိုယ်တွင်းပျံ့နှံ့၍ သေရကုန်၏။” || “သၟိၚ်သီုဂၞကျာ် ညာတ်အသဝ်ဒါန်ဇကုအိုတ်ဂှ်တုဲ ပဳတိသ္ဍိုက်မၠိုက်ဗျာပ်အာအလုံဂၠံဟဒယရ။” (ဇ—၄၂၄။ အစွောံ။) = “မင်းရောမိဖုရားပါ မိမိတို့အလှူဒါန၏အံ့ဖွယ်ကိုမြင်၍ နှစ်သက်သောပီတိအဟုန်သည် နှလုံးဟဒယအလုံးသို့ နှံ့၍လွှမ်းမိုးသွား၏။” || “ယာံရဂွံညာတ်ကေတ်ရုပ်အဲဗက်ဂးကီုရ အလုံဟဒယသၟိၚ်မဂှ် ဇြဟာန်ဗျာပ်အာပ္ဍဲအဲရဂမှဳတံ။” (သၠပတ်သုရသာ) = “ငါ့ရုပ်လွှာကို မြင်လိုက်ရသည်နှင့် ငါ့ခမည်းတော်မင်းသည် ငါ­ချစ်ခြင်းနှံ့သွား၏။” || “သၟိၚ်တၠသဒ္ဓါ ဂွံမိၚ်ပရိုၚ်ဂွံဒှ်ဒဒှ်ကျာ် ဗၞးဂးတုဲ အလုံအဿဘဴဇကု ဒဵုက္ၜဝ်ဇုတ်ဗျာပ်အာရ။” (သၠပတ်အရုဒုမ္မ) = “သဒ္ဓါတရားရှင်မင်းသည် ဘုရားဖြစ်လတ္တံ့သော သတင်းစကားကိုပုဏ္ဏားပြော၍ ကြားရသည်ရှိသော် ခန္ဓာကိုယ်အလုံး ရိုးတွင်းခြၚ်ဆီအထိ နှံ့၍စိမ့်သွား၏။”')
,(10777,3,4,'ပျံ့နှံ့သည်။','“မြမောဝ်သဳလမ္ဂးဂှ် ဗျာပ်တရးအာ ဒစးကျာ ဗလောဲကျာ လမၞၚ်ကျာ ဇၟာပ်ဒိုဟ်အိုတ်သီုရောၚ်။” = “သီလတည်းဟူသောမွှေးရနံ့သည် လေညာ၊ လေကြေ၊ လေဖီလာ အရပ်ရပ်သို့ပျံ့နှံ့မွှေးကြိုင်၏။” || ‘တရးဗျာပ်’ နှင့်အတူတူ။')
,(10778,3,4,'ရွယ်သည်။ ချိန်ရွယ်သည်။ တည့်အောင်ထားသည်။','ဗျာံလဝ်ကဵုမြ = ဓါးနှင့်ခုတ်ရန်ရွယ်သည်။ || “မၞိဟ်မရပ်သၞာ်တၠညးဂှ် စၚိန်ဗျာံဒၟံၚ်သၞာ်ဂှ်—။” (ဇ—၂၆ဝ။ အစွောံ။) = “ဘုရင့်သန်လျက်ကို ကိုင်ထားသောလူသည် သန်လျက်ကို ပင့်ချီချိန်ရွယ်လျက်နေ၏။” || “သၞာ်ညးကဵုဗျာံလဝ်ကီုရ ဗၞုဟ်ညးကဵုထံၚ်လဝ်ကီုရ သမ္ဘာအဲဂှ်ဟွံဒိုအ် သ္ပာ်ကၠုၚ်ကဵုအဲဗိုန်ရ။” (ဇ—၂၉၇။ အစွောံ။) = “သန်လျက်ဖြင့် ချိန်ရွယ်ထားသည်ဖြစ်စေ၊ လှံဖြင့်ထောင်ထားသည်ဖြစ်စေ၊ ငါ၏မယားသည်မရပ်ဘဲ တိုးဝှေ့ဖြတ်သန်း၍ ငါ့ဆီသို့ အရောက်လာလိမ့်မည်။” || “ကၠဂှ် လုပ်စိုပ်ကၠိက်မဗျာံလဝ်ဂၞေဟ်ဂှ်တုဲ ဍေံတုက်သာ်ဒးသပါဂၞဴၜါလပါ်ရ။” (ဇ—၄၉၂။ အစွောံ။) = “ထိုကျားသည် အစွယ်ဖြင့်ချိန်ရွယ်ထားသော တောဝက်တို့ရှိရာသို့ ဝင်ရောက်သည်ရှိသော် တောဝက်တို့က အစွယ်ဖြင့်ထိုးခတ်ဖြဲသဖြင့် ကျား၏ဝမ်းဗိုက်သည် နှစ်ခြမ်းကွဲလေ၏။” || “ကောန်ဒေဝတဴမာတလိဗ္ဂေတ်ကၠေံကွဳဂှ်တုဲ ဗွဲဍုတ်အယဴကွဳဂှ် ဗျာံလဝ်ကဵုတရၚ်ရ။” (ဇ—၄၉၄။ အစွောံ။) = “မာတလိနတ်သားသည် ရထားကိုလှည့်လျက် ရထား၏နောက်အဘို့ကို တံခါးဖြင့်တည့်အောင်ထား၏။”')
,(10778,3,9,'ကြိယာ၊ နာမ်စသည်ကို ထောက်ပံ့သောစကားလုံး။','“ၜါစှ်ောကဝ်ဗျာံ၊ ပယျာံမူလ။” (လိက်လ္ၚောဝ်ကျာ်) = “ကပ်ကမ္ဘာနှစ်ဆယ်သောမူလကာလ။”')
,(10779,3,4,'၁။ငေးငိုင်သည်။ မိန်းမောတွေဝေသည်။','“ယွံတ္ၚေက်မၞုံသၟဴမသ္ကေက်တဴ၊ မူပဟွံဂ္ၚေၚ်အာဆုသ္အာၚ်တုဲ မဗျောံဒၟံၚ်ရော။” (ဇ—၄၂၉။ အစွောံ။) = “ချွန်သောနှုတ်သီးရှိသောကျေးသား၊ သင်သည် တစ်ပါးသောသစ်ပင်သို့ အဘယ်ကြောင့်မသွားမူဘဲ (ခြောက်သောသစ်ပင်­)ငေးငိုင်နေပါသနည်း။”')
,(10779,3,4,'၂။ (အရောင်) သန်းသည်။','“ယွံဒေံဗြဴ၊ ဒေံဗြဴမၞုံကဵုဒွက်သော်လမ္စံက်ဓယောံ ဗျောံဒၟံၚ်သာ်နဳလာဆာဲ။” (သုဓမ္မဒေသနာ။ ဂရိုက်သာံ။) = “အိုနှမငယ်၊ နှမငယ်သည် မည်းနက်ညိုမှိုင်းသော နီလာရောၚ်သန်းနေသော ဆံထုံးရှိ၏။”')
,(10780,3,4,'မိန်းမောတွေဝေသည်။ မူးမိုက်တွေဝေသည်။','“(မှောဝ်ရပ်ဂွံကၠေံတုဲ) ဇၟူဗျောံထၜိုမ်ဒၟံၚ် စံၚ်တူဒွိၚ်တဟး သြိုဟ်ညံၚ်ဒးဒကးအာၜါလွးကီု။” (ဇ—မဟောဟ်သဓ။ အစွောံ။) =“ဆင်ဆရာဖမ်းဆီးရမိလိုက်သဖြင့် ဆင်ပြောင်ကြီးသည် မူးမိုက်တွေဝေ ပူလောင်ခံစား စိုးရိမ်ပူပန်သည်ဖြစ်၍ ရင်နှစ်ခြမ်းကွဲအံ့သကဲ့သို့ရှိ၏။”')
,(10781,3,4,'ဆာသည်။','ဗျဵုပုၚ် = ထမင်းဆာသည်။ || “ကောန်ကၠဵုၜါဂှ် ဍေံဗျဵုစၞတုဲ ဍေံဗြုတိုန်ရ။” (ဇ—၄၁၆။ အစွောံ။) = “ခွေးသားငယ်နှစ်ကောင်သည် ဆာလောင်၍ အော်မြည်၏။”')
,(10782,3,4,'ရန်တိုက်ပေးသည်။ ကုန်းချောသည်။','“တြုံစၚးပိုဲမွဲဂှ် ဍေံဟီုဗျဵုပိုဲဍိက်အဴ။ ဍေံဗျဵုဟွံမာန်တုဲ ဍေံသ္ဍးအာကၠေံရအဴ။” (ဇ—၃၆၁။ အစွောံ။) = “တစ်ယောက်သောစားကြွင်းစားသည်တပည့်တော်တို့ကို ပြောဆိုကုန်းတိုက်၏။ ကုန်းတိုက်အံ့သောငှာ မတတ်နိုင်၍ ဖဲခွာသွား၏။”')
,(10783,3,4,'နှစ်ဦးအကြား ရန်တိုက်ပေးသည်။ ကုန်းချောသည်။','“ညးမွဲသ္အာၚ်ဂှ်စောန်စိုတ်ကဵုအမာတ်ဂှ်တုဲ ဍေံဟီုဗျဵုကဵုသၟိၚ်ရ။” (ဇ—၂၈၂။ အစွောံ။) = “တစ်ပါးသောသူတို့သည် ထိုအမတ်ကိုမနာလို၍ မင်းအားကုန်းတိုက်၏။” || “ယွံမရှာတ်၊ အသဒိသကုမာကောတၠအဲဂှ် သၟိက်တသိုၚ်ကေတ်ကၟိန်ဍုၚ်တၠအဲပၠန်ယး” သာ်ဝွံဍေံဟီုဗျဵုအကြာရ။ (ဇ—၁၈၁။ အစွောံ။) = “မင်းမြတ်၊ အရှင်၏နောင်တော် အသဒိသကုမာသည် အရှင်၏တိုင်းနိုင်ငံကို လုယူလိုပြန်သတတ်” ဟုကုန်းချော၏။ || “ဟီုဗျဵုနၚ်ဗျဵုဏာအကြာညး။” (ဇ—၂၈၇။ အစွောံ။) = “သူတစ်ပါးတို့အကြား­ ကုန်းချောရန်တိုက်ပေးသည်။” || “ဟိုတ်နူမဟီုဗျဵုတုဲ မိတ်မဆာန်ဂှ် မလီုအာရ။” (ဇ—၃၄၉။ အစွောံ။) = “ကုန်းချောခြင်းကြောင့် ချစ်သောအဆွေခင်ပွန်းသည် ပျက်ရ၏။”')
,(10784,3,4,'ဆင်စီးသူရဲချင်း စစ်ထိုးသည်။','“ဒကိုပ်ပၞာန်ဗၠာဲ မဗျဵုစိၚ်ကဵုညးဒှ်—။” (အကြီုရာဇာဓိရာဇ်) = “ရန်သူနှင့် ဆင်စီးချင်းစစ်ထိုးနိုင်သော စစ်သူကြီးပျို။” || ‘ဗဇဵုစိၚ်’ (ကြိ) နှင့်အတူတူ။')
,(10785,3,4,'(လူနှစ်ဦးနှစ်ဖက်အကြား) ချစ်ခြင်းကိုဖျက်သည်။ ကုန်းချောသည်။ ချောပစ်သည်။','“ဇၞော်ပဏတ်ကွေံသွံ။ ဟွံဂြၚ်ဂုန်ညးဟေၚ်သွံ။ ဗျဵုပလီုဇြဟာန်ညးရောၚ်သွံ။ ဒမြိုဟ်မဒြိုဟ်ကဵုမိတ်ရောၚ်သွံ။” (ဇ—၆၃။ အစွောံ။) = “အမျက်လည်း ထွက်တတ်ကုန်၏။ သူ့ကျေးဇူးကိုလည်း မသိတတ်ကုန်။ ချောပစ်ခြင်းကိုလည်း ပြုတတ်ကုန်၏။ အဆွေခင်ပွန်းကို ပြစ်မှားတတ်ကုန်၏။” (ညောင်ကန်) || ‘ဂလာန်မဗျဵုဇြဟာန်ညး။’ (ဇ—၆၃။ အစွောံ။) =‘သူတစ်ပါးအား ချောပစ်ချစ်ခြင်းဖျက်သောစကား။’')
,(10786,3,4,'သွေးဆာသည်။ (ဥပစာ) သတ်ဖြတ်လိုစိတ်ပြင်းပြသည်။',NULL)
,(10787,3,4,'ဆာလောင်မွတ်သိပ်သည်။ ဆာမွတ်သည်။','“အဲဍိက်ဗျဵုထၚ်လောန်—။” (ဇ—၁၅၄။အစွောံ။) = “အကျွန်ုပ်သည် ဆာမွတ်၏။” (ညောင်ကန်) || “အဲဗျဵုထၚ်လောန်၊ အဲစမရာတ်လၟုဟ်ရောၚ်” ကလော်ဂး။ (ဇ—၅၁၃။ အစွောံ။) = “ငါသည် အလွန်ဆာမွတ်၏။ သင်မင်းကြီးအား ယခုစားအံ့” ဟုဘီလူးဆို၏။')
,(10788,3,4,'ကုန်းတိုက်သည်။ ကုန်းချောသည်။ ချစ်ခြင်းကိုဖျက်သည်။',NULL)
,(10789,3,4,'စွပ်စွဲသည်။ သွားပုပ်လေလွင့်ပြောသည်။','“ဟာဲသေနာပတိဒမိက်၊ ကၠာတေံဗှ်ေကၠတ်စသဳဖဵုညးတုဲ ဗှ်ေဟီုဗျဵုဗျံက်တၠပညာရောၚ်သွံ” ညးဂမၠိုၚ်ဂး။ (ဇ—၂၂ဝ။ အစွောံ) = “ဟယ်တံစိုးစားတတ်သော ခိုးသူပျက်သေနာပတိ၊ သင်သည်တံစိုးစား၍ ပညာရှိကိုစွပ်စွဲ၏” ဟုလူအများဆိုကုန်၏။ || “ဍေံဂရိုဟ်ညး ဍေံဟီုပျုတ်ပျတ်ညး ဍေံဟီုဗျဵုဗျံက်ညး—။” (ဇ—နေမိ။ အစွောံ။) =“သူတစ်ပါးကို ကဲ့ရဲ့၏၊ သူတစ်ပါးကို နှိမ့်ချစော်ကား၏၊ သူတစ်ပါးကို ပြောဆိုစွပ်စွဲ၏။”')
,(10790,3,4,'ကုန်းချောသည်။ ကုန်းတိုက်သည်။','‘ပူဂဵုမလေပ်ဗျဵုလအက် ထပက်အကြာညးၜါ။’ = ‘လူနှစ်ဦးအကြား ခြေထိုးကုန်းတိုက်တတ်သောသူ။’ (ပါဠိ—ပေသုည)')
,(10791,3,4,'ကုန်းချောသည်။ ကုန်းတိုက်သည်။','“သေနာပတိဝွံ ဍေံဟီုဗျဵုသ္ဍက်အဲရောၚ်” သၟိၚ်ဂး။ (ဇ—၂၂ဝ။ အစွောံ) = “ဤသေနာပတိသည် ငါ့ကိုကုန်းချော၏” ဟုမင်းဆို၏။ || “ဂလာန်ဗျဵုသ္ဍက်မ္ဂးဂှ် မတုပ်တဴရဴဗၞုဟ်ဇမ်ကေက်ကီု—။” (ဇ—၃၄၉။ အစွောံ။) = “ကုန်းတိုက်သောစကားမည်သည်ကား ထက်စွာသောသန်လျက်ဖြင့် ထိုးခုတ်သည်နှင့်တူ၏။” (ညောင်ကန်)')
,(10792,3,4,'(အရောင်) ဖျော့မှိန်သည်။ (ရနံ့) လျော့ပါးသည်။ (အရသာ) ပေါ့ပျက်သည်။','“အရံၚ်ဗျဟ်အာရ။” = အရောင်ဖျော့မှိန်သွားသည်။ || “ပ္ကဴဂှ် သၟူဗျဟ်အာရ။” = “ပန်းသည် ရနံ့လျော့သွားပြီ။” || “သွဂှ် စုတ်ဒးဍာ်ဂၠိုၚ်အာတုဲ ရှ်ဟွံမွဲဗျဟ်အာရ။” = “ရေထည့်များသောကြောင့် ဟင်းသည် အရသာပေါ့ပျက်သွားသည်။”')
,(10793,3,4,'ညွတ်ချသည်။ ညွတ်ကျစေသည်။ နှိမ့်သည်။','ဗျအ်က္ဍိုပ်၊ ဗျအ်ကၞိပ် = ဦးညွတ်အလေးပြုသည်။ ဦးခေါင်းကိုနှိမ့်ချသည်။ || “ညံၚ်ဗီုကြဝိတ်ထဝ် — ဗျအ်သၞေၚ်ဖျေၚ်သၟဴတုဲ ညံၚ်မဂြဴတာၚ်ဖအဝ်ဒၟံၚ် ပ္ဍဲဂြိုပ်စံပလံဂှ်ကီု။” (ဇ—ဝိဓုရ။ အစွောံ။) = “ရွှေကရဝိတ်သည် တောင်ပံကိုချနှုတ်သီးကိုလှည့်ချီလျက် စွန်ပလွံတော­ သာယာစွာတွန်ကျူးနေဘိသကဲ့သို့။” || “သီုမသိပ်ဇၟအ်၊ဗျအ်က္ၜံၚ်တိတ်အာ။” (လိက်ဇိဝှစက္က) = “သေသပ်စွာဒူးကိုနှိမ့်လျက် ထွက်သွား၏။” || “ဖျေံက္ဍိုပ်မအ်ဂြအ်၊ ဗျအ်က္ၜံၚ်အောပ်မာ။” (လိက်ဇိဝှစက္က) = “ဦးချအရိုအသေပြု၍ ဒူးကိုနှိမ့်ကာဝပ်တွားသည်။” || “အဲဍိက်လ္ၚောဝ်၊ ဗျအ်ဖျဝ်ကာယ။” (လိက်ဂါထာလ္ၚောဝ်ကျာ်) = “ကိုယ်ကိုညွတ်ချနှိမ့်ချ၍ ကျွန်ုပ်ရှိခိုးပါ၏။” || ‘မသက္ကုဗျအ်’ (ကြိ) လည်းရှု။')
,(10794,3,1,'သင်းကျစ်။ နဖူးစည်းတန်ဆာ။ (ပါဠိ—ဥဏှဳသ)','“ဗောဓိသတ် (သၟိၚ်ပဒုမ) သလိုက်ၝောံကိုတ်၊ ဗြကၞေၚ်၊ ဗသေၚ်၊ တဝ်စရှ်တုဲ—။” (ဇ—၁၉၃။ အစွောံ။) = “ဘုရားလောင်းပဒုမမင်းသည် မကိုဋ်၊ နဖူးတန်ဆာ၊ သရဖူ၊ ဦးဆောက်ပန်းတို့ကို တန်ဆာဆင်ယင်ပြီးသော်—။” || “ဥဏှဳသံ၊ ပွမသၠိုက်လဝ်ဗြကၞေၚ်ကီု။” (တြာဲသုတ်သဳလက္ခန်။ ဝိန္ဒသာရ။) = “သင်းကျစ်ကိုဝတ်ထားခြင်း။”')
,(10795,3,1,'ပုဏ္ဏား။','‘ဗမၞး’ နှင့်အတူတူ။')
,(10796,3,4,'ကြမ်းတမ်းသည်။ မညီမညာဖြစ်သည်။',NULL)
,(10797,3,4,'ပေါများသည်။ ပွားများသည်။ တိုးများသည်။','“ပွမဗြဳဗြော်ကဵုကောန်ဇာတ်စဴစေက်ဂမၠိုၚ်—။” (တြာဲအလၚ်္ကာ) = “သားသမီးမြေးမြစ်များ ပွားများခြင်း။” || ‘ဗြေဝ်ဗြော်’နှင့်အတူတူ။')
,(10798,3,4,'အသံမြည်သည်။','“သၟိၚ်ဂစေံဝွံဂှ် ဂေါဝ်ဆာဲလောန်က္ဍၚ်သန်၊ ဗြုမိပ်လောန်က္ဍၚ်သန်။” (ဇ—၃၃၉။ အစွောံ။) = “ဤငှက်မင်းသည် အလွန်လျှင်တင့်တယ်လှပ၏။ အလွန်လျှင်နာပျော်ဖွယ်တွန်ကျူး၏။” || “ၚဴက္ဍိုပ်ဒဵုဗြုတိုန်ရ။” (ဇ—၃၅၇။ အစွောံ။) = “တောင်ထိပ်မှဖားသည် အော်မြည်၏။”')
,(10799,3,4,'(လူအများအသံဖြင့်) ဆူညံသည်။','“မၞိဟ်အလုံဍုၚ်ဝေၚ်သဘၚ် ဗြုကၠံၚ်တမ္ညဝ်ဒၟံၚ်ရ။”= “မြို့အလုံးမှလူများ ပွဲသဘင်ကစားကြရာ အုတ်အော်သောင်းတင်းဆူညံနေ၏။”')
,(10800,3,4,'တွန်မြည်သည်။','“ဇရေၚ်ဇိုၚ်လှာ၊ စာၚ်ဍာ်ဗြုကွက်။ အဍေဝ်ဂြဴကီု၊ သီုစက္ကဝက်။” (လိက်ကကၠာ်။ ကောန်ဍး။) = “ရေအိုင်အနီး­ ရေကြက်တွန်မြည်၏၊ တောကြက်နှင့်စက္ကဝက်လည်းတွန်ကျူး၏။”')
,(10801,3,4,'(လက်ကောက်အချင်းချင်း ထိခတ်သောအခါကဲ့သို့) အသံမြည်သည်။ ခရင်းခရင်းမြည်သည်။','“ပ္ဍဲတဲမွဲလကံက်ၜါဂှ် ကာလဍေံမဂုံတဴဂှ် ဍေံသ္ဍဳလယတ်ရၚ်သ္ကံတုဲ ဍေံဗြုခမြေၚ်တဴရ။” (ဇ—မှာဇနက်။ အစွောံ။) = “လက်ကောက်နှစ်ကွင်း ဝတ်ထားသောလက်သည် ဆန်ပြာကစားသောအခါ လက်ကောက်အချင်းချင်းထိခတ်၍ ခရင်းခရင်းအသံမြည်၏။”')
,(10802,3,4,'မြည်ဟည်းသည်။ ထစ်ချုန်းသည်။ ထစ်ကြိုးသည်။','“တိဗြုဂဟဳ၊ ၜဳဒှ်ယဝီု။ မှာသမိတ်တြအ်၊ ဒဵုတၟအ်အိုဿီု။ ဂရိုက်ဂရာၚ်၊ ကဵုရမျှာၚ်ကြီု။” (လိက်ပထမဗောဓိ။ မၚ်ဍိက်လ။) =“မြေကြီးသည် မြည်ဟည်းထစ်ကြိုး၍ အလုံးစုံသော ပင်လယ်သမုဒ္ဒရာနှင့် ကျောက်တောင်တို့သည် ဘောင်ဘၚ်ခတ်တုန်လှုပ်ကုန်လျက် သည်းစွာအသံပေး၍ ကြုံးဝါးနေကုန်၏။”')
,(10803,3,4,'မြည်ကြွေးသည်။ သာယာစွာမြည်သည်။','“ဂစေံဂြိုပ်ပၠန်၊ ဂၠိုၚ်သန်ဗြုၚာဲ။ စာၚ်ဍေဝ် မြာ်ထဝ်၊ ဗီုဂတဝ်သာဲ။” (လိက်ပ္တံပါရမဳ။ အစွောံ။) = “တောငှက်တို့သည် အသံမျိုးစုံစွာဖြင့် မြည်ကြွေးကြကုန်၏။ တောကြက်နှင့်ရွှေဥဒေါင်းတို့၏ အသံသည်လည်း ပျားသကာကဲ့သို့ချိုသာ၏။”')
,(10804,3,4,'(ခေါင်းလောင်းစသည်ကဲ့သို့) မြည်သည်။','“ခနှိၚ်သၠဇြဲမဗြုစမြေဲဒၟံၚ်။” (အာန်ဇုနာန်) = “ညောင်ရွက်ပုံခေါင်းလောင်းသံ မြည်နေသည်။”')
,(10805,3,4,'မြည်ဟည်းသည်။ ခြိမ့်ခြိမ့်သဲမြည်သည်။','“ဖံကၠေဝ်ဖံမန်၊ ဗြုဇရန်က္ဍၚ်။” (လိက်ဗြရတ်ဣဏၚ်ကၚ်ရဳ) = “တမီကုလားစည်နှင့် မွန်စည်တို့သည် ခြိမ့်ခြိမ့်သဲမြည်ကုန်၏။”')
,(10806,3,4,'အော်မြည်သည်။','“(ဒြာဲဂှ်ဒးဒၞက်လၟတုဲ) ညံၚ်အၚဝ်မချိုတ်ဂှ်ပတုဲ ရုဲကၠံၚ်ဗဗဵုတဴရ။ ခဍာ်လေဝ် ကၠုၚ်ဗြုတမာဲတဴရ။” (ဇ—၁၆။ အစွောံ။) = “ထိုသမင်သည် မုဆိုးကျော့ကွင်း­မိ၍သေဟန်ကိုပြု၍ ယၚ်ကောင်များဝိုင်းအုံဆူညံလျက် ကျီးတို့သည်လည်းလာ၍ အော်မြည်ကြကုန်၏။” || “ထိုၚ်သာဲအဒဲါ၊ ဗြုတမာဲကၠံၚ်။” (လိက်သၟိၚ်ဇဲယဒတ္တ) = “ပိတုန်း၊ ပျား၊ လိပ်ပြာတို့သည် အော်မြည်ဆူညံနေ၏။”')
,(10807,3,5,'တဖွဲဖွဲ။ တဖြုတ်ဖြုတ်။','“ကၞာၚ်ဆုၜါဂှ် ဒးကျာတုဲ ဂရိတ်ဗုတ်ရၚ်သ္ကံရ။ ကနှိက်ဆုဂှ်ဗြုဗြုတိတ်ဗဝ်ဒၟံၚ်။” (ဇ—၃၆။ အစွောံ။) = “သစ်ခက်နှစ်ခုတို့သည် လေထိ၍ အချင်းချင်းပွတ်တိုက်ကြကုန်၏။ သစ်မှုန့်တို့သည် တဖွဲဖွဲကျ၍ စုပုံနေ၏။”')
,(10808,3,4,'အသံမြည်သည်။ ကျယ်လောင်စွာမြည်သည်။','“(ပ္ဍဲနန်ပြာသာဒ်သၟိၚ်ဂှ်) နရမျှာၚ်တွိၚ်တွိုက်သဒ္ဒါရီုတံဂှ် လလောၚ်ဂမ်အတ်တဴ ညံၚ်အသံဂၞဴမှာသၟိတ်ကီု အသံဗရုမွဲဂှ် ဗြုဗြန်တဴအိုတ်ရ။” (ဇ—၁၃၂။ အစွောံ။) = “သီချင်းသံ၊ တီးမှုတ်သံဖြင့် မင်း၏နန်းတော်သည် မိုဃ်း၏ထစ်ကြိုးသံဖြင့်ပြည့်သော မဟာသမုဒြာဝှမ်းကဲ့သို့ တပြိုၚ်နက်တချက်တည်း အုတ်အုတ်ကျက်ကျက်ဖြစ်၏။” (ညောင်ကန်)')
,(10809,3,4,'ပဲ့တၚ်ထပ်မျှမြည်သည်။','“(ဗရုတွိၚ်ထဏဗောဓိသတ်ဂှ်) ရဴတွိၚ်ကောန်ဒေဝတဴဂန္ဓဗ္ဗကီု ဗြုလလောၚ်တဴရ။” (ဇ—၂၄၃။ အစွောံ။) = “ဘုရားလောင်း၏စောင်းသံသည် ဂန္ဓဗ္ဗနတ်သား၏စောင်းသံကဲ့သို့ ပဲ့တၚ်ထပ်မျှမြည်၏။”')
,(10810,3,4,'ပြိုကွဲသည်။ ကစဉ့်ကလျားဖြစ်သည်။','“ဗောဓိသတ်ကဵုရမျှာၚ်ဇမၞး ပၞာန်ထပှ်မုက် ဗြူပေက်အာရ။” (ဇ—မဟောဟ်သဓ။ အစွောံ။) = “ဘုရားလောင်းသည် အောင်သံဟစ်ကြွေးသည်ရှိသော် ခုနစ်မျက်နှာသောရန်သူ့စစ်သည် ကစဉ့်ကလျားပြိုကွဲသွား၏။” || “သရာဲတအ်ပ္ညုၚ်၊ ညးဍုၚ်ပည္စာ။ ဝဲယဒတ္တ၊ ဟိုတ်မချိုတ်အာ။ ရုဒှ်တိုန်ကၠာ၊ ဗြူပေက်အာဟေၚ်။” (လိက်ဝါရဝေါၚ်သ။အစွောံ။) = “ပဥ္စာတိုင်းသားသူရဲတို့သည် ဝဲယဒတ္တသေသွားသောကြောင့် ရုတ်ရုတ်သဲသဲဖြစ်ကာကစဉ့်ကလျားပြိုကွဲသွား၏။”')
,(10811,3,5,'ကစဉ့်ကလျား။','“ဗြူဗြူသရာဲသၟိၚ်စူဠဏဳ မဒးဒြေပ်ပေက်အာရ။” (ဇ—မဟောဟ်သဓ။ အစွောံ။) = “စူဠဏီမင်း၏သူရဲတို့သည် ကစဉ့်ကလျား ထွက်ပြေးပြိုကွဲကုန်၏။”')
,(10812,3,5,'တဖြုတ်ဖြုတ်။','“ဍာ်ရမတ်မတုပ်တဴ ရဴဗြဲမခတုံဗြူဗြူ နူအမှဲကီုမဒှ်။” (အကြီုရာဇာဓိရာဇ်) = “မျက်ရည်တို့သည် ကောင်းကင်မှ တဖြုတ်ဖြုတ်ကျသော မိုးပေါက်များပမာဖြစ်၏။” || “ညံၚ်ကဵုဗြဲဂူ၊ ဗြူဗြူစှ်ေကၠုၚ်။” (လိက်မိဍောၚ်ကှ်ေထဝ်) = “မိုးရွာဘိသကဲ့သို့ တဖြုတ်ဖြုတ်ကျလာ၏။”')
,(10813,3,1,'မိုး။','ဗြဲဂူ၊ ဗြဲဗ္ဂူ = မိုးရွာသည်။ || ‘ဗြဲဇၞော်ဂူဟွံတီဍး။’ = ‘စဲရမှန်းမသိရွာသောမိုး။’')
,(10814,3,1,'မိုးလေဝသအခြေအနေ။',NULL)
,(10815,3,4,'မိုးလေဝသအခြေအနေ ကောင်းသည်၊ သာယာသည်။',NULL)
,(10816,3,1,'ပေါက္ခရဝဿမိုး။ စွတ်စိုစေလိုသူကို စွတ်စိုစေ၍ မစွတ်စိုစေလိုသူကို မစွတ်စိုစေသော ကွက်ကြားမိုး။',NULL)
,(10817,3,1,'မိုးသီး။','ဗြဲပၠဳဂူ = မိုးသီးကြွေသည်။ (ပါဠိ—ကရကဝဿ)')
,(10818,3,1,'မျက်ရည်မိုး။ (ဥပစာ) အလွန်အမင်းငိုကြွေးရခြင်း။','“ဗြိုဟ်ဗြိုဟ်ဗြဲမတ်၊ ဍာ်ရမတ်ဇွောဝ်။” (လိက်ကောန်သၟိၚ်ပိ။ မာံခစုန်အံက်။) = “မျက်ရည်မိုးဖြိုင်ဖြိုင်ဖြင့် မျက်ရည်ယို၏။”')
,(10819,3,4,'မိုးကွင်းသည်။ မိုးကွက်သည်။',NULL)
,(10820,3,1,'၁။ (လူ) အမျိုးသမီး။ မိန်းမ။','သၟတ်ဗြဴ = သူငယ်မ။ မိန်းမငယ်။ || ညးဗြဴ၊ မၞိဟ်ဗြဴ =မိန်းမ။ || ခံါသဳဗြဴ = ယောက္ခမမိန်းမသူ။')
,(10820,3,1,'၂။ ဇနီးမယား။ မိန်းမ။','ဗြဴအဲ = ကျွန်တော်၏မယား။ ကျွန်တော်၏ဇနီး။')
,(10820,3,1,'၃။ (တိရိစ္ဆာန်) အမ။','‘ဒြာဲဗြဴ’ (ဇ—၁၂။ အစွောံ။) = သမင်မ။ || “ကကၟက်ကဵုကဗြဴဂ္ၚေၚ်အာ။” (ဇ—၂၁၆။ အစွောံ။) = “ငါးဖိုနှင့်ငါးမတို့ လှည့်လည်သွားလာ၏။” || “ပ္ဍဲဇရေၚ်ဂြိုပ်ဒုန် မညန်ကဵုအဿမာပိုတ်ဂှ် ဖရာပ်ကၟက်ကဵုဖရာပ်ဗြဴၜါ မတဴလၟိုန်ရ။” (ဇ—၄၉ဝ။ အစွောံ။) = “ကျောင်းသင်္ခမ်းအနီးရှိဝါးတော­ နှစ်ခုကုန်သောခိုဖိုနှင့်ခိုမတို့သည် အမြဲနေကြ၏။”')
,(10821,3,1,'ဇနီးမယား။',NULL)
,(10822,3,1,'အမျိုးကောင်းသမီး။ (ပါဠိ—ကုလဓဳတာ)',NULL)
,(10823,3,1,'အပျိုတော်။ နန်းတွင်းသူ။',NULL)
,(10824,3,1,'မုဆိုးမ။','“အဲဒှ်တဴဗြဴကၟာဲမ္ဂးဂှ် သီုဒဒိုက်အဲမဒးဒၟံၚ်တဴရ။” (ဇ—၄၁၇။ အစွောံ။) = “ငါမုဆိုးမဖြစ်လျှင် ဆင်းရဲစွာနေရတော့မည်။” || “မိမွဲပူဆာ၊ တြုံသ္ၚိခြာအဴ။ မိဒးယုတ်မတ်၊ သွတ်စိုတ်ရအဴ။ ဒဒိုက်ဗြဴကၟာဲ၊ ကာဲကၞာဲတဴ။” (လိက်စိတ္တကုမ္မာ) = “မယ်တစ်ကိုယ်တည်း လင်ယောကျ်ားနှင့်ကွဲကွာ၍ မပြည့်စုံချို့တဲ့ကာ အားငယ်သိမ်ငယ်နေရ၏။ မုဆိုးမ၏ဒုက္ခသည် အလွန်ဆင်းရဲလေစွတကား။”')
,(10825,3,1,'တစ်ခုလပ်။ တစ်လင်ကွာမိန်းမ။',NULL)
,(10826,3,1,'မယားငယ်။ အပျော်မယား။','“ကာလတီတဴ၊ ဒှ်ဒၟံၚ်ဗြဴကျာ။ ပတိပတ်လုတ်၊ ဒှ်ဗြဴယုတ်မာ။ ဂွံတြုံကျာအဴ၊ ဗတံဒဴအာ။” (လိက်သၟိၚ်ဇဲယဒတ္တ) = “သိရသောအခါ အပျော်မယားဖြစ်နေ၏၊ အကျင့်မှားသော မိန်းမယုတ်ဖြစ်၏၊ အပျော်လၚ်ကိုရ၍ ညအခါပြေးရှောင်သွား၏။”')
,(10827,3,1,'သားမဖွားသောအမြုံမ။',NULL)
,(10828,3,1,'မိန်းမယုတ်။',NULL)
,(10829,3,1,'ပြည့်တန်ဆာမ။ ပြည်ကြီးတန်ဆာ။','“(ဂွါကၟက်ကအ်ဂှ်) အဲဍိက်စုတ်လဝ် ပ္ဍဲတဲဗြဴစရာဲဍုၚ်ရအဴ” သမာကွိၚ်ဂးတုဲ ကော်ဗြဴသရာဲဍုၚ်သၟာန်ရ။ (ဇ—၉၂။ အစွောံ။) || “သဟာဲကောန်သေဋ္ဌဳဂှ် အာကေတ်နၚ်ဗြဴကျာ်သြဳဍုၚ်မွဲ မၞုံကဵုရုပ်သာ်ကျာ်သြဳဂေါဝ်ဂပ်လောန်—။” (ဇ—၁၁၈။ အစွောံ။) = “သူဋ္ဌေးသား၏မိတ်ဆွေသည် ရုပ်အဆင်းအသရေနှင့် ပြည့်စုံသော တစ်ယောက်သောပြည့်တန်ဆာမကို သွား၍ခေါ်ဆောင်လာ၏။” || “ဗြဴသရာဲဍုၚ်မွဲဂှ်သုလသာဂးယၟု။” (ဇ—၄၁၉။ အစွောံ။) = “သုလသာအမည်ရှိသော ပြည့်တန်ဆာမသည်—။” (ညောင်ကန်)')
,(10830,3,1,'မူလမယား။ ငယ်မယား။','“ဗြဴဝွံ မဒှ်ဗြဴတၞံအဲရ။” = “ဤမိန်းမသည် ငါ၏ငယ်မယားမူလမယားတည်း။”')
,(10831,3,1,'အိမ်ရှင်မ။ အိမ့်ရှင်မ။ (ပါဠိ—အဂါရိကာ)',NULL)
,(10832,3,1,'နတ်ကတော်အမျိုးသမီး။ နတ်ဝၚ်မ။',NULL)
,(10833,3,1,'မိန်းမယုတ်။',NULL)
,(10834,3,1,'ကလေးထိန်း။ သူနာပြုအမျိုးသမီး။',NULL)
,(10835,3,1,'သီလရှင်။',NULL)
,(10836,3,1,'စည်းစိမ်ရှင်မိန်းမ။ အထက်တန်းအမျိုးသမီး။ ဂုဏ်ကြီးရှင်မိန်းမ။','“လာပ်မိဗြဴယာန်၊ ဍုၚ်ကွာန်တံဂှ်။ အဲဟွံကေတ်ရ၊ ကာလလၟုဟ်။” (လိက်သၟိၚ်စိၚ်ဆဒ္ဒန်။ နာဲထဝ်စိုပ်။) =“စည်းစိမ်ရှင်မထံမှ ဆုလာဘ်ဖြစ်သောမြို့ရွာတို့ကို ယခုငါမယူလိုတော့ပြီ။” (သောနုတ္တရမုဆိုးကြံ၏။) || “စံၚ်နှာပ္ဍဲစိုတ်၊ ဟိုတ်နူဗြဴယာန်။” (လိက်ဗြရတ်ဣဏၚ်ကၚ်ရဳ) = “ဂုဏ်ကြီးရှင်မိန်းမကြောင့် စိတ်ပူပန်ခံစားရ၏။”')
,(10837,3,1,'၁။ (စကြဝတေးမင်း၏) မိန်းမရတနာ။ မိဖုယားရတနာ။','“ကျာ်တြဲဂှ် ဗတ်ရဣတေံတဴပ္ဍဲသ္ၚိကၟိန်ဂှ် ဒှ်စက္ကဝဝ်ရောၚ်။ ရာဟုလလေဝ် ဒှ်ပရိနာယကရတ်ရ။ ဘိမ္မာလေဝ် ဒှ်ဗြဴရတ်ရ။” (ဇ—၂၈၁။ အစွောံ။) = “သဗ္ဗညုမြတ်စွာဘုရားသည် အကယ်၍အိမ်­နေငြားအံ့၊ စကြဝတေးမင်းဖြစ်လတ္တံ့။ ရာဟုလာသာမဏေသည် သားကြီးရတနာဖြစ်လတ္တံ့။ ယသောဓရာထေရီမသည် မိန်းမရတနာဖြစ်လတ္တံ့။” (ညောင်ကန်)')
,(10837,3,1,'၂။ ရတောင့်ရခဲ ရတနာကဲ့သို့ အဖိုးတန်သောမိန်းမ။ ရတနာမယ်။','“ဒၞာဲညးမဂံၚ်စၞေဟ်ကဵုသၟိၚ်ကလိၚ်ဂှ် ဗြဴရတ်ပန်ဝွံ ဂိုၚ်လဝ်ရ။” (ဇ—၃ဝ၁။အစွောံ။) = “ကာလိၚ်္ဂမင်းနှင့်တကွ စစ်ထိုးခြင်းငှာဝံ့သောသူသည် ဤရတနာမယ်လေးယောက်တို့ကို သိမ်းယူထားပေလော့။”')
,(10838,3,1,'မြှောက်စားခံရသူ အထက်တန်းအမျိုးသမီး။ မိန်းမကောင်းမိန်းမမြတ်။','“စှ်ေစိုပ်တိတုဲ၊ ဗြဴလွုဲကညာ။ လ္ၚောဝ်ရတ်ပိ၊ မိမအစာ။” (လိက်သၚ်ဂဒါ။ သဳလဝန္တ။) || “မသုန်ကၠံဟေၚ်၊ကုန်ကွရေၚ်တုဲ။ ဝဳဝတ်ပတ်ပေါန်၊ မိကောန်ဗြဴလွုဲ။” (လိက်ပတ္တစာရဳ။ နာဲထဝ်စိုပ်။) = “ငါးရာကုန်သောကျေးကျွန်တို့သည် မြတ်သောသတို့သမီးငယ်ကို ပြုစုလုပ်ကျွေးကုန်၏။”')
,(10839,3,1,'အပျိုမ။ အပျိုစၚ်။',NULL)
,(10840,3,1,'သားမဖွားသောအမြုံမ။',NULL)
,(10841,3,1,'‘ဗြဴစရာဲဍုၚ်’ ရှု။',NULL)
,(10842,3,1,'နူးညံ့သိမ်မွေ့သောအမျိုးသမီး။',NULL)
,(10843,3,1,'မိန်းမကောင်းမိန်းမမြတ်။ ဘုန်းရှင်မိန်းမ။','“ကောန်ရသိနာၚ်၊ ဗြဴသာၚ်ဂကူ။” (လိက်သၟိၚ်ဇဲယဒတ္တ) = “အမျိုးမြတ်သော ဘုန်းရှင်မိန်းမကောင်းဖြစ်သော ရသေ့သမီး။”')
,(10844,3,1,'နတ်သမီး။',NULL)
,(10845,3,1,'ဖါသည်မ။',NULL)
,(10846,3,1,'အဖိုးတန်သောမိန်းမ။ မိန်းမကောင်း။',NULL)
,(10847,3,1,'မယားငယ်။','‘ဒေပ်ဗြဴအဗၠံက်’ (ကြိ) လည်းရှု။')
,(10848,3,1,'ပြည့်တန်ဆာမ။',NULL)
,(10849,3,1,'ကြာသပတေး။','တ္ၚဲဗြဴပတိ = ကြာသပတေးနေ့။ || ဂြိုဟ်ဗြဴပတိ = ကြာသပတေးဂြိုဟ်။')
,(10850,3,4,'၁။ အသီးများကြွေကျပျက်စီးသည်။','“ခတောဲကြုက်တံဂှ် ဗြံအိုတ်ရ။” = “သရက်သီးအကင်းများ မအောင်ဘဲကြွေကျပျက်စီးကုန်ပြီ။” || “ညံၚ်သတ်ကြုက်ကီု၊ ဗီုပမာဏ။ ဗြဲကျာဟွံဓဝ်၊ ပမှောဝ်ကၞာၚ်သၠ။ ကဴတုဲဗြံအာ၊ ဂၠိုၚ်ကဵုဝါရ။” (လိက်တလိၚ်ပန်) = “သရက်သီးကဲ့သို့ ပမာတူ၏၊ မိုးလေမမှန်၍ အဖူးအရွက်တို့မှသည် ပန်းပွင့်ပြီးနောက် ကြိမ်ဖန်များစွာ အသီးကင်းများပျက်ကြွေကုန်၏။”')
,(10850,3,4,'၂။ ထိစပ်သည်။','“သတ်ကဵုသတ်ဗြံ၊ တၞံကဵုတၞံကာန်။” (လိက်မာဃဒေဝါန်) = “အသီးအသီးချင်းထိစပ်၍ အပၚ်အပၚ်ချင်းပူးကပ်သည်။”')
,(10850,3,4,'၃။ (လှေသင်္ဘော) နစ်မြုပ်သည်။ မှောက်သည်။','ဂၠုၚ်ဗြံ = လှေမှောက်သည်။ လှေနစ်သည်။ || “ညံၚ်မၞိဟ်မဗြံက္ၜၚ်ဒေါဝ်မှာသၟိတ်—။” (ဇ—၃၅၃။ အစွောံ။) = “သမုဒ္ဒရာလယ်­ သင်္ဘောမှောက်သောလူကဲ့သို့။” || ‘ဂၠုၚ်ဂှ် ဗြံဗကပ်အာ။’ (ဇ—၄၇၈။ အစွောံ။) = ‘ထိုလှေမှောက်၍နစ်သွား၏။’')
,(10851,3,4,'ကုန်းကြည်း­ပၚ် ဒုက္ခတွေ့သည်။','“ပြးအာဗြံတိုက်၊ ဒဒိုက်ဂၠိုၚ်ရာ။” (လိက်ကောန်သၟိၚ်ပိ။ မာံခစုန်အံက်။) = “ကုန်းကြည်း­ပၚ် ကွဲကွာသွား၍ ဒုက္ခအမျိုးမျိုးကြုံရ၏။” || “ဗြံက္ၜၚ်ဟွံပြး၊ ဗြံတိုက်ပြးအာ။” (လိက်ကောန်သၟိၚ်ပိ။ မာံခစုန်အံက်။) = “သင်္ဘောမှောက်၍မကွဲကွာဘဲ ကုန်းကြည်း­ပၚ် ဒုက္ခတွေ့၍ ကွဲကွာသွားရ၏။”')
,(10852,3,4,'ဒုက္ခပင်လယ်­နစ်မြုပ်သည်။ ဒုက္ခပင်လယ်ဝေသည်။ အကြီးအကျယ်ဒုက္ခတွေ့သည်။','“(ဍိက်သၚ်ခသေဋ္ဌဳတြေံတံဂှ် ဟွံဒက်စိုတ်ကဵုတၠ) ညာတ်တၠမဗြံဒဒိုက် ဂိုၚ်ဟံၚ်ဆာဲကဵုဨကရာတ်ရ။” (ဇ—၁၃၁။ အစွောံ။) = “သၚ်္ခသူဋ္ဌေး၏ကျွန်ဟောင်းတို့သည် သခင်­ရန်ငြိုးမထားဘဲ သခင်ဒုက္ခပင်လယ်ဝေသည်ကိုမြင်သော် ဘုရင့်ထံပို့ဆောင်၍ ကယ်တင်၏။”')
,(10853,3,3,'(အရိပ်) ကျဲသော။ ကျဲကျဲ။','သမၞိၚ်ဗြးဗြး = ကျဲသောအရိပ်။')
,(10854,3,4,'ပြည့်နှက်သည်။ ပြန့်ကြဲသည်။','“(မၞိဟ်အလုံနန်ဂှ် ကလော်ဗြဴတံဂှ် စထောံကၠေံအိုတ်သ္အး) ဆဇုတ်မကိုဟ်ဗြးဗြော်ဒၟံၚ် အလုံနန်ရ။” (ဇ—၉၆။ အစွောံ။) = “နန်းတော်အလုံးရှိလူများအားလုံးကို အကုန်အစင် ဘီလူးမများစားပစ်လိုက်၏။ နန်းအိမ်အလုံး­ အရိုးများသာဖြူလျက် ပြည့်နှက်ပြန့်ကြဲနေ၏။” || “သၟန်သၞံၚ်နက်သတ်မဗြးဗြော်ဒၟံၚ်ဂှ်။” (အာန်ဇုနာန်) = “ပြည့်နှက်နေသော ကြယ်နက္ခတ်တာရာများ။” || “ကောံဘိက္ခုသၚ်၊ မက္ဍၚ်အဒ္ညာ။ တဝဳဗဝိုၚ်၊ ဗြးဗြော်ရိုၚ်ဗ္ဂာ။” (လိက်ပထမဗောဓိ။ မၚ်ဍိက်လ။) = “အကြားအမြင်များကုန်သော ဘိက္ခုသံဃာတော်များသည် (မြတ်စွာဘုရားအား) ပြည့်နှက်စွာခြံရံနေကုန်၏။”')
,(10855,3,5,'ရုတ်တရက်။ ရုတ်ချည်း။ ဝက်ခနဲ။ (ကွဲသည်) ။','“မိၚ်ဗရုဍေံ၊ ချေံကဆဟ်ဗက်။သြိုဟ်ဒကးဗြက်၊ ကၞုဝက်ဇၞး။” (လိက်မိဍောၚ်ကှ်ေထဝ်။) = “သူ့အသံကိုကြား၍ မြင်းသည်ပြေးလိုက်၏၊ ဝက်ခနဲရၚ်ကွဲသွားကာ ခရုပက်ကျိအနိုင်ရ၏။” || “ဗြက်သြိုဟ်ဒကး၊ ၜါလွးရသွံ။” (လိက်သောဝိန်ဇဲယ။ မာံရောဂေါ။) = “ဝက်ခနဲ ရၚ်နှစ်ခြမ်းကွဲသကဲ့သို့ပင်တကား။”')
,(10856,3,1,'ဆူးပုပ်ရွက်။','‘ပြက္ခ’ ရှု။')
,(10857,3,5,'စွာကျယ်စွာကျယ်။','“ဟီုဒၟံၚ်ဗြက်ဗြက်၊ သီုလက်သီုချဴ။” (လိက်သုပိဏ္ဏကုမ္မာ။မၚ်သၚ်ကြာ။) = “ဆဲရေး၍လည်းကောင်း ကျိန်ဆဲ၍လည်ကောင်း စွာကျယ်စွာကျယ်ပြောနေ၏။”')
,(10858,3,4,'ပေါများသည်။ ပြည့်နှက်သည်။ အနှံ့ပြန့်ကြဲသည်။','“မၞိဟ်အလုံနန်ဂှ် ကလော်ဂမၠိုၚ်ဗိုၚ်စကၠေံဖအိုတ်ရ။ ဆဇုတ်ဗြော်ဒၟံၚ် ပ္ဍဲနန်ဂှ်ရ။” (ဇ—၉၆။ အစွောံ။) = “နန်းတော်အလုံးရှိလူများကို ဘီလူးများစားပစ်ကုန်၏။ အရိုးတို့မျှသာ နန်းတော်­ ပြန့်ကြဲနေ၏။”')
,(10859,3,1,'ဦးခေါင်းခွံ။','“ဍေံကေတ်ဍိုတ်ဇမၞော်တုဲ ဍေံဇီုဖျေံဒးဗြော်က္ဍဟ်တုဲ ကမၠတ်တြုံဂှ် ဒးပကာဂစိုတ်ရ။” (ဇ—၄၁၉။ အစွောံ။) = “အုတ်ခဲကြီးကိုယူ၍ ဆောင့်ပစ်ချလိုက်ရာ ဦးခေါင်းခွံကိုထိ၍ ထိုခိုးသူယောကျာ်းသည် သေ၏။” || ‘ဗြံက်က္ဍိုပ်’ နှင့်အတူတူ။')
,(10860,3,4,'၁။ တွေးကြံသည်။ စဉ်းစားသည်။ (?)','“ဒေံဗြဴဂွံသော်၊ ဗြော်ဗြချပ်ရ။” (လိက်မိဍောၚ်ကှ်ေထဝ်။) = “နှမသည် ဆံတစ်မျှင်ကို ရသည်ရှိသော် တွေးကြံစဉ်းစား၏။”')
,(10860,3,4,'၂။ မြတ်နိုးတနာပြုသည်။','“(ကုဗြဴကလော်ဂှ်) ပဂၞကျာ်ဇၞော်၊ ဗြော်ဗြပ္ဍဲနန်။” (လိက်မိဍောၚ်ကှ်ေထဝ်) =“ဘီလူးမကို မိဖုရားကြီးလုပ်၍ နန်းတော်­ မြတ်နိုးတနာပြုထား၏။” || “ပသၟိၚ်ဓဝ်ဗၠာဲ၊ ဓဇန်နာဲလောန်။ ဂွံဗြဴကလော်၊ ဗြော်ဗြပ္ဍဲနန်။” (လိက်မိဍောၚ်ကှ်ေထဝ်) || “ဓဝ်သဳလဟေၚ်၊ ဗြော်ဗြရေၚ်ကာန်။” (လိက်တလိၚ်ပန်) = “သီလတရားကိုသာ မြတ်နိုးတနာပြု၍ မကွာရှိစေ၏။”')
,(10860,3,4,'၃။ ပြည့်နှက်သည်။','“ရတ်ဒစိတ်ဗော်၊ ရေၚ်လဝ်ဗြော်ဗြ။” (လိက်ပထမဗောဓိ။ မၚ်ဍိက်လ။) =“ရတနာကိုးပါးတို့ကို ပြည့်နှက်စွာစီရီထားရှိ၏။”')
,(10861,3,4,'ပြည့်နှက်သည်။ လွှမ်းမိုးသည်။','“ကာယဝွံ ဟိုတ်ဍေံဟွံဂွံသ္အးဇ္ၚး ဗြော်ဗြးဒၟံၚ်ကေုာံမသသ္အုဲ — ဂပ်ဂဝ်က္ဍုဟ်မၠေံဇအိုန်ဇရလောန်။” (သၠပတ်အနမတဂ္ဂသံသာရကထာ) = “ဤခန္ဓာကိုယ်သည် မသန့်မစင် အပုပ်နံ့ပြည့်နှက်လွှမ်းမိုးနေသဖြင့် စက်ဆုပ်ရွံရှာအပ်၏။” || “ဗြာတ်သီုသၞိၚ်ဗ္ဂာ၊ တာသီုသၞိၚ်ပြး။ ဗြော်ဗြးပေၚ်ဟး၊ သစးပေၚ်တိ။” (လိက်ဗြရတ်ဣဏၚ်ကၚ်ရဳ) =“ငှက်ပျောသီးထန်းသီးတို့သည် အခိုၚ်လိုက်ပြွတ်သိပ်ပြည့်နှက်ကာ မြေအနှံ့ပြန့်ကြဲနေ၏။”')
,(10862,3,1,'ရေမှုတ်။','ဗြံက်ဍာ် = ရေခတ်သောရေမှုတ်။ || ဍာ်မွဲဗြံက် = ရေတစ်မှုတ်။ ရေတစ်ခွက်။ || “ဗၞတ်ဍာ်မွဲဗြံက်ကီု မိဟွံကဵုကောသုၚ်—။” (ဇ—၃၈ဝ။ အစွောံ။)')
,(10863,3,1,'ဦးခေါင်းအရိုးခွံ။','“(ကၠၚ်ဟိုက်တံဂှ်) ၜံက်ဗြံက်က္ဍိုပ်ခဍာ်တုဲ ခဍာ်ဒးပကာဂစိုတ်ရ။” (ဇ—၂၇ဝ။ အစွောံ။) = “ခၚ်ပုပ်တို့သည် ကျီးတို့၏ဦးခေါင်းကို ထိုးပေါက်ကုန်၍ ကျီးတို့သေရကုန်၏။” || “(ဣသိဇၞော်ဂှ်) ၜုၚ်အဲကဵုဒလေၚ်တုဲ ဗြံက်က္ဍိုပ်အဲဒကးအာပၠန်ရ။” (ဇ—၅၂၆။အစွောံ။) = “ထိုရသေ့ကြီးသည် ငါ့ကို ထမ်းပိုးဖြင့်ရိုက်၍ ငါ့ဦးခေါင်းခွံကွဲလတ္တံ့။” || ‘ကေၚ်ကာဗြံက်က္ဍိုပ်’ (န) လည်းရှု။')
,(10864,3,1,'ဦးနှောက်။ (ပါဠိ—မတ္တလုၚ်္ဂ)','“မတ္တလုၚ်ဂံၚ်စိ၊ ဗြံက်က္ဍဟ်ညိဟွံဂေၚ်။” (လိက်လက္ခဏာဒိပ္ပဗိန္ဒော) = “မတ္တလုၚ်္ဂမည်သည် ဦးနှောက်ဖြစ်သည်မလွဲ။” || “မုတ္တလုဂ¢၊ ဗြံက်က္ဍဟ်ဆံၚ်ဏာ။” (လိက်ဇမ္ဗူပတိ။ မာံဒေံဍောတ်။) ဗြံက်ဂၞာ (န) အုန်းမှုတ်ခွက်။')
,(10865,3,4,'၁။ (အဝတ်အစား၊ အဆင်တန်ဆာ) ဝတ်စားဆင်ယင်သည်။','“ဂၞကျာ်ဇၞော်သၟိၚ်ဂှ်ကျိုၚ်ကျဝ်ဗြံက်ဗြ ပတၠစရာဲရုပ်မဂေါဝ်လောန်။” (ဇ—၄ဝ၁။ အစွောံ။) = “မင်း၏မိဖုရားကြီးသည် ခပ်သိမ်းသောတန်ဆာတို့ဖြင့် တန်ဆာဆင်အပ်သော မြတ်သောအဆင်းကို ဆောင်၏။” (ညောင်ကန်) || “ကောန်သၟိၚ်ကီု သီုမံၚ်မဂၞကျာ်ကမၠောန်သၟိၚ်ကီု သီုဍိက်ကုန်ကွတံဂှ်ကီု ကျိုၚ်ကျဝ်ဗြံက်ဗြဖေၚ်ထဝ်ယာတ်ထဝ် ယာတ်ကသဳကရးတံဂှ်ရ။” (ဇ—၅၃၄။ အစွောံ။) = “မင်းသားတို့သည်၄င်း မိဖုရား၊ ကိုယ်လုပ်၊ မောင်းမတို့သည်၄င်း အခြံအရံကျွန်တို့သည်၄င်း ရွှေဦးပေါင်း၊ရွှေအဝတ်ပုဆိုး၊ ကာသိကတိုင်းဖြစ်အဝတ်တို့ကို ဝတ်စားဆင်ယင်လျက် တန်ဆာဆင်ကုန်၏။”')
,(10865,3,4,'၂။ (ပန်းနံ့သာစသည်) ပန်ဆင်လိမ်းကျံသည်။','“နူဝဳမာန်သၟိၚ်သပဝ်ဂှ် အမြာဲမြမောဝ်ဒိပ်ဂှ် ဒေံဗြဴအဲဗြံက်ဗြဂှ် မောဝ်တမှာဲပ္ဍးဗက်ကၠုၚ်သၟိၚ်သပဝ် စိုပ်ကၠုၚ်ဒဵုဒၞာဲဏအ်ရ။” (ဇ—၃၂၇။ အစွောံ။) =“ဂဠုန်မင်း၏ဗိမာန်မှ ငါ့နှမတော်လိမ်းကျံသော နတ်နံ့သာ၏ရနံ့သည် ဂဠုန်မင်းနောက်လိုက်၍ဤနေရာသို့တိုၚ် သင်းပျံ့ကြိုင်လှိုင်၏။” || “မြမောဝ်ဒိပ်ဂှ် ကဵုဟုံဗြံက်ဗြတုဲ ယာတ်ဒိပ်ဂှ် ကဵုၜးဗိုက်ကျိုၚ်ကျဝ်တုဲ။” (ဇ—၃၆ဝ။ အစွောံ။) = “နတ်နံ့သာကို လိမ်းကျံစေ၍ နတ်­ဖြစ်သောအဝတ်ကို ဝတ်လဲဆင်ယင်စေ၍။” || “ပ္ကဴမြမောဝ်တံဂှ်လေဝ် မဟွံဗြံက်ဗြရ။” (ဇ—၃၁၈။ အစွောံ။) = “ပန်းနံ့သာတို့ကိုလည်း မပန်ဆင်မလိမ်းကျံ။” || “ၜးကြိယာရ၊ ဗြံက်ဗြစလန်။” (လိက်ဇိဝှစက္က) = “အဝတ်တန်ဆာကိုလဲ၍ နံ့သာလိမ်းကျံ၏။”')
,(10866,3,5,'၁။ များပြားစွာထလျက်။ စုအုံလျက်။ (ပိုးလောက်) ထိုးလျက်။','“ဇွကၠဵုသမ်အုဲပၠန်၊ ၜန်ၜေဲါမပု၊ တယျုဗြိုက်ဗြိုက်ကီု။” (အဘိဓမ္မတ္ထဒဳပနဳ။ ဂရိုက်သာံ။) = “ခွေးသေကောင်ပုပ်သည် ပုပ်ပွဖူးရောၚ်၍ ပိုးလောက်ထလျက်ရှိ၏။” || “ယွံပြိုတ်၊ တၠအဲဂှ် မၞုံကဵုပါၚ်လေဝ်မသ္အုဲလောန်၊ မၞုံကဵုဇကုတယုဗိုဟ်စဒၟံၚ်ဗြိုက်ဗြိုက်။” (ဓမ္မဒဳပနဳ။ မာံရွှေငိုး။) = “အိုပြိတ္တာ၊ သင်သည်အလွန်ပုပ်နံသောပါးစပ်ရှိ၍ ပိုးလောက်ထထိုးစားနေသော ခန္ဓာကိုယ်ရှိ၏။”')
,(10866,3,5,'၂။ (ချွေး) ပြိုက်ပြိုက်၊ (မျက်ရည်) ဖြိုင်ဖြိုင်။','“ဟးဒေံသ္ဍိုက်၊ ဗြိုက်ဗြိုက်မတ်ၜါ။ — နာဲသာဲနူကော၊ ကောဒးလ္ၚာပ်လ္ၚာ။ ကောဒးစံၚ်တူ၊ ကောဒးပူဆာ။” (လိက်သၚ်ဂဒါ။ သဳလဝန္တ။) = “မျက်စိနှစ်ဖက်တွင်မျက်ရည်ဖြိုင်ဖြိုင်လျက်ရှိသော အိုချစ်နှမ၊ သင်သည် မောင်မှကွဲကွာရခြင်းကြောင့် မောင့်ခမျာပူဆွေးပင်ပန်းရပါ၏။” || “ပလက်တိတ်ဇွောဝ်၊ ဇတဝ်နရိုက်။ ဇွောဝ်တိတ်ဗြိုက်ဗြိုက်၊ ဇိုတ်ဖ္ဍိုက်ဟွံမာန်။” (လိက်ဇမ္ဗူပတိ။ မာံဒေံဍောတ်။) = “ချွေးယိုစီးထွက်ကာ တုန်လှုပ်လျက် ပြိုက်ပြိုက်ယိုစီးထွက်သောချွေးကို မသုတ်နိုင်ဘဲရှိ၏။” || “ရမတ်ဗြိုက်ဗြိုက်၊ သီုကဵုသ္ဍိုက်ဂွ။” (လိက်သောဝိန်ဇဲယ။ မာံရောဂေါ။) = “အရှက်ရခြင်းနှင့်အတူ မျက်ရည်ဖြိုင်ဖြိုင်ကျ၏။”')
,(10867,3,1,'ဖျဉ်း။ ဝမ်းဗိုက်ဖောင်းသော အသည်းရောဂါ။ (လေဖျဉ်း၊ ရေဖျဉ်း၊ သွေးဖျဉ်းစသည်ဖြင့်သုံးမျိုးပြားသည်) ။','ယဲဗြိၚ် = ဖျဉ်းရောဂါ။')
,(10868,3,1,'မြွေတွင်း။',NULL)
,(10869,3,1,'ဥရောပတိုက်သား ဘရၚ်ဂျီလူမျိုး။ (?)',NULL)
,(10870,3,5,'တပြောင်ပြောင်။ တောက်လောင်လျက်။','“မအံက်ယာံမိၚ်၊ တွိၚ်ပါၚ်မွဲတောင်။ပ္ဍဲစိုတ်ဗြောၚ်ဗြောၚ်၊ ဍောၚ်တိုန်ခန္ဓ။” (လိက်ဇိဝှစက္က) = “သား၏နှုတ်ထွက်စကားကို ဖခင်ကြားသည်ရှိသော် စိတ်ထဲ­ တပြောင်ပြောင်တောက်လောင်လျက် ခန္ဓာမောပန်းလာ၏။”')
,(10871,3,5,'၁။ ပြိုးပြိုးပြက်ပြက်။ ပြိုးပြိုးပြောင်ပြောင်။ တပြောင်ပြောင်တောက်ပလျက်။','“ညံၚ်ဗီုလျးသၞံၚ်စံပါရောဟိဏဳ မပၠတဴလျးဗြံၚ်ဗြံၚ်။” (ဇ—၃၈ဝ။ အစွောံ။) = “သောက်ရှူးကြယ်ကဲ့သို့ အလင်းရောင် တပြောင်ပြောင်တောက်ပလျက်။” || “ကျာ်တြဲသီုကဵုလျးတရဴမဂဵုတဴဗြံၚ်ဗြံၚ်။” (အဓါန်မသုန်။ အစွောံ။) = “ရောင်ခြည်တော်ခြောက်သွယ်ဖြင့် ပြိုးပြိုးပြောင်ပြောင်တောက်ပသော မြတ်စွာဘုရား။”')
,(10871,3,5,'၂။ ပွက်ပွက်ဆူလျက်။','“ကၠေၚ်ဍာ်မတၞံဒၟံၚ်ဗြံၚ်ဗြံၚ်တံဂှ် ပွမကဵုဆာဲဖျေံပ္ဍဲက္ဍိုပ်။” (သၚ်္ခါရဘေဒနဳ။ ဝိန္ဒသာရ။) = “ပွက်ပွက်ဆူလျက်ရှိသော ဆီနှင့်ရေတို့ကို ဦးခေါင်းတွင်လောင်းချခြင်း။”')
,(10871,3,5,'၃။ (မျက်ရည်) ဖြိုင်ဖြိုင်ကျလျက်။ ဝမ်းနည်းပူဆွေးလျက်။','“မရဏကေတ်ဏာ၊ ပဟွံဗ္စာရံၚ်။ ရမတ်ဗြံၚ်ဗြံၚ်၊ ဒှ်မံၚ်သိၚ်သာ၊ ယာံအာလုံတိ။” (နရသာသန။ သဳလဝန္တ။) = “သေမင်းခေါ်ဆောင်သွားသည်ကို ဘာကြောင့်မဆင်ခြင်ကြည့်ပါသနည်း။ မျက်ရည်ဖြိုင်ဖြိုင်နှင့် ပူဆွေးသောကရောက်ကုန်၍ မြေအနှံ့ငိုကြွေးလျက် သွားနေကြရ၏။”')
,(10872,3,4,'အပြိုၚ်ဖြစ်သည်။ ပြိုၚ်တူဖြစ်သည်။','“(ကၠဵုကေုာံဇာဒိသိုၚ်) ဂတာကမၠိုၚ်၊ ချိုတ်ဗြိုၚ်သီုၜါ။” (လိက်မ္ၚဵုပိစှ်ောဒစာံ။ မာံထဝ်စိုပ်။) = “ခွေးနှင့်ခြင်္သေ့တို့သည် ထိုရေတွင်းကြမ်းပြၚ်­ နှစ်ကောင်စလုံး အပြိုၚ်သေကုန်၏။”')
,(10873,3,5,'တဖွဲဖွဲ။ တဖြုတ်ဖြတ်။','“အသဝ်ထာၚ်သ္ဂေဟ်၊ ပြဟ်စှ်ေဗြိုၚ်ဗြိုၚ်။” (လိက်ကောန်သၟိၚ်ပိ။ မာံခစုန်အံက်) = “ဝတ်ဆံဝတ်မှုန်တို့သည် တဖွဲဖွဲကြွေကျ၏။”')
,(10874,3,1,'ငှက်ပျောသီး။',NULL)
,(10875,3,1,'ပၚ်ပုငှက်ပျော။',NULL)
